              '[   "수열 \$\\{a_n\\}\$에서 이웃하는 두 항의 차 \$a_{n+1} - a_n\$을 새로운 수열 \$\\{b_n\\}\$이라고 할 때, 이 수열 \$\\{b_n\\}\$을 수열 \$\\{a_n\\}\$의 계차수열이라고 합니다. 즉, \$b_n = a_{n+1} - a_n\$의 관계가 성립하며, 원래 수열의 각 항 사이의 변화량을 관찰함으로써 수열의 규칙성을 찾아낼 수 있습니다.",   "계차수열 \$\\{b_n\\}\$을 알면 원래 수열 \$\\{a_n\\}\$의 일반항을 구할 수 있습니다. \$n \\ge 2\$일 때, \$a_n\$은 첫째항 \$a_1\$에 첫 번째부터 \$(n-1)\$번째까지의 계차를 모두 더한 값과 같습니다. 이를 공식으로 나타내면 다음과 같습니다. \$\$a_n = a_1 + \\sum_{k=1}^{n-1} b_k \\\\quad (n \\ge 2)\$\$ 이 공식은 수열의 항이 어떻게 변화하는지를 누적하여 계산하는 원리를 담고 있습니다.",   "계차수열의 성질을 이용할 때 주의할 점은 \$n=1\$일 때의 값입니다. 위 공식은 \$n \\ge 2\$인 경우에 성립하므로, 구한 일반항 식에 \$n=1\$을 대입했을 때 실제 첫째항 \$a_1\$과 일치하는지 반드시 확인해야 합니다. 만약 일치하지 않는다면 일반항을 \$n=1\$인 경우와 \$n \\ge 2\$인 경우로 나누어 써야 합니다.",   "예제: 수열 \$2, 5, 10, 17, 26, \\dots\$의 일반항 \$a_n\$을 구해 봅시다. 먼저 이웃하는 항의 차를 구하면 \$5-2=3, 10-5=5, 17-10=7, 26-17=9\$가 됩니다. 따라서 계차수열 \$\\{b_n\\}\$은 \$3, 5, 7, 9, \\dots\$인 등차수열이며, 일반항은 \$b_n = 2n+1\$입니다.",   "이제 계차수열 공식을 적용합니다. \$n \\ge 2\$일 때, \$\$a_n = a_1 + \\sum_{k=1}^{n-1} (2k+1) = 2 + \\left( 2 \\cdot \\frac{(n-1)n}{2} + (n-1) \\right) = 2 + (n^2 - n + n - 1) = n^2 + 1\$\$ 입니다. 마지막으로 \$n=1\$을 대입하면 \$1^2 + 1 = 2\$가 되어 실제 첫째항과 일치하므로, 이 수열의 일반항은 모든 자연수 \$n\$에 대하여 \$a_n = n^2 + 1\$입니다." ]',
