              '[   "두 조건 \$p, q\$에 대하여 명제 \'\$p \\\\implies q\$\'가 참일 때, 기호로 \$p \\\\implies q\$라고 나타냅니다. 이때 조건 \$p\$는 조건 \$q\$이기 위한 \'충분조건\'이라고 합니다. 이는 \$p\$라는 조건이 성립하기만 하면 \$q\$라는 결과가 반드시 따라온다는 의미로, \$p\$가 \$q\$를 포함하는 더 좁고 구체적인 범위임을 나타냅니다.",   "충분조건의 핵심은 진리집합 사이의 포함 관계입니다. 조건 \$p\$의 진리집합을 \$P\$, 조건 \$q\$의 진리집합을 \$Q\$라고 할 때, \$p \\\\implies q\$가 참이라는 것은 \$P \\\\subset Q\$임을 의미합니다. 즉, \$P\$에 속하는 모든 원소가 \$Q\$에 속할 때 \$p\$는 \$q\$이기 위한 충분조건이 됩니다. 만약 \$P = Q\$인 경우라면 \$p\$는 \$q\$이기 위한 충분조건인 동시에 필요조건이 되어 \'필요충분조건\'이라고 부릅니다.",   "예를 들어, \$p: x=1\$, \$q: x^2=1\$인 경우를 생각해 봅시다. \$p\$의 진리집합은 \$\\{1\\}\$이고, \$q\$의 진리집합은 \$\\{-1, 1\\}\$입니다. 이때 \$\\{1\\} \\\\subset \\{-1, 1\\}\$이 성립하므로 \$p \\\\implies q\$는 참입니다. 따라서 \$x=1\$은 \$x^2=1\$이기 위한 충분조건이 됩니다. 반대로 \$x^2=1\$이라고 해서 반드시 \$x=1\$인 것은 아니므로, \$q\$는 \$p\$이기 위한 충분조건이 될 수 없습니다.",   "다음 예제를 통해 충분조건을 확인해 보겠습니다. 두 조건 \$p: x > 3\$, \$q: x > 1\$에 대하여 \$p\$가 \$q\$이기 위한 충분조건인지 판별해 봅시다. 먼저 각 조건의 진리집합을 수직선 위에 나타내면, \$P = \\{x \\\\mid x > 3\\}\$이고 \$Q = \\{x \\\\mid x > 1\\}\$입니다.",   "단계별 풀이를 진행하면 다음과 같습니다. 첫째, 두 집합의 포함 관계를 확인합니다. \$x > 3\$인 모든 실수는 당연히 \$x > 1\$을 만족하므로 \$P \\\\subset Q\$가 성립합니다. 둘째, 포함 관계가 성립하므로 명제 \$p \\\\implies q\$는 참입니다. 따라서 조건 \$p\$는 조건 \$q\$이기 위한 충분조건이 됩니다. 이처럼 범위가 더 좁은 쪽이 충분조건이 된다는 점을 기억하면 문제를 쉽게 해결할 수 있습니다." ]',
