              '구한 기울기 \$m\$과 점 \$A(x_1, y_1)\$을 직선의 방정식 기본 형태인 \$y - y_1 = m(x - x_1)\$에 대입하면 두 점을 지나는 직선의 방정식을 완성할 수 있습니다. 만약 \$x_1 = x_2\$인 경우에는 \$x\$의 변화량이 0이 되어 기울기를 정의할 수 없으며, 이때 직선은 \$y\$축에 평행한 수직선이 되어 방정식은 \$x = x_1\$이 됩니다. 반대로 \$y_1 = y_2\$인 경우에는 기울기가 0이 되어 \$x\$축에 평행한 수평선 \$y = y_1\$이 됩니다.',
