              '가장 대표적인 인수분해 공식으로는 완전제곱식과 합차 공식이 있습니다. 완전제곱식은 \$\$a^2 + 2ab + b^2 = (a+b)^2\$\$ 및 \$\$a^2 - 2ab + b^2 = (a-b)^2\$\$와 같이 나타내며, 합차 공식은 \$\$a^2 - b^2 = (a+b)(a-b)\$\$로 표현됩니다. 또한, 이차항의 계수가 1인 이차식의 인수분해 공식인 \$\$x^2 + (a+b)x + ab = (x+a)(x+b)\$\$는 다항식을 인수로 분해할 때 가장 빈번하게 활용되는 핵심 공식입니다.',
              '조금 더 복잡한 형태로는 세 항의 제곱이나 세제곱의 합과 차에 관한 공식이 있습니다. 예를 들어, \$\$a^3 + b^3 = (a+b)(a^2 - ab + b^2)\$\$와 \$\$a^3 - b^3 = (a-b)(a^2 + ab + b^2)\$\$는 고등학교 과정에서 매우 중요한 공식입니다. 이러한 공식들을 자유자재로 활용하기 위해서는 식의 구조를 관찰하고, 어떤 공식에 해당하는지 빠르게 판단하는 연습이 필요합니다.',
