              '[   "이차부등식이란 부등식의 모든 항을 좌변으로 이항하여 정리했을 때, 좌변이 \$x\$에 대한 이차식인 부등식을 말합니다. 즉, \$ax^2 + bx + c > 0\$ (또는 \$<, \\\\le, \\\\ge\$) 꼴로 나타낼 수 있는 식을 의미합니다. 이차부등식의 해를 구한다는 것은 부등식을 참이 되게 하는 \$x\$의 값의 범위를 찾는 과정입니다. 이때 이차함수 \$y = ax^2 + bx + c\$의 그래프와 \$x\$축(\$y=0\$)의 위치 관계를 이용하면 매우 직관적으로 해를 구할 수 있습니다.",   "이차부등식의 해를 결정하는 핵심은 이차방정식 \$ax^2 + bx + c = 0\$의 판별식 \$D = b^2 - 4ac\$와 이차항의 계수 \$a\$의 부호입니다. 만약 \$a > 0\$일 때, 이차함수 그래프가 \$x\$축과 두 점 \$(\\\\alpha, 0), (\\\\beta, 0)\$에서 만난다면(단, \$\\\\alpha < \\\\beta\$), 부등식 \$ax^2 + bx + c > 0\$의 해는 \$x < \\\\alpha\$ 또는 \$x > \\\\beta\$가 됩니다. 반대로 \$ax^2 + bx + c < 0\$의 해는 두 근 사이인 \$\\\\alpha < x < \\\\beta\$가 됩니다. 판별식 \$D\$가 0이거나 음수인 경우에는 그래프가 \$x\$축과 접하거나 떠 있으므로, 부등식의 방향에 따라 해가 모든 실수가 되거나 해가 없을 수도 있습니다.",   "예를 들어 이차부등식 \$x^2 - 5x + 6 < 0\$의 해를 구해보겠습니다. 먼저 좌변을 인수분해하면 \$(x-2)(x-3) < 0\$이 됩니다. 이는 이차함수 \$y = x^2 - 5x + 6\$의 그래프가 \$x\$축과 \$x=2\$와 \$x=3\$에서 만난다는 것을 의미합니다. \$x^2\$의 계수가 양수이므로 아래로 볼록한 포물선이 그려지며, 함숫값이 0보다 작은 구간은 \$x\$축 아래쪽에 위치한 부분입니다.",   "따라서 그래프를 그려보면 \$x\$의 값이 2와 3 사이에 있을 때 함숫값이 음수가 됨을 확인할 수 있습니다. 즉, 부등식의 해는 \$2 < x < 3\$이 됩니다. 이처럼 이차부등식은 단순히 식을 푸는 것이 아니라, 이차함수의 그래프가 \$x\$축보다 위에 있는지(양수), 아래에 있는지(음수)를 파악하는 것이 핵심입니다.",   "다음으로 이차부등식 \$x^2 - 4x + 4 \\le 0\$을 풀어봅시다. 먼저 좌변을 인수분해하면 \$(x-2)^2 \\le 0\$이 됩니다. 실수의 제곱은 항상 0보다 크거나 같으므로, 이 식은 0보다 작을 수는 없고 0과 같아지는 경우만 존재합니다. 즉, \$(x-2)^2 = 0\$을 만족하는 \$x=2\$가 이 부등식의 유일한 해가 됩니다.",   "마지막으로 \$x^2 - x + 1 > 0\$의 경우를 살펴봅시다. 판별식 \$D = (-1)^2 - 4(1)(1) = -3\$으로 \$D < 0\$입니다. 이는 그래프가 \$x\$축과 만나지 않고 항상 떠 있음을 의미합니다. \$x^2\$의 계수가 양수이므로 모든 \$x\$에 대하여 \$x^2 - x + 1 > 0\$이 성립합니다. 따라서 이 부등식의 해는 \'모든 실수\'가 됩니다." ]',
            ],
          ),
        ],
      ),
    ],
  ),
  '필요충분조건': BookData(
    id: 'concept_필요충분조건',
    title: '필요충분조건',
    subtitle: '공통수학2 > 명제 > 충분조건과필요조건 > 필요충분조건',
    category: 'common',
    tags: ['공통수학2', '명제', '충분조건과필요조건', '필요충분조건'],
    chapters: [
      BookChapter(
        title: '필요충분조건',
        intro: ['공통수학2 > 명제 > 충분조건과필요조건 > 필요충분조건 개념 학습'],
        sections: [
          BookSection(
            title: '필요충분조건',
            paragraphs: [
              '두 조건 \$p\$와 \$q\$에 대하여 명제 \'\$p \\implies q\$\'가 참일 때, \$p\$는 \$q\$이기 위한 충분조건이라고 하고, \$q\$는 \$p\$이기 위한 필요조건이라고 합니다. 여기서 \'충분하다\'는 말은 \$p\$라는 조건만 만족해도 \$q\$가 되기에 충분하다는 뜻이고, \'필요하다\'는 말은 \$q\$가 되기 위해 \$p\$라는 조건이 반드시 필요하다는 의미로 이해하면 쉽습니다.',
              '만약 두 명제 \'\$p \\implies q\$\'와 \'\$q \\implies p\$\'가 모두 참이라면, 기호로 \$p \\iff q\$와 같이 나타내며 이때 \$p\$와 \$q\$는 서로에게 필요충분조건이라고 합니다. 이는 두 조건의 진리집합을 각각 \$P, Q\$라고 할 때, \$P = Q\$인 경우와 정확히 일치합니다. 즉, 두 조건이 논리적으로 완전히 같은 내용을 담고 있을 때 우리는 이를 필요충분조건 관계라고 부릅니다.',
              '필요충분조건을 판별할 때는 진리집합의 포함 관계를 확인하는 것이 가장 정확합니다. \$P \\subset Q\$이면 \$p\$는 \$q\$이기 위한 충분조건이고, \$Q \\subset P\$이면 \$p\$는 \$q\$이기 위한 필요조건입니다. 만약 \$P = Q\$라면 \$p\$는 \$q\$이기 위한 필요충분조건이 됩니다. 이 관계를 화살표로 나타내면 \$p \\implies q\$는 \$p\$가 \$q\$의 부분집합임을, \$p \\iff q\$는 두 집합이 서로 같음을 의미합니다.',
              '예제: 두 조건 \$p: x=2\$, \$q: x^2-4=0\$에 대하여 \$p\$는 \$q\$이기 위한 어떤 조건인지 판별해 봅시다. 먼저 각 조건의 진리집합을 구하면, \$p\$의 진리집합은 \$P = \\{2\\}\$이고, \$q\$의 진리집합은 \$x^2-4=0\$을 만족하는 \$x\$의 값이므로 \$Q = \\{-2, 2\\}\$가 됩니다.',
              '이제 두 집합의 포함 관계를 살펴봅니다. \$P = \\{2\\}\$이고 \$Q = \\{-2, 2\\}\$이므로, \$P \\subset Q\$가 성립합니다. 하지만 \$Q \\not\\subset P\$이므로 두 집합은 서로 같지 않습니다. 따라서 \$p \\implies q\$는 참이지만 \$q \\implies p\$는 거짓이 됩니다.',
              '결론적으로 \$p\$는 \$q\$이기 위한 충분조건이지만 필요조건은 아닙니다. 반대로 \$q\$는 \$p\$이기 위한 필요조건이지만 충분조건은 아닙니다. 이처럼 진리집합을 구하여 포함 관계를 비교하면 어떤 조건인지 명확하게 구분할 수 있습니다.',
            ],
          ),
        ],
      ),
    ],
  ),
  '밑': BookData(
    id: 'concept_밑',
    title: '밑',
    subtitle: '대수 > 로그 > 로그의정의 > 밑',
    category: 'common',
    tags: ['대수', '로그', '로그의정의', '밑'],
    chapters: [
      BookChapter(
        title: '밑',
        intro: ['대수 > 로그 > 로그의정의 > 밑 개념 학습'],
        sections: [
          BookSection(
            title: '밑',
            paragraphs: [
              '로그에서 \'밑\'이란 로그의 값을 결정하는 기준이 되는 수를 말합니다. 로그 \$\\log_a b\$에서 아래쪽에 작게 쓰여 있는 \$a\$를 바로 \'밑\'이라고 부릅니다. 로그는 \'어떤 수 \$a\$를 몇 번 곱해야 \$b\$가 되는가?\'라는 질문에 대한 답을 구하는 도구인데, 이때 곱해지는 대상인 \$a\$가 바로 밑의 역할을 합니다. 따라서 밑은 로그의 구조를 지탱하는 가장 중요한 기초라고 할 수 있습니다.',
              '로그가 수학적으로 의미를 갖기 위해서는 밑 \$a\$에 엄격한 조건이 필요합니다. 첫째, 밑 \$a\$는 \$0\$보다 커야 합니다(\$a > 0\$). 둘째, 밑 \$a\$는 \$1\$이 아니어야 합니다(\$a \\neq 1\$). 만약 밑이 \$1\$이라면 \$1\$을 아무리 거듭제곱해도 항상 \$1\$이 되므로, \$1\$이 아닌 다른 수에 대한 로그 값을 정의할 수 없기 때문입니다. 또한 밑이 음수이거나 \$0\$이면 거듭제곱을 할 때 값이 일정하게 유지되지 않거나 정의되지 않는 경우가 발생하여 로그의 성질을 유지할 수 없습니다.',
              '이러한 밑의 조건은 로그의 정의인 \$x = \\log_a b \\iff a^x = b\$에서 비롯됩니다. 지수함수 \$y = a^x\$의 밑 조건과 동일하게, 밑 \$a\$가 \$0\$보다 크고 \$1\$이 아닐 때 로그함수는 일대일 대응 관계를 가지며 안정적인 그래프를 형성합니다. 따라서 로그를 다룰 때는 항상 밑이 이 조건을 만족하는지 먼저 확인하는 습관을 들이는 것이 매우 중요합니다.',
              '예제: 다음 로그가 정의되기 위한 실수 \$x\$의 범위를 구하시오. \$\\log_{x-2} (5-x)\$',
              '풀이 단계: 로그가 정의되려면 밑 조건과 진수 조건 두 가지를 모두 만족해야 합니다. 첫째, 밑 조건에 의해 \$x-2 > 0\$이고 \$x-2 \\neq 1\$이어야 합니다. 이를 정리하면 \$x > 2\$이고 \$x \\neq 3\$입니다. 둘째, 진수 조건에 의해 \$5-x > 0\$이어야 하므로 \$x < 5\$입니다. 이 모든 조건을 종합하면 \$2 < x < 3\$ 또는 \$3 < x < 5\$가 됩니다.',
              '예제: \$\\log_a 8 = 3\$을 만족하는 밑 \$a\$의 값을 구하시오. 풀이: 로그의 정의에 따라 \$\\log_a 8 = 3\$은 \$a^3 = 8\$과 같습니다. \$8\$은 \$2\$를 세 번 곱한 수(\$2^3 = 8\$)이므로 \$a^3 = 2^3\$이 성립합니다. 따라서 \$a = 2\$입니다. 이때 \$a=2\$는 \$a > 0\$이고 \$a \\neq 1\$이라는 밑의 조건을 만족하므로 구하는 값은 \$2\$가 됩니다.',
            ],
          ),
        ],
      ),
    ],
  ),
  '최댓값(미분)': BookData(
    id: 'concept_최댓값(미분)',
