    category: 'common',
    tags: ['미적분Ⅰ', '미분과최대최소', '최댓값(미분)'],
    chapters: [
      BookChapter(
        title: '최댓값(미분)',
        intro: ['미적분Ⅰ > 미분과최대최소 > 최댓값(미분) 개념 학습'],
        sections: [
          BookSection(
            title: '최댓값(미분)',
            paragraphs: [
              '함수 \$f(x)\$가 어떤 구간에서 정의될 때, 그 구간에 속하는 모든 \$x\$에 대하여 \$f(x) \\leq M\$을 만족하는 상수 \$M\$이 존재하고, \$f(c) = M\$인 \$x=c\$가 존재한다면, 우리는 \$f(c)\$를 함수 \$f(x)\$의 최댓값이라고 합니다. 미분 가능한 함수에서 최댓값을 찾기 위해서는 먼저 도함수 \$f\'(x)\$를 구하여 \$f\'(x)=0\$이 되는 지점인 \'임계점\'을 찾아야 합니다. 이 지점들은 함수가 증가하다가 감소하거나, 감소하다가 증가하는 등 변화가 일어나는 후보지이기 때문입니다.',
              '구체적으로 닫힌 구간 \$[a, b]\$에서 연속인 함수 \$f(x)\$의 최댓값을 구하는 방법은 다음과 같습니다. 첫째, 구간 내에서 \$f\'(x)=0\$을 만족하는 모든 \$x\$의 값을 구합니다. 둘째, 구간의 양 끝점인 \$f(a)\$와 \$f(b)\$의 값을 계산합니다. 셋째, 위에서 구한 모든 후보값들(\$f(a), f(b)\$ 및 임계점에서의 함숫값들)을 서로 비교하여 그중 가장 큰 값을 선택합니다. 이때 사용되는 핵심 공식은 도함수의 부호 변화를 확인하는 것이며, \$f\'(x)\$의 부호가 양(+)에서 음(-)으로 바뀔 때 그 지점이 극대이자 최댓값의 강력한 후보가 됩니다.',
              '예제 문제를 통해 최댓값을 구하는 과정을 살펴보겠습니다. 함수 \$f(x) = -x^3 + 3x^2 + 9x\$의 구간 \$[-2, 4]\$에서의 최댓값을 구하시오. 먼저 함수를 미분하여 도함수를 구하면 \$\$f\'(x) = -3x^2 + 6x + 9\$\$가 됩니다. 이 도함수가 \$0\$이 되는 지점을 찾기 위해 방정식을 풀면 \$\$-3(x^2 - 2x - 3) = -3(x-3)(x+1) = 0\$\$이 되어, \$x = -1\$ 또는 \$x = 3\$이라는 두 개의 임계점을 얻을 수 있습니다.',
              '이제 구간 \$[-2, 4]\$ 내에 포함된 임계점과 양 끝점에서의 함숫값을 각각 계산합니다. 먼저 양 끝점인 \$x = -2\$와 \$x = 4\$를 대입하면, \$\$f(-2) = -(-8) + 3(4) + 9(-2) = 8 + 12 - 18 = 2\$\$이고, \$\$f(4) = -(64) + 3(16) + 9(4) = -64 + 48 + 36 = 20\$\$이 됩니다. 다음으로 임계점 \$x = -1\$과 \$x = 3\$을 대입하면, \$\$f(-1) = -(-1) + 3(1) + 9(-1) = 1 + 3 - 9 = -5\$\$이며, \$\$f(3) = -(27) + 3(9) + 9(3) = -27 + 27 + 27 = 27\$\$이 나옵니다.',
              '마지막으로 구한 함숫값들을 모두 비교합니다. 후보값들은 \$f(-2)=2, f(4)=20, f(-1)=-5, f(3)=27\$입니다. 이 중에서 가장 큰 값은 \$27\$임을 알 수 있습니다. 따라서 주어진 구간 \$[-2, 4]\$에서 함수 \$f(x)\$의 최댓값은 \$27\$입니다. 이처럼 미분을 이용하면 복잡한 그래프의 개형을 그리지 않고도 함숫값들을 비교하여 최댓값을 정확하게 찾아낼 수 있습니다.',
            ],
          ),
        ],
      ),
    ],
