    tags: ['공통수학1', '경우의수', '합의법칙', '사건의합'],
    chapters: [
      BookChapter(
        title: '사건의합',
        intro: ['공통수학1 > 경우의수 > 합의법칙 > 사건의합 개념 학습'],
