            title: '사건의합',
            paragraphs: [
              '[   "두 사건 \$A\$와 \$B\$가 동시에 일어나지 않을 때, 사건 \$A\$가 일어나는 경우의 수를 \$m\$, 사건 \$B\$가 일어나는 경우의 수를 \$n\$이라고 하면, 사건 \$A\$ 또는 사건 \$B\$가 일어나는 경우의 수는 \$m+n\$입니다. 이를 \'합의 법칙\'이라고 하며, 일상생활에서 \'어느 한쪽을 선택하는 상황\'을 수학적으로 표현한 것입니다. 여기서 \'동시에 일어나지 않는다\'는 말은 두 사건이 서로 겹치는 경우가 전혀 없다는 뜻으로, 이를 수학 용어로 \'배반사건\'이라고 합니다.",   "합의 법칙은 사건이 3개 이상일 때도 똑같이 적용됩니다. 사건 \$A, B, C\$가 서로 겹치지 않게 일어날 때, 사건 \$A\$ 또는 \$B\$ 또는 \$C\$가 일어나는 경우의 수는 각 사건의 경우의 수를 모두 더한 \$\$m + n + k\$\$가 됩니다. 중요한 점은 각 사건이 서로 영향을 주지 않으면서 동시에 발생할 수 없는 상황이어야 한다는 것입니다. 만약 두 사건이 동시에 일어날 가능성이 있다면, 단순히 더하기만 해서는 안 되고 겹치는 부분을 고려해야 하므로 주의가 필요합니다.",   "예를 들어, 어느 분식집에서 김밥 3종류와 라면 2종류를 판매하고 있다고 가정해 봅시다. 이때 김밥 한 줄을 고르거나 라면 한 그릇을 고르는 경우의 수를 구해 보겠습니다. 김밥을 고르는 사건을 \$A\$, 라면을 고르는 사건을 \$B\$라고 하면, 김밥을 고르는 경우의 수는 \$3\$, 라면을 고르는 경우의 수는 \$2\$입니다. 김밥과 라면을 동시에 고르는 것이 아니라 \'둘 중 하나\'를 선택하는 것이므로 합의 법칙을 적용합니다.",   "따라서 구하는 경우의 수는 \$\$3 + 2 = 5\$\$가 됩니다. 즉, 분식집에서 메뉴 하나를 선택하는 방법은 총 5가지입니다. 이처럼 합의 법칙은 \'또는(~거나)\'이라는 표현이 포함된 문제를 해결할 때 가장 기본이 되는 도구입니다. 문제 상황에서 선택지가 서로 배타적인지 확인하는 습관을 들이면 경우의 수를 훨씬 정확하게 계산할 수 있습니다.",   "조금 더 복잡한 예제로, 주사위 한 개를 던졌을 때 2의 배수가 나오거나 5의 약수가 나오는 경우의 수를 구해 봅시다. 먼저 2의 배수가 나오는 사건을 \$A\$라고 하면 \$A = \\{2, 4, 6\\}\$으로 경우의 수는 \$3\$입니다. 다음으로 5의 약수가 나오는 사건을 \$B\$라고 하면 \$B = \\{1, 5\\}\$로 경우의 수는 \$2\$입니다. 두 사건을 확인해 보면 겹치는 숫자가 없으므로 합의 법칙을 바로 사용할 수 있습니다.",   "최종적으로 구하는 경우의 수는 \$\$3 + 2 = 5\$\$입니다. 만약 2의 배수가 나오거나 4의 약수가 나오는 경우라면 어떻게 될까요? 2의 배수는 \$\\{2, 4, 6\\}\$이고 4의 약수는 \$\\{1, 2, 4\\}\$입니다. 이때는 \'2\'와 \'4\'가 두 사건에 모두 포함되어 있으므로, 단순히 더하면 겹치는 부분을 두 번 세게 됩니다. 이럴 때는 겹치는 부분을 제외하고 계산해야 한다는 점을 항상 기억하세요." ]',
            ],
          ),
        ],
      ),
    ],
  ),
  '부분분수': BookData(
    id: 'concept_부분분수',
    title: '부분분수',
    subtitle: '대수 > 수열 > 여러가지수열의합 > 부분분수',
    category: 'common',
    tags: ['대수', '수열', '여러가지수열의합', '부분분수'],
    chapters: [
      BookChapter(
        title: '부분분수',
        intro: ['대수 > 수열 > 여러가지수열의합 > 부분분수 개념 학습'],
        sections: [
          BookSection(
            title: '부분분수',
            paragraphs: [
              '부분분수란 분모가 곱의 형태로 이루어진 분수를 여러 개의 분수의 차(뺄셈)로 나누어 표현하는 방법을 말합니다. 복잡한 분수식을 간단하게 분해함으로써, 특히 수열의 합을 구할 때 항들이 서로 상쇄되도록 유도하여 계산을 획기적으로 줄여주는 매우 유용한 도구입니다. 분모가 두 인수의 곱으로 나타난 분수는 다음과 같은 기본 공식으로 변형할 수 있습니다.',
              '두 인수 \$A\$와 \$B\$의 곱을 분모로 가지는 분수는 다음과 같이 분해됩니다. \$\$ \\frac{1}{A \\times B} = \\frac{1}{B - A} \\left( \\frac{1}{A} - \\frac{1}{B} \\right) \$\$ 여기서 \$A\$와 \$B\$는 다항식일 수도 있고 수일 수도 있습니다. 이 공식의 핵심은 분모의 차이인 \$(B-A)\$를 분모에 나누어 줌으로써, 전체 식의 값은 유지하면서 분수 형태를 뺄셈 구조로 바꾸는 것입니다. 만약 분자가 1이 아니라면, 그 상수만큼 전체 식에 곱해주면 됩니다.',
              '부분분수를 활용하면 수열의 합을 구할 때 \'망원급수(Telescoping Series)\'의 원리를 적용할 수 있습니다. 수열의 각 항을 부분분수로 분해하면, 앞 항의 뒷부분과 뒤 항의 앞부분이 서로 더해지거나 빼지면서 중간 항들이 모두 사라지고 처음과 끝의 항만 남게 됩니다. 이를 통해 무한히 더해지는 복잡한 수열의 합도 아주 간단하게 계산할 수 있습니다.',
              '예제 문제: 다음 수열의 합 \$S = \\frac{1}{1 \\times 2} + \\frac{1}{2 \\times 3} + \\frac{1}{3 \\times 4} + \\dots + \\frac{1}{n(n+1)}\$을 구하시오. 이 문제는 분모가 연속된 자연수의 곱으로 이루어져 있습니다. 먼저 일반항 \$a_k = \\frac{1}{k(k+1)}\$을 부분분수 공식에 대입하여 변형합니다. \$\$ \\frac{1}{k(k+1)} = \\frac{1}{(k+1) - k} \\left( \\frac{1}{k} - \\frac{1}{k+1} \\right) = \\frac{1}{k} - \\frac{1}{k+1} \$\$',
              '이제 구하고자 하는 합 \$S\$에 변형된 식을 대입하여 나열해 봅니다. \$\$ S = \\left( 1 - \\frac{1}{2} \\right) + \\left( \\frac{1}{2} - \\frac{1}{3} \\right) + \\left( \\frac{1}{3} - \\frac{1}{4} \\right) + \\dots + \\left( \\frac{1}{n} - \\frac{1}{n+1} \\right) \$\$ 식을 살펴보면 \$-\\frac{1}{2}\$와 \$+\\frac{1}{2}\$, \$-\\frac{1}{3}\$과 \$+\\frac{1}{3}\$ 등 중간의 모든 항이 상쇄되는 것을 확인할 수 있습니다. 결과적으로 첫 번째 항인 \$1\$과 마지막 항인 \$-\\frac{1}{n+1}\$만 남게 됩니다.',
              '따라서 최종적인 합은 다음과 같이 정리됩니다. \$\$ S = 1 - \\frac{1}{n+1} = \\frac{n+1-1}{n+1} = \\frac{n}{n+1} \$\$ 이처럼 부분분수를 이용하면 복잡해 보이는 수열의 합도 단계별로 차근차근 접근하여 매우 간결한 결과값을 얻을 수 있습니다. 이 기법은 고등학교 수학에서 수열뿐만 아니라 적분이나 극한 문제를 해결할 때도 자주 등장하므로 반드시 숙달해 두어야 합니다.',
            ],
          ),
        ],
      ),
    ],
  ),
  '지수함수의평행이동': BookData(
    id: 'concept_지수함수의평행이동',
    title: '지수함수의평행이동',
    subtitle: '대수 > 지수함수 > 지수함수의평행이동',
    category: 'common',
    tags: ['대수', '지수함수', '지수함수의평행이동'],
    chapters: [
      BookChapter(
        title: '지수함수의평행이동',
        intro: ['대수 > 지수함수 > 지수함수의평행이동 개념 학습'],
        sections: [
          BookSection(
            title: '지수함수의평행이동',
            paragraphs: [
              '지수함수의 평행이동이란 기본적인 지수함수 \$y = a^x\$ (단, \$a > 0, a  eq 1\$)의 그래프를 좌표평면 위에서 가로 방향(x축)이나 세로 방향(y축)으로 밀어서 옮기는 것을 의미합니다. 함수 \$y = a^x\$의 그래프를 x축의 방향으로 \$p\$만큼, y축의 방향으로 \$q\$만큼 평행이동하면, 새로운 함수식은 \$y - q = a^{x - p}\$가 되며, 이를 정리하면 \$\$y = a^{x - p} + q\$\$가 됩니다.',
              '이 평행이동은 함수의 그래프 모양 자체를 바꾸지는 않지만, 점근선과 치역에 변화를 줍니다. 원래 지수함수 \$y = a^x\$의 점근선은 x축인 \$y = 0\$이었으나, y축으로 \$q\$만큼 평행이동하게 되면 점근선은 \$\$y = q\$\$로 변하게 됩니다. 또한, 원래의 치역은 \$y > 0\$이었으나, 평행이동 후에는 \$\$y > q\$\$로 바뀌어 함숫값의 범위가 결정됩니다.',
              '예를 들어, 함수 \$y = 2^{x-1} + 3\$의 그래프를 그려봅시다. 이 함수는 기본형인 \$y = 2^x\$를 x축의 방향으로 \$1\$만큼, y축의 방향으로 \$3\$만큼 평행이동한 것입니다. 이때 \$x\$에 \$1\$을 대입하면 \$y = 2^0 + 3 = 4\$가 되어 점 \$(1, 4)\$를 지나며, 점근선은 \$y = 3\$이 됩니다. 이처럼 평행이동을 이해하면 복잡한 지수함수도 기본형의 성질을 이용해 쉽게 파악할 수 있습니다.',
              '이제 구체적인 예제 문제를 풀어보겠습니다. \'함수 \$y = 3^{x+2} - 1\$의 그래프는 \$y = 3^x\$의 그래프를 어느 방향으로 얼마만큼 평행이동한 것인지 구하고, 이 함수의 점근선을 찾으시오.\'라는 문제가 있습니다. 먼저 주어진 식을 평행이동의 정의와 비교합니다. \$y = 3^{x - (-2)} - 1\$로 나타낼 수 있으므로, x축의 방향으로 \$-2\$만큼, y축의 방향으로 \$-1\$만큼 평행이동했음을 알 수 있습니다.',
              '마지막으로 점근선을 구하는 단계입니다. 지수함수 \$y = a^{x-p} + q\$에서 \$x\$가 매우 작아지거나 커질 때 \$a^{x-p}\$ 항은 \$0\$에 한없이 가까워집니다. 따라서 \$y = 3^{x+2} - 1\$에서 \$3^{x+2}\$ 항이 \$0\$에 가까워질 때 \$y\$값은 \$-1\$에 수렴하게 됩니다. 그러므로 이 함수의 점근선은 \$\$y = -1\$\$이 되며, 치역은 \$\$y > -1\$\$이 됩니다.',
            ],
          ),
        ],
      ),
    ],
  ),
  '평행조건': BookData(
    id: 'concept_평행조건',
    title: '평행조건',
    subtitle: '공통수학2 > 좌표평면 > 두직선의위치관계 > 평행조건',
    category: 'common',
    tags: ['공통수학2', '좌표평면', '두직선의위치관계', '평행조건'],
    chapters: [
      BookChapter(
        title: '평행조건',
        intro: ['공통수학2 > 좌표평면 > 두직선의위치관계 > 평행조건 개념 학습'],
        sections: [
          BookSection(
            title: '평행조건',
            paragraphs: [
              '좌표평면 위에서 두 직선이 서로 만나지 않고 나란히 뻗어 나가는 상태를 \'평행하다\'고 합니다. 두 직선이 평행하기 위해서는 두 직선의 기울기가 서로 같아야 하며, 동시에 y축과 만나는 점인 y절편은 서로 달라야 합니다. 만약 기울기와 y절편이 모두 같다면 두 직선은 서로 일치하게 되어 평행하다고 하지 않으므로, 이 점을 주의해야 합니다.',
              '두 직선의 방정식을 각각 \$y = mx + n\$과 \$y = m\'x + n\'\$이라고 할 때, 두 직선이 평행할 조건은 다음과 같습니다. 기울기를 나타내는 \$m\$과 \$m\'\$이 같고, y절편을 나타내는 \$n\$과 \$n\'\$은 달라야 합니다. 이를 수식으로 표현하면 \$\$m = m\', \\quad n \\neq n\'\$\$ 입니다. 만약 직선이 \$ax + by + c = 0\$과 \$a\'x + b\'y + c\' = 0\$의 일반형으로 주어졌다면, 기울기와 y절편을 비교하여 \$\$ \\frac{a}{a\'} = \\frac{b}{b\'} \\neq \\frac{c}{c\'} \$\$ 라는 관계식을 얻을 수 있습니다.',
              '이제 예제를 통해 평행조건을 적용해 봅시다. 두 직선 \$y = 2x + 3\$과 \$y = ax - 1\$이 서로 평행할 때, 상수 \$a\$의 값을 구하는 문제입니다. 평행하기 위해서는 두 직선의 기울기가 같아야 하므로, 첫 번째 직선의 기울기인 \$2\$와 두 번째 직선의 기울기인 \$a\$가 같아야 합니다. 따라서 \$a = 2\$가 됩니다.',
              '이때, y절편을 확인하여 두 직선이 일치하지 않는지 검토해야 합니다. 첫 번째 직선의 y절편은 \$3\$이고, 두 번째 직선의 y절편은 \$-1\$입니다. \$3 \\neq -1\$이므로 두 직선은 일치하지 않으며, 따라서 \$a = 2\$일 때 두 직선은 평행합니다.',
              '조금 더 복잡한 형태의 예제를 살펴봅시다. 두 직선 \$2x - y + 1 = 0\$과 \$4x + ky + 3 = 0\$이 평행하도록 하는 상수 \$k\$의 값을 구해 보겠습니다. 평행조건인 계수의 비를 이용하면 \$\$ \\frac{2}{4} = \\frac{-1}{k} \\neq \\frac{1}{3} \$\$ 이 성립해야 합니다. 먼저 앞의 등식 \$\\frac{2}{4} = \\frac{-1}{k}\$를 풀면, \$2k = -4\$가 되어 \$k = -2\$를 얻습니다.',
              '마지막으로 \$k = -2\$일 때 상수항의 비를 확인합니다. \$\\frac{2}{4} = \\frac{-1}{-2} = \\frac{1}{2}\$이고, 상수항의 비는 \$\\frac{1}{3}\$이므로 \$\\frac{1}{2} \\neq \\frac{1}{3}\$이 성립합니다. 따라서 두 직선은 일치하지 않고 평행하므로, 구하는 값은 \$k = -2\$입니다.',
            ],
          ),
        ],
      ),
    ],
  ),
  '고차식인수분해': BookData(
    id: 'concept_고차식인수분해',
    title: '고차식인수분해',
    subtitle: '공통수학1 > 다항식 > 인수분해 > 고차식인수분해',
    category: 'common',
    tags: ['공통수학1', '다항식', '인수분해', '고차식인수분해'],
    chapters: [
      BookChapter(
        title: '고차식인수분해',
        intro: ['공통수학1 > 다항식 > 인수분해 > 고차식인수분해 개념 학습'],
        sections: [
          BookSection(
            title: '고차식인수분해',
            paragraphs: [
              '[   "고차식의 인수분해란 차수가 3차 이상인 다항식을 두 개 이상의 다항식의 곱으로 나타내는 과정을 말합니다. 2차식은 근의 공식이나 인수분해 공식을 통해 쉽게 해결할 수 있지만, 3차 이상의 고차식은 \'인수정리\'와 \'조립제법\'을 활용하는 것이 핵심입니다. 인수정리란 다항식 \$P(x)\$에 대하여 \$P(\\alpha)=0\$이면 \$P(x)\$는 \$(x-\\alpha)\$를 인수로 가진다는 성질을 의미합니다.",   "고차식을 인수분해하기 위해서는 먼저 다항식의 상수항의 약수들을 후보로 대입하여 \$P(\\alpha)=0\$이 되는 \$\\alpha\$ 값을 찾습니다. 이렇게 찾은 인수를 바탕으로 조립제법을 시행하면 고차식을 \$(x-\\alpha) \\times Q(x)\$ 형태로 나눌 수 있습니다. 이때 몫인 \$Q(x)\$가 2차식이라면 다시 우리가 아는 인수분해 공식을 사용하여 끝까지 분해할 수 있습니다. 만약 \$Q(x)\$가 여전히 3차 이상이라면 같은 과정을 반복하여 완전히 인수분해합니다.",   "조립제법을 수행할 때는 다항식의 각 항의 계수를 순서대로 나열하되, 특정 차수의 항이 없다면 반드시 \$0\$을 써주어야 함을 주의해야 합니다. 또한, 인수정리를 이용할 때 대입하는 후보 값은 \$\\\\pm \\\\frac{\\\\text{상수항의 약수}}{\\\\text{최고차항의 계수의 약수}}\$ 범위 내에서 찾는 것이 효율적입니다. 이 과정을 통해 복잡한 고차식도 차수를 하나씩 낮추어 간단한 다항식들의 곱으로 표현할 수 있습니다.",   "예제 문제: 다항식 \$P(x) = x^3 - 2x^2 - x + 2\$를 인수분해하시오. 먼저 \$P(x)=0\$이 되는 \$x\$ 값을 찾기 위해 상수항 \$2\$의 약수인 \$\\\\pm 1, \\\\pm 2\$를 대입해 봅니다. \$P(1) = 1^3 - 2(1)^2 - 1 + 2 = 1 - 2 - 1 + 2 = 0\$이므로, \$(x-1)\$은 \$P(x)\$의 인수입니다.",   "이제 조립제법을 사용하여 \$P(x)\$를 \$(x-1)\$로 나눕니다. 계수 \$1, -2, -1, 2\$를 사용하여 조립제법을 수행하면 몫은 \$x^2 - x - 2\$가 됩니다. 즉, \$P(x) = (x-1)(x^2 - x - 2)\$로 나타낼 수 있습니다. 마지막으로 몫인 \$x^2 - x - 2\$를 인수분해하면 \$(x-2)(x+1)\$이 되므로, 최종 결과는 \$P(x) = (x-1)(x-2)(x+1)\$입니다." ]',
            ],
          ),
        ],
      ),
    ],
  ),
