        sections: [
          BookSection(
            title: '진수',
            paragraphs: [
              '로그 \$\\log_a b\$에서 아래에 있는 수 \$a\$를 밑이라고 부른다면, 오른쪽에 위치한 수 \$b\$를 바로 \'진수\'라고 합니다. 로그의 정의에 따르면, 양수 \$a\$(\$a \\neq 1\$)에 대하여 \$a^x = b\$를 만족하는 실수 \$x\$를 \$x = \\log_a b\$라고 나타냅니다. 이때 진수 \$b\$는 지수함수의 결과값이기 때문에 항상 0보다 커야 한다는 매우 중요한 성질을 가집니다.',
              '진수가 가져야 할 가장 핵심적인 조건은 \'진수 조건\'입니다. 로그 \$\\log_a b\$가 정의되기 위해서는 밑 조건인 \$a > 0, a \\neq 1\$과 더불어 반드시 \$\$b > 0\$\$이어야 합니다. 만약 진수가 0이거나 음수라면, 어떤 실수 \$a\$를 거듭제곱하더라도 그 결과가 \$b\$가 될 수 없으므로 로그 값 자체가 존재하지 않게 됩니다. 따라서 로그 문제를 풀 때는 항상 진수가 0보다 큰지 먼저 확인하는 습관을 들여야 합니다.',
              '예를 들어, \$\\log_2 8\$이라는 로그에서 진수는 8입니다. \$2^3 = 8\$이므로 이 로그의 값은 3이 됩니다. 반면, \$\\log_2 (-4)\$나 \$\\log_2 0\$은 진수 조건인 \$b > 0\$을 만족하지 않으므로 수학적으로 정의되지 않습니다. 이처럼 진수는 로그라는 식의 \'주인공\'과 같아서, 이 값이 양수라는 범위 안에서만 로그의 성질을 자유롭게 활용할 수 있습니다.',
              '이제 구체적인 예제를 풀어봅시다. \'로그 \$\\log_3 (x-2)\$가 정의되기 위한 \$x\$의 값의 범위를 구하시오.\'라는 문제가 있다면 어떻게 접근해야 할까요? 로그가 정의되려면 진수 조건에 의해 진수 부분이 0보다 커야 합니다. 즉, \$\$x - 2 > 0\$\$이라는 부등식을 세울 수 있습니다.',
              '위의 부등식을 풀면 \$x > 2\$가 됩니다. 따라서 이 로그가 정의되기 위한 \$x\$의 범위는 \$x > 2\$입니다. 만약 \$x\$에 2를 대입하면 진수가 0이 되고, 2보다 작은 수를 대입하면 진수가 음수가 되어 로그가 정의될 수 없습니다. 이처럼 진수 조건은 로그가 포함된 방정식이나 부등식을 풀 때 가장 먼저 고려해야 하는 필수적인 단계입니다.',
            ],
          ),
        ],
      ),
    ],
  ),
  '최솟값(미분)': BookData(
    id: 'concept_최솟값(미분)',
    title: '최솟값(미분)',
    subtitle: '미적분Ⅰ > 미분과최대최소 > 최솟값(미분)',
    category: 'common',
    tags: ['미적분Ⅰ', '미분과최대최소', '최솟값(미분)'],
    chapters: [
      BookChapter(
        title: '최솟값(미분)',
        intro: ['미적분Ⅰ > 미분과최대최소 > 최솟값(미분) 개념 학습'],
        sections: [
          BookSection(
            title: '최솟값(미분)',
            paragraphs: [
              '[   "함수 \$f(x)\$가 어떤 구간에서 정의될 때, 그 구간 내의 모든 함숫값 중에서 가장 작은 값을 \'최솟값\'이라고 합니다. 미분을 이용하면 함수의 그래프가 어떻게 변하는지 정확히 파악할 수 있어, 복잡한 함수의 최솟값을 매우 효율적으로 찾을 수 있습니다. 특히, 함수가 극솟값을 가지거나 구간의 양 끝점에서 함숫값이 가장 작아지는 경우를 확인하는 것이 핵심입니다.",   "어떤 구간 \$[a, b]\$에서 연속인 함수 \$f(x)\$의 최솟값을 구하려면 먼저 \$f\'(x)=0\$이 되는 점을 찾아야 합니다. 이때 \$f\'(x)=0\$을 만족하는 \$x\$의 값들에서 함수가 극솟값을 갖는지 확인하고, 구간의 양 끝점인 \$f(a)\$와 \$f(b)\$의 값도 함께 비교해야 합니다. 즉, 최솟값은 \'구간 내의 모든 극솟값\'과 \'양 끝점의 함숫값\' 중에서 가장 작은 값을 선택하여 결정합니다.",   "수학적으로 최솟값을 구하는 과정을 정리하면 다음과 같습니다. 먼저 도함수 \$f\'(x)\$를 구한 뒤, \$f\'(x)=0\$이 되는 \$x\$의 값(임계점)을 찾습니다. 이후 증감표를 작성하여 각 점에서의 함숫값을 계산합니다. 최종적으로 최솟값 \$m\$은 다음과 같은 집합에서 가장 작은 원소를 고르는 과정으로 정의됩니다. \$\$m = \\\\min \\\\{f(a), f(b), \\\\text{모든 극솟값}\\\\}\$\$",   "예제 문제를 통해 최솟값을 구해봅시다. 구간 \$[0, 3]\$에서 정의된 함수 \$f(x) = x^3 - 3x^2 + 5\$의 최솟값을 구해보겠습니다. 먼저 도함수를 구하면 \$f\'(x) = 3x^2 - 6x\$입니다. \$f\'(x) = 3x(x-2) = 0\$을 만족하는 \$x\$의 값은 \$x=0\$ 또는 \$x=2\$입니다.",   "이제 구간의 양 끝점과 극솟값을 비교합니다. \$x=0\$일 때 \$f(0) = 0^3 - 3(0)^2 + 5 = 5\$이고, \$x=2\$일 때 \$f(2) = 2^3 - 3(2)^2 + 5 = 8 - 12 + 5 = 1\$입니다. 마지막으로 구간의 오른쪽 끝점인 \$x=3\$일 때의 값을 구하면 \$f(3) = 3^3 - 3(3)^2 + 5 = 27 - 27 + 5 = 5\$입니다.",   "비교 대상인 함숫값들은 \$\\{f(0), f(2), f(3)\\} = \\{5, 1, 5\\}\$입니다. 이 중에서 가장 작은 값은 \$1\$이므로, 주어진 구간 \$[0, 3]\$에서 함수 \$f(x)\$의 최솟값은 \$1\$이 됩니다. 이처럼 미분을 활용하면 함수의 변화를 관찰하여 최솟값을 명확하게 찾아낼 수 있습니다." ]',
            ],
          ),
        ],
      ),
    ],
  ),
  '귀납법의원리': BookData(
    id: 'concept_귀납법의원리',
    title: '귀납법의원리',
    subtitle: '대수 > 수열 > 수학적귀납법 > 귀납법의원리',
    category: 'common',
    tags: ['대수', '수열', '수학적귀납법', '귀납법의원리'],
    chapters: [
      BookChapter(
        title: '귀납법의원리',
        intro: ['대수 > 수열 > 수학적귀납법 > 귀납법의원리 개념 학습'],
        sections: [
          BookSection(
            title: '귀납법의원리',
            paragraphs: [
              '수학적 귀납법은 자연수 \$n\$에 관한 명제 \$P(n)\$이 모든 자연수에 대하여 성립함을 증명하는 매우 강력한 도구입니다. 이 원리는 도미노가 줄지어 서 있는 모습과 같습니다. 첫 번째 도미노가 쓰러지고, 어떤 도미노가 쓰러지면 반드시 그 다음 도미노도 쓰러진다는 사실을 알면, 결국 모든 도미노가 쓰러지게 된다는 논리입니다.',
              '이를 수학적으로 엄밀하게 정의하면 다음과 같습니다. 첫째, \$n=1\$일 때 명제 \$P(1)\$이 참임을 보입니다. 둘째, \$n=k\$일 때 명제 \$P(k)\$가 참이라고 가정하면, \$n=k+1\$일 때도 명제 \$P(k+1)\$이 참이 됨을 보입니다. 이 두 가지 과정을 모두 증명하면, 수학적 귀납법의 원리에 의해 모든 자연수 \$n\$에 대하여 명제 \$P(n)\$이 참이 됩니다.',
              '수학적 귀납법의 핵심 공식은 증명 과정의 논리적 연결 고리입니다. \$n=k\$일 때의 가정을 \$P(k)\$라 하고, 이를 이용하여 \$P(k+1)\$을 유도하는 과정은 주로 다음과 같은 형태를 띱니다. 만약 \$1+2+3+\\cdots+n = \\frac{n(n+1)}{2}\$이라는 명제를 증명한다면, \$n=k\$일 때의 식에 \$(k+1)\$을 양변에 더하여 \$n=k+1\$일 때의 식인 \$\\frac{(k+1)(k+2)}{2}\$가 됨을 확인하는 방식입니다.',
              '이제 예제를 통해 직접 적용해 봅시다. \'모든 자연수 \$n\$에 대하여 \$1+3+5+\\cdots+(2n-1) = n^2\$이 성립함을 수학적 귀납법으로 증명하시오.\'라는 문제를 풀어보겠습니다. 먼저 \$n=1\$일 때, 좌변은 \$2(1)-1=1\$이고 우변은 \$1^2=1\$이므로 \$P(1)\$은 참입니다.',
              '다음으로 \$n=k\$일 때, 즉 \$1+3+5+\\cdots+(2k-1) = k^2\$이 성립한다고 가정합니다. 이제 \$n=k+1\$일 때의 식을 확인하기 위해 양변에 \$(k+1)\$번째 항인 \$2(k+1)-1 = 2k+1\$을 더합니다. 그러면 좌변은 \$1+3+5+\\cdots+(2k-1) + (2k+1)\$이 되고, 우변은 \$k^2 + (2k+1)\$이 됩니다.',
              '우변을 정리하면 \$k^2 + 2k + 1 = (k+1)^2\$이 됩니다. 이는 \$n=k+1\$일 때의 명제와 일치합니다. 따라서 \$n=k\$일 때 성립한다고 가정하면 \$n=k+1\$일 때도 성립함이 증명되었습니다. 결론적으로 수학적 귀납법에 의해 주어진 명제는 모든 자연수 \$n\$에 대하여 항상 참입니다.',
            ],
          ),
        ],
      ),
    ],
  ),
  '정의역(함수)': BookData(
    id: 'concept_정의역(함수)',
    title: '정의역(함수)',
    subtitle: '공통수학2 > 함수 > 함수의정의 > 정의역(함수)',
    category: 'common',
    tags: ['공통수학2', '함수', '함수의정의', '정의역(함수)'],
    chapters: [
      BookChapter(
        title: '정의역(함수)',
        intro: ['공통수학2 > 함수 > 함수의정의 > 정의역(함수) 개념 학습'],
        sections: [
          BookSection(
            title: '정의역(함수)',
            paragraphs: [
              '함수에서 \'정의역\'이란 함수가 입력값을 받아들일 수 있는 모든 가능한 값들의 집합을 의미합니다. 쉽게 말해, 함수라는 기계에 넣을 수 있는 \'재료\'들의 모임이라고 생각하면 됩니다. 함수 \$f: X \\rightarrow Y\$에서 집합 \$X\$의 모든 원소가 공역 \$Y\$의 원소에 단 하나씩 대응될 때, 이 집합 \$X\$를 함수 \$f\$의 정의역이라고 부릅니다.',
              '정의역을 결정할 때 가장 중요한 것은 함수가 수학적으로 \'정의\'될 수 있어야 한다는 점입니다. 예를 들어, 분수 함수에서는 분모가 0이 되면 안 되고, 제곱근(루트) 함수에서는 루트 안의 값이 0보다 크거나 같아야 합니다. 만약 이러한 조건을 만족하지 않는 값을 입력하면 함수값이 존재하지 않게 되므로, 그러한 값들은 정의역에서 제외해야 합니다.',
              '정의역을 수식으로 표현할 때는 주로 조건제시법을 사용합니다. 예를 들어, 함수 \$f(x) = \\frac{1}{x-2}\$의 정의역은 분모가 0이 되는 \$x=2\$를 제외한 모든 실수이므로, 다음과 같이 나타냅니다. \$\$D = \\{x \\mid x \\in \\mathbb{R}, x \\neq 2\\}\$\$ 이처럼 정의역은 함수의 성격에 따라 실수 전체의 집합이 될 수도 있고, 특정 구간이나 제한된 범위로 주어질 수도 있습니다.',
              '이제 구체적인 예제를 통해 정의역을 구하는 방법을 알아봅시다. 함수 \$f(x) = \\sqrt{x-3}\$의 정의역을 구해보겠습니다. 제곱근 안의 값은 항상 0보다 크거나 같아야 하므로, \$x-3 \\geq 0\$이라는 부등식을 세울 수 있습니다. 이를 풀면 \$x \\geq 3\$이 됩니다.',
              '따라서 이 함수의 정의역은 3보다 크거나 같은 모든 실수의 집합입니다. 이를 집합 기호로 나타내면 다음과 같습니다. \$\$D = \\{x \\mid x \\geq 3\\}\$\$ 이와 같이 함수가 주어졌을 때, 해당 함수가 실숫값을 가질 수 있는 \$x\$의 범위를 찾는 것이 정의역 구하기의 핵심입니다.',
              '마지막으로 분수 함수 \$f(x) = \\frac{5}{x^2-4}\$의 정의역을 구해봅시다. 분모가 0이 되는 지점에서는 함수값이 정의되지 않으므로, \$x^2-4 = 0\$이 되는 \$x\$값을 찾아야 합니다. \$x^2 = 4\$를 풀면 \$x = 2\$ 또는 \$x = -2\$가 나옵니다. 따라서 이 두 값을 제외한 모든 실수가 정의역이 되며, 수식으로는 다음과 같이 씁니다. \$\$D = \\{x \\mid x \\neq 2, x \\neq -2\\}\$\$',
