    category: 'common',
    tags: ['공통수학1', '경우의수', '곱의법칙', '사건의곱'],
    chapters: [
      BookChapter(
        title: '사건의곱',
        intro: ['공통수학1 > 경우의수 > 곱의법칙 > 사건의곱 개념 학습'],
        sections: [
          BookSection(
            title: '사건의곱',
            paragraphs: [
              '[   "경우의 수에서 \'사건의 곱(곱의 법칙)\'은 두 사건이 연달아 일어나거나 동시에 일어나는 상황을 다룰 때 사용합니다. 사건 A가 일어나는 경우의 수가 \$m\$가지이고, 그 각각의 경우에 대하여 사건 B가 일어나는 경우의 수가 \$n\$가지일 때, 두 사건 A와 B가 잇따라 일어나는 경우의 수는 \$m \\\\times n\$가지입니다. 이는 단순히 두 수를 곱하는 것이 아니라, 첫 번째 선택의 모든 갈래마다 두 번째 선택이 각각 존재한다는 논리적 구조를 바탕으로 합니다.",   "이 법칙이 성립하기 위해서는 두 사건이 서로 영향을 주지 않으면서 연속적으로 발생해야 합니다. 예를 들어, 사건 A를 선택한 후 그 결과에 상관없이 사건 B를 선택할 수 있는 구조라면 우리는 전체 경우의 수를 구하기 위해 곱셈을 수행합니다. 이를 수학적 기호로 나타내면, 사건 A의 경우의 수를 \$n(A)\$, 사건 B의 경우의 수를 \$n(B)\$라 할 때, 두 사건이 동시에 일어나는 경우의 수는 \$\$n(A \\\\times B) = n(A) \\\\times n(B)\$\$와 같이 표현할 수 있습니다.",   "이제 구체적인 예제를 통해 곱의 법칙을 적용해 봅시다. \'상의 3종류와 하의 4종류가 있을 때, 상의와 하의를 각각 하나씩 골라 입는 경우의 수\'를 구하는 문제입니다. 상의를 고르는 사건을 A, 하의를 고르는 사건을 B라고 하면, 상의를 고르는 경우의 수는 \$n(A) = 3\$이고, 하의를 고르는 경우의 수는 \$n(B) = 4\$입니다. 상의 하나를 고를 때마다 4가지의 하의를 짝지을 수 있으므로, 전체 경우의 수는 \$\$3 \\\\times 4 = 12\$\$가지가 됩니다.",   "조금 더 복잡한 예제로, \'서로 다른 주사위 2개를 동시에 던질 때 나오는 눈의 수의 경우의 수\'를 생각해 봅시다. 첫 번째 주사위에서 나올 수 있는 눈의 수는 \$\\{1, 2, 3, 4, 5, 6\\}\$으로 총 6가지입니다. 두 번째 주사위 역시 \$\\{1, 2, 3, 4, 5, 6\\}\$으로 총 6가지입니다. 첫 번째 주사위의 각 눈에 대하여 두 번째 주사위의 눈이 각각 대응되므로, 곱의 법칙에 의해 전체 경우의 수는 \$\$6 \\\\times 6 = 36\$\$가지가 됩니다.",   "마지막으로 경로의 수를 구하는 문제에 적용해 보겠습니다. 도시 A에서 도시 B로 가는 길이 2개 있고, 도시 B에서 도시 C로 가는 길이 3개 있을 때, A에서 B를 거쳐 C로 가는 방법의 수를 구해봅시다. A에서 B로 가는 사건을 \$m=2\$, B에서 C로 가는 사건을 \$n=3\$이라고 하면, 전체 경로는 A에서 B로 가는 각각의 길마다 B에서 C로 가는 3개의 길이 연결되어 있으므로 \$\$2 \\\\times 3 = 6\$\$가지가 됩니다. 이처럼 곱의 법칙은 복잡한 선택의 과정을 단순화하여 전체 경우를 빠짐없이 세는 데 매우 유용한 도구입니다." ]',
            ],
          ),
        ],
      ),
    ],
  ),
  '허수단위': BookData(
    id: 'concept_허수단위',
    title: '허수단위',
    subtitle: '공통수학1 > 복소수 > 허수단위',
    category: 'common',
    tags: ['공통수학1', '복소수', '허수단위'],
    chapters: [
      BookChapter(
        title: '허수단위',
        intro: ['공통수학1 > 복소수 > 허수단위 개념 학습'],
        sections: [
          BookSection(
            title: '허수단위',
            paragraphs: [
              '수학에서 실수는 제곱하면 항상 0 이상이 된다는 성질을 가지고 있습니다. 하지만 수학자들은 방정식을 풀다 보면 제곱해서 음수가 되는 새로운 수가 필요하다는 것을 깨달았습니다. 이러한 필요성에 의해 도입된 것이 바로 \'허수단위\'입니다. 허수단위는 제곱하여 \$-1\$이 되는 새로운 수로, 알파벳 \$i\$로 나타냅니다. 즉, 허수단위 \$i\$는 다음과 같이 정의됩니다. \$\$i^2 = -1\$\$ 여기서 \$i\$는 \'상상 속의 수\'라는 뜻인 \'imaginary number\'의 첫 글자에서 따온 것입니다.',
              '허수단위 \$i\$를 사용하면 음수의 제곱근을 표현할 수 있습니다. 예를 들어, \$\\sqrt{-1} = i\$로 정의하며, 일반적으로 양수 \$a\$에 대하여 \$\\sqrt{-a} = \\sqrt{a} \\cdot \\sqrt{-1} = \\sqrt{a}i\$와 같이 나타냅니다. 또한, 허수단위는 거듭제곱할 때마다 일정한 규칙을 가지고 순환하는 재미있는 성질이 있습니다. \$i^1 = i\$, \$i^2 = -1\$, \$i^3 = i^2 \\cdot i = -i\$, \$i^4 = i^2 \\cdot i^2 = (-1) \\cdot (-1) = 1\$이 되며, 이후로는 다시 \$i, -1, -i, 1\$이 반복됩니다.',
              '예제 1: 다음 식을 허수단위를 사용하여 간단히 나타내어 봅시다. (1) \$\\sqrt{-9}\$, (2) \$\\sqrt{-5}\$',
              '풀이 과정: 음수의 제곱근은 \$\\sqrt{-a} = \\sqrt{a}i\$의 성질을 이용하여 해결합니다. (1) \$\\sqrt{-9} = \\sqrt{9} \\cdot \\sqrt{-1} = 3i\$입니다. (2) \$\\sqrt{-5} = \\sqrt{5} \\cdot \\sqrt{-1} = \\sqrt{5}i\$입니다. 이처럼 음수 기호 안의 값을 양수로 바꾸고 \$i\$를 곱해주기만 하면 쉽게 표현할 수 있습니다.',
              '예제 2: \$i^{10}\$의 값을 구하여 봅시다.',
              '풀이 과정: 허수단위의 거듭제곱은 4를 주기로 순환합니다. \$i^4 = 1\$임을 이용하면 큰 지수를 가진 식도 간단히 계산할 수 있습니다. \$i^{10} = i^{4 \\times 2 + 2} = (i^4)^2 \\cdot i^2\$입니다. 여기서 \$i^4 = 1\$이므로, \$1^2 \\cdot i^2 = 1 \\cdot (-1) = -1\$이 됩니다. 따라서 \$i^{10} = -1\$입니다.',
            ],
          ),
        ],
      ),
    ],
