    tags: ['공통수학2', '좌표평면', '두직선의위치관계', '수직조건'],
    chapters: [
      BookChapter(
        title: '수직조건',
        intro: ['공통수학2 > 좌표평면 > 두직선의위치관계 > 수직조건 개념 학습'],
        sections: [
          BookSection(
            title: '수직조건',
            paragraphs: [
              '좌표평면 위에서 두 직선이 서로 수직으로 만날 때, 이 두 직선의 기울기 사이에는 아주 특별한 관계가 성립합니다. 서로 다른 두 직선 \$y = mx + n\$과 \$y = m\'x + n\'\$이 수직이라면, 두 직선의 기울기인 \$m\$과 \$m\'\$의 곱은 항상 \$-1\$이 됩니다. 즉, 한 직선의 기울기가 \$m\$일 때, 이와 수직인 직선의 기울기는 \$-1/m\$이 된다는 것을 알 수 있습니다.',
              '이 성질을 수학적 공식으로 나타내면 다음과 같습니다. 두 직선의 방정식이 각각 \$ax + by + c = 0\$과 \$a\'x + b\'y + c\' = 0\$으로 주어졌을 때, 두 직선이 수직일 조건은 \$\$aa\' + bb\' = 0\$\$입니다. 이 공식은 기울기를 직접 구하기 어려운 일반형 방정식에서도 두 직선의 수직 여부를 즉각적으로 판단할 수 있게 해주는 매우 유용한 도구입니다.',
              '이러한 수직 조건은 피타고라스 정리를 좌표평면 위에서 해석함으로써 유도됩니다. 원점을 지나는 두 직선 위에 각각 점 \$(1, m)\$과 \$(1, m\')\$을 잡고, 두 점 사이의 거리가 원점과 이루는 삼각형이 직각삼각형임을 이용하면 \$m \\times m\' = -1\$이라는 결론에 도달하게 됩니다. 따라서 두 직선이 수직이라는 것은 단순히 각도가 90도라는 기하학적 의미를 넘어, 기울기의 곱이 \$-1\$이라는 대수적 관계로 완벽하게 설명됩니다.',
              '이제 구체적인 예제를 통해 확인해 봅시다. 직선 \$y = 2x + 3\$과 수직이면서 점 \$(4, 1)\$을 지나는 직선의 방정식을 구하는 문제입니다. 먼저, 주어진 직선의 기울기가 \$2\$이므로, 우리가 구하려는 직선의 기울기를 \$m\$이라 하면 수직 조건에 의해 \$2 \\times m = -1\$이 성립해야 합니다. 따라서 구하는 직선의 기울기는 \$\$m = -\\frac{1}{2}\$\$이 됩니다.',
              '기울기를 구했으므로, 이제 점 \$(4, 1)\$을 지나는 직선의 방정식 공식을 사용하여 식을 완성합니다. 직선의 방정식은 \$y - y_1 = m(x - x_1)\$이므로, 여기에 \$m = -1/2\$과 점 \$(4, 1)\$을 대입하면 \$\$y - 1 = -\\frac{1}{2}(x - 4)\$\$가 됩니다. 이를 정리하면 \$\$y = -\\frac{1}{2}x + 2 + 1\$\$이 되어 최종적으로 \$\$y = -\\frac{1}{2}x + 3\$\$이라는 직선의 방정식을 얻을 수 있습니다.',
            ],
          ),
        ],
      ),
