  '로그법칙': BookData(
    id: 'concept_로그법칙',
    title: '로그법칙',
    subtitle: '대수 > 로그 > 로그의성질 > 로그법칙',
    category: 'common',
    tags: ['대수', '로그', '로그의성질', '로그법칙'],
    chapters: [
      BookChapter(
        title: '로그법칙',
        intro: ['대수 > 로그 > 로그의성질 > 로그법칙 개념 학습'],
        sections: [
          BookSection(
            title: '로그법칙',
            paragraphs: [
              '로그는 지수와 밀접한 관계를 맺고 있는 개념으로, 어떤 수 \$a\$를 몇 번 거듭제곱해야 \$M\$이 되는지를 나타내는 수입니다. 이를 기호로 \$x = \\log_a M\$이라고 쓰며, 이때 \$a\$를 밑, \$M\$을 진수라고 합니다. 로그가 정의되기 위해서는 밑 \$a\$는 \$1\$이 아닌 양수여야 하고, 진수 \$M\$은 항상 양수여야 한다는 중요한 전제 조건이 있습니다.',
              '로그의 연산 법칙은 지수 법칙에서 유래되었습니다. 가장 핵심적인 성질들은 다음과 같습니다. 먼저, 로그의 합은 진수의 곱으로 나타낼 수 있는 \$\\log_a M + \\log_a N = \\log_a (MN)\$이 있고, 로그의 차는 진수의 나눗셈인 \$\\log_a M - \\log_a N = \\log_a (\\frac{M}{N})\$이 있습니다. 또한, 진수의 지수는 로그 앞으로 내려올 수 있는 \$\\log_a M^k = k \\log_a M\$이라는 성질이 있어 복잡한 계산을 매우 간편하게 만들어 줍니다.',
              '추가적으로 밑과 진수가 같으면 \$\\log_a a = 1\$이고, 진수가 \$1\$이면 어떤 밑에서도 \$\\log_a 1 = 0\$이 됩니다. 또한, 밑을 변환해야 할 때는 \$\\log_a b = \\frac{\\log_c b}{\\log_c a}\$라는 밑 변환 공식을 사용합니다. 이 공식들은 로그를 포함한 방정식이나 부등식을 풀 때 필수적으로 사용되는 도구이므로, 각 성질이 왜 성립하는지 지수 법칙과 연결 지어 이해하는 것이 중요합니다.',
              '이제 예제를 통해 로그 법칙을 적용해 보겠습니다. 문제: \'\$\\log_2 12 - \\log_2 3\$의 값을 구하시오.\' 이 문제는 로그의 차 성질을 이용하면 간단히 해결됩니다. 로그의 차는 진수의 나눗셈으로 바꿀 수 있으므로, 식을 정리하면 \$\\log_2 (\\frac{12}{3})\$이 됩니다. 이를 계산하면 \$\\log_2 4\$가 되며, \$4\$는 \$2^2\$이므로 최종 결과는 \$2\$가 됩니다.',
              '조금 더 복잡한 예제를 살펴봅시다. 문제: \'\$2 \\log_3 2 + \\log_3 (9/4)\$의 값을 구하시오.\' 먼저 첫 번째 항에 로그의 지수 법칙 \$\\log_a M^k = k \\log_a M\$을 적용합니다. 그러면 \$2 \\log_3 2 = \\log_3 2^2 = \\log_3 4\$가 됩니다. 이제 식을 합치면 \$\\log_3 4 + \\log_3 (9/4)\$가 되고, 로그의 합 성질에 의해 \$\\log_3 (4 \\times \\frac{9}{4})\$가 됩니다. 진수를 계산하면 \$\\log_3 9\$가 되며, \$9\$는 \$3^2\$이므로 정답은 \$2\$가 됩니다.',
            ],
          ),
        ],
      ),
    ],
  ),
