            title: '최대최소문제',
            paragraphs: [
              '[   "함수의 최대·최소 문제는 주어진 구간에서 함수가 가질 수 있는 가장 큰 값과 가장 작은 값을 찾는 과정입니다. 닫힌 구간 \$[a, b]\$에서 연속인 함수 \$f(x)\$는 반드시 최댓값과 최솟값을 가지며, 이를 구하기 위해서는 먼저 구간 내에서 미분계수가 0이 되는 점, 즉 \$f\'(x)=0\$인 점을 찾아야 합니다. 이러한 점들을 \'임계점\'이라고 하며, 함수가 극대나 극소를 가질 가능성이 있는 후보지입니다.",   "최댓값과 최솟값을 구하는 구체적인 단계는 다음과 같습니다. 첫째, 주어진 구간 \$(a, b)\$에서 \$f\'(x)=0\$을 만족하는 \$x\$의 값들을 모두 구합니다. 둘째, 구간의 양 끝점인 \$f(a)\$와 \$f(b)\$의 값을 계산합니다. 셋째, 구한 임계점에서의 함숫값들과 양 끝점의 함숫값을 모두 비교합니다. 이들 중 가장 큰 값이 최댓값, 가장 작은 값이 최솟값이 됩니다. 공식으로 표현하면 구간 내의 임계점 집합을 \$C\$라 할 때, 최댓값과 최솟값은 다음과 같이 결정됩니다. \$\$M = \\\\max \\\\{f(a), f(b), f(c) \\\\mid c \\\\in C\\\\}, \\\\quad m = \\\\min \\\\{f(a), f(b), f(c) \\\\mid c \\\\in C\\\\}\$\$",   "이제 예제를 통해 직접 적용해 봅시다. 구간 \$[-1, 2]\$에서 함수 \$f(x) = x^3 - 3x + 2\$의 최댓값과 최솟값을 구해보겠습니다. 먼저 함수를 미분하여 도함수를 구하면 \$f\'(x) = 3x^2 - 3\$입니다. \$f\'(x) = 0\$이 되는 지점을 찾기 위해 방정식을 풀면 \$3(x^2 - 1) = 0\$이 되어 \$x = 1\$ 또는 \$x = -1\$을 얻습니다. 두 값 모두 주어진 구간 \$[-1, 2]\$에 포함되므로 후보가 됩니다.",   "다음으로 각 후보 지점과 구간의 양 끝점에서의 함숫값을 계산합니다. 구간의 끝점인 \$x = -1\$과 \$x = 2\$, 그리고 임계점인 \$x = 1\$을 대입합니다. \$f(-1) = (-1)^3 - 3(-1) + 2 = -1 + 3 + 2 = 4\$이고, \$f(1) = 1^3 - 3(1) + 2 = 1 - 3 + 2 = 0\$입니다. 마지막으로 구간의 오른쪽 끝점인 \$f(2) = 2^3 - 3(2) + 2 = 8 - 6 + 2 = 4\$를 구합니다.",   "마지막으로 계산된 함숫값들을 비교합니다. 후보군 \$\\{f(-1), f(1), f(2)\\}\$의 값은 \$\\{4, 0, 4\\}\$입니다. 이 중에서 가장 큰 값은 \$4\$이고, 가장 작은 값은 \$0\$입니다. 따라서 주어진 구간 \$[-1, 2]\$에서 함수 \$f(x)\$의 최댓값은 \$4\$, 최솟값은 \$0\$이 됩니다. 이처럼 미분을 이용하면 복잡한 그래프를 모두 그리지 않고도 함수의 변화를 파악하여 정확한 최대·최솟값을 찾아낼 수 있습니다." ]',
            ],
          ),
        ],
      ),
    ],
  ),
  '순열의수': BookData(
    id: 'concept_순열의수',
    title: '순열의수',
    subtitle: '공통수학1 > 경우의수 > 순열 > 순열의수',
    category: 'common',
    tags: ['공통수학1', '경우의수', '순열', '순열의수'],
    chapters: [
      BookChapter(
        title: '순열의수',
        intro: ['공통수학1 > 경우의수 > 순열 > 순열의수 개념 학습'],
        sections: [
          BookSection(
            title: '순열의수',
            paragraphs: [
              '[   "순열이란 서로 다른 \$n\$개에서 \$r\$개를 택하여 \'순서대로\' 나열하는 것을 말합니다. 예를 들어, 3명의 학생 중 반장과 부반장을 뽑는 것은 순서가 중요하므로 순열에 해당합니다. 이때 서로 다른 \$n\$개에서 \$r\$개를 택하는 순열의 수를 기호로 \$P\$를 사용하여 \$_nP_r\$과 같이 나타냅니다.",   "순열의 수를 구하는 공식은 다음과 같습니다. 서로 다른 \$n\$개에서 \$r\$개를 택해 나열할 때, 첫 번째 자리에 올 수 있는 것은 \$n\$가지, 두 번째는 \$(n-1)\$가지, 이런 식으로 \$r\$번째 자리까지 곱해 나갑니다. 이를 수학적으로 정리하면 다음과 같은 공식이 성립합니다. \$\$_nP_r = n \\times (n-1) \\times (n-2) \\times \\cdots \\times (n-r+1) = \\\\frac{n!}{(n-r)!}\$\$ 여기서 \$n!\$은 \$n\$부터 1까지의 모든 자연수를 곱한 값인 \'팩토리얼(계승)\'을 의미합니다.",   "순열의 성질 중 기억해야 할 중요한 약속이 있습니다. 하나도 뽑지 않는 경우인 \$_nP_0\$은 1로 정의하며, \$n\$개에서 \$n\$개를 모두 나열하는 \$_nP_n\$은 \$n!\$과 같습니다. 또한, 순열은 선택하는 순서가 바뀌면 다른 경우로 간주한다는 점이 조합과 가장 큰 차이점입니다. 이 개념을 잘 이해하면 복잡한 경우의 수 문제도 체계적으로 해결할 수 있습니다.",   "예제 문제: 5명의 후보 중에서 회장 1명과 부회장 1명을 뽑는 경우의 수를 구하시오. 이 문제는 5명 중 순서를 고려하여 2명을 뽑는 상황이므로 \$_5P_2\$를 계산하면 됩니다. 공식에 대입하면 다음과 같습니다. \$\$_5P_2 = 5 \\\\times 4 = 20\$\$ 따라서 회장과 부회장을 뽑는 경우의 수는 총 20가지입니다.",   "또 다른 예제로, 4명의 학생이 일렬로 서는 방법의 수를 구해봅시다. 이는 4명 중에서 4명을 모두 선택하여 나열하는 \$_4P_4\$의 상황입니다. 공식에 따라 계산하면 다음과 같습니다. \$\$_4P_4 = 4! = 4 \\\\times 3 \\\\times 2 \\\\times 1 = 24\$\$ 즉, 4명의 학생을 일렬로 세우는 방법은 총 24가지가 됩니다. 이처럼 순열은 나열해야 하는 대상의 개수와 선택하는 개수를 정확히 파악하는 것이 문제 풀이의 핵심입니다." ]',
            ],
          ),
        ],
      ),
    ],
  ),
  '공역': BookData(
    id: 'concept_공역',
    title: '공역',
    subtitle: '공통수학2 > 함수 > 함수의정의 > 공역',
    category: 'common',
    tags: ['공통수학2', '함수', '함수의정의', '공역'],
    chapters: [
      BookChapter(
        title: '공역',
        intro: ['공통수학2 > 함수 > 함수의정의 > 공역 개념 학습'],
        sections: [
          BookSection(
            title: '공역',
            paragraphs: [
              '함수 \$f: X \\to Y\$에서 집합 \$X\$를 정의역이라고 부르며, 함수에 의해 대응되는 결과값들이 모인 집합인 공역은 함수가 정의될 때 반드시 함께 주어져야 하는 \'도착지\'의 전체 집합입니다. 즉, 공역은 함수 \$f\$에서 화살표를 받는 대상들이 속해 있는 전체 집합 \$Y\$를 의미합니다. 함수를 정의할 때는 단순히 어떤 규칙으로 대응되는지만 중요한 것이 아니라, 그 규칙이 어떤 집합에서 어떤 집합으로 향하는지를 명확히 밝혀야 하므로 공역은 함수의 구성 요소 중 하나입니다.',
              '공역과 혼동하기 쉬운 개념으로 \'치역\'이 있습니다. 공역(\$Y\$)은 화살표를 받을 준비가 되어 있는 모든 원소의 집합인 반면, 치역은 실제로 정의역의 원소들이 화살표를 보내어 선택된 원소들의 집합입니다. 따라서 치역은 항상 공역의 부분집합(\$\\text{치역} \\subseteq Y\$)이 됩니다. 수학적으로 표현하면 치역은 다음과 같이 나타낼 수 있습니다. \$\$\\text{치역} = \\{f(x) \\mid x \\in X\\}\$\$',
              '예를 들어, 정의역 \$X = \\{1, 2, 3\\}\$이고 공역 \$Y = \\{a, b, c, d\\}\$인 함수 \$f\$가 있다고 가정해 봅시다. 만약 \$f(1)=a, f(2)=b, f(3)=c\$로 대응된다면, 이때 공역은 \$Y = \\{a, b, c, d\\}\$ 전체가 되지만, 실제로 선택받은 원소들인 치역은 \$\\{a, b, c\\}\$가 됩니다. 이처럼 공역은 함수가 정의된 범위 전체를 의미하며, 치역은 그중에서 실제로 함숫값을 가지는 부분만을 의미한다는 점을 기억해야 합니다.',
              '이제 구체적인 예제를 풀어보겠습니다. 두 집합 \$X = \\{-1, 0, 1\\}\$, \$Y = \\{0, 1, 2, 3\\}\$에 대하여 함수 \$f: X \\to Y\$가 \$f(x) = x^2 + 1\$로 정의될 때, 이 함수의 공역과 치역을 각각 구해보세요. 먼저 공역은 문제에서 주어진 집합 \$Y\$ 그 자체이므로, 공역은 \$\\{0, 1, 2, 3\\}\$입니다.',
              '다음으로 치역을 구하기 위해 정의역의 각 원소를 함수식 \$f(x) = x^2 + 1\$에 대입해 봅니다. 먼저 \$x = -1\$일 때 \$f(-1) = (-1)^2 + 1 = 2\$이고, \$x = 0\$일 때 \$f(0) = 0^2 + 1 = 1\$이며, \$x = 1\$일 때 \$f(1) = 1^2 + 1 = 2\$입니다. 따라서 실제로 대응된 값들을 모으면 \$\\{1, 2\\}\$가 됩니다. 결과적으로 이 함수의 공역은 \$\\{0, 1, 2, 3\\}\$이고, 치역은 \$\\{1, 2\\}\$가 되어 치역이 공역의 부분집합임을 확인할 수 있습니다.',
            ],
          ),
        ],
      ),
    ],
  ),
  '귀납법증명': BookData(
    id: 'concept_귀납법증명',
    title: '귀납법증명',
    subtitle: '대수 > 수열 > 수학적귀납법 > 귀납법증명',
    category: 'common',
    tags: ['대수', '수열', '수학적귀납법', '귀납법증명'],
    chapters: [
      BookChapter(
        title: '귀납법증명',
        intro: ['대수 > 수열 > 수학적귀납법 > 귀납법증명 개념 학습'],
        sections: [
          BookSection(
            title: '귀납법증명',
            paragraphs: [
              '수학적 귀납법은 자연수 \$n\$에 관한 명제 \$P(n)\$이 모든 자연수에 대하여 성립함을 증명하는 매우 강력한 방법입니다. 마치 도미노 게임과 같습니다. 첫 번째 도미노가 쓰러지는 것을 확인하고, 어떤 도미노가 쓰러지면 그 다음 도미노도 반드시 쓰러진다는 것을 증명하면, 결국 모든 도미노가 쓰러지는 것과 같은 원리입니다.',
              '이를 수학적으로 표현하면 두 단계로 나뉩니다. 첫째, \$n=1\$일 때 명제 \$P(1)\$이 참임을 보입니다. 둘째, \$n=k\$일 때 명제 \$P(k)\$가 참이라고 가정하면 \$n=k+1\$일 때도 명제 \$P(k+1)\$이 참임을 보입니다. 이 두 과정을 모두 마치면, 모든 자연수 \$n\$에 대하여 명제 \$P(n)\$이 성립한다는 결론을 내릴 수 있습니다.',
              '수학적 귀납법의 핵심 공식은 다음과 같습니다. 명제 \$P(n)\$에 대하여 다음 두 조건이 만족되면 \$P(n)\$은 모든 자연수 \$n\$에 대하여 참입니다. (1) \$P(1)\$이 참이다. (2) \$P(k)\$가 참이라고 가정할 때, \$P(k+1)\$이 참임을 증명한다. 즉, \$\$P(1) \\text{ is true} \\quad \\text{and} \\quad P(k) \\implies P(k+1)\$\$ 이 성립하면 모든 \$n \\in \\mathbb{N}\$에 대해 \$P(n)\$은 참입니다.',
              '이제 예제를 통해 확인해 봅시다. \'모든 자연수 \$n\$에 대하여 \$1 + 2 + 3 + \\dots + n = \\frac{n(n+1)}{2}\$이 성립함을 수학적 귀납법으로 증명하시오.\' 우선 \$n=1\$일 때, 좌변은 \$1\$이고 우변은 \$\\frac{1(1+1)}{2} = 1\$이므로 \$P(1)\$은 참입니다.',
              '다음으로 \$n=k\$일 때, 즉 \$1 + 2 + \\dots + k = \\frac{k(k+1)}{2}\$이 성립한다고 가정합니다. 이제 \$n=k+1\$일 때 성립하는지 확인하기 위해 양변에 \$(k+1)\$을 더합니다. 그러면 좌변은 \$1 + 2 + \\dots + k + (k+1)\$이 되고, 우변은 \$\\frac{k(k+1)}{2} + (k+1)\$이 됩니다.',
              '우변을 정리하면 \$\\frac{k(k+1) + 2(k+1)}{2} = \\frac{(k+1)(k+2)}{2}\$가 됩니다. 이는 \$n=k+1\$을 대입했을 때의 공식과 일치합니다. 따라서 \$P(k)\$가 참이면 \$P(k+1)\$도 참임이 증명되었으므로, 수학적 귀납법에 의해 주어진 등식은 모든 자연수 \$n\$에 대하여 성립합니다.',
            ],
          ),
        ],
      ),
    ],
  ),
