    tags: ['미적분Ⅰ', '함수의극대와극소', '극값의판정'],
    chapters: [
      BookChapter(
        title: '극값의판정',
        intro: ['미적분Ⅰ > 함수의극대와극소 > 극값의판정 개념 학습'],
        sections: [
          BookSection(
            title: '극값의판정',
            paragraphs: [
              '[   "함수의 극값이란 함수가 특정 구간에서 가장 크거나 작은 값을 가지는 지점을 의미합니다. 미분 가능한 함수 \$f(x)\$에 대하여, \$x=a\$를 포함하는 어떤 열린 구간에서 \$f(a) \\ge f(x)\$이면 \$f(a)\$를 극대값이라 하고, \$f(a) \\le f(x)\$이면 \$f(a)\$를 극소값이라 합니다. 이때 극대값과 극소값을 통틀어 극값이라고 부릅니다.",   "함수의 극값을 판정하는 가장 핵심적인 방법은 도함수 \$f\'(x)\$의 부호 변화를 관찰하는 것입니다. 미분 가능한 함수 \$f(x)\$에 대하여 \$f\'(a)=0\$일 때, \$x=a\$의 좌우에서 \$f\'(x)\$의 부호가 양(+)에서 음(-)으로 바뀌면 \$f(x)\$는 \$x=a\$에서 극대이고, 반대로 음(-)에서 양(+)으로 바뀌면 \$x=a\$에서 극소입니다. 이를 식으로 나타내면 다음과 같습니다.",   "\$\$f\'(a) = 0 \\\\text{이고, } x=a \\\\text{의 좌우에서 } f\'(x) \\\\text{의 부호가 바뀌면 } f(a) \\\\text{는 극값이다.}\$\$ 특히 \$f\'(x)\$의 부호가 양에서 음으로 변할 때 \$f(a)\$는 극대값, 음에서 양으로 변할 때 \$f(a)\$는 극소값이 됩니다. 만약 \$f\'(a)=0\$이지만 부호 변화가 없다면, 그 지점은 극값이 아닙니다.",   "예제: 함수 \$f(x) = x^3 - 3x^2 + 2\$의 극값을 구해보겠습니다. 먼저 도함수를 구하면 \$f\'(x) = 3x^2 - 6x\$입니다. 극값이 될 후보를 찾기 위해 \$f\'(x)=0\$을 풀면 \$3x(x-2)=0\$이 되어, \$x=0\$ 또는 \$x=2\$에서 도함수가 \$0\$이 됨을 알 수 있습니다.",   "이제 \$x=0\$과 \$x=2\$를 기준으로 \$f\'(x)\$의 부호를 조사합니다. \$x < 0\$일 때 \$f\'(x) > 0\$, \$0 < x < 2\$일 때 \$f\'(x) < 0\$, \$x > 2\$일 때 \$f\'(x) > 0\$입니다. 따라서 \$x=0\$에서는 부호가 양에서 음으로 바뀌므로 극대이고, \$x=2\$에서는 음에서 양으로 바뀌므로 극소입니다.",   "최종적으로 극값을 계산하면, \$x=0\$일 때 극대값은 \$f(0) = 0^3 - 3(0)^2 + 2 = 2\$가 됩니다. 또한 \$x=2\$일 때 극소값은 \$f(2) = 2^3 - 3(2)^2 + 2 = 8 - 12 + 2 = -2\$입니다. 이와 같이 도함수의 부호 변화를 확인하면 함수의 극대와 극소를 명확하게 판정할 수 있습니다." ]',
            ],
          ),
        ],
      ),
    ],
  ),
  '실수와허수': BookData(
    id: 'concept_실수와허수',
    title: '실수와허수',
    subtitle: '공통수학1 > 복소수 > 실수와허수',
    category: 'common',
    tags: ['공통수학1', '복소수', '실수와허수'],
    chapters: [
      BookChapter(
        title: '실수와허수',
        intro: ['공통수학1 > 복소수 > 실수와허수 개념 학습'],
        sections: [
          BookSection(
            title: '실수와허수',
            paragraphs: [
              '[   "우리가 흔히 사용하는 수인 실수(real number)는 제곱하면 항상 0보다 크거나 같은 성질을 가집니다. 하지만 수학자들은 제곱하여 음수가 되는 새로운 수의 필요성을 느꼈고, 이를 위해 제곱하여 \$-1\$이 되는 수 \$i\$를 도입하였습니다. 여기서 \$i\$는 허수 단위(imaginary unit)라고 부르며, \$i^2 = -1\$이라는 정의를 가집니다. 이처럼 실수와 허수를 통틀어 복소수(complex number)라고 하며, 복소수는 실수부와 허수부로 구성됩니다.",   "복소수는 일반적으로 \$a + bi\$ (단, \$a, b\$는 실수)의 꼴로 나타냅니다. 이때 \$a\$를 실수부분, \$b\$를 허수부분이라고 합니다. 만약 \$b=0\$이면 이 복소수는 실수가 되고, \$b \\neq 0\$이면 허수가 됩니다. 특히 \$a=0\$이고 \$b \\neq 0\$인 경우를 순허수라고 부릅니다. 복소수의 체계에서 실수는 허수부분이 0인 특별한 경우로 포함되며, 모든 실수는 복소수의 일부분입니다.",   "복소수의 연산에서 가장 중요한 성질은 \$i^2 = -1\$이라는 점입니다. 두 복소수 \$a+bi\$와 \$c+di\$가 서로 같을 조건은 실수부분끼리 같고(\$a=c\$), 허수부분끼리 같아야(\$b=d\$) 한다는 것입니다. 또한, 복소수 \$z = a+bi\$에 대하여 \$a-bi\$를 \$z\$의 켤레복소수라고 하며 \$\\bar{z}\$로 표기합니다. 이러한 성질들을 이용하면 복소수의 덧셈, 뺄셈, 곱셈, 나눗셈을 실수와 유사하게 계산할 수 있습니다.",   "예제 1: 다음 복소수 \$(2 + 3i) + (1 - 4i)\$를 계산해 봅시다. 복소수의 덧셈은 실수부분은 실수부분끼리, 허수부분은 허수부분끼리 모아서 계산하면 됩니다. 먼저 식을 정리하면 \$(2+1) + (3i - 4i)\$가 됩니다. 이를 계산하면 실수부분은 \$2+1=3\$이 되고, 허수부분은 \$3-4=-1\$이 되어 최종 결과는 \$\$3 - i\$\$가 됩니다.",   "예제 2: 복소수의 곱셈인 \$(1 + 2i)(3 - i)\$를 계산해 봅시다. 다항식의 곱셈과 마찬가지로 분배법칙을 사용하여 전개합니다. 식을 전개하면 \$1 \\cdot 3 + 1 \\cdot (-i) + 2i \\cdot 3 + 2i \\cdot (-i)\$가 됩니다. 이를 계산하면 \$3 - i + 6i - 2i^2\$이 됩니다. 여기서 \$i^2 = -1\$임을 이용하면 \$-2i^2 = -2(-1) = 2\$가 됩니다. 따라서 실수부분은 \$3+2=5\$, 허수부분은 \$-i+6i=5i\$가 되어 최종 결과는 \$\$5 + 5i\$\$가 됩니다." ]',
            ],
          ),
        ],
      ),
    ],
  ),
  '일치조건': BookData(
    id: 'concept_일치조건',
    title: '일치조건',
    subtitle: '공통수학2 > 좌표평면 > 두직선의위치관계 > 일치조건',
    category: 'common',
    tags: ['공통수학2', '좌표평면', '두직선의위치관계', '일치조건'],
    chapters: [
      BookChapter(
        title: '일치조건',
        intro: ['공통수학2 > 좌표평면 > 두직선의위치관계 > 일치조건 개념 학습'],
        sections: [
          BookSection(
            title: '일치조건',
            paragraphs: [
              '좌표평면 위에서 두 직선이 서로 \'일치한다\'는 것은 두 직선이 모든 점에서 만난다는 것을 의미합니다. 즉, 한 직선 위의 모든 점이 다른 직선 위에도 존재하여 두 직선이 완전히 겹쳐지는 상태를 말합니다. 이를 수식으로 나타내기 위해 두 직선의 방정식을 각각 \$a_1x + b_1y + c_1 = 0\$과 \$a_2x + b_2y + c_2 = 0\$이라고 가정해 봅시다.',
              '두 직선이 일치하기 위해서는 기울기가 같아야 할 뿐만 아니라, \$y\$절편까지 완전히 같아야 합니다. 이를 계수의 비를 이용하여 표현하면 다음과 같은 일치 조건을 얻을 수 있습니다. 두 직선이 일치할 필요충분조건은 각 계수의 비가 모두 같아야 한다는 것이며, 이를 공식으로 나타내면 \$\$ \\frac{a_1}{a_2} = \\frac{b_1}{b_2} = \\frac{c_1}{c_2} \$\$ 와 같습니다.',
              '이 조건은 두 직선의 방정식이 사실상 같은 식의 배수 관계에 있음을 의미합니다. 예를 들어, 한 직선의 방정식에 0이 아닌 상수 \$k\$를 곱했을 때 다른 직선의 방정식이 된다면, 두 직선은 일치하게 됩니다. 즉, \$a_1 = ka_2\$, \$b_1 = kb_2\$, \$c_1 = kc_2\$를 만족하는 상수 \$k\$가 존재한다면 두 직선은 좌표평면상에서 동일한 경로를 지나게 됩니다.',
              '이제 구체적인 예제를 통해 확인해 보겠습니다. 두 직선 \$2x + 3y - 6 = 0\$과 \$4x + 6y + k = 0\$이 서로 일치할 때, 상수 \$k\$의 값을 구하는 문제를 풀어봅시다. 두 직선이 일치하려면 계수의 비가 모두 같아야 하므로, 공식에 따라 다음과 같은 식을 세울 수 있습니다. \$\$ \\frac{2}{4} = \\frac{3}{6} = \\frac{-6}{k} \$\$',
              '위 식을 단계별로 계산하면 먼저 첫 번째와 두 번째 항에서 \$\\frac{2}{4} = \\frac{1}{2}\$이고 \$\\frac{3}{6} = \\frac{1}{2}\$임을 알 수 있습니다. 이제 일치 조건인 \$\\frac{1}{2} = \\frac{-6}{k}\$를 만족하는 \$k\$를 찾기 위해 양변에 \$2k\$를 곱하여 정리하면 \$k = 2 \\times (-6)\$이 됩니다. 따라서 최종적으로 \$k = -12\$라는 값을 얻을 수 있습니다.',
              '결과적으로 \$k = -12\$를 대입하면 두 번째 직선의 방정식은 \$4x + 6y - 12 = 0\$이 됩니다. 이 식을 2로 나누면 \$2x + 3y - 6 = 0\$이 되어 첫 번째 직선과 완전히 같아짐을 확인할 수 있습니다. 이처럼 일치 조건은 두 직선의 계수 비율을 비교함으로써 두 직선이 같은 직선인지 판별하는 매우 유용한 도구가 됩니다.',
            ],
          ),
        ],
      ),
    ],
  ),
  '밑의변환': BookData(
    id: 'concept_밑의변환',
    title: '밑의변환',
    subtitle: '대수 > 로그 > 로그의성질 > 밑의변환',
    category: 'common',
    tags: ['대수', '로그', '로그의성질', '밑의변환'],
    chapters: [
      BookChapter(
        title: '밑의변환',
        intro: ['대수 > 로그 > 로그의성질 > 밑의변환 개념 학습'],
        sections: [
          BookSection(
            title: '밑의변환',
            paragraphs: [
              '로그의 밑의 변환 공식은 로그의 밑을 우리가 원하는 새로운 밑으로 자유롭게 바꿀 수 있게 해주는 매우 유용한 도구입니다. 로그 \$\\log_a b\$에서 밑 \$a\$가 계산하기 불편하거나, 다른 로그들과 밑을 통일해야 할 때 이 공식을 사용합니다. 임의의 양수 \$c\$ (\$c \\neq 1\$)에 대하여, 로그의 밑을 \$c\$로 바꾸는 공식은 다음과 같습니다. \$\$ \\log_a b = \\frac{\\log_c b}{\\log_c a} \$\$',
              '이 공식의 핵심은 원래 로그의 진수 \$b\$는 분자로, 원래 로그의 밑 \$a\$는 분모로 가되, 새로운 밑 \$c\$를 각각의 로그 밑으로 취해준다는 점입니다. 특히, 원래 로그의 진수 \$b\$를 새로운 밑으로 설정하면 더욱 간단한 성질을 얻을 수 있습니다. 즉, \$c=b\$를 대입하면 \$\\log_a b = \\frac{\\log_b b}{\\log_b a}\$가 되는데, \$\\log_b b = 1\$이므로 다음과 같은 역수 관계가 성립합니다. \$\$ \\log_a b = \\frac{1}{\\log_b a} \$\$',
              '또한, 밑의 변환 공식을 응용하면 로그끼리의 곱셈에서 매우 편리한 성질을 발견할 수 있습니다. 서로 다른 밑과 진수를 가진 두 로그의 곱은 다음과 같이 정리됩니다. \$\$ \\log_a b \\times \\log_b c = \\frac{\\log c}{\\log a} \\times \\frac{\\log b}{\\log b} = \\frac{\\log c}{\\log a} = \\log_a c \$\$ 이처럼 밑의 변환은 복잡한 로그 식을 간단히 약분하거나 합치는 과정에서 수학적 효율성을 극대화해 줍니다.',
              '이제 예제를 통해 직접 적용해 봅시다. 문제: \'\$\\log_2 3 \\times \\log_3 4\$의 값을 구하시오.\' 이 문제는 밑의 변환 공식을 이용하면 아주 쉽게 해결할 수 있습니다. 먼저 각 로그를 상용로그(밑이 10인 로그)로 변환하여 식을 다시 써봅니다. \$\$ \\log_2 3 \\times \\log_3 4 = \\frac{\\log 3}{\\log 2} \\times \\frac{\\log 4}{\\log 3} \$\$',
              '위 식에서 분자와 분모에 공통으로 들어있는 \$\\log 3\$을 약분합니다. 그러면 식은 다음과 같이 남게 됩니다. \$\$ \\frac{\\log 4}{\\log 2} \$\$ 여기서 \$4\$는 \$2^2\$이므로 로그의 성질에 의해 \$\\log 4 = \\log 2^2 = 2\\log 2\$로 바꿀 수 있습니다. 이를 대입하면 최종 결과는 다음과 같습니다. \$\$ \\frac{2\\log 2}{\\log 2} = 2 \$\$ 따라서 주어진 식의 값은 \$2\$가 됩니다.',
            ],
          ),
        ],
      ),
    ],
  ),
  '위치함수': BookData(
    id: 'concept_위치함수',
    title: '위치함수',
    subtitle: '미적분Ⅰ > 속도와가속도 > 위치함수',
    category: 'common',
    tags: ['미적분Ⅰ', '속도와가속도', '위치함수'],
    chapters: [
      BookChapter(
        title: '위치함수',
        intro: ['미적분Ⅰ > 속도와가속도 > 위치함수 개념 학습'],
        sections: [
          BookSection(
            title: '위치함수',
            paragraphs: [
              '수직선 위를 움직이는 점 \$P\$의 시각 \$t\$에서의 위치를 \$x(t)\$라고 할 때, 이 함수 \$x(t)\$를 위치함수라고 합니다. 위치함수는 시간이 흐름에 따라 점 \$P\$가 수직선 위의 어느 지점에 있는지를 나타내며, 미분과 적분의 관계를 이해하는 데 매우 중요한 기초가 됩니다. 점 \$P\$의 위치가 시각 \$t\$에 대한 함수로 주어지면, 우리는 그 점이 어느 방향으로 얼마나 빠르게 움직이는지, 그리고 어떻게 가속되는지를 수학적으로 분석할 수 있습니다.',
              '위치함수 \$x(t)\$를 시각 \$t\$에 대하여 미분하면 점 \$P\$의 속도 \$v(t)\$를 구할 수 있습니다. 즉, 속도는 위치의 변화율을 의미하며 공식은 \$\$v(t) = \\frac{dx}{dt} = x\'(t)\$\$와 같습니다. 또한, 속도함수 \$v(t)\$를 다시 한번 미분하면 가속도 \$a(t)\$가 되는데, 이는 \$\$a(t) = \\frac{dv}{dt} = v\'(t) = x\'\'(t)\$\$로 표현됩니다. 반대로 속도함수를 적분하면 위치의 변화량을 구할 수 있으며, 시각 \$t=a\$에서 \$t=b\$까지의 위치 변화량은 \$x(b) - x(a) = \\int_{a}^{b} v(t) dt\$라는 관계가 성립합니다.',
              '이제 구체적인 예제를 통해 위치함수를 다루어 보겠습니다. 수직선 위를 움직이는 점 \$P\$의 시각 \$t\$에서의 위치함수가 \$x(t) = t^3 - 6t^2 + 9t\$로 주어졌다고 가정합시다. 이때 시각 \$t=2\$에서의 점 \$P\$의 속도와 가속도를 구하는 과정은 다음과 같습니다. 먼저 속도 \$v(t)\$를 구하기 위해 위치함수를 미분하면 \$\$v(t) = x\'(t) = 3t^2 - 12t + 9\$\$가 됩니다.',
              '다음으로 가속도 \$a(t)\$를 구하기 위해 속도함수를 한 번 더 미분합니다. 그러면 \$\$a(t) = v\'(t) = 6t - 12\$\$라는 식을 얻을 수 있습니다. 이제 문제에서 요구한 시각 \$t=2\$를 각각의 식에 대입하여 값을 계산합니다. 속도는 \$\$v(2) = 3(2)^2 - 12(2) + 9 = 12 - 24 + 9 = -3\$\$이고, 가속도는 \$\$a(2) = 6(2) - 12 = 0\$\$이 됩니다. 따라서 시각 \$t=2\$일 때 점 \$P\$는 음의 방향으로 속력 3만큼 움직이고 있으며, 가속도는 0임을 알 수 있습니다.',
            ],
          ),
        ],
      ),
    ],
  ),
  '팩토리얼': BookData(
    id: 'concept_팩토리얼',
    title: '팩토리얼',
    subtitle: '공통수학1 > 경우의수 > 순열 > 팩토리얼',
    category: 'common',
    tags: ['공통수학1', '경우의수', '순열', '팩토리얼'],
    chapters: [
      BookChapter(
        title: '팩토리얼',
        intro: ['공통수학1 > 경우의수 > 순열 > 팩토리얼 개념 학습'],
        sections: [
          BookSection(
            title: '팩토리얼',
            paragraphs: [
              '팩토리얼(factorial)은 서로 다른 \$n\$개의 물건을 일렬로 나열하는 방법의 수를 나타내는 수학적 개념입니다. 기호로는 \$n!\$이라고 쓰며, \'\$n\$ 팩토리얼\' 또는 \'\$n\$ 계승\'이라고 읽습니다. 이는 \$n\$부터 시작하여 1씩 줄여가며 1까지의 모든 자연수를 곱하는 것을 의미합니다. 즉, \$n\$개의 자리에 첫 번째 자리에 올 수 있는 경우의 수가 \$n\$가지, 두 번째 자리에 올 수 있는 경우의 수가 \$(n-1)\$가지가 되는 식으로 마지막 자리까지 곱해 나가는 원리입니다.',
              '팩토리얼의 핵심 공식은 다음과 같습니다. 자연수 \$n\$에 대하여 \$n! = n \\times (n-1) \\times (n-2) \\times \\cdots \\times 2 \\times 1\$로 정의합니다. 또한, 수학적 편의를 위해 \$0! = 1\$로 약속합니다. 이는 아무것도 선택하지 않는 경우의 수를 1가지로 보는 조합론적 관점과, \$n! = n \\times (n-1)!\$이라는 점화식 관계를 유지하기 위한 약속입니다. 이 공식은 순열의 수를 계산할 때 매우 유용하게 사용됩니다.',
              '팩토리얼의 성질 중 가장 중요한 것은 큰 팩토리얼을 작은 팩토리얼로 나누어 간단히 표현할 수 있다는 점입니다. 예를 들어, \$n! = n \\times (n-1)!\$과 같이 표현할 수 있습니다. 이러한 성질을 이용하면 복잡한 분수 형태의 순열 계산을 훨씬 빠르고 정확하게 수행할 수 있습니다. 팩토리얼은 숫자가 커질수록 값이 매우 빠르게 증가하는 특징이 있어, 경우의 수를 다룰 때 필수적인 도구입니다.',
              '예제: 5명의 학생이 일렬로 서서 사진을 찍는 방법의 수를 구해보세요. 이 문제는 서로 다른 5개를 일렬로 나열하는 순열의 문제이므로 팩토리얼을 사용하여 해결할 수 있습니다. 첫 번째 자리에 5명, 두 번째 자리에 4명, 세 번째 자리에 3명, 네 번째 자리에 2명, 마지막 자리에 1명이 서는 경우의 수를 모두 곱하면 됩니다.',
              '단계별 풀이: 5명의 학생을 일렬로 세우는 경우의 수는 \$5!\$입니다. 이를 공식에 대입하면 \$5! = 5 \\times 4 \\times 3 \\times 2 \\times 1\$이 됩니다. 계산 과정을 차례대로 수행하면 \$5 \\times 4 = 20\$, \$20 \\times 3 = 60\$, \$60 \\times 2 = 120\$, \$120 \\times 1 = 120\$이 됩니다. 따라서 5명의 학생을 일렬로 세우는 방법은 총 120가지입니다.',
            ],
          ),
        ],
      ),
    ],
  ),
  '치역': BookData(
    id: 'concept_치역',
    title: '치역',
    subtitle: '공통수학2 > 함수 > 함수의정의 > 치역',
    category: 'common',
    tags: ['공통수학2', '함수', '함수의정의', '치역'],
    chapters: [
      BookChapter(
        title: '치역',
        intro: ['공통수학2 > 함수 > 함수의정의 > 치역 개념 학습'],
        sections: [
          BookSection(
            title: '치역',
            paragraphs: [
              '[   "함수 \$f: X \\\\to Y\$에서 정의역 \$X\$의 각 원소 \$x\$에 대응하는 공역 \$Y\$의 원소 전체의 집합을 \'치역\'이라고 합니다. 쉽게 말해, 함수를 통해 실제로 \'선택받은\' 공역의 원소들만을 모아놓은 집합입니다. 공역은 함수가 도착할 수 있는 후보지 전체를 의미하지만, 치역은 그중에서 실제로 화살표를 받은 값들만을 의미하므로 치역은 항상 공역의 부분집합이 됩니다.",   "치역을 수학적 기호로 나타내면 다음과 같습니다. 정의역 \$X\$의 임의의 원소 \$x\$에 대하여 \$f(x)\$의 값들을 모두 모은 집합을 치역이라 하며, 보통 \$f(X)\$ 또는 \$\\{f(x) | x \\\\in X\\}\$로 표현합니다. 공식으로 정리하면 \$\$f(X) = \\\\{ y \\\\in Y \\\\mid y = f(x) \\\\text{를 만족하는 } x \\\\in X \\\\text{가 존재한다} \\\\}\$\$와 같이 나타낼 수 있습니다. 이 정의를 통해 우리는 함수가 주어졌을 때, 정의역의 모든 원소를 대입하여 나오는 결과값들의 범위를 찾아냄으로써 치역을 구할 수 있습니다.",   "예를 들어, 정의역이 \$X = \\\\{-1, 0, 1\\\\}\$이고 함수가 \$f(x) = x^2\$으로 정의된 경우를 생각해 봅시다. 각 원소를 대입하면 \$f(-1) = (-1)^2 = 1\$, \$f(0) = 0^2 = 0\$, \$f(1) = 1^2 = 1\$이 됩니다. 이때 결과값은 \$0\$과 \$1\$이므로, 이 함수의 치역은 \$\\{0, 1\\}\$이 됩니다. 공역이 만약 실수 전체의 집합이었다면, 치역은 공역의 일부분인 \$\\{0, 1\\}\$만 해당하게 되는 것입니다.",   "조금 더 복잡한 예제로, 정의역이 \$\\{x \\\\mid -2 \\\\le x \\\\le 3\\}\$인 함수 \$f(x) = 2x - 1\$의 치역을 구하는 과정을 단계별로 살펴보겠습니다. 첫째, 주어진 함수의 정의역 양 끝값을 대입하여 함숫값을 구합니다. \$x = -2\$일 때 \$f(-2) = 2(-2) - 1 = -5\$이고, \$x = 3\$일 때 \$f(3) = 2(3) - 1 = 5\$입니다.",   "둘째, 함수 \$f(x) = 2x - 1\$은 기울기가 양수인 직선이므로 \$x\$값이 커질수록 \$f(x)\$값도 커집니다. 따라서 정의역의 범위가 \$-2\$에서 \$3\$까지일 때, 함숫값은 \$-5\$에서 \$5\$까지 연속적으로 나타나게 됩니다. 이를 부등식으로 표현하면 \$-5 \\\\le f(x) \\\\le 5\$가 됩니다. 따라서 이 함수의 치역은 \$\\{y \\\\mid -5 \\\\le y \\\\le 5\\}\$가 됩니다." ]',
            ],
          ),
        ],
      ),
    ],
  ),
  '복소수의연산': BookData(
    id: 'concept_복소수의연산',
    title: '복소수의연산',
    subtitle: '공통수학1 > 복소수 > 복소수의연산',
    category: 'common',
    tags: ['공통수학1', '복소수', '복소수의연산'],
    chapters: [
      BookChapter(
        title: '복소수의연산',
        intro: ['공통수학1 > 복소수 > 복소수의연산 개념 학습'],
        sections: [
          BookSection(
            title: '복소수의연산',
            paragraphs: [
              '복소수란 실수와 허수단위 \$i\$를 이용하여 \$a+bi\$ (단, \$a, b\$는 실수)의 꼴로 나타내는 수입니다. 여기서 \$i\$는 제곱하여 \$-1\$이 되는 수, 즉 \$i^2 = -1\$을 만족하는 단위입니다. 복소수의 덧셈과 뺄셈은 다항식의 계산과 매우 유사합니다. 실수 부분은 실수 부분끼리, 허수 부분은 허수 부분끼리 모아서 계산하면 됩니다. 즉, 두 복소수 \$z_1 = a+bi\$, \$z_2 = c+di\$에 대하여 덧셈과 뺄셈은 다음과 같이 정의합니다.',
              '\$\$z_1 + z_2 = (a+c) + (b+d)i\$\$ \$\$z_1 - z_2 = (a-c) + (b-d)i\$\$ 복소수의 곱셈은 분배법칙을 이용하여 전개한 뒤, \$i^2 = -1\$임을 이용하여 실수 부분과 허수 부분으로 정리합니다. 나눗셈은 분모의 켤레복소수를 분모와 분자에 각각 곱하여 분모를 실수화한 뒤 계산합니다. \$z = a+bi\$일 때, 그 켤레복소수는 \$\\bar{z} = a-bi\$이며, \$z\\bar{z} = a^2+b^2\$이라는 성질을 이용하면 나눗셈을 쉽게 수행할 수 있습니다.',
              '이제 구체적인 예제를 통해 복소수의 연산을 익혀봅시다. 첫 번째 예제로 두 복소수 \$z_1 = 3+2i\$, \$z_2 = 1-4i\$가 주어졌을 때, \$z_1 + z_2\$와 \$z_1 - z_2\$를 계산해 보겠습니다. 덧셈은 실수부끼리 더하고 허수부끼리 더합니다. \$z_1 + z_2 = (3+1) + (2-4)i = 4-2i\$가 됩니다. 뺄셈은 \$z_1 - z_2 = (3-1) + (2-(-4))i = 2+6i\$가 됩니다.',
              '두 번째 예제로 복소수의 곱셈을 살펴봅시다. \$(2+i)(3-2i)\$를 계산해 보겠습니다. 분배법칙을 적용하면 \$(2+i)(3-2i) = 2 \\cdot 3 + 2 \\cdot (-2i) + i \\cdot 3 + i \\cdot (-2i) = 6 - 4i + 3i - 2i^2\$입니다. 여기서 \$i^2 = -1\$이므로 \$-2i^2 = -2(-1) = 2\$가 됩니다. 따라서 식을 정리하면 \$(6+2) + (-4+3)i = 8-i\$라는 결과를 얻을 수 있습니다.',
              '마지막으로 복소수의 나눗셈 예제입니다. \$\\frac{1+i}{2-i}\$를 계산하려면 분모의 켤레복소수인 \$2+i\$를 분모와 분자에 곱합니다. 식은 다음과 같습니다. \$\$\\frac{1+i}{2-i} = \\frac{(1+i)(2+i)}{(2-i)(2+i)} = \\frac{2+i+2i+i^2}{2^2 - i^2}\$\$ 분모는 \$4 - (-1) = 5\$가 되고, 분자는 \$2+3i-1 = 1+3i\$가 됩니다. 따라서 최종 결과는 \$\\frac{1}{5} + \\frac{3}{5}i\$입니다.',
            ],
          ),
        ],
      ),
    ],
  ),
  '좌극한': BookData(
    id: 'concept_좌극한',
    title: '좌극한',
    subtitle: '미적분Ⅰ > 함수의극한 > 극한의정의 > 좌극한',
    category: 'common',
    tags: ['미적분Ⅰ', '함수의극한', '극한의정의', '좌극한'],
    chapters: [
      BookChapter(
        title: '좌극한',
        intro: ['미적분Ⅰ > 함수의극한 > 극한의정의 > 좌극한 개념 학습'],
        sections: [
          BookSection(
            title: '좌극한',
            paragraphs: [
              '함수의 극한에서 \'좌극한\'이란, 변수 \$x\$가 어떤 값 \$a\$보다 작은 값을 가지면서 \$a\$에 한없이 가까워질 때, 함수 \$f(x)\$의 값이 도달하는 목표 지점을 의미합니다. 이를 기호로는 \$x\$가 \$a\$의 왼쪽에서 다가온다는 뜻의 \$x \\to a^-\$를 사용하여 다음과 같이 나타냅니다. 즉, \$x\$가 \$a\$보다 작은 범위에서 \$a\$로 접근할 때 \$f(x)\$가 일정한 값 \$L\$에 수렴한다면, 이를 \$L\$을 \$x=a\$에서의 좌극한이라 하고 \$\\lim_{x \\to a^-} f(x) = L\$이라고 씁니다.',
              '좌극한을 이해할 때 중요한 점은 \$x\$가 \$a\$에 도달하는 것이 아니라, \$a\$보다 작은 쪽에서 아주 가까운 값들을 대입했을 때 함수가 어떤 높이로 향하는지를 관찰하는 것입니다. 만약 함수가 \$x=a\$를 기준으로 왼쪽과 오른쪽에서 서로 다른 값으로 향한다면, 좌극한과 우극한이 다르다고 말합니다. 함수의 극한값이 존재하기 위해서는 좌극한과 우극한이 모두 존재하고 그 두 값이 서로 같아야 한다는 점을 반드시 기억해야 합니다.',
              '예를 들어, 함수 \$f(x) = \\begin{cases} x+1 & (x < 1) \\\\ 3 & (x \\ge 1) \\end{cases}\$가 주어졌을 때, \$x=1\$에서의 좌극한을 구해봅시다. 좌극한은 \$x\$가 1보다 작은 쪽에서 1로 다가갈 때의 값이므로, \$x < 1\$일 때의 식인 \$f(x) = x+1\$을 이용합니다. 이때 \$x\$에 1을 대입하는 것처럼 생각하면 \$\\lim_{x \\to 1^-} f(x) = \\lim_{x \\to 1^-} (x+1) = 1+1 = 2\$가 됩니다. 따라서 이 함수의 \$x=1\$에서의 좌극한은 2입니다.',
              '또 다른 예제로, 가우스 함수 \$f(x) = [x]\$의 \$x=2\$에서의 좌극한을 구해보겠습니다. 가우스 기호 \$[x]\$는 \$x\$보다 크지 않은 최대의 정수를 의미합니다. \$x\$가 2보다 작은 쪽에서 2로 다가갈 때, \$x\$는 1.9, 1.99, 1.999와 같은 값을 가집니다. 이 값들에 대해 가우스 기호를 씌우면 \$[1.9] = 1, [1.99] = 1, [1.999] = 1\$이 됩니다. 따라서 \$x\$가 2보다 작은 쪽에서 접근할 때 함수값은 항상 1을 유지하므로, \$\\lim_{x \\to 2^-} [x] = 1\$이 됩니다.',
              '마지막으로 그래프가 끊어져 있는 함수 \$g(x)\$에서 \$x=0\$일 때의 좌극한을 확인해 봅시다. 그래프 상에서 \$x\$축의 음수 방향에서 0으로 다가갈 때, 함수가 \$y=3\$이라는 높이를 향해 가고 있다면 좌극한은 3입니다. 만약 \$x=0\$일 때의 실제 함숫값이 5라고 하더라도, 좌극한은 \'다가가는 목표 지점\'을 의미하므로 함숫값과는 무관하게 3이 됩니다. 이처럼 좌극한은 그래프의 왼쪽 끝에서부터 0을 향해 손가락을 따라갔을 때 도착하는 \$y\$좌표를 읽는 것과 같습니다.',
            ],
          ),
        ],
      ),
    ],
  ),
  '거리공식(점직선)': BookData(
    id: 'concept_거리공식(점직선)',
    title: '거리공식(점직선)',
    subtitle: '공통수학2 > 좌표평면 > 점과직선사이의거리 > 거리공식(점직선)',
    category: 'common',
    tags: ['공통수학2', '좌표평면', '점과직선사이의거리', '거리공식(점직선)'],
    chapters: [
      BookChapter(
        title: '거리공식(점직선)',
        intro: ['공통수학2 > 좌표평면 > 점과직선사이의거리 > 거리공식(점직선) 개념 학습'],
        sections: [
          BookSection(
            title: '거리공식(점직선)',
            paragraphs: [
              '좌표평면 위에서 한 점 \$P(x_1, y_1)\$과 직선 \$ax + by + c = 0\$ 사이의 거리는 점 \$P\$에서 직선에 내린 수선의 발까지의 선분 길이를 의미합니다. 이 거리는 직선 위의 모든 점 중에서 점 \$P\$와 가장 가까운 거리를 나타내며, 기하학적으로는 점과 직선이 이루는 최단 거리를 뜻합니다. 이 거리를 구하기 위해서는 직선의 방정식이 일반형인 \$ax + by + c = 0\$ 꼴로 정리되어 있어야 합니다.',
              '점 \$(x_1, y_1)\$과 직선 \$ax + by + c = 0\$ 사이의 거리 \$d\$를 구하는 공식은 다음과 같습니다. 분자에는 점의 좌표를 직선의 방정식에 대입한 값의 절댓값을 취하고, 분모에는 직선의 \$x\$ 계수와 \$y\$ 계수의 제곱의 합에 루트를 씌운 값을 배치합니다. 공식은 다음과 같습니다. \$\$d = \\frac{|ax_1 + by_1 + c|}{\\sqrt{a^2 + b^2}}\$\$ 이 공식은 점과 직선 사이의 위치 관계를 파악하거나, 원과 직선이 접하는 조건을 구할 때 매우 유용하게 사용됩니다.',
              '이제 구체적인 예제를 통해 공식을 적용해 보겠습니다. 점 \$P(2, 1)\$과 직선 \$3x + 4y - 5 = 0\$ 사이의 거리를 구해 봅시다. 먼저 공식에 대입하기 위해 점의 좌표 \$x_1 = 2, y_1 = 1\$과 직선의 계수 \$a = 3, b = 4, c = -5\$를 확인합니다. 이 값들을 공식에 그대로 대입하면 계산을 시작할 수 있습니다.',
              '단계별 풀이를 진행하면, 먼저 분자에 점 \$(2, 1)\$을 직선의 식에 대입하여 \$|3(2) + 4(1) - 5|\$를 계산합니다. 이는 \$|6 + 4 - 5| = |5| = 5\$가 됩니다. 다음으로 분모에는 \$\\sqrt{3^2 + 4^2}\$을 계산합니다. \$\\sqrt{9 + 16} = \\sqrt{25} = 5\$가 되므로, 최종적으로 거리 \$d\$는 다음과 같이 계산됩니다. \$\$d = \\frac{5}{5} = 1\$\$ 따라서 점 \$(2, 1)\$과 직선 사이의 거리는 \$1\$입니다.',
            ],
          ),
        ],
      ),
    ],
  ),
  '상용로그': BookData(
    id: 'concept_상용로그',
    title: '상용로그',
    subtitle: '대수 > 로그 > 로그의성질 > 상용로그',
    category: 'common',
    tags: ['대수', '로그', '로그의성질', '상용로그'],
    chapters: [
      BookChapter(
        title: '상용로그',
        intro: ['대수 > 로그 > 로그의성질 > 상용로그 개념 학습'],
        sections: [
          BookSection(
            title: '상용로그',
            paragraphs: [
              '상용로그란 밑이 10인 로그를 말하며, 수학과 과학 분야에서 매우 자주 사용되기 때문에 밑 10을 생략하여 간단히 \$\\log_{10} N\$을 \$\\log N\$과 같이 나타냅니다. 10을 밑으로 하는 이유는 우리가 일상생활에서 십진법을 사용하기 때문인데, 이를 통해 큰 수나 아주 작은 수를 다룰 때 자릿수를 쉽게 파악할 수 있다는 장점이 있습니다.',
              '상용로그의 값은 일반적으로 정수 부분과 소수 부분으로 나뉩니다. 양수 \$N\$에 대하여 \$\\log N = n + \\alpha\$ (단, \$n\$은 정수, \$0 \\le \\alpha < 1\$)라고 할 때, 정수 부분 \$n\$은 수의 자릿수나 소수점 아래 첫 번째로 0이 아닌 숫자가 나타나는 위치를 결정하며, 소수 부분 \$\\alpha\$는 수의 숫자 배열을 결정합니다. 이러한 성질 덕분에 상용로그표를 이용하면 복잡한 수의 계산을 훨씬 수월하게 할 수 있습니다.',
              '예를 들어, \$\\log 10 = 1\$, \$\\log 100 = 2\$, \$\\log 1000 = 3\$과 같이 10의 거듭제곱 형태는 상용로그를 취했을 때 정수로 깔끔하게 떨어집니다. 일반적으로 \$\\log 10^n = n\$이라는 성질을 기억하면, 주어진 수의 크기를 가늠하는 데 큰 도움이 됩니다. 이제 이 개념을 활용하여 실제 문제를 어떻게 해결하는지 단계별로 살펴보겠습니다.',
              '예제 문제: \$\\log 2 \\approx 0.3010\$일 때, \$2^{10}\$의 값을 상용로그를 이용하여 추측해 봅시다. 먼저 \$x = 2^{10}\$이라고 하면, 양변에 상용로그를 취하여 \$\\log x = \\log 2^{10}\$이 됩니다. 로그의 성질에 의해 지수는 앞으로 내려올 수 있으므로, \$\\log x = 10 \\times \\log 2\$라는 식을 얻을 수 있습니다.',
              '이제 주어진 값 \$\\log 2 \\approx 0.3010\$을 대입하여 계산하면 \$\\log x = 10 \\times 0.3010 = 3.010\$이 됩니다. 여기서 정수 부분은 3이고 소수 부분은 0.010입니다. 정수 부분이 3이라는 것은 \$x\$가 4자리 수임을 의미하며, \$\\log 1 = 0\$이고 \$\\log 2 = 0.3010\$이므로 소수 부분 0.010은 1과 2 사이의 어떤 수임을 나타냅니다. 따라서 \$2^{10}\$은 1000보다 조금 큰 수임을 알 수 있으며, 실제 값인 1024와 일치함을 확인할 수 있습니다.',
            ],
          ),
        ],
      ),
    ],
  ),
  '속도': BookData(
    id: 'concept_속도',
    title: '속도',
    subtitle: '미적분Ⅰ > 속도와가속도 > 속도',
    category: 'common',
    tags: ['미적분Ⅰ', '속도와가속도', '속도'],
    chapters: [
      BookChapter(
        title: '속도',
        intro: ['미적분Ⅰ > 속도와가속도 > 속도 개념 학습'],
        sections: [
          BookSection(
            title: '속도',
            paragraphs: [
              '수직선 위를 움직이는 점 \$P\$의 시각 \$t\$에서의 위치를 \$x(t)\$라고 할 때, 시각 \$t\$에서 \$t+\\Delta t\$까지의 위치의 변화량은 \$x(t+\\Delta t) - x(t)\$입니다. 이때 단위 시간당 위치의 변화율인 \'평균속도\'는 \$\\frac{x(t+\\Delta t) - x(t)}{\\Delta t}\$로 정의됩니다. 여기서 시간의 간격 \$\\Delta t\$를 한없이 \$0\$에 가깝게 줄이면, 특정 시각 \$t\$에서의 순간적인 움직임의 정도를 나타내는 \'속도\'를 구할 수 있습니다.',
              '속도 \$v(t)\$는 위치 함수 \$x(t)\$를 시각 \$t\$에 대하여 미분하여 얻을 수 있습니다. 즉, 속도는 위치의 시간 변화율을 의미하며 수학적으로 다음과 같이 정의합니다. \$\$v(t) = \\lim_{\\Delta t \\to 0} \\frac{x(t+\\Delta t) - x(t)}{\\Delta t} = \\frac{dx}{dt}\$\$ 속도는 방향을 가지는 물리량으로, 수직선 위에서 양의 방향으로 움직이면 속도는 양(\$+\$)의 값을, 음의 방향으로 움직이면 속도는 음(\$-\$)의 값을 갖습니다. 반면, 속도의 절댓값인 \$|v(t)|\$는 \'속력\'이라고 부르며, 이는 물체가 움직이는 빠르기만을 나타냅니다.',
              '수직선 위를 움직이는 점 \$P\$의 시각 \$t\$에서의 위치가 \$x(t) = t^3 - 6t^2 + 9t\$라고 할 때, 시각 \$t=4\$에서의 속도를 구하는 과정을 살펴봅시다. 속도 \$v(t)\$는 위치 \$x(t)\$를 미분한 것이므로, 미분법의 기본 공식을 적용하면 다음과 같습니다. \$\$v(t) = \\frac{d}{dt}(t^3 - 6t^2 + 9t) = 3t^2 - 12t + 9\$\$',
              '이제 구한 속도 함수 \$v(t) = 3t^2 - 12t + 9\$에 시각 \$t=4\$를 대입하여 순간 속도를 계산합니다. \$\$v(4) = 3(4)^2 - 12(4) + 9 = 3(16) - 48 + 9 = 48 - 48 + 9 = 9\$\$ 따라서 시각 \$t=4\$일 때 점 \$P\$의 속도는 \$9\$입니다. 이는 점 \$P\$가 해당 시각에 수직선의 양의 방향으로 \$9\$만큼의 속도로 움직이고 있음을 의미합니다.',
              '추가로, 점 \$P\$가 운동 방향을 바꾸는 순간은 속도 \$v(t)\$가 \$0\$이 되는 지점입니다. 위 예제에서 \$3t^2 - 12t + 9 = 0\$을 풀면 \$3(t^2 - 4t + 3) = 0\$이 되어 \$3(t-1)(t-3) = 0\$이 됩니다. 즉, \$t=1\$과 \$t=3\$일 때 속도가 \$0\$이 되며, 이 시점들을 기준으로 점 \$P\$는 운동 방향을 바꾸게 됩니다. 이처럼 미분을 이용하면 물체의 위치 변화를 매우 정밀하게 분석할 수 있습니다.',
            ],
          ),
        ],
      ),
    ],
  ),
  '중복순열': BookData(
    id: 'concept_중복순열',
    title: '중복순열',
    subtitle: '공통수학1 > 경우의수 > 순열 > 중복순열',
    category: 'common',
    tags: ['공통수학1', '경우의수', '순열', '중복순열'],
    chapters: [
      BookChapter(
        title: '중복순열',
        intro: ['공통수학1 > 경우의수 > 순열 > 중복순열 개념 학습'],
        sections: [
          BookSection(
            title: '중복순열',
            paragraphs: [
              '중복순열이란 서로 다른 \$n\$개에서 중복을 허용하여 \$r\$개를 택해 일렬로 나열하는 것을 말합니다. 일반적인 순열과 달리, 한 번 선택한 대상을 다시 선택할 수 있다는 점이 가장 큰 특징입니다. 예를 들어, 비밀번호를 설정할 때 0부터 9까지의 숫자 10개 중 하나를 골라 4자리를 채우는 경우, 같은 숫자를 여러 번 사용할 수 있으므로 이는 중복순열의 대표적인 사례가 됩니다.',
              '서로 다른 \$n\$개에서 중복을 허용하여 \$r\$개를 택하는 중복순열의 수는 기호로 \$\\Pi\$를 사용하여 \$_n\\Pi_r\$과 같이 나타냅니다. 각 자리에 올 수 있는 경우의 수가 모두 \$n\$가지씩이므로, 이를 \$r\$번 곱하면 전체 경우의 수를 구할 수 있습니다. 따라서 중복순열의 핵심 공식은 다음과 같습니다. \$\$ _n\\Pi_r = n^r \$\$',
              '중복순열의 성질을 이해할 때는 \'각 자리를 채우는 선택지\'를 생각하는 것이 좋습니다. 첫 번째 자리에 올 수 있는 것이 \$n\$가지, 두 번째 자리도 \$n\$가지, 이런 식으로 \$r\$번째 자리까지 모두 \$n\$가지의 선택지가 존재합니다. 곱의 법칙에 따라 이들을 모두 곱하면 \$n \\times n \\times \\dots \\times n\$ (\$r\$번 곱함)이 되어 공식 \$n^r\$이 유도되는 것입니다.',
              '예제 문제: 서로 다른 3개의 우체통에 서로 다른 4통의 편지를 넣는 방법의 수를 구해봅시다. 단, 편지를 하나도 받지 못하는 우체통이 있어도 됩니다. 이 문제는 각 편지마다 들어갈 우체통을 선택하는 과정으로 생각할 수 있습니다.',
              '단계별 풀이: 첫 번째 편지는 3개의 우체통 중 하나를 선택할 수 있고, 두 번째 편지도 3개 중 하나, 세 번째와 네 번째 편지도 각각 3개 중 하나를 선택할 수 있습니다. 즉, 편지 4통이 각각 3개의 선택지를 가지므로 중복순열의 개념을 적용하면 됩니다. \$\$ 3 \\times 3 \\times 3 \\times 3 = 3^4 = 81 \$\$ 따라서 편지를 넣는 방법은 총 81가지입니다.',
              '또 다른 예제로, 0과 1 두 개의 숫자만을 사용하여 만들 수 있는 5자리 자연수의 개수를 구해봅시다. 첫 번째 자리는 0이 올 수 없으므로 1만 올 수 있고(1가지), 나머지 4개의 자리는 0과 1 중 아무거나 올 수 있으므로 각각 2가지씩 선택 가능합니다. 따라서 전체 개수는 다음과 같습니다. \$\$ 1 \\times 2 \\times 2 \\times 2 \\times 2 = 2^4 = 16 \$\$ 이처럼 중복순열은 문제의 조건에 따라 첫 자리에 제약이 있는 경우 등을 고려하여 응용할 수 있습니다.',
            ],
          ),
        ],
      ),
    ],
  ),
  '대응': BookData(
    id: 'concept_대응',
    title: '대응',
    subtitle: '공통수학2 > 함수 > 함수의정의 > 대응',
    category: 'common',
    tags: ['공통수학2', '함수', '함수의정의', '대응'],
    chapters: [
      BookChapter(
        title: '대응',
        intro: ['공통수학2 > 함수 > 함수의정의 > 대응 개념 학습'],
        sections: [
          BookSection(
            title: '대응',
            paragraphs: [
              '두 집합 \$X\$와 \$Y\$가 있을 때, 집합 \$X\$의 각 원소에 집합 \$Y\$의 원소를 짝지어 주는 것을 \'대응\'이라고 합니다. 예를 들어, 우리 반 학생들의 이름이 적힌 집합 \$X\$와 그들의 혈액형이 적힌 집합 \$Y\$가 있다면, 각 학생에게 해당하는 혈액형을 연결하는 것이 바로 대응입니다. 이때 집합 \$X\$를 대응의 시작점인 \'정의역\'과 관련된 집합으로, 집합 \$Y\$를 대응의 도착점인 \'공역\'과 관련된 집합으로 생각할 수 있습니다.',
              '대응은 화살표를 사용하여 시각적으로 나타낼 수 있습니다. 집합 \$X\$의 원소 \$x\$에서 집합 \$Y\$의 원소 \$y\$로 화살표를 그어 \$x\$가 \$y\$에 대응됨을 표현하며, 이를 기호로 \$x \\longmapsto y\$와 같이 나타냅니다. 대응은 단순히 짝을 짓는 모든 관계를 포함하는 넓은 개념으로, 나중에 배우게 될 \'함수\'는 이 대응 중에서 \'집합 \$X\$의 모든 원소가 집합 \$Y\$의 원소에 오직 하나씩만 대응되는 특별한 규칙\'을 가진 것을 말합니다.',
              '대응의 성질을 이해하기 위해 집합 \$X = \\{1, 2, 3\\}\$과 \$Y = \\{a, b, c, d\\}\$를 예로 들어보겠습니다. \$1\$은 \$a\$에, \$2\$는 \$b\$에, \$3\$은 \$c\$에 대응시키는 것과 같이, 집합 \$X\$의 원소들이 집합 \$Y\$의 원소 중 하나를 선택하여 연결되는 모든 경우의 수가 대응의 예시가 됩니다. 대응에서는 \$X\$의 한 원소가 \$Y\$의 여러 원소에 대응될 수도 있고, \$X\$의 어떤 원소는 \$Y\$의 아무 원소와도 대응되지 않을 수도 있다는 점이 특징입니다.',
              '이제 구체적인 예제를 풀어봅시다. 두 집합 \$X = \\{1, 2\\}\$, \$Y = \\{3, 4, 5\\}\$가 있을 때, 집합 \$X\$에서 집합 \$Y\$로의 대응 관계를 하나 정해봅시다. \'집합 \$X\$의 원소 \$x\$에 \$x+2\$를 더한 값을 대응시킨다\'는 규칙을 적용하면 어떻게 될까요? 먼저 \$x=1\$일 때, \$1+2=3\$이므로 \$1\$은 \$3\$에 대응됩니다. 다음으로 \$x=2\$일 때, \$2+2=4\$이므로 \$2\$는 \$4\$에 대응됩니다.',
              '위의 대응을 기호로 정리하면 \$1 \\longmapsto 3\$ 그리고 \$2 \\longmapsto 4\$가 됩니다. 이 과정을 집합의 원소로 표현하면 대응 관계는 \$\\{(1, 3), (2, 4)\\}\$와 같이 순서쌍의 집합으로 나타낼 수 있습니다. 여기서 \$5\$는 집합 \$X\$의 어떤 원소와도 대응되지 않았는데, 대응의 정의에서는 집합 \$Y\$의 모든 원소가 반드시 선택받아야 할 필요는 없으므로 이 또한 올바른 대응의 사례가 됩니다.',
            ],
          ),
        ],
      ),
    ],
