  '우극한': BookData(
    id: 'concept_우극한',
    title: '우극한',
    subtitle: '미적분Ⅰ > 함수의극한 > 극한의정의 > 우극한',
    category: 'common',
    tags: ['미적분Ⅰ', '함수의극한', '극한의정의', '우극한'],
    chapters: [
      BookChapter(
        title: '우극한',
        intro: ['미적분Ⅰ > 함수의극한 > 극한의정의 > 우극한 개념 학습'],
        sections: [
          BookSection(
            title: '우극한',
            paragraphs: [
              '[   "함수의 극한에서 \'우극한\'이란, 변수 \$x\$가 어떤 값 \$a\$보다 큰 쪽에서 \$a\$에 한없이 가까워질 때, 함수 \$f(x)\$의 값이 일정한 값 \$L\$에 가까워지는 상태를 의미합니다. 즉, 수직선 위에서 \$a\$의 오른쪽 방향에서 왼쪽으로 다가가는 경우를 말하며, 이를 기호로는 \$x \\\\to a+\$라고 표현합니다. 이때의 극한값은 다음과 같이 나타냅니다. \$\$ \\\\lim_{x \\\\to a+} f(x) = L \$\$",   "우극한을 이해할 때 가장 중요한 점은 \$x\$가 \$a\$보다 큰 값을 가지면서 \$a\$로 접근한다는 것입니다. 만약 함수가 \$x=a\$에서 끊어져 있거나, \$x=a\$에서의 함숫값과 상관없이 오른쪽에서 다가오는 그래프의 높이만 관찰하면 됩니다. 만약 \$x\$가 \$a\$에 가까워질 때 함수 \$f(x)\$의 값이 무한히 커지거나 작아지지 않고 특정한 실수 \$L\$에 수렴한다면, 우리는 그 \$L\$을 우극한값이라고 정의합니다.",   "우극한의 성질은 일반적인 극한의 성질과 동일합니다. 두 함수 \$f(x)\$와 \$g(x)\$에 대하여 우극한이 각각 존재할 때, 상수배, 덧셈, 뺄셈, 곱셈, 나눗셈(단, 분모의 우극한이 0이 아닐 때)에 대하여 각각의 우극한을 따로 계산하여 연산할 수 있습니다. 예를 들어, 두 함수의 합의 우극한은 각 함수의 우극한의 합과 같습니다. \$\$ \\\\lim_{x \\\\to a+} \\{f(x) + g(x)\\} = \\\\lim_{x\\\\to a+} f(x) + \\\\lim_{x\\\\to a+} g(x) \$\$",   "이제 구체적인 예제를 살펴보겠습니다. 함수 \$f(x) = \\\\begin{cases} x+2 & (x \\\\ge 1) \\\\\\\\ 3x & (x < 1) \\\\end{cases}\$일 때, \$x \\\\to 1+\$에서의 우극한을 구해보세요. 우극한은 \$x\$가 1보다 큰 쪽에서 1로 다가가는 것이므로, \$x > 1\$일 때의 식인 \$f(x) = x+2\$를 사용해야 합니다. 단계별 풀이는 다음과 같습니다. 첫째, \$x > 1\$인 구간의 함수식을 확인합니다. 둘째, 해당 식에 \$x=1\$을 대입하여 극한값을 계산합니다. \$\$ \\\\lim_{x \\\\to 1+} f(x) = \\\\lim_{x \\\\to 1+} (x+2) = 1+2 = 3 \$\$",   "또 다른 예제로, 분수 함수 \$f(x) = \\\\frac{|x-2|}{x-2}\$의 \$x \\\\to 2+\$에서의 우극한을 구해봅시다. 이 함수는 \$x\$가 2보다 클 때와 작을 때의 형태가 다릅니다. \$x > 2\$이면 \$x-2 > 0\$이므로 \$|x-2| = x-2\$가 됩니다. 따라서 식은 \$f(x) = \\\\frac{x-2}{x-2} = 1\$이 됩니다. 이를 극한식으로 나타내면 다음과 같습니다. \$\$ \\\\lim_{x \\\\to 2+} \\\\frac{|x-2|}{x-2} = \\\\lim_{x \\\\to 2+} 1 = 1 \$\$ 이처럼 우극한은 그래프의 오른쪽에서 다가오는 경로를 따라 함수가 향하는 목적지를 찾는 과정임을 기억하면 쉽게 해결할 수 있습니다." ]',
            ],
          ),
        ],
      ),
    ],
  ),
  '켤레복소수': BookData(
    id: 'concept_켤레복소수',
    title: '켤레복소수',
    subtitle: '공통수학1 > 복소수 > 켤레복소수',
    category: 'common',
    tags: ['공통수학1', '복소수', '켤레복소수'],
    chapters: [
      BookChapter(
        title: '켤레복소수',
        intro: ['공통수학1 > 복소수 > 켤레복소수 개념 학습'],
        sections: [
          BookSection(
            title: '켤레복소수',
            paragraphs: [
              '복소수 \$z = a + bi\$ (단, \$a, b\$는 실수)에 대하여, 허수부분의 부호를 바꾼 \$a - bi\$를 \$z\$의 켤레복소수라고 하며, 기호로는 \$\\bar{z}\$와 같이 나타냅니다. 예를 들어, 복소수 \$3 + 2i\$의 켤레복소수는 \$3 - 2i\$이고, \$-1 - 5i\$의 켤레복소수는 \$-1 + 5i\$입니다. 실수 부분은 그대로 두고 허수 부분의 부호만 반대로 바꾼다는 점을 기억하세요.',
              '켤레복소수는 사칙연산과 관련하여 매우 유용한 성질들을 가지고 있습니다. 두 복소수 \$z_1, z_2\$에 대하여 \$\\overline{z_1 + z_2} = \\bar{z_1} + \\bar{z_2}\$, \$\\overline{z_1 - z_2} = \\bar{z_1} - \\bar{z_2}\$, \$\\overline{z_1 z_2} = \\bar{z_1} \\cdot \\bar{z_2}\$, \$\\overline{\\left(\\frac{z_1}{z_2}\\right)} = \\frac{\\bar{z_1}}{\\bar{z_2}}\$ (\$z_2 \\neq 0\$)가 성립합니다. 또한, 어떤 복소수와 그 켤레복소수를 더하거나 곱하면 항상 실수가 된다는 중요한 특징이 있습니다. 즉, \$z + \\bar{z} = 2a\$이고 \$z \\cdot \\bar{z} = a^2 + b^2\$입니다.',
              '이제 구체적인 예제를 통해 켤레복소수를 활용하는 방법을 알아봅시다. 문제: 복소수 \$z = 2 + i\$일 때, \$z \\cdot \\bar{z}\$의 값을 구하시오. 먼저 \$z = 2 + i\$이므로, 그 켤레복소수 \$\\bar{z}\$는 허수 부분의 부호를 바꾼 \$2 - i\$가 됩니다. 이제 두 수를 곱하는 과정을 단계별로 수행합니다.',
              '단계별 풀이는 다음과 같습니다. 먼저 곱셈 식을 세우면 \$z \\cdot \\bar{z} = (2 + i)(2 - i)\$입니다. 이를 전개하면 \$(2)^2 - (i)^2\$이 되는데, 복소수의 정의에 따라 \$i^2 = -1\$임을 이용합니다. 따라서 \$4 - (-1) = 4 + 1 = 5\$가 됩니다. 이처럼 복소수와 그 켤레복소수를 곱하면 항상 허수 단위 \$i\$가 사라지고 실수가 된다는 점을 확인할 수 있습니다.',
            ],
          ),
        ],
      ),
    ],
  ),
  '중심': BookData(
    id: 'concept_중심',
    title: '중심',
    subtitle: '공통수학2 > 원의방정식 > 원의표준형 > 중심',
    category: 'common',
    tags: ['공통수학2', '원의방정식', '원의표준형', '중심'],
    chapters: [
      BookChapter(
        title: '중심',
        intro: ['공통수학2 > 원의방정식 > 원의표준형 > 중심 개념 학습'],
        sections: [
          BookSection(
            title: '중심',
            paragraphs: [
              '원의 중심이란 원을 구성하는 모든 점으로부터 같은 거리에 있는 평면 위의 고정된 점을 의미합니다. 원의 방정식에서 중심은 원의 위치를 결정하는 가장 중요한 요소이며, 좌표평면 위에서 원의 중심을 \$(a, b)\$라고 할 때, 중심으로부터의 거리가 반지름 \$r\$인 원의 방정식은 다음과 같은 표준형으로 나타낼 수 있습니다. \$\$ (x - a)^2 + (y - b)^2 = r^2 \$\$ 이 식에서 \$x\$와 \$y\$의 값에 각각 \$a\$와 \$b\$를 대입하면 좌변이 \$0\$이 되어 반지름의 제곱인 \$r^2\$과 같아지므로, 점 \$(a, b)\$가 원의 중심임을 쉽게 확인할 수 있습니다.',
              '원의 방정식이 일반형인 \$x^2 + y^2 + Ax + By + C = 0\$의 형태로 주어질 때는, 완전제곱식을 이용하여 표준형으로 변형해야 중심을 찾을 수 있습니다. \$x\$항끼리, \$y\$항끼리 묶어 정리하면 \$x^2 + Ax + (rac{A}{2})^2\$와 \$y^2 + By + (rac{B}{2})^2\$의 꼴을 만들 수 있으며, 이를 통해 중심의 좌표 \$(a, b)\$는 다음과 같이 구할 수 있습니다. \$\$ a = -rac{A}{2}, \\; b = -rac{B}{2} \$\$ 즉, 일반형에서 중심의 좌표는 \$x\$와 \$y\$의 일차항 계수를 각각 \$-2\$로 나눈 값과 같습니다.',
              '이제 구체적인 예제를 통해 중심을 찾아봅시다. 방정식 \$(x - 3)^2 + (y + 2)^2 = 16\$이 나타내는 원의 중심을 구해 보겠습니다. 이 식은 이미 표준형으로 잘 정리되어 있습니다. 표준형의 기본 형태인 \$(x - a)^2 + (y - b)^2 = r^2\$과 비교해 보면, \$a = 3\$이고 \$b = -2\$임을 알 수 있습니다. 따라서 이 원의 중심은 \$(3, -2)\$가 됩니다.',
              '다음으로 일반형 방정식 \$x^2 + y^2 - 4x + 6y - 3 = 0\$의 중심을 구하는 과정을 살펴보겠습니다. 먼저 \$x\$항과 \$y\$항을 모아 완전제곱식으로 만듭니다. \$(x^2 - 4x) + (y^2 + 6y) = 3\$에서, 각 괄호 안에 필요한 상수를 더해줍니다. \$x^2 - 4x + 4\$와 \$y^2 + 6y + 9\$를 만들기 위해 양변에 \$4\$와 \$9\$를 더하면 다음과 같습니다. \$\$ (x^2 - 4x + 4) + (y^2 + 6y + 9) = 3 + 4 + 9 \$\$ 이를 정리하면 \$(x - 2)^2 + (y + 3)^2 = 16\$이 됩니다. 따라서 이 원의 중심은 \$(2, -3)\$임을 알 수 있습니다.',
            ],
          ),
        ],
      ),
    ],
  ),
  '로그함수의그래프': BookData(
    id: 'concept_로그함수의그래프',
    title: '로그함수의그래프',
    subtitle: '대수 > 로그함수 > 로그함수의그래프',
    category: 'common',
    tags: ['대수', '로그함수', '로그함수의그래프'],
    chapters: [
      BookChapter(
        title: '로그함수의그래프',
        intro: ['대수 > 로그함수 > 로그함수의그래프 개념 학습'],
        sections: [
          BookSection(
            title: '로그함수의그래프',
            paragraphs: [
              '로그함수 \$y = \\log_a x\$ (단, \$a > 0, a \\neq 1\$)는 지수함수 \$y = a^x\$의 역함수입니다. 이 함수의 그래프를 그리기 위해서는 먼저 정의역과 치역을 이해해야 합니다. 로그의 정의에 의해 진수 조건인 \$x > 0\$이 항상 성립해야 하므로, 로그함수의 정의역은 양의 실수 전체의 집합이며, 치역은 실수 전체의 집합입니다. 그래프는 항상 점 \$(1, 0)\$을 지나며, \$y\$축을 점근선으로 가집니다.',
              '로그함수의 그래프 모양은 밑 \$a\$의 값에 따라 결정됩니다. \$a > 1\$일 때, \$x\$값이 증가하면 \$y\$값도 증가하는 증가함수의 형태를 띠며 그래프는 오른쪽 위로 향합니다. 반면, \$0 < a < 1\$일 때, \$x\$값이 증가하면 \$y\$값은 감소하는 감소함수의 형태를 띠며 그래프는 오른쪽 아래로 향합니다. 또한, \$y = \\log_a x\$와 \$y = \\log_{1/a} x\$의 그래프는 \$x\$축에 대하여 서로 대칭인 관계에 있습니다.',
              '로그함수의 그래프를 평행이동하거나 대칭이동하여 더욱 다양한 형태를 만들 수 있습니다. 예를 들어, \$y = \\log_a(x - p) + q\$의 그래프는 \$y = \\log_a x\$의 그래프를 \$x\$축의 방향으로 \$p\$만큼, \$y\$축의 방향으로 \$q\$만큼 평행이동한 것입니다. 이때 점근선은 원래 \$x=0\$이었으나 평행이동에 의해 \$x=p\$로 변하게 됩니다. 이러한 성질을 이용하면 복잡한 로그함수의 그래프도 쉽게 그릴 수 있습니다.',
              '예제: 함수 \$y = \\log_2(x - 1) + 3\$의 그래프의 점근선을 구하고, \$x=5\$일 때의 함숫값을 구하시오. 첫 번째 단계로 점근선을 찾습니다. 로그함수 \$y = \\log_a(x - p) + q\$에서 진수 조건인 \$x - p > 0\$을 만족해야 하므로, \$x - 1 > 0\$에서 \$x > 1\$입니다. 따라서 그래프의 점근선은 \$\$x = 1\$\$이 됩니다.',
              '두 번째 단계로 \$x=5\$일 때의 함숫값을 계산합니다. 주어진 식에 \$x=5\$를 대입하면 \$\$y = \\log_2(5 - 1) + 3\$\$이 됩니다. 이를 정리하면 \$\$y = \\log_2 4 + 3\$\$이 되며, \$\\log_2 4 = 2\$이므로 \$\$y = 2 + 3 = 5\$\$입니다. 따라서 \$x=5\$일 때의 함숫값은 \$5\$입니다.',
            ],
          ),
        ],
      ),
    ],
  ),
  '가속도': BookData(
    id: 'concept_가속도',
    title: '가속도',
    subtitle: '미적분Ⅰ > 속도와가속도 > 가속도',
    category: 'common',
    tags: ['미적분Ⅰ', '속도와가속도', '가속도'],
    chapters: [
      BookChapter(
        title: '가속도',
        intro: ['미적분Ⅰ > 속도와가속도 > 가속도 개념 학습'],
        sections: [
          BookSection(
            title: '가속도',
            paragraphs: [
              '가속도란 물체의 속도가 시간에 따라 얼마나 빠르게 변하는지를 나타내는 물리량입니다. 수직선 위를 움직이는 점 \$P\$의 시각 \$t\$에서의 위치를 \$x(t)\$라고 할 때, 속도 \$v(t)\$는 위치를 시간에 대해 미분하여 \$v(t) = \\frac{dx}{dt} = x\'(t)\$로 정의합니다. 이때 가속도 \$a(t)\$는 속도를 다시 시간에 대해 한 번 더 미분한 값으로, 다음과 같이 정의됩니다. \$\$a(t) = \\frac{dv}{dt} = v\'(t) = x\'\'(t)\$\$',
              '가속도의 부호는 속도의 변화 방향을 결정합니다. 가속도가 양수(\$a(t) > 0\$)이면 속도가 증가하는 방향으로 힘이 작용하고 있음을 의미하며, 가속도가 음수(\$a(t) < 0\$)이면 속도가 감소하는 방향으로 힘이 작용함을 뜻합니다. 특히 가속도가 \$0\$인 순간은 물체의 속도가 일시적으로 변하지 않는 상태를 나타냅니다. 속도와 가속도의 부호가 같으면 물체의 속력은 점점 빨라지고, 두 값의 부호가 다르면 물체의 속력은 점점 느려지게 됩니다.',
              '예를 들어, 수직선 위를 움직이는 점 \$P\$의 시각 \$t\$에서의 위치가 \$x(t) = t^3 - 6t^2 + 9t\$로 주어졌다고 가정해 봅시다. 이때 시각 \$t=3\$에서의 가속도를 구하는 과정을 단계별로 살펴보겠습니다. 먼저 속도 \$v(t)\$를 구하기 위해 위치 함수 \$x(t)\$를 \$t\$에 대하여 미분합니다. \$\$v(t) = \\frac{dx}{dt} = 3t^2 - 12t + 9\$\$',
              '다음으로, 구한 속도 함수 \$v(t)\$를 한 번 더 \$t\$에 대하여 미분하여 가속도 함수 \$a(t)\$를 구합니다. \$\$a(t) = \\frac{dv}{dt} = 6t - 12\$\$ 이제 문제에서 요구한 시각 \$t=3\$을 가속도 함수에 대입합니다. \$\$a(3) = 6(3) - 12 = 18 - 12 = 6\$\$ 따라서 시각 \$t=3\$에서의 점 \$P\$의 가속도는 \$6\$입니다.',
            ],
          ),
        ],
      ),
    ],
  ),
  '합성함수의정의': BookData(
    id: 'concept_합성함수의정의',
    title: '합성함수의정의',
    subtitle: '공통수학2 > 함수 > 합성함수 > 합성함수의정의',
    category: 'common',
    tags: ['공통수학2', '함수', '합성함수', '합성함수의정의'],
    chapters: [
      BookChapter(
        title: '합성함수의정의',
        intro: ['공통수학2 > 함수 > 합성함수 > 합성함수의정의 개념 학습'],
        sections: [
          BookSection(
            title: '합성함수의정의',
            paragraphs: [
              '합성함수란 두 함수를 이어 붙여 하나의 새로운 함수를 만드는 과정을 의미합니다. 두 집합 \$X, Y, Z\$에 대하여 함수 \$f: X \\to Y\$와 함수 \$g: Y \\to Z\$가 있을 때, 집합 \$X\$의 임의의 원소 \$x\$를 \$f\$에 의해 \$f(x)\$로 보내고, 다시 그 결과값인 \$f(x)\$를 \$g\$에 의해 \$g(f(x))\$로 보내는 대응을 생각할 수 있습니다. 이때 집합 \$X\$의 각 원소 \$x\$를 \$g(f(x))\$에 대응시키는 새로운 함수를 \$f\$와 \$g\$의 합성함수라고 하며, 기호로는 \$g \\circ f\$와 같이 나타냅니다.',
              '합성함수 \$(g \\circ f)(x)\$의 정의를 수식으로 표현하면 \$\$(g \\circ f)(x) = g(f(x))\$\$가 됩니다. 여기서 중요한 점은 합성함수가 정의되기 위해서는 첫 번째 함수 \$f\$의 공역이 두 번째 함수 \$g\$의 정의역의 부분집합이어야 한다는 것입니다. 또한, 합성함수는 일반적으로 교환법칙이 성립하지 않습니다. 즉, \$f \\circ g\$와 \$g \\circ f\$는 서로 다른 함수인 경우가 많으므로 순서에 주의하여 계산해야 합니다.',
              '합성함수의 성질 중 가장 대표적인 것은 결합법칙입니다. 세 함수 \$f, g, h\$에 대하여 \$(h \\circ g) \\circ f = h \\circ (g \\circ f)\$가 성립합니다. 이는 함수를 합성하는 순서가 같기만 하다면, 어느 쪽을 먼저 합성하더라도 결과가 같음을 의미합니다. 이러한 성질 덕분에 우리는 세 개 이상의 함수를 합성할 때 괄호를 생략하고 \$h \\circ g \\circ f\$와 같이 간단히 표기할 수 있습니다.',
              '이제 구체적인 예제를 통해 합성함수를 계산해 봅시다. 두 함수 \$f(x) = 2x + 1\$과 \$g(x) = x^2\$이 주어졌을 때, \$(g \\circ f)(2)\$의 값을 구하는 과정을 살펴봅시다. 먼저 합성함수의 정의에 따라 \$(g \\circ f)(2) = g(f(2))\$로 식을 변형합니다. 단계별로 계산하면, 먼저 \$f(2)\$의 값을 구합니다. \$f(2) = 2(2) + 1 = 5\$입니다. 이제 이 결과값을 \$g\$에 대입하면 \$g(5) = 5^2 = 25\$가 됩니다. 따라서 \$(g \\circ f)(2) = 25\$입니다.',
              '이번에는 함수식 자체를 합성하는 연습을 해보겠습니다. \$f(x) = x - 3\$이고 \$g(x) = 3x + 2\$일 때, \$(f \\circ g)(x)\$를 구해보겠습니다. 정의에 의해 \$(f \\circ g)(x) = f(g(x))\$입니다. 여기서 \$g(x)\$ 자리에 \$3x + 2\$를 대입하면 \$f(3x + 2)\$가 됩니다. 이제 \$f\$의 정의에 따라 \$x\$ 대신 \$(3x + 2)\$를 넣으면 \$f(3x + 2) = (3x + 2) - 3\$이 됩니다. 이를 정리하면 최종적으로 \$\$(f \\circ g)(x) = 3x - 1\$\$이라는 결과를 얻을 수 있습니다.',
            ],
          ),
        ],
      ),
    ],
  ),
  '원순열': BookData(
    id: 'concept_원순열',
    title: '원순열',
    subtitle: '공통수학1 > 경우의수 > 순열 > 원순열',
    category: 'common',
    tags: ['공통수학1', '경우의수', '순열', '원순열'],
    chapters: [
      BookChapter(
        title: '원순열',
        intro: ['공통수학1 > 경우의수 > 순열 > 원순열 개념 학습'],
        sections: [
          BookSection(
            title: '원순열',
            paragraphs: [
              '원순열이란 서로 다른 \$n\$개를 원형으로 배열하는 경우의 수를 의미합니다. 일반적인 순열은 일렬로 나열하기 때문에 시작과 끝이 분명하지만, 원형으로 배열할 때는 회전하여 일치하는 경우를 모두 같은 것으로 간주합니다. 예를 들어, 4명을 원탁에 앉힐 때 일렬로 나열하면 \$4!\$가지이지만, 원탁에서는 회전했을 때 겹치는 4가지 경우를 하나로 보아야 합니다.',
              '따라서 원순열의 핵심은 \'회전의 중복을 제거하는 것\'입니다. \$n\$개를 원형으로 배열하는 경우의 수는 일렬로 나열하는 수인 \$n!\$을 회전했을 때 같은 모양이 되는 개수인 \$n\$으로 나누어 계산합니다. 이를 공식으로 나타내면 다음과 같습니다. \$\$ \\frac{n!}{n} = (n-1)! \$\$ 이 공식은 한 명을 고정하고 나머지 \$(n-1)\$명을 일렬로 나열하는 것과 같은 원리로 이해할 수 있습니다.',
              '원순열의 성질을 확장하면, \$n\$개의 자리가 모두 구별되지 않을 때 특정 대상을 고정하는 방식이 매우 유용합니다. 만약 \$n\$개의 자리가 번호가 매겨져 있거나 위치가 구별된다면 일반 순열을 사용해야 하지만, 단순히 원탁에 둘러앉는 상황이라면 위 공식을 적용합니다. 또한, 원순열은 다각형의 탁자에 앉거나 목걸이를 만드는 등 대칭성을 고려해야 하는 문제로 응용될 수 있습니다.',
              '예제: 5명의 학생이 원형 탁자에 둘러앉는 경우의 수를 구하시오. 단계별 풀이: 첫째, 원순열 공식 \$(n-1)!\$을 떠올립니다. 둘째, \$n=5\$를 공식에 대입합니다. 셋째, 계산을 수행합니다. \$\$ (5-1)! = 4! = 4 \\times 3 \\times 2 \\times 1 = 24 \$\$ 따라서 5명의 학생이 원형 탁자에 앉는 경우의 수는 24가지입니다.',
              '심화 예제: 남학생 3명과 여학생 2명이 원형 탁자에 앉을 때, 여학생 2명이 서로 이웃하게 앉는 경우의 수를 구하시오. 단계별 풀이: 첫째, 이웃하는 여학생 2명을 한 묶음으로 생각합니다. 둘째, 전체 4개의 묶음(남학생 3명 + 여학생 묶음 1개)을 원형으로 배열하는 경우의 수는 \$(4-1)! = 3! = 6\$입니다. 셋째, 묶음 안에서 여학생 2명이 자리를 바꾸는 경우의 수 \$2! = 2\$를 곱합니다. \$\$ 3! \\times 2! = 6 \\times 2 = 12 \$\$ 따라서 구하는 경우의 수는 12가지입니다.',
            ],
          ),
        ],
      ),
    ],
  ),
  '극한의사칙연산': BookData(
    id: 'concept_극한의사칙연산',
    title: '극한의사칙연산',
    subtitle: '미적분Ⅰ > 함수의극한 > 극한의성질 > 극한의사칙연산',
    category: 'common',
    tags: ['미적분Ⅰ', '함수의극한', '극한의성질', '극한의사칙연산'],
    chapters: [
      BookChapter(
        title: '극한의사칙연산',
        intro: ['미적분Ⅰ > 함수의극한 > 극한의성질 > 극한의사칙연산 개념 학습'],
        sections: [
          BookSection(
            title: '극한의사칙연산',
            paragraphs: [
              '함수의 극한에서 가장 기본이 되는 성질은 두 함수의 극한값이 존재할 때, 사칙연산에 대하여 극한 기호를 자유롭게 분배할 수 있다는 점입니다. 두 함수 \$f(x)\$와 \$g(x)\$에 대하여 \$x\$가 \$a\$로 한없이 가까워질 때, \$\\lim_{x \\to a} f(x) = \\alpha\$, \$\\lim_{x \\to a} g(x) = \\beta\$ (단, \$\\alpha, \\beta\$는 실수)라고 가정합시다. 이때 두 함수의 합, 차, 곱, 그리고 나눗셈에 대한 극한은 각각의 극한값을 먼저 구한 뒤 사칙연산을 수행한 결과와 같습니다.',
              '이를 수학적 공식으로 나타내면 다음과 같습니다. 먼저 덧셈과 뺄셈은 \$\\lim_{x \\to a} \\{f(x) \\pm g(x)\\} = \\lim_{x \\to a} f(x) \\pm \\lim_{x \\to a} g(x) = \\alpha \\pm \\beta\$가 성립합니다. 곱셈의 경우 \$\\lim_{x \\to a} \\{f(x)g(x)\\} = \\lim_{x \\to a} f(x) \\cdot \\lim_{x \\to a} g(x) = \\alpha \\cdot \\beta\$이며, 상수 \$c\$가 곱해진 경우 \$\\lim_{x \\to a} \\{c f(x)\\} = c \\cdot \\lim_{x \\to a} f(x) = c\\alpha\$가 됩니다.',
              '나눗셈의 경우에는 분모가 0이 되지 않아야 한다는 중요한 조건이 붙습니다. 즉, \$\\lim_{x \\to a} \\frac{f(x)}{g(x)} = \\frac{\\lim_{x \\to a} f(x)}{\\lim_{x \\to a} g(x)} = \\frac{\\alpha}{\\beta}\$가 성립하며, 이때 반드시 \$\\beta \\neq 0\$이어야 합니다. 이 성질들은 극한값이 존재하는 경우에만 적용할 수 있으므로, 문제를 풀 때 각 함수의 극한값이 실제로 존재하는지 먼저 확인하는 습관을 들이는 것이 중요합니다.',
              '이제 예제를 통해 직접 적용해 봅시다. \$\\lim_{x \\to 2} f(x) = 3\$이고 \$\\lim_{x \\to 2} g(x) = 4\$일 때, \$\\lim_{x \\to 2} \\{2f(x) + g(x)\\}\$의 값을 구하는 문제입니다. 이 문제는 극한의 성질을 이용하여 각 항으로 분리할 수 있습니다. 단계별로 풀이하면, 먼저 \$\\lim_{x \\to 2} \\{2f(x) + g(x)\\} = 2\\lim_{x \\to 2} f(x) + \\lim_{x \\to 2} g(x)\$로 식을 나눕니다.',
              '이제 주어진 극한값을 대입합니다. \$2 \\times 3 + 4\$를 계산하면 \$6 + 4 = 10\$이 됩니다. 따라서 구하고자 하는 극한값은 \$10\$입니다. 이처럼 극한의 사칙연산 성질을 이용하면 복잡한 함수의 극한도 각각의 단순한 극한값들의 조합으로 바꾸어 쉽게 해결할 수 있습니다.',
            ],
          ),
        ],
      ),
    ],
  ),
  '반지름': BookData(
    id: 'concept_반지름',
    title: '반지름',
    subtitle: '공통수학2 > 원의방정식 > 원의표준형 > 반지름',
    category: 'common',
    tags: ['공통수학2', '원의방정식', '원의표준형', '반지름'],
    chapters: [
      BookChapter(
        title: '반지름',
        intro: ['공통수학2 > 원의방정식 > 원의표준형 > 반지름 개념 학습'],
        sections: [
          BookSection(
            title: '반지름',
            paragraphs: [
              '[   "원의 정의는 평면 위의 한 점으로부터 일정한 거리에 있는 점들의 집합입니다. 이때 \'일정한 거리\'를 우리는 \'반지름(radius)\'이라고 부르며, 보통 알파벳 \$r\$로 나타냅니다. 원의 중심을 \$(a, b)\$라고 할 때, 원 위의 임의의 점을 \$(x, y)\$라고 하면 두 점 사이의 거리 공식에 의해 원의 방정식은 \$\$(x - a)^2 + (y - b)^2 = r^2\$\$과 같이 표현됩니다. 여기서 우변의 \$r^2\$은 반지름의 제곱을 의미하며, 반지름 \$r\$은 항상 양수(\$r > 0\$)여야 한다는 점이 매우 중요합니다.",   "반지름은 원의 크기를 결정하는 핵심 요소입니다. 원의 방정식이 표준형인 \$(x - a)^2 + (y - b)^2 = r^2\$ 꼴로 주어졌을 때, 우변의 값을 확인하여 제곱근을 취하면 반지름을 바로 구할 수 있습니다. 만약 방정식이 일반형인 \$x^2 + y^2 + Ax + By + C = 0\$으로 주어진다면, 완전제곱식으로 변형하여 \$\$(x + \\frac{A}{2})^2 + (y + \\frac{B}{2})^2 = \\frac{A^2 + B^2 - 4C}{4}\$\$의 형태로 만든 뒤, 우변의 값에 루트를 씌워 반지름을 찾아낼 수 있습니다.",   "예제 1: 원의 방정식 \$(x - 3)^2 + (y + 2)^2 = 16\$이 주어졌을 때, 이 원의 반지름을 구해보겠습니다. 먼저 주어진 식을 표준형인 \$(x - a)^2 + (y - b)^2 = r^2\$과 비교합니다. 식에서 \$r^2 = 16\$임을 알 수 있습니다. 반지름 \$r\$은 길이를 나타내므로 항상 양수여야 합니다. 따라서 \$r = \\sqrt{16} = 4\$가 됩니다. 즉, 이 원의 반지름은 4입니다.",   "예제 2: 방정식 \$x^2 + y^2 - 4x + 6y - 3 = 0\$이 나타내는 원의 반지름을 구하는 과정을 살펴봅시다. 먼저 \$x\$항과 \$y\$항을 각각 묶어 완전제곱식으로 만듭니다. \$(x^2 - 4x + 4) + (y^2 + 6y + 9) = 3 + 4 + 9\$가 되어, 정리하면 \$\$(x - 2)^2 + (y + 3)^2 = 16\$\$이 됩니다. 이 식에서 \$r^2 = 16\$이므로, 반지름 \$r\$은 \$\\sqrt{16} = 4\$임을 알 수 있습니다.",   "이처럼 반지름은 원의 중심에서 원 위의 임의의 점까지 이르는 거리를 의미하며, 원의 방정식에서 가장 중요한 정보 중 하나입니다. 문제를 풀 때 항상 우변이 반지름의 \'제곱\' 값이라는 사실을 기억하세요. 반지름이 주어지면 원의 둘레(\$2\\pi r\$)나 넓이(\$\\pi r^2\$)도 쉽게 구할 수 있으므로, 방정식에서 \$r\$의 값을 정확히 추출하는 연습을 충분히 해두는 것이 좋습니다." ]',
            ],
