  '인수분해법': BookData(
    id: 'concept_인수분해법',
    title: '인수분해법',
    subtitle: '공통수학1 > 이차방정식 > 이차방정식의풀이 > 인수분해법',
    category: 'common',
    tags: ['공통수학1', '이차방정식', '이차방정식의풀이', '인수분해법'],
    chapters: [
      BookChapter(
        title: '인수분해법',
        intro: ['공통수학1 > 이차방정식 > 이차방정식의풀이 > 인수분해법 개념 학습'],
        sections: [
          BookSection(
            title: '인수분해법',
            paragraphs: [
              '이차방정식의 인수분해법은 이차방정식 \$ax^2 + bx + c = 0\$ (\$a \\neq 0\$)의 좌변을 두 일차식의 곱으로 나타내어 해를 구하는 방법입니다. 이는 \'두 수의 곱이 0이면, 적어도 하나는 0이다\'라는 성질인 \$AB = 0 \\iff A = 0\$ 또는 \$B = 0\$을 이용합니다. 즉, 이차식을 \$(px + q)(rx + s) = 0\$의 꼴로 변형하면, \$px + q = 0\$ 또는 \$rx + s = 0\$을 만족하는 \$x\$ 값을 각각 찾아내어 방정식의 해를 구할 수 있습니다.',
              '인수분해를 하기 위해서는 먼저 식의 형태를 관찰해야 합니다. 가장 먼저 공통인수를 묶어내고, 이후에는 곱셈 공식의 역과정을 적용합니다. 특히 \$x^2 + (a+b)x + ab = (x+a)(x+b)\$와 같은 형태나, 완전제곱식 \$x^2 + 2ax + a^2 = (x+a)^2\$을 활용하는 것이 핵심입니다. 만약 \$x^2\$의 계수가 1이 아니라면, 대각선 곱셈법을 사용하여 계수를 맞추는 연습이 필요합니다.',
              '예를 들어, 이차방정식 \$x^2 - 5x + 6 = 0\$을 풀어봅시다. 먼저 좌변의 이차식 \$x^2 - 5x + 6\$을 인수분해해야 합니다. 곱해서 \$6\$이 되고 더해서 \$-5\$가 되는 두 정수를 찾으면 \$-2\$와 \$-3\$입니다. 따라서 식은 \$(x - 2)(x - 3) = 0\$으로 인수분해됩니다. 이제 두 일차식의 곱이 0이 되는 조건을 적용합니다.',
              '위 식에서 \$(x - 2)(x - 3) = 0\$이 성립하려면 \$x - 2 = 0\$ 또는 \$x - 3 = 0\$이어야 합니다. 따라서 \$x = 2\$ 또는 \$x = 3\$이 이 이차방정식의 해가 됩니다. 이처럼 인수분해법은 이차방정식을 가장 빠르고 효율적으로 해결할 수 있는 방법 중 하나이므로, 다양한 다항식의 인수분해 형태를 익혀두는 것이 매우 중요합니다.',
              '조금 더 복잡한 예제로 \$2x^2 + 7x + 3 = 0\$을 살펴봅시다. 이 식은 \$x^2\$의 계수가 \$2\$이므로 대각선 곱셈법을 사용합니다. 곱해서 \$2\$가 되는 수 \$1, 2\$와 곱해서 \$3\$이 되는 수 \$1, 3\$을 배열하여 합이 \$7\$이 되도록 조합합니다. \$(1 \\times 1) + (2 \\times 3) = 7\$이 되므로, 식은 \$(x + 3)(2x + 1) = 0\$으로 인수분해됩니다.',
              '마지막으로 인수분해된 식 \$(x + 3)(2x + 1) = 0\$에서 각 인수가 0이 되는 값을 찾습니다. \$x + 3 = 0\$에서 \$x = -3\$을 얻고, \$2x + 1 = 0\$에서 \$2x = -1\$, 즉 \$x = -\\frac{1}{2}\$을 얻습니다. 따라서 주어진 이차방정식의 최종 해는 \$x = -3\$ 또는 \$x = -\\frac{1}{2}\$입니다.',
            ],
          ),
        ],
      ),
    ],
  ),
  '로그함수의성질': BookData(
    id: 'concept_로그함수의성질',
    title: '로그함수의성질',
    subtitle: '대수 > 로그함수 > 로그함수의성질',
    category: 'common',
    tags: ['대수', '로그함수', '로그함수의성질'],
    chapters: [
      BookChapter(
        title: '로그함수의성질',
        intro: ['대수 > 로그함수 > 로그함수의성질 개념 학습'],
        sections: [
          BookSection(
            title: '로그함수의성질',
            paragraphs: [
              '로그함수 \$y = \\log_a x\$ (단, \$a > 0, a \\neq 1\$)는 지수함수 \$y = a^x\$의 역함수입니다. 로그함수의 정의역은 양의 실수 전체의 집합이고, 치역은 실수 전체의 집합입니다. 그래프는 항상 점 \$(1, 0)\$을 지나며, 밑 \$a\$의 값에 따라 \$a > 1\$이면 \$x\$가 증가할 때 \$y\$도 증가하는 증가함수이고, \$0 < a < 1\$이면 \$x\$가 증가할 때 \$y\$는 감소하는 감소함수가 됩니다.',
              '로그의 성질을 이용하면 복잡한 식을 간단히 계산할 수 있습니다. 로그의 정의에 의해 \$a^{\\log_a x} = x\$가 성립하며, 로그의 연산 법칙인 \$\\log_a (MN) = \\log_a M + \\log_a N\$, \$\\log_a (M/N) = \\log_a M - \\log_a N\$, 그리고 \$\\log_a M^k = k \\log_a M\$은 로그함수의 성질을 이해하는 핵심 도구입니다. 또한, 밑 변환 공식인 \$\\log_a b = \\frac{\\log_c b}{\\log_c a}\$를 활용하면 서로 다른 밑을 가진 로그함수들을 비교하거나 계산할 수 있습니다.',
              '로그함수의 성질을 활용한 첫 번째 예제로, 식 \$\\log_2 12 - \\log_2 3\$을 간단히 해봅시다. 로그의 뺄셈 성질인 \$\\log_a M - \\log_a N = \\log_a (M/N)\$을 적용하면, \$\\log_2 12 - \\log_2 3 = \\log_2 \\left( \\frac{12}{3} \\right)\$이 됩니다. 이를 계산하면 \$\\log_2 4\$가 되며, \$4 = 2^2\$이므로 최종 결과는 \$2 \\log_2 2 = 2 \\times 1 = 2\$가 됩니다.',
              '두 번째 예제로, 로그함수의 성질을 이용해 방정식 \$\\log_3 x + \\log_3 (x-2) = 1\$을 풀어보겠습니다. 먼저 로그의 정의에 의해 진수 조건인 \$x > 0\$이고 \$x-2 > 0\$이어야 하므로 \$x > 2\$라는 범위를 확보합니다. 로그의 덧셈 성질을 적용하면 \$\\log_3 (x(x-2)) = 1\$이 되고, 이를 지수 형태로 바꾸면 \$x(x-2) = 3^1\$이 됩니다. 이차방정식 \$x^2 - 2x - 3 = 0\$을 인수분해하면 \$(x-3)(x+1) = 0\$이 되어 \$x=3\$ 또는 \$x=-1\$을 얻습니다. 앞서 구한 진수 조건 \$x > 2\$에 의해 최종 해는 \$x=3\$입니다.',
            ],
          ),
        ],
      ),
    ],
  ),
  '부정적분의정의': BookData(
    id: 'concept_부정적분의정의',
    title: '부정적분의정의',
    subtitle: '미적분Ⅰ > 부정적분 > 부정적분의정의',
    category: 'common',
    tags: ['미적분Ⅰ', '부정적분', '부정적분의정의'],
    chapters: [
      BookChapter(
        title: '부정적분의정의',
        intro: ['미적분Ⅰ > 부정적분 > 부정적분의정의 개념 학습'],
        sections: [
          BookSection(
            title: '부정적분의정의',
            paragraphs: [
              '부정적분이란 미분의 역과정으로, 어떤 함수를 미분하기 전의 원래 함수를 찾는 것을 의미합니다. 함수 \$f(x)\$에 대하여 미분하여 \$f(x)\$가 되는 함수 \$F(x)\$를 \$f(x)\$의 \'원시함수\'라고 합니다. 이때 \$F(x)\$를 미분하면 \$f(x)\$가 되는데, 상수를 미분하면 \$0\$이 되므로 \$F(x) + C\$ (단, \$C\$는 상수) 또한 미분하면 \$f(x)\$가 됩니다. 이와 같이 \$f(x)\$의 모든 원시함수를 통틀어 \$f(x)\$의 부정적분이라 하며, 기호로 \$\\int f(x) dx\$와 같이 나타냅니다.',
              '부정적분의 핵심 공식은 다항함수의 적분법입니다. 실수 \$n\$에 대하여 \$x^n\$을 적분하면 차수는 하나 커지고, 그 커진 지수로 전체를 나누어주면 됩니다. 이를 공식으로 나타내면 다음과 같습니다. \$n \\neq -1\$일 때, \$\$\\int x^n dx = \\frac{1}{n+1}x^{n+1} + C\$\$ 여기서 \$C\$는 적분상수라고 부르며, 부정적분을 구할 때 반드시 뒤에 붙여주어야 합니다. 이 공식은 미분의 역연산 원리를 이용하면 쉽게 이해할 수 있습니다.',
              '부정적분은 선형성이라는 중요한 성질을 가집니다. 함수 \$f(x), g(x)\$에 대하여 실수배와 덧셈, 뺄셈에 대해 자유롭게 분리하거나 합칠 수 있습니다. 즉, \$\$\\int k f(x) dx = k \\int f(x) dx \\quad (k \\text{는 상수})\$\$ 이고, \$\$\\int \\{f(x) \\pm g(x)\\} dx = \\int f(x) dx \\pm \\int g(x) dx\$\$ 가 성립합니다. 이러한 성질을 이용하면 복잡한 다항식의 부정적분도 각 항별로 나누어 간단하게 계산할 수 있습니다.',
              '예제 문제: 다음 부정적분을 구하시오. \$\$\\int (3x^2 + 4x + 5) dx\$\$ 이 문제를 풀기 위해서는 앞서 배운 부정적분의 선형성 성질을 활용하여 각 항을 따로 적분하면 됩니다. 먼저 각 항을 분리하면 \$\$\\int 3x^2 dx + \\int 4x dx + \\int 5 dx\$\$ 가 됩니다. 이제 각각의 항에 다항함수의 적분 공식을 적용합니다.',
              '단계별 풀이: 첫 번째 항 \$3x^2\$은 \$3 \\cdot \\frac{x^3}{3} = x^3\$이 되고, 두 번째 항 \$4x\$는 \$4 \\cdot \\frac{x^2}{2} = 2x^2\$이 됩니다. 마지막 상수항 \$5\$는 \$5x\$로 적분됩니다. 모든 적분을 마친 후에는 마지막에 적분상수 \$C\$를 더해줍니다. 따라서 최종 결과는 다음과 같습니다. \$\$\\int (3x^2 + 4x + 5) dx = x^3 + 2x^2 + 5x + C\$\$ 이처럼 부정적분은 각 항의 차수를 높이고 그 계수를 조정하는 과정을 통해 쉽게 구할 수 있습니다.',
            ],
          ),
        ],
      ),
    ],
  ),
  '합성함수의성질': BookData(
    id: 'concept_합성함수의성질',
    title: '합성함수의성질',
    subtitle: '공통수학2 > 함수 > 합성함수 > 합성함수의성질',
    category: 'common',
    tags: ['공통수학2', '함수', '합성함수', '합성함수의성질'],
    chapters: [
      BookChapter(
        title: '합성함수의성질',
        intro: ['공통수학2 > 함수 > 합성함수 > 합성함수의성질 개념 학습'],
        sections: [
          BookSection(
            title: '합성함수의성질',
            paragraphs: [
              '[   "합성함수란 두 함수 \$f: X \\\\to Y\$와 \$g: Y \\\\to Z\$가 있을 때, \$X\$의 원소 \$x\$를 \$f\$에 의해 \$f(x)\$로 보내고, 다시 \$g\$에 의해 \$g(f(x))\$로 보내는 새로운 함수를 말합니다. 이를 기호로 \$(g \\\\circ f)(x) = g(f(x))\$라고 나타내며, 여기서 \'\$\\circ\$\'는 합성 연산을 의미합니다. 합성함수가 정의되기 위해서는 첫 번째 함수 \$f\$의 공역이 두 번째 함수 \$g\$의 정의역의 부분집합이어야 한다는 점을 기억해야 합니다.",   "합성함수의 가장 중요한 성질 중 하나는 \'교환법칙이 성립하지 않는다\'는 점입니다. 일반적으로 \$f \\\\circ g \\\\neq g \\\\circ f\$이므로, 함수를 합성하는 순서가 매우 중요합니다. 반면, 세 함수 \$f, g, h\$에 대하여 \$(h \\\\circ g) \\\\circ f = h \\\\circ (g \\\\circ f)\$와 같이 \'결합법칙\'은 항상 성립합니다. 또한, 항등함수 \$I(x) = x\$에 대하여 \$f \\\\circ I = I \\\\circ f = f\$가 성립한다는 성질도 합성함수의 연산에서 자주 활용됩니다.",   "이제 구체적인 예제를 통해 합성함수를 계산해 봅시다. 두 함수 \$f(x) = 2x + 1\$과 \$g(x) = x^2\$이 주어졌을 때, \$(g \\\\circ f)(x)\$와 \$(f \\\\circ g)(x)\$를 각각 구해 보겠습니다. 먼저 \$(g \\\\circ f)(x)\$는 \$g(f(x))\$이므로, \$g\$ 함수의 \$x\$ 자리에 \$f(x)\$인 \$2x+1\$을 대입합니다. 즉, \$(g \\\\circ f)(x) = (2x+1)^2 = 4x^2 + 4x + 1\$이 됩니다.",   "반대로 \$(f \\\\circ g)(x)\$는 \$f(g(x))\$이므로, \$f\$ 함수의 \$x\$ 자리에 \$g(x)\$인 \$x^2\$을 대입합니다. 따라서 \$(f \\\\circ g)(x) = 2(x^2) + 1 = 2x^2 + 1\$이 됩니다. 결과를 비교해 보면 \$4x^2 + 4x + 1 \\\\neq 2x^2 + 1\$임을 알 수 있으며, 이를 통해 합성함수에서 순서가 바뀌면 결과가 달라진다는 교환법칙의 비성립을 명확히 확인할 수 있습니다.",   "마지막으로 조금 더 복잡한 형태인 \$(f \\\\circ f)(x)\$를 계산해 보겠습니다. \$f(x) = 2x + 1\$일 때, \$(f \\\\circ f)(x) = f(f(x))\$입니다. 이는 \$f\$ 함수의 \$x\$ 자리에 다시 \$f(x)\$ 전체를 넣는 것과 같습니다. 즉, \$f(f(x)) = 2(2x + 1) + 1\$이 됩니다. 이를 전개하면 \$4x + 2 + 1 = 4x + 3\$이라는 결과를 얻을 수 있습니다. 이처럼 합성함수는 함수 안에 함수를 중첩하여 대입하는 과정임을 이해하면 어떤 복잡한 문제도 단계별로 해결할 수 있습니다." ]',
            ],
          ),
        ],
      ),
    ],
  ),
  '인수분해를이용한극한': BookData(
    id: 'concept_인수분해를이용한극한',
    title: '인수분해를이용한극한',
    subtitle: '미적분Ⅰ > 함수의극한 > 극한값계산 > 인수분해를이용한극한',
    category: 'common',
    tags: ['미적분Ⅰ', '함수의극한', '극한값계산', '인수분해를이용한극한'],
    chapters: [
      BookChapter(
        title: '인수분해를이용한극한',
        intro: ['미적분Ⅰ > 함수의극한 > 극한값계산 > 인수분해를이용한극한 개념 학습'],
        sections: [
          BookSection(
            title: '인수분해를이용한극한',
            paragraphs: [
              '함수의 극한에서 가장 먼저 마주하는 난관은 분모와 분자가 모두 0으로 향하는 \'0/0꼴\'의 부정형입니다. 이러한 형태는 단순히 값을 대입하는 것만으로는 극한값을 구할 수 없는데, 이때 사용하는 가장 강력한 도구가 바로 \'인수분해\'입니다. 분모를 0으로 만드는 원인인 공통 인수를 찾아 분자와 분모에서 각각 약분해 줌으로써, 극한값을 구할 수 있는 형태로 식을 변형하는 것이 이 개념의 핵심입니다.',
              '다항함수 \$f(x)\$와 \$g(x)\$에 대하여, \$x=a\$일 때 \$f(a)=0\$이고 \$g(a)=0\$이라면, 다항식의 성질에 의해 \$f(x)\$와 \$g(x)\$는 모두 \$(x-a)\$를 인수로 가집니다. 따라서 극한식은 다음과 같이 표현할 수 있습니다. \$\$\\lim_{x \\to a} \\frac{f(x)}{g(x)} = \\lim_{x \\to a} \\frac{(x-a)Q_1(x)}{(x-a)Q_2(x)} = \\lim_{x \\to a} \\frac{Q_1(x)}{Q_2(x)}\$\$ 여기서 \$Q_1(x)\$와 \$Q_2(x)\$는 각각 \$f(x)\$와 \$g(x)\$를 \$(x-a)\$로 나눈 몫입니다. 이 과정을 통해 분모가 0이 되는 요소를 제거하면, 비로소 \$x\$에 \$a\$를 대입하여 극한값을 구할 수 있게 됩니다.',
              '예를 들어, \$\\lim_{x \\to 2} \\frac{x^2-4}{x-2}\$라는 극한 문제를 풀어봅시다. 먼저 \$x=2\$를 대입하면 분모는 \$2-2=0\$, 분자는 \$2^2-4=0\$이 되어 \$0/0\$꼴임을 알 수 있습니다. 이때 분자 \$x^2-4\$는 합차 공식에 의해 \$(x-2)(x+2)\$로 인수분해됩니다. 식을 다시 쓰면 \$\$\\lim_{x \\to 2} \\frac{(x-2)(x+2)}{x-2}\$\$가 됩니다.',
              '이제 분모와 분자에 공통으로 들어있는 \$(x-2)\$를 약분합니다. 극한의 정의에서 \$x \\to 2\$라는 것은 \$x\$가 2에 한없이 가까워질 뿐 \$x=2\$는 아니라는 뜻이므로, \$x-2 \\neq 0\$이 보장되어 자유롭게 약분이 가능합니다. 약분 후 남은 식은 \$x+2\$입니다. 따라서 극한값은 다음과 같이 계산됩니다. \$\$\\lim_{x \\to 2} (x+2) = 2+2 = 4\$\$ 이처럼 인수분해를 이용하면 복잡해 보이는 극한식도 간단하게 해결할 수 있습니다.',
            ],
          ),
        ],
      ),
    ],
  ),
  '조합의수': BookData(
    id: 'concept_조합의수',
    title: '조합의수',
    subtitle: '공통수학1 > 경우의수 > 조합 > 조합의수',
    category: 'common',
    tags: ['공통수학1', '경우의수', '조합', '조합의수'],
    chapters: [
      BookChapter(
        title: '조합의수',
        intro: ['공통수학1 > 경우의수 > 조합 > 조합의수 개념 학습'],
        sections: [
          BookSection(
            title: '조합의수',
            paragraphs: [
              '조합이란 서로 다른 \$n\$개에서 순서를 생각하지 않고 \$r\$개를 택하는 것을 말합니다. 순열이 \'순서\'를 중요하게 생각하여 나열하는 것이라면, 조합은 단순히 \'어떤 것들을 뽑을 것인가\'라는 구성 자체에 집중합니다. 예를 들어, 3명의 학생 중 대표 2명을 뽑는 상황에서 \'철수와 영희\'를 뽑는 것과 \'영희와 철수\'를 뽑는 것은 결국 같은 구성이므로 이를 하나로 간주하는 것이 조합의 핵심입니다.',
              '서로 다른 \$n\$개에서 \$r\$개를 택하는 조합의 수를 기호로 \$_nC_r\$이라고 나타냅니다. 조합의 수는 순열의 수 \$_nP_r\$에서 순서가 바뀌는 경우의 수인 \$r!\$만큼 중복이 발생하므로, 이를 나누어 계산합니다. 따라서 조합의 수 공식은 다음과 같습니다. \$\$ _nC_r = \\frac{_nP_r}{r!} = \\frac{n!}{r!(n-r)!} \\quad (0 \\le r \\le n) \$\$ 또한, 조합에는 \$_nC_r = _nC_{n-r}\$이라는 중요한 성질이 있습니다. 이는 \$n\$개 중 \$r\$개를 뽑는 것은 뽑히지 않을 \$n-r\$개를 선택하는 것과 같다는 논리적 근거를 가집니다.',
              '조합의 성질 중 하나인 파스칼의 삼각형 원리도 매우 유용합니다. 이는 서로 다른 \$n\$개에서 \$r\$개를 뽑을 때, 특정 한 개를 반드시 포함하는 경우와 포함하지 않는 경우로 나누어 생각하는 방법입니다. 이를 공식으로 나타내면 다음과 같습니다. \$\$ _nC_r = _{n-1}C_{r-1} + _{n-1}C_r \$\$ 이 공식은 복잡한 조합의 합을 구할 때 매우 효율적으로 사용되며, 조합의 기본 성질을 이해하는 데 큰 도움을 줍니다.',
              '예제 문제: 7명의 학생 중에서 청소 당번 3명을 뽑는 경우의 수를 구하시오. 단계별 풀이: 첫째, 서로 다른 7명에서 순서를 고려하지 않고 3명을 선택하는 상황이므로 조합 공식 \$_7C_3\$을 사용합니다. 둘째, 공식에 대입하면 다음과 같습니다. \$\$ _7C_3 = \\frac{7 \\times 6 \\times 5}{3 \\times 2 \\times 1} \$\$ 셋째, 분자와 분모를 약분하여 계산하면 \$7 \\times 5 = 35\$가 됩니다. 따라서 청소 당번 3명을 뽑는 경우의 수는 총 35가지입니다.',
              '예제 문제: 5개의 과일 중에서 3개를 골라 바구니에 담는 방법의 수를 구하시오. 단계별 풀이: 첫째, 5개 중 3개를 고르는 것이므로 \$_5C_3\$을 계산합니다. 둘째, 앞서 배운 성질 \$_nC_r = _nC_{n-r}\$을 활용하면 \$_5C_3 = _5C_{5-3} = _5C_2\$임을 알 수 있습니다. 셋째, \$_5C_2\$를 계산하면 다음과 같습니다. \$\$ _5C_2 = \\frac{5 \\times 4}{2 \\times 1} = 10 \$\$ 따라서 5개의 과일 중 3개를 고르는 방법은 총 10가지입니다.',
            ],
          ),
        ],
      ),
    ],
