  '일반형을표준형으로': BookData(
    id: 'concept_일반형을표준형으로',
    title: '일반형을표준형으로',
    subtitle: '공통수학2 > 원의방정식 > 원의일반형 > 일반형을표준형으로',
    category: 'common',
    tags: ['공통수학2', '원의방정식', '원의일반형', '일반형을표준형으로'],
    chapters: [
      BookChapter(
        title: '일반형을표준형으로',
        intro: ['공통수학2 > 원의방정식 > 원의일반형 > 일반형을표준형으로 개념 학습'],
        sections: [
          BookSection(
            title: '일반형을표준형으로',
            paragraphs: [
              '원의 방정식은 좌표평면 위에서 중심과 반지름을 알 수 있는 \'표준형\'과, 식을 전개하여 정리한 \'일반형\'으로 나뉩니다. 일반형은 보통 \$\$x^2 + y^2 + Ax + By + C = 0\$\$의 꼴로 나타내는데, 이 식만 봐서는 원의 중심이 어디인지, 반지름의 길이가 얼마인지 바로 파악하기 어렵습니다. 따라서 원의 기하학적 성질을 명확히 확인하기 위해서는 일반형을 표준형인 \$\$ (x-a)^2 + (y-b)^2 = r^2 \$\$ 꼴로 바꾸는 과정이 필수적입니다.',
              '일반형을 표준형으로 바꾸는 핵심 전략은 \'완전제곱식\'을 만드는 것입니다. \$\$x^2 + Ax\$\$ 항을 보고 \$\$ (x + \\frac{A}{2})^2 \$\$을 만들기 위해 필요한 상수항을 더하고 빼주며, \$\$y^2 + By\$\$ 항에 대해서도 동일하게 \$\$ (y + \\frac{B}{2})^2 \$\$을 만들기 위한 과정을 거칩니다. 이때 식의 균형을 맞추기 위해 더해준 값만큼 우변에도 똑같이 더해주면, 원의 중심 \$\$(a, b)\$\$와 반지름 \$\$r\$\$을 쉽게 찾아낼 수 있습니다.',
              '이 과정을 통해 변형된 식 \$\$ (x + \\frac{A}{2})^2 + (y + \\frac{B}{2})^2 = \\frac{A^2}{4} + \\frac{B^2}{4} - C \$\$에서, 우변의 값이 양수여야만 비로소 반지름이 존재하는 하나의 원이 됩니다. 만약 우변이 0이면 점 하나가 되고, 음수라면 실수 범위에서 만족하는 점이 없으므로 원을 나타내지 않는다는 점도 함께 기억해 두면 좋습니다.',
              '예제 문제: 방정식 \$\$x^2 + y^2 - 4x + 6y - 3 = 0\$\$이 나타내는 원의 중심과 반지름을 구하시오. 먼저 \$\$x\$\$항끼리, \$\$y\$\$항끼리 모아서 정리하면 \$\$(x^2 - 4x) + (y^2 + 6y) = 3\$\$이 됩니다. 이제 각 괄호 안을 완전제곱식으로 만들기 위해 필요한 상수를 더해줍니다. \$\$x\$\$항은 \$\$-4\$\$의 절반의 제곱인 \$\$4\$\$를, \$\$y\$\$항은 \$\$6\$\$의 절반의 제곱인 \$\$9\$\$를 양변에 더합니다.',
              '양변에 같은 수를 더하여 식을 완성하면 \$\$(x^2 - 4x + 4) + (y^2 + 6y + 9) = 3 + 4 + 9\$\$가 됩니다. 이를 완전제곱식으로 묶으면 \$\$(x - 2)^2 + (y + 3)^2 = 16\$\$이라는 표준형을 얻을 수 있습니다. 여기서 \$\$16\$\$은 \$\$4^2\$\$이므로, 이 원의 중심은 \$\$(2, -3)\$\$이고 반지름의 길이는 \$\$4\$\$임을 알 수 있습니다.',
            ],
          ),
        ],
      ),
    ],
  ),
  '완성제곱법': BookData(
    id: 'concept_완성제곱법',
    title: '완성제곱법',
    subtitle: '공통수학1 > 이차방정식 > 이차방정식의풀이 > 완성제곱법',
    category: 'common',
    tags: ['공통수학1', '이차방정식', '이차방정식의풀이', '완성제곱법'],
    chapters: [
      BookChapter(
        title: '완성제곱법',
        intro: ['공통수학1 > 이차방정식 > 이차방정식의풀이 > 완성제곱법 개념 학습'],
        sections: [
          BookSection(
            title: '완성제곱법',
            paragraphs: [
              '완성제곱법이란 이차방정식의 좌변을 \$(x+p)^2 = q\$의 꼴로 변형하여 해를 구하는 방법입니다. 이차방정식 \$ax^2 + bx + c = 0\$에서 \$a\$로 양변을 나누어 \$x^2\$의 계수를 1로 만든 뒤, \$x\$항의 계수의 절반을 제곱한 값을 양변에 더해 완전제곱식을 만드는 것이 핵심입니다. 이 과정을 거치면 제곱근의 성질을 이용하여 방정식을 훨씬 쉽게 풀 수 있습니다.',
              '구체적인 공식의 흐름은 다음과 같습니다. 이차방정식 \$x^2 + bx + c = 0\$이 있을 때, 상수항 \$c\$를 우변으로 이항하여 \$x^2 + bx = -c\$로 만듭니다. 그 후 좌변을 완전제곱식으로 만들기 위해 양변에 \$(\\frac{b}{2})^2\$을 더해줍니다. 그러면 좌변은 \$\$(x + \\frac{b}{2})^2 = \\frac{b^2}{4} - c\$\$와 같은 형태가 되며, 여기서 우변의 값을 \$q\$라고 할 때 \$x + \\frac{b}{2} = \\pm\\sqrt{q}\$를 통해 \$x\$의 값을 구할 수 있습니다.',
              '완성제곱법은 단순히 방정식을 푸는 도구를 넘어, 이차함수의 그래프를 그릴 때 꼭짓점의 좌표를 찾는 표준형으로 변형하는 기초가 됩니다. 또한, 이차방정식의 근의 공식을 유도하는 논리적 근거가 되므로, 이 과정을 완벽히 이해하는 것은 고등 수학의 대수적 사고력을 기르는 데 매우 중요합니다.',
              '예제 문제: 이차방정식 \$x^2 - 6x + 5 = 0\$을 완성제곱법을 이용하여 풀어봅시다. 먼저 상수항 5를 우변으로 이항하면 \$x^2 - 6x = -5\$가 됩니다. 이제 좌변을 완전제곱식으로 만들기 위해 \$x\$의 계수인 \$-6\$의 절반인 \$-3\$을 제곱한 값인 \$9\$를 양변에 더합니다. 그러면 식은 \$\$x^2 - 6x + 9 = -5 + 9\$\$가 됩니다.',
              '위 식의 좌변을 인수분해하면 \$\$(x - 3)^2 = 4\$\$가 됩니다. 이제 제곱근의 성질에 의해 \$x - 3 = \\pm\\sqrt{4}\$이므로 \$x - 3 = \\pm 2\$가 성립합니다. 따라서 \$x = 3 + 2\$ 또는 \$x = 3 - 2\$가 되어, 최종적인 해는 \$\$x = 5 \\text{ 또는 } x = 1\$\$이 됩니다. 이처럼 완성제곱법을 활용하면 복잡한 인수분해 없이도 이차방정식의 해를 정확하게 찾아낼 수 있습니다.',
            ],
          ),
        ],
      ),
    ],
  ),
