    category: 'common',
    tags: ['미적분Ⅰ', '부정적분', '부정적분공식'],
    chapters: [
      BookChapter(
        title: '부정적분공식',
        intro: ['미적분Ⅰ > 부정적분 > 부정적분공식 개념 학습'],
        sections: [
          BookSection(
            title: '부정적분공식',
            paragraphs: [
              '부정적분이란 미분의 역과정으로, 어떤 함수 \$f(x)\$를 미분하여 \$F\'(x) = f(x)\$가 될 때, 함수 \$F(x)\$를 \$f(x)\$의 부정적분이라고 합니다. 이때 부정적분은 하나로 정해지지 않고 상수만큼의 차이가 발생하는데, 이를 나타내기 위해 임의의 상수 \$C\$를 더하여 \$F(x) + C\$와 같이 표현하며, 여기서 \$C\$를 적분상수라고 부릅니다. 기호로는 \$\\int f(x) \\, dx = F(x) + C\$와 같이 나타냅니다.',
              '다항함수의 부정적분은 미분법의 역순을 생각하면 쉽게 구할 수 있습니다. 자연수 \$n\$에 대하여 \$x^n\$을 적분하는 기본 공식은 \$\$ \\int x^n \\, dx = \\frac{1}{n+1} x^{n+1} + C \\quad (n \\neq -1) \$\$ 입니다. 또한, 적분은 선형성을 가지므로 실수배와 덧셈, 뺄셈에 대하여 다음과 같은 성질이 성립합니다. \$\$ \\int k f(x) \\, dx = k \\int f(x) \\, dx, \\quad \\int \\{f(x) \\pm g(x)\\} \\, dx = \\int f(x) \\, dx \\pm \\int g(x) \\, dx \$\$',
              '이제 구체적인 예제를 통해 부정적분을 계산해 봅시다. 다항함수 \$f(x) = 3x^2 + 4x + 5\$의 부정적분을 구하는 과정은 다음과 같습니다. 먼저 적분의 선형성 성질을 이용하여 각 항을 따로 적분합니다. 즉, \$\\int (3x^2 + 4x + 5) \\, dx = 3 \\int x^2 \\, dx + 4 \\int x^1 \\, dx + \\int 5 \\, dx\$로 식을 분리합니다.',
              '각 항에 공식 \$\\int x^n \\, dx = \\frac{1}{n+1} x^{n+1} + C\$를 적용합니다. 첫 번째 항은 \$3 \\cdot \\frac{1}{2+1} x^{2+1} = x^3\$, 두 번째 항은 \$4 \\cdot \\frac{1}{1+1} x^{1+1} = 2x^2\$, 세 번째 항은 상수 \$5\$를 적분하여 \$5x\$가 됩니다. 마지막으로 모든 항을 더하고 적분상수 \$C\$를 붙여주면 최종 결과는 \$\$ \\int (3x^2 + 4x + 5) \\, dx = x^3 + 2x^2 + 5x + C \$\$ 가 됩니다.',
