  '로그함수의평행이동': BookData(
    id: 'concept_로그함수의평행이동',
    title: '로그함수의평행이동',
    subtitle: '대수 > 로그함수 > 로그함수의평행이동',
    category: 'common',
    tags: ['대수', '로그함수', '로그함수의평행이동'],
    chapters: [
      BookChapter(
        title: '로그함수의평행이동',
        intro: ['대수 > 로그함수 > 로그함수의평행이동 개념 학습'],
        sections: [
          BookSection(
            title: '로그함수의평행이동',
            paragraphs: [
              '로그함수의 평행이동이란 기본적인 로그함수 \$y = \\log_a x\$ (단, \$a > 0, a \\neq 1\$)의 그래프를 좌표평면 위에서 가로 방향이나 세로 방향으로 밀어서 옮기는 것을 의미합니다. 함수 \$y = \\log_a x\$의 그래프를 \$x\$축의 방향으로 \$p\$만큼, \$y\$축의 방향으로 \$q\$만큼 평행이동하면, 새로운 함수식은 \$y - q = \\log_a (x - p)\$가 됩니다. 이를 \$y\$에 관하여 정리하면 \$\$y = \\log_a (x - p) + q\$\$라는 표준형 식을 얻을 수 있습니다.',
              '이 평행이동은 그래프의 모양은 그대로 유지하면서 위치만 변화시킵니다. 특히 로그함수의 중요한 특징인 점근선과 정의역에 큰 변화를 줍니다. 원래 \$y = \\log_a x\$의 점근선은 \$y\$축(\$x=0\$)이었으나, \$x\$축으로 \$p\$만큼 평행이동하면 점근선은 \$\$x = p\$\$로 바뀝니다. 또한, 원래 \$x > 0\$이었던 정의역은 평행이동 후 \$\$x > p\$\$로 변하게 되어, 로그의 진수 조건인 \'진수는 항상 양수여야 한다\'는 원칙을 그대로 따르게 됩니다.',
              '이제 구체적인 예제를 통해 평행이동을 적용해 봅시다. 문제: 함수 \$y = \\log_2 x\$의 그래프를 \$x\$축의 방향으로 \$3\$만큼, \$y\$축의 방향으로 \$-1\$만큼 평행이동한 함수의 식을 구하고, 그 점근선과 정의역을 구하시오. 먼저 평행이동의 원리에 따라 \$x\$ 대신 \$x-3\$을, \$y\$ 대신 \$y-(-1)\$을 대입합니다. 그러면 \$\$y + 1 = \\log_2 (x - 3)\$\$이 되며, 이를 정리하면 \$\$y = \\log_2 (x - 3) - 1\$\$이 됩니다.',
              '이어서 구한 함수의 성질을 분석해 보겠습니다. 점근선은 진수 부분이 \$0\$이 되는 \$x\$의 값에서 결정되므로, \$x - 3 = 0\$을 만족하는 \$\$x = 3\$\$이 이 함수의 점근선이 됩니다. 또한, 로그함수의 진수는 항상 \$0\$보다 커야 하므로 \$x - 3 > 0\$이 성립해야 합니다. 따라서 이 함수의 정의역은 \$\$x > 3\$\$인 모든 실수입니다. 이처럼 평행이동된 로그함수는 점근선을 기준으로 그래프가 어느 방향으로 그려지는지 파악하는 것이 핵심입니다.',
            ],
          ),
        ],
      ),
    ],
  ),
  '조합의성질': BookData(
    id: 'concept_조합의성질',
    title: '조합의성질',
    subtitle: '공통수학1 > 경우의수 > 조합 > 조합의성질',
    category: 'common',
    tags: ['공통수학1', '경우의수', '조합', '조합의성질'],
    chapters: [
      BookChapter(
        title: '조합의성질',
        intro: ['공통수학1 > 경우의수 > 조합 > 조합의성질 개념 학습'],
        sections: [
          BookSection(
            title: '조합의성질',
            paragraphs: [
              '조합이란 서로 다른 \$n\$개에서 순서를 생각하지 않고 \$r\$개를 택하는 것을 말하며, 기호로는 \$_nC_r\$로 나타냅니다. 조합의 가장 중요한 성질 중 하나는 \'선택하는 것\'과 \'제외하는 것\'이 같다는 점입니다. 즉, \$n\$개 중에서 \$r\$개를 뽑는 것은 동시에 뽑지 않을 \$(n-r)\$개를 결정하는 것과 같으므로, 다음과 같은 대칭적 성질이 성립합니다. 이를 수식으로 표현하면 \$\$_nC_r = _nC_{n-r}\$\$ 입니다.',
              '조합의 또 다른 핵심 성질은 파스칼의 삼각형을 만드는 기초가 되는 \'덧셈 정리\'입니다. 이는 \$n\$개의 원소 중 특정 원소 하나를 포함하여 뽑는 경우와, 그 원소를 포함하지 않고 뽑는 경우로 나누어 생각하는 원리입니다. 이 성질을 이용하면 복잡한 조합의 합을 간단히 계산할 수 있으며, 공식은 다음과 같습니다. \$\$_nC_r = _{n-1}C_{r-1} + _{n-1}C_r\$\$ 이 공식은 \$n\$개 중에서 \$r\$개를 선택할 때, 특정 대상이 포함되는 경우와 포함되지 않는 경우의 합이 전체 경우의 수와 같음을 의미합니다.',
              '이제 구체적인 예제를 통해 조합의 성질을 적용해 보겠습니다. 첫 번째 예제는 대칭 성질을 이용한 계산입니다. 문제: \'서로 다른 10개의 과일 중에서 8개를 고르는 경우의 수를 구하시오.\' 풀이: 직접 \$_10C_8\$을 계산하는 것보다 성질 \$_nC_r = _nC_{n-r}\$을 이용하는 것이 훨씬 빠릅니다. 즉, \$_10C_8 = _{10}C_{10-8} = _{10}C_2\$가 됩니다. 이를 계산하면 \$\$\$_10C_2 = rac{10 	imes 9}{2 	imes 1} = 45\$\$가 되어, 정답은 45가지입니다.',
              '두 번째 예제는 덧셈 정리를 활용한 문제입니다. 문제: \'\$_5C_2 + _5C_3\$의 값을 구하시오.\' 풀이: 이 식은 앞서 배운 덧셈 정리 \$_nC_r + _nC_{r+1} = _{n+1}C_{r+1}\$의 형태를 따르고 있습니다. 여기서 \$n=5, r=2\$라고 생각하면, 공식에 의해 다음과 같이 정리할 수 있습니다. \$\$_5C_2 + _5C_3 = _{5+1}C_3 = _6C_3\$\$ 이제 \$_6C_3\$을 계산하면 \$\$\$_6C_3 = rac{6 	imes 5 	imes 4}{3 	imes 2 	imes 1} = 20\$\$이 됩니다. 이처럼 조합의 성질을 활용하면 복잡한 덧셈 과정을 훨씬 효율적으로 해결할 수 있습니다.',
            ],
          ),
        ],
      ),
    ],
  ),
  '근의공식': BookData(
    id: 'concept_근의공식',
    title: '근의공식',
    subtitle: '공통수학1 > 이차방정식 > 이차방정식의풀이 > 근의공식',
    category: 'common',
    tags: ['공통수학1', '이차방정식', '이차방정식의풀이', '근의공식'],
    chapters: [
      BookChapter(
        title: '근의공식',
        intro: ['공통수학1 > 이차방정식 > 이차방정식의풀이 > 근의공식 개념 학습'],
        sections: [
          BookSection(
            title: '근의공식',
            paragraphs: [
              '이차방정식 \$ax^2 + bx + c = 0\$ (\$a \\neq 0\$)을 풀 때, 인수분해가 바로 되지 않는다면 우리는 \'근의 공식\'이라는 강력한 도구를 사용합니다. 근의 공식은 이차방정식의 계수인 \$a, b, c\$를 공식에 대입하기만 하면 해를 바로 구할 수 있게 해주는 만능 열쇠와 같습니다. 이 공식은 이차방정식의 일반형을 \'완전제곱식\' 형태로 변형하는 과정을 통해 유도됩니다.',
              '이차방정식 \$ax^2 + bx + c = 0\$의 해를 구하는 근의 공식은 다음과 같습니다. \$\$x = \\frac{-b \\pm \\sqrt{b^2 - 4ac}}{2a}\$\$ 여기서 \$\\pm\$ 기호는 해가 두 개일 수 있음을 의미하며, 루트(\$\\sqrt{\\quad}\$) 안의 값인 \$b^2 - 4ac\$는 방정식의 해가 실수인지, 중근인지, 혹은 허수인지 판별하는 중요한 역할을 합니다. 만약 \$b\$가 짝수인 경우, 즉 \$b = 2b\'\$라면 계산을 더 간편하게 만드는 \'짝수 공식\'을 사용할 수 있습니다. \$\$x = \\frac{-b\' \\pm \\sqrt{b\'^2 - ac}}{a}\$\$',
              '이제 예제를 통해 근의 공식을 직접 적용해 봅시다. 이차방정식 \$x^2 - 5x + 4 = 0\$을 풀어보겠습니다. 이 식에서 계수를 확인하면 \$a=1, b=-5, c=4\$입니다. 근의 공식에 이 값들을 대입하면 다음과 같습니다. \$\$x = \\frac{-(-5) \\pm \\sqrt{(-5)^2 - 4 \\times 1 \\times 4}}{2 \\times 1}\$\$',
              '위 식을 단계별로 계산해 보면, 먼저 루트 안의 값을 정리합니다. \$\$x = \\frac{5 \\pm \\sqrt{25 - 16}}{2} = \\frac{5 \\pm \\sqrt{9}}{2}\$\$ 루트 9는 3이므로, 식은 \$x = \\frac{5 \\pm 3}{2}\$가 됩니다. 따라서 두 개의 해는 \$x = \\frac{5+3}{2} = 4\$ 또는 \$x = \\frac{5-3}{2} = 1\$이 됩니다. 이처럼 근의 공식을 이용하면 복잡해 보이는 이차방정식도 체계적으로 해결할 수 있습니다.',
            ],
          ),
        ],
      ),
    ],
  ),
  '일대일함수': BookData(
    id: 'concept_일대일함수',
    title: '일대일함수',
    subtitle: '공통수학2 > 함수 > 역함수 > 일대일함수',
    category: 'common',
    tags: ['공통수학2', '함수', '역함수', '일대일함수'],
    chapters: [
      BookChapter(
        title: '일대일함수',
        intro: ['공통수학2 > 함수 > 역함수 > 일대일함수 개념 학습'],
        sections: [
          BookSection(
            title: '일대일함수',
            paragraphs: [
              '함수란 정의역의 각 원소에 공역의 원소가 오직 하나씩 대응하는 관계를 말합니다. 그중에서도 \'일대일함수\'는 정의역의 서로 다른 두 원소 \$x_1, x_2\$가 공역의 서로 다른 원소 \$f(x_1), f(x_2)\$에 대응하는 함수를 의미합니다. 즉, 입력값이 다르면 출력값도 반드시 달라야 한다는 조건입니다. 이를 수학적 기호로 표현하면, 정의역에 속하는 임의의 두 원소 \$x_1, x_2\$에 대하여 \$x_1 \\neq x_2\$이면 \$f(x_1) \\neq f(x_2)\$가 성립해야 합니다.',
              '일대일함수를 판별하는 또 다른 중요한 방법은 대우 명제를 이용하는 것입니다. \$f(x_1) = f(x_2)\$이면 \$x_1 = x_2\$라는 성질이 성립하면 그 함수는 일대일함수입니다. 또한, 그래프를 그렸을 때 어느 가로선(x축과 평행한 직선)을 그어도 그래프와 최대 한 점에서만 만난다면 그 함수는 일대일함수라고 할 수 있습니다. 만약 일대일함수이면서 공역과 치역이 같다면, 이를 특별히 \'일대일대응\'이라고 부릅니다.',
              '이제 예제를 통해 일대일함수를 확인해 봅시다. 실수 전체의 집합에서 정의된 함수 \$f(x) = 3x + 2\$가 일대일함수인지 확인해 보겠습니다. 정의에 따라 \$f(x_1) = f(x_2)\$라고 가정하면, \$3x_1 + 2 = 3x_2 + 2\$가 됩니다. 양변에서 2를 빼고 3으로 나누면 \$x_1 = x_2\$라는 결론을 얻을 수 있습니다. 따라서 \$f(x) = 3x + 2\$는 일대일함수의 조건을 만족합니다.',
              '다음으로 조금 더 복잡한 예제를 살펴보겠습니다. 정의역이 실수 전체인 함수 \$f(x) = x^2\$은 일대일함수일까요? 결론부터 말하면 일대일함수가 아닙니다. 예를 들어, \$x_1 = -1\$일 때 \$f(-1) = (-1)^2 = 1\$이고, \$x_2 = 1\$일 때 \$f(1) = 1^2 = 1\$입니다. 즉, \$x_1 \\neq x_2\$이지만 \$f(x_1) = f(x_2)\$인 경우가 존재하므로, 이 함수는 일대일함수가 아닙니다. 그래프로 보아도 \$y=1\$이라는 가로선을 그으면 두 점에서 만나기 때문에 일대일함수가 아님을 쉽게 알 수 있습니다.',
            ],
          ),
        ],
      ),
    ],
  ),
  '유리화를이용한극한': BookData(
    id: 'concept_유리화를이용한극한',
    title: '유리화를이용한극한',
    subtitle: '미적분Ⅰ > 함수의극한 > 극한값계산 > 유리화를이용한극한',
    category: 'common',
    tags: ['미적분Ⅰ', '함수의극한', '극한값계산', '유리화를이용한극한'],
    chapters: [
      BookChapter(
        title: '유리화를이용한극한',
        intro: ['미적분Ⅰ > 함수의극한 > 극한값계산 > 유리화를이용한극한 개념 학습'],
        sections: [
          BookSection(
            title: '유리화를이용한극한',
            paragraphs: [
              '함수의 극한을 구할 때, 분자나 분모에 무리식이 포함되어 있고 극한값이 \'0/0\' 꼴의 부정형으로 나타나는 경우가 있습니다. 이때 식의 형태를 바꾸어 극한값을 구하는 가장 효과적인 방법이 바로 \'유리화\'입니다. 유리화란 분자나 분모에 있는 무리식의 켤레식(합차 공식을 이용할 수 있는 식)을 곱하여 근호를 없애는 과정을 말합니다.',
              '유리화를 할 때는 합차 공식인 \$\$(a-b)(a+b) = a^2 - b^2\$\$을 활용합니다. 예를 들어 분자에 \$\$\\sqrt{f(x)} - g(x)\$\$가 있다면, 분자·분모에 \$\$\\sqrt{f(x)} + g(x)\$\$를 곱하여 분자의 근호를 제거합니다. 이 과정을 거치면 복잡했던 무리식이 다항식 형태로 변환되어, 약분을 통해 극한값을 결정짓는 0이 되는 인자를 쉽게 찾아낼 수 있게 됩니다.',
              '유리화를 이용한 극한 계산의 핵심 성질은 \'식의 변형\'입니다. 극한을 구하려는 식의 분자나 분모에 1을 곱하되, 그 1을 \$\$\\frac{\\sqrt{f(x)} + g(x)}{\\sqrt{f(x)} + g(x)}\$\$와 같은 형태로 만드는 것입니다. 이렇게 하면 식의 전체 값은 변하지 않으면서, 근호 안의 변수들이 제곱되어 근호 밖으로 나오게 되므로 극한값을 구하기 훨씬 수월한 구조로 바뀝니다.',
              '예제: \$\$\\lim_{x \\to 0} \\frac{\\sqrt{x+1} - 1}{x}\$\$의 값을 구하시오. 이 식에 \$x=0\$을 대입하면 \$\$\\frac{\\sqrt{1}-1}{0} = \\frac{0}{0}\$\$ 꼴이 되어 바로 값을 알 수 없습니다. 따라서 분자를 유리화해야 합니다. 분자·분모에 \$\$\\sqrt{x+1} + 1\$\$을 곱하면 식은 다음과 같이 변합니다. \$\$\\lim_{x \\to 0} \\frac{(\\sqrt{x+1} - 1)(\\sqrt{x+1} + 1)}{x(\\sqrt{x+1} + 1)} = \\lim_{x \\to 0} \\frac{(x+1) - 1}{x(\\sqrt{x+1} + 1)}\$\$',
              '위 식을 정리하면 분자는 \$x\$가 되고, 분모에도 \$x\$가 있으므로 약분이 가능합니다. \$\$\\lim_{x \\to 0} \\frac{x}{x(\\sqrt{x+1} + 1)} = \\lim_{x \\to 0} \\frac{1}{\\sqrt{x+1} + 1}\$\$이 됩니다. 이제 \$x\$에 0을 대입하면 \$\$\\frac{1}{\\sqrt{0+1} + 1} = \\frac{1}{1+1} = \\frac{1}{2}\$\$라는 결과를 얻을 수 있습니다. 이처럼 유리화는 무리식의 극한에서 0이 되는 인자를 제거하는 강력한 도구입니다.',
            ],
          ),
        ],
      ),
    ],
  ),
