    tags: ['공통수학2', '원의방정식', '평행이동', 'x방향이동'],
    chapters: [
      BookChapter(
        title: 'x방향이동',
        intro: ['공통수학2 > 원의방정식 > 평행이동 > x방향이동 개념 학습'],
        sections: [
          BookSection(
            title: 'x방향이동',
            paragraphs: [
              '평행이동이란 도형의 모양과 크기를 바꾸지 않고 일정한 방향으로 일정한 거리만큼 옮기는 것을 말합니다. 좌표평면 위에서 어떤 도형을 \$x\$축의 방향으로 \$a\$만큼 평행이동한다는 것은, 도형 위의 모든 점 \$(x, y)\$를 \$(x+a, y)\$로 옮기는 것을 의미합니다. 이때 도형의 방정식은 어떻게 변하는지 살펴보는 것이 핵심입니다.',
              '도형의 방정식 \$f(x, y) = 0\$을 \$x\$축의 방향으로 \$a\$만큼 평행이동하면, 새로운 방정식은 \$f(x-a, y) = 0\$이 됩니다. 이는 이동 후의 점을 \$(x\', y\')\$라고 할 때 \$x\' = x+a\$이므로 \$x = x\'-a\$가 성립하기 때문입니다. 즉, 원래의 식에서 \$x\$ 대신에 \$(x-a)\$를 대입하면 평행이동된 도형의 방정식을 얻을 수 있습니다.',
              '원의 방정식에서도 이 원리는 동일하게 적용됩니다. 중심이 \$(p, q)\$이고 반지름의 길이가 \$r\$인 원의 방정식은 \$(x-p)^2 + (y-q)^2 = r^2\$입니다. 이 원을 \$x\$축의 방향으로 \$a\$만큼 평행이동하면, 중심은 \$(p+a, q)\$로 변하고 방정식은 다음과 같이 바뀝니다. \$\$ (x-a-p)^2 + (y-q)^2 = r^2 \$\$ 이처럼 \$x\$ 자리에 \$(x-a)\$를 대입하는 것만으로도 평행이동된 원의 방정식을 쉽게 구할 수 있습니다.',
              '예제 문제를 통해 확인해 봅시다. 중심이 \$(2, 3)\$이고 반지름의 길이가 \$4\$인 원을 \$x\$축의 방향으로 \$-3\$만큼 평행이동했을 때의 방정식을 구해보세요. 먼저 원래 원의 방정식은 \$(x-2)^2 + (y-3)^2 = 16\$입니다. 여기서 \$x\$축의 방향으로 \$-3\$만큼 이동하므로, \$x\$ 대신에 \$x - (-3)\$, 즉 \$(x+3)\$을 대입해야 합니다.',
              '이제 대입 과정을 단계별로 수행합니다. 원래 식 \$(x-2)^2 + (y-3)^2 = 16\$의 \$x\$ 자리에 \$(x+3)\$을 넣으면, \$\$ ((x+3)-2)^2 + (y-3)^2 = 16 \$\$ 이 됩니다. 식을 정리하면 \$(x+1)^2 + (y-3)^2 = 16\$이 됩니다. 결과적으로 중심은 \$(2-3, 3) = (-1, 3)\$으로 이동하였으며, 반지름은 그대로 \$4\$인 원의 방정식이 완성됩니다.',
            ],
          ),
        ],
      ),
    ],
