  '지수방정식': BookData(
    id: 'concept_지수방정식',
    title: '지수방정식',
    subtitle: '대수 > 지수방정식과지수부등식 > 지수방정식',
    category: 'common',
    tags: ['대수', '지수방정식과지수부등식', '지수방정식'],
    chapters: [
      BookChapter(
        title: '지수방정식',
        intro: ['대수 > 지수방정식과지수부등식 > 지수방정식 개념 학습'],
        sections: [
          BookSection(
            title: '지수방정식',
            paragraphs: [
              '[   "지수방정식은 미지수가 지수에 포함되어 있는 방정식을 말합니다. 이 방정식을 풀기 위한 가장 기본적인 전략은 지수법칙을 이용하여 밑을 같게 만드는 것입니다. 만약 \$a^f(x) = a^g(x)\$ (단, \$a > 0, a \\neq 1\$)의 꼴로 식을 변형할 수 있다면, 밑이 같으므로 지수끼리 서로 같아야 한다는 성질을 이용하여 \$f(x) = g(x)\$라는 방정식으로 바꾸어 해결할 수 있습니다.",   "만약 지수방정식의 형태가 복잡하다면 치환을 이용하는 것이 효과적입니다. 예를 들어 \$a^x\$가 반복적으로 나타나는 식은 \$a^x = t\$로 치환하여 \$t\$에 관한 이차방정식이나 다항방정식으로 변형할 수 있습니다. 이때 주의할 점은 지수함수의 성질에 의해 \$a^x > 0\$이므로, 치환한 변수 \$t\$의 범위가 항상 \$t > 0\$이어야 한다는 것입니다. 이 조건을 놓치면 해를 구하는 과정에서 오류가 발생할 수 있으니 반드시 확인해야 합니다.",   "또한, 밑에 미지수가 포함된 경우에는 밑이 1인 경우와 지수가 0인 경우 등을 나누어 세심하게 살펴야 합니다. \$f(x)^{h(x)} = g(x)^{h(x)}\$와 같은 형태라면 지수가 같을 때 밑이 같거나, 혹은 지수 자체가 0이 되어 양변이 1이 되는 경우를 모두 고려해야 합니다. 이처럼 지수방정식은 단순히 식을 푸는 것을 넘어, 지수함수의 정의와 성질을 종합적으로 이해하고 있어야 정확한 해를 구할 수 있습니다.",   "이제 구체적인 예제를 통해 풀어보겠습니다. 방정식 \$4^x - 3 \\cdot 2^x - 4 = 0\$을 풀어봅시다. 먼저 \$4^x\$는 \$(2^2)^x = (2^x)^2\$으로 나타낼 수 있습니다. 여기서 \$2^x = t\$ (\$t > 0\$)로 치환하면 주어진 식은 \$t^2 - 3t - 4 = 0\$이 됩니다. 이 이차방정식을 인수분해하면 \$(t - 4)(t + 1) = 0\$이 되어 \$t = 4\$ 또는 \$t = -1\$이라는 해를 얻습니다.",   "마지막으로 치환했던 \$t\$를 다시 원래의 지수 형태로 되돌려야 합니다. \$t > 0\$이라는 조건에 따라 \$t = -1\$은 해가 될 수 없으므로 \$t = 4\$만 가능합니다. 따라서 \$2^x = 4\$가 되며, \$4 = 2^2\$이므로 지수를 비교하면 \$x = 2\$라는 최종적인 해를 구할 수 있습니다. 이처럼 치환을 이용할 때는 반드시 치환한 문자의 범위를 고려하여 타당한 해만을 선택하는 습관을 가져야 합니다." ]',
            ],
          ),
        ],
      ),
    ],
  ),
  '부정적분의성질': BookData(
    id: 'concept_부정적분의성질',
    title: '부정적분의성질',
    subtitle: '미적분Ⅰ > 부정적분 > 부정적분의성질',
    category: 'common',
    tags: ['미적분Ⅰ', '부정적분', '부정적분의성질'],
    chapters: [
      BookChapter(
        title: '부정적분의성질',
        intro: ['미적분Ⅰ > 부정적분 > 부정적분의성질 개념 학습'],
        sections: [
          BookSection(
            title: '부정적분의성질',
            paragraphs: [
              '[   "부정적분은 미분의 역연산으로, 어떤 함수 \$f(x)\$를 미분하여 \$F(x)\$가 되었을 때, 다시 \$F(x)\$를 적분하여 원래의 함수 \$f(x)\$를 찾아가는 과정을 의미합니다. 이때 적분 결과에는 상수항이 무엇인지 알 수 없으므로 항상 적분상수 \$C\$를 붙여야 합니다. 즉, \$\\\\int f(x) dx = F(x) + C\$와 같이 표현하며, 여기서 \$F\'(x) = f(x)\$가 성립합니다.",   "부정적분은 함수의 합, 차, 그리고 실수배에 대하여 선형성을 가집니다. 두 함수 \$f(x)\$와 \$g(x)\$의 부정적분이 각각 \$F(x)+C_1\$, \$G(x)+C_2\$일 때, 실수 \$k\$에 대하여 다음의 성질들이 성립합니다. 첫째, \$\\\\int k f(x) dx = k \\\\int f(x) dx\$이고, 둘째, \$\\\\int \\{f(x) \\\\pm g(x)\\} dx = \\\\int f(x) dx \\\\pm \\\\int g(x) dx\$입니다. 이러한 성질은 복잡한 다항함수를 적분할 때 각 항별로 나누어 계산할 수 있게 해줍니다.",   "다항함수의 적분에서 가장 기본이 되는 공식은 \$n\$이 자연수일 때 \$\\\\int x^n dx = \\\\frac{1}{n+1}x^{n+1} + C\$입니다. 이 공식과 앞서 언급한 부정적분의 선형성을 결합하면, 임의의 다항함수를 쉽게 적분할 수 있습니다. 예를 들어 \$\\\\int (ax^2 + bx + c) dx\$는 각 항을 따로 적분하여 \$\\\\frac{a}{3}x^3 + \\frac{b}{2}x^2 + cx + C\$와 같이 구할 수 있습니다.",   "예제: 다음 부정적분을 구하시오. \$\\\\int (6x^2 - 4x + 3) dx\$. 이 문제를 풀기 위해서는 부정적분의 덧셈과 뺄셈 성질을 이용하여 각 항을 분리합니다. 즉, \$\\\\int 6x^2 dx - \\\\int 4x dx + \\\\int 3 dx\$로 나누어 생각할 수 있습니다.",   "단계별 풀이: 먼저 각 항에 실수배 성질을 적용하여 상수를 밖으로 뺍니다. \$6 \\\\int x^2 dx - 4 \\\\int x^1 dx + 3 \\\\int x^0 dx\$가 됩니다. 이제 적분 공식을 적용하면 \$6 \\\\cdot \\\\frac{1}{3}x^3 - 4 \\\\cdot \\\\frac{1}{2}x^2 + 3x + C\$가 됩니다. 이를 정리하면 최종 결과는 \$2x^3 - 2x^2 + 3x + C\$가 됩니다." ]',
            ],
          ),
        ],
      ),
    ],
  ),
  '중복조합': BookData(
    id: 'concept_중복조합',
    title: '중복조합',
    subtitle: '공통수학1 > 경우의수 > 조합 > 중복조합',
    category: 'common',
    tags: ['공통수학1', '경우의수', '조합', '중복조합'],
    chapters: [
      BookChapter(
        title: '중복조합',
        intro: ['공통수학1 > 경우의수 > 조합 > 중복조합 개념 학습'],
        sections: [
          BookSection(
            title: '중복조합',
            paragraphs: [
              '[   "중복조합이란 서로 다른 \$n\$개에서 중복을 허용하여 \$r\$개를 택하는 경우의 수를 의미합니다. 일반적인 조합이 서로 다른 대상에서 순서를 고려하지 않고 뽑기만 하는 것이라면, 중복조합은 한 번 뽑은 대상을 다시 뽑을 수 있다는 점이 다릅니다. 예를 들어, 사과, 배, 귤 세 종류의 과일 중에서 중복을 허용하여 5개를 고르는 경우 등이 이에 해당합니다.",   "서로 다른 \$n\$개에서 \$r\$개를 택하는 중복조합의 수는 기호로 \$_nH_r\$과 같이 나타냅니다. 이 값은 수학적으로 조합의 수로 변환하여 계산할 수 있는데, 그 공식은 다음과 같습니다. \$\$_nH_r = {}_{n+r-1}C_r = \\frac{(n+r-1)!}{r!(n-1)!}\$\$ 이 공식은 중복 선택을 칸막이 모델로 해석하여 유도할 수 있으며, \$n\$개의 종류를 구분하는 \$n-1\$개의 칸막이와 \$r\$개의 선택 대상을 일렬로 나열하는 경우의 수와 동일한 원리를 가집니다.",   "중복조합의 성질 중 가장 중요한 것은 방정식의 해의 개수와 연결된다는 점입니다. 음이 아닌 정수 \$x_1, x_2, \\dots, x_n\$에 대하여 \$x_1 + x_2 + \\dots + x_n = r\$을 만족하는 해의 개수는 서로 다른 \$n\$개에서 중복을 허용하여 \$r\$개를 뽑는 중복조합의 수 \$_nH_r\$과 같습니다. 이는 실생활에서 물건을 나누어 주는 문제나 함수의 개수를 구하는 문제에 매우 유용하게 활용됩니다.",   "예제 문제: 서로 다른 3종류의 음료수(콜라, 사이다, 환타) 중에서 중복을 허용하여 5병을 사는 경우의 수를 구하시오. 이 문제는 서로 다른 3개(\$n=3\$)에서 중복을 허용하여 5개(\$r=5\$)를 택하는 중복조합의 문제입니다. 따라서 구하는 경우의 수는 \$_3H_5\$가 됩니다.",   "단계별 풀이: 먼저 중복조합 공식을 적용합니다. \$_3H_5 = {}_{3+5-1}C_5 = {}_7C_5\$입니다. 조합의 성질에 의해 \${}_7C_5 = {}_7C_2\$와 같으므로, 이를 계산하면 다음과 같습니다. \$\${}_7C_2 = \\frac{7 \\times 6}{2 \\times 1} = 21\$\$ 따라서 서로 다른 3종류의 음료수 중에서 5병을 사는 경우의 수는 총 21가지입니다." ]',
            ],
          ),
        ],
      ),
    ],
  ),
  '무한대의극한': BookData(
    id: 'concept_무한대의극한',
    title: '무한대의극한',
    subtitle: '미적분Ⅰ > 함수의극한 > 극한값계산 > 무한대의극한',
    category: 'common',
    tags: ['미적분Ⅰ', '함수의극한', '극한값계산', '무한대의극한'],
    chapters: [
      BookChapter(
        title: '무한대의극한',
        intro: ['미적분Ⅰ > 함수의극한 > 극한값계산 > 무한대의극한 개념 학습'],
        sections: [
          BookSection(
            title: '무한대의극한',
            paragraphs: [
              '함수의 극한에서 \'무한대(\$\\infty\$)\'란 어떤 값이 아니라, 변수 \$x\$가 한없이 커지거나 작아지는 상태를 의미합니다. \$x\$가 양의 방향으로 한없이 커질 때(\$x \\to \\infty\$) 또는 음의 방향으로 한없이 작아질 때(\$x \\to -\\infty\$), 함수 \$f(x)\$의 값이 일정한 값 \$L\$에 한없이 가까워지면 이를 \'함수의 극한값이 \$L\$이다\'라고 하며, 기호로 \$\\lim_{x \\to \\infty} f(x) = L\$ 또는 \$\\lim_{x \\to -\\infty} f(x) = L\$로 나타냅니다.',
              '무한대에서의 극한을 계산할 때 가장 중요한 성질은 분모의 차수가 분자의 차수보다 클 때 극한값은 0이 된다는 점입니다. 일반적으로 다항함수의 극한을 구할 때는 분모와 분자의 최고차항으로 각각 나누어 계산합니다. 특히 \$k > 0\$일 때, 다음의 기본 공식을 기억하면 편리합니다. \$\$ \\lim_{x \\to \\infty} \\frac{1}{x^k} = 0, \\quad \\lim_{x \\to \\infty} \\frac{c}{x^k} = 0 \\quad (c는 상수) \$\$ 이 원리를 이용하면 복잡한 분수식의 극한도 분모와 분자의 차수를 비교하여 쉽게 해결할 수 있습니다.',
              '만약 분수식에서 분모와 분자의 차수가 같다면, 극한값은 분모의 최고차항 계수와 분자의 최고차항 계수의 비가 됩니다. 예를 들어, \$f(x) = \\frac{ax^n + \\dots}{bx^n + \\dots}\$일 때, \$x\$가 무한대로 가면 불필요한 항들은 0으로 수렴하므로 결과적으로 \$\$ \\lim_{x \\to \\infty} \\frac{ax^n + \\dots}{bx^n + \\dots} = \\frac{a}{b} \$\$ 가 성립합니다. 이를 통해 우리는 식을 일일이 나누지 않고도 최고차항의 계수만 비교하여 극한값을 빠르게 찾아낼 수 있습니다.',
              '이제 구체적인 예제를 풀어봅시다. 다음 극한값을 구하시오: \$\\lim_{x \\to \\infty} \\frac{3x^2 + 5x}{2x^2 - 1}\$. 이 문제를 해결하기 위해 분모와 분자를 각각 \$x^2\$으로 나누어 봅니다. 식을 변형하면 다음과 같습니다. \$\$ \\lim_{x \\to \\infty} \\frac{\\frac{3x^2}{x^2} + \\frac{5x}{x^2}}{\\frac{2x^2}{x^2} - \\frac{1}{x^2}} = \\lim_{x \\to \\infty} \\frac{3 + \\frac{5}{x}}{2 - \\frac{1}{x^2}} \$\$',
              '위의 식에서 \$x\$가 무한대로 커지면 \$\\frac{5}{x}\$와 \$\\frac{1}{x^2}\$은 모두 0으로 수렴합니다. 따라서 극한값은 다음과 같이 계산됩니다. \$\$ \\lim_{x \\to \\infty} \\frac{3 + 0}{2 - 0} = \\frac{3}{2} \$\$ 이처럼 분모와 분자의 차수가 같을 때는 최고차항의 계수만 따져서 바로 \$\\frac{3}{2}\$이라는 결과를 얻을 수 있습니다. 이 방법을 익히면 복잡한 극한 문제도 자신 있게 해결할 수 있습니다.',
            ],
          ),
        ],
      ),
    ],
  ),
  '일대일대응': BookData(
    id: 'concept_일대일대응',
    title: '일대일대응',
    subtitle: '공통수학2 > 함수 > 역함수 > 일대일대응',
    category: 'common',
    tags: ['공통수학2', '함수', '역함수', '일대일대응'],
    chapters: [
      BookChapter(
        title: '일대일대응',
        intro: ['공통수학2 > 함수 > 역함수 > 일대일대응 개념 학습'],
        sections: [
          BookSection(
            title: '일대일대응',
            paragraphs: [
              '[   "함수에서 \'일대일대응\'이란, 정의역의 서로 다른 원소가 공역의 서로 다른 원소에 대응하는 \'일대일함수\'의 조건을 만족하면서, 동시에 공역과 치역이 일치하는 함수를 말합니다. 즉, 정의역의 모든 원소가 공역의 원소와 빠짐없이 하나씩 짝을 이루는 상태를 의미합니다. 이를 수학적으로 표현하면, 정의역의 임의의 두 원소 \$x_1, x_2\$에 대하여 \$x_1 \\neq x_2\$이면 \$f(x_1) \\neq f(x_2)\$를 만족하고, 동시에 공역의 모든 원소 \$y\$에 대하여 \$f(x)=y\$를 만족하는 \$x\$가 정의역에 반드시 존재해야 합니다.",   "일대일대응이 성립하기 위한 핵심 조건은 그래프의 형태에서 잘 드러납니다. 함수가 일대일대응이려면 그래프가 항상 증가하거나 항상 감소하는 형태여야 합니다. 만약 그래프가 중간에 꺾이거나 위아래로 진동한다면, 가로선(x축과 평행한 직선)을 그었을 때 그래프와 두 점 이상에서 만나거나 아예 만나지 않는 구간이 생기기 때문입니다. 또한, 일대일대응인 함수만이 역함수를 가질 수 있다는 점은 매우 중요한 성질입니다. 역함수가 존재하기 위해서는 모든 출력값에 대해 유일한 입력값이 대응되어야 하기 때문입니다.",   "실수 전체의 집합에서 정의된 함수 \$f(x) = ax + b\$ (\$a \\neq 0\$)가 일대일대응이 되기 위한 조건은 무엇일까요? 일차함수의 그래프는 직선이므로, 기울기 \$a\$가 \$0\$이 아니면 항상 일대일대응이 됩니다. 하지만 정의역과 공역이 제한된 구간으로 주어질 때는 주의가 필요합니다. 예를 들어, 정의역이 \$\\{x | x_1 \\le x \\le x_2\\}\$이고 공역이 \$\\{y | y_1 \\le y \\le y_2\\}\$인 함수 \$f(x) = ax + b\$가 일대일대응이 되려면, \$f(x_1)\$과 \$f(x_2)\$가 각각 \$y_1\$과 \$y_2\$에 대응되어야 합니다. 즉, \$\$f(x_1) = y_1, f(x_2) = y_2 \\quad (\\text{단조 증가})\$\$ 또는 \$\$f(x_1) = y_2, f(x_2) = y_1 \\quad (\\text{단조 감소})\$\$를 만족해야 합니다.",   "이제 구체적인 예제를 풀어봅시다. 정의역이 \$\\{x | 0 \\le x \\le 2\\}\$이고 공역이 \$\\{y | 1 \\le y \\le 5\\}\$인 함수 \$f(x) = ax + b\$ (\$a > 0\$)가 일대일대응이 되도록 하는 상수 \$a, b\$의 값을 구해보겠습니다. 함수가 일대일대응이 되려면 정의역의 양 끝값이 공역의 양 끝값에 각각 대응되어야 합니다. \$a > 0\$이므로 함수는 증가함수여야 하며, 따라서 \$f(0) = 1\$이고 \$f(2) = 5\$를 만족해야 합니다.",   "단계별 풀이를 진행하면 다음과 같습니다. 첫째, \$f(0) = a(0) + b = 1\$에서 \$b = 1\$임을 바로 알 수 있습니다. 둘째, 구한 \$b\$의 값을 \$f(2) = 5\$에 대입합니다. 즉, \$a(2) + 1 = 5\$가 성립합니다. 이를 정리하면 \$2a = 4\$가 되어 \$a = 2\$를 얻습니다. 결과적으로 \$a=2, b=1\$일 때 이 함수는 주어진 구간에서 일대일대응이 됩니다. 이처럼 일대일대응 문제는 그래프의 양 끝점을 연결하는 직선의 기울기와 절편을 찾는 과정으로 이해하면 쉽습니다." ]',
            ],
          ),
        ],
      ),
    ],
  ),
  '판별식과근의개수': BookData(
    id: 'concept_판별식과근의개수',
    title: '판별식과근의개수',
    subtitle: '공통수학1 > 이차방정식 > 이차방정식의판별식 > 판별식과근의개수',
    category: 'common',
    tags: ['공통수학1', '이차방정식', '이차방정식의판별식', '판별식과근의개수'],
    chapters: [
      BookChapter(
        title: '판별식과근의개수',
        intro: ['공통수학1 > 이차방정식 > 이차방정식의판별식 > 판별식과근의개수 개념 학습'],
        sections: [
          BookSection(
            title: '판별식과근의개수',
            paragraphs: [
              '이차방정식 \$ax^2 + bx + c = 0\$ (\$a \\neq 0\$)의 해를 구하는 근의 공식은 \$x = \\frac{-b \\pm \\sqrt{b^2 - 4ac}}{2a}\$입니다. 여기서 근호(\$\\sqrt{\\quad}\$) 안에 있는 식 \$b^2 - 4ac\$는 근의 종류와 개수를 결정하는 매우 중요한 역할을 합니다. 이 식을 이차방정식의 \'판별식\'이라 부르며, 보통 알파벳 \$D\$로 나타냅니다. 즉, \$D = b^2 - 4ac\$입니다.',
              '판별식 \$D\$의 값에 따라 근의 개수는 다음과 같이 결정됩니다. 첫째, \$D > 0\$이면 서로 다른 두 실근을 갖습니다. 둘째, \$D = 0\$이면 근호 안이 0이 되어 \$x = -b/2a\$라는 하나의 실근, 즉 중근을 갖습니다. 셋째, \$D < 0\$이면 근호 안이 음수가 되어 실수 범위에서는 근이 존재하지 않으며, 서로 다른 두 허근을 갖게 됩니다. 이처럼 판별식은 방정식을 직접 풀지 않고도 근의 성질을 미리 파악할 수 있게 해줍니다.',
              '만약 이차방정식의 일차항의 계수 \$b\$가 짝수라면, \$b = 2b\'\$로 나타낼 수 있습니다. 이때 판별식 \$D = (2b\')^2 - 4ac = 4(b\'^2 - ac)\$가 되는데, 여기서 4를 제외한 \$D/4 = b\'^2 - ac\$를 사용하여 판별해도 결과는 동일합니다. 이를 \'짝수 공식 판별식\'이라고 하며, 계산을 훨씬 간편하게 만들어 줍니다.',
              '예제 문제: 이차방정식 \$x^2 - 4x + 3 = 0\$의 근의 개수를 판별해 봅시다. 먼저 계수를 확인하면 \$a=1, b=-4, c=3\$입니다. 판별식 \$D = b^2 - 4ac\$에 대입하면 \$D = (-4)^2 - 4 \\times 1 \\times 3 = 16 - 12 = 4\$가 됩니다. \$D > 0\$이므로 이 방정식은 서로 다른 두 실근을 가짐을 알 수 있습니다.',
              '또 다른 예제로 \$x^2 + 2x + 5 = 0\$의 경우를 살펴봅시다. 여기서는 일차항의 계수가 2로 짝수이므로 \$b\'=1\$을 사용하여 \$D/4 = b\'^2 - ac\$를 적용합니다. \$D/4 = 1^2 - 1 \\times 5 = 1 - 5 = -4\$입니다. \$D/4 < 0\$이므로 이 방정식은 실수 범위에서 해가 없으며, 서로 다른 두 허근을 갖는다는 결론을 얻을 수 있습니다.',
            ],
          ),
        ],
      ),
    ],
  ),
  'y방향이동': BookData(
    id: 'concept_y방향이동',
    title: 'y방향이동',
    subtitle: '공통수학2 > 원의방정식 > 평행이동 > y방향이동',
    category: 'common',
    tags: ['공통수학2', '원의방정식', '평행이동', 'y방향이동'],
    chapters: [
      BookChapter(
        title: 'y방향이동',
        intro: ['공통수학2 > 원의방정식 > 평행이동 > y방향이동 개념 학습'],
        sections: [
          BookSection(
            title: 'y방향이동',
            paragraphs: [
              '평행이동이란 도형의 모양과 크기를 바꾸지 않고 일정한 방향으로 옮기는 것을 말합니다. 그중에서도 \$y\$축 방향으로의 평행이동은 좌표평면 위의 모든 점 \$(x, y)\$를 \$y\$축 방향으로 \$b\$만큼 옮겨 새로운 점 \$(x, y+b)\$로 대응시키는 변환입니다. 이때 도형의 방정식 \$f(x, y) = 0\$을 \$y\$축 방향으로 \$b\$만큼 평행이동하면, 새로운 방정식은 \$f(x, y-b) = 0\$이 됩니다.',
              '왜 \$y\$ 대신 \$y-b\$를 대입하는지 궁금할 수 있습니다. 원래의 점을 \$(x, y)\$, 이동한 점을 \$(x\', y\')\$라고 하면 \$x\'=x\$, \$y\'=y+b\$라는 관계가 성립합니다. 이를 \$x\$와 \$y\$에 대해 정리하면 \$x=x\'\$, \$y=y\'-b\$가 됩니다. 따라서 원래의 방정식 \$f(x, y)=0\$에 이 식들을 대입하면 \$f(x\', y\'-b)=0\$이 되며, 좌표평면 위에서 \$x\', y\'\$는 일반적인 변수 \$x, y\$로 표현할 수 있으므로 최종적으로 \$\$f(x, y-b) = 0\$\$이라는 공식이 유도되는 것입니다.',
              '원의 방정식을 예로 들어보면, 중심이 \$(a, b)\$이고 반지름의 길이가 \$r\$인 원의 방정식은 \$\$(x-a)^2 + (y-b)^2 = r^2\$\$입니다. 이 원을 \$y\$축 방향으로 \$k\$만큼 평행이동하면, \$y\$ 자리에 \$y-k\$를 대입하여 \$\$(x-a)^2 + (y-k-b)^2 = r^2\$\$이 됩니다. 즉, 원의 중심은 \$(a, b+k)\$로 변하지만 반지름의 길이는 그대로 \$r\$을 유지한다는 성질을 확인할 수 있습니다.',
              '이제 구체적인 예제를 풀어봅시다. 중심이 \$(2, 3)\$이고 반지름의 길이가 \$1\$인 원의 방정식은 \$\$(x-2)^2 + (y-3)^2 = 1\$\$입니다. 이 원을 \$y\$축 방향으로 \$-4\$만큼 평행이동했을 때의 방정식을 구해보겠습니다. 평행이동의 원리에 따라 \$y\$ 대신 \$y-(-4)\$, 즉 \$y+4\$를 대입합니다.',
              '단계별 풀이는 다음과 같습니다. 먼저 주어진 원의 방정식 \$\$(x-2)^2 + (y-3)^2 = 1\$\$에서 \$y\$를 \$y+4\$로 바꿉니다. 그러면 \$\$(x-2)^2 + ((y+4)-3)^2 = 1\$\$이 됩니다. 식을 정리하면 \$\$(x-2)^2 + (y+1)^2 = 1\$\$이 됩니다. 따라서 평행이동한 원의 중심은 \$(2, -1)\$이 되고 반지름은 여전히 \$1\$임을 알 수 있습니다.',
            ],
          ),
        ],
      ),
    ],
  ),
  '지수부등식': BookData(
    id: 'concept_지수부등식',
    title: '지수부등식',
    subtitle: '대수 > 지수방정식과지수부등식 > 지수부등식',
    category: 'common',
    tags: ['대수', '지수방정식과지수부등식', '지수부등식'],
    chapters: [
      BookChapter(
        title: '지수부등식',
        intro: ['대수 > 지수방정식과지수부등식 > 지수부등식 개념 학습'],
        sections: [
          BookSection(
            title: '지수부등식',
            paragraphs: [
              '지수부등식이란 지수에 미지수가 포함되어 있는 부등식을 말합니다. 이 부등식을 풀기 위해서는 먼저 밑을 통일하는 것이 가장 중요합니다. 밑을 통일한 후에는 지수끼리 비교하게 되는데, 이때 밑의 크기에 따라 부등호의 방향이 결정된다는 점을 반드시 기억해야 합니다. 밑이 1보다 크면 지수가 클수록 전체 값도 커지지만, 밑이 0과 1 사이의 수라면 지수가 클수록 전체 값은 오히려 작아지기 때문입니다.',
              '구체적인 성질을 공식으로 나타내면 다음과 같습니다. 밑이 \$a > 1\$인 경우, 지수부등식 \$a^{f(x)} > a^{g(x)}\$는 지수끼리 비교할 때 부등호 방향이 그대로 유지되어 \$f(x) > g(x)\$가 됩니다. 반면, 밑이 \$0 < a < 1\$인 경우, \$a^{f(x)} > a^{g(x)}\$는 지수끼리 비교할 때 부등호 방향이 반대로 바뀌어 \$f(x) < g(x)\$가 됩니다. 이 원리를 이용하면 복잡한 지수 형태의 부등식도 다항식의 부등식 문제로 바꾸어 쉽게 해결할 수 있습니다.',
              '이제 예제를 통해 직접 풀어봅시다. 부등식 \$2^{x+1} < 8^{x-1}\$을 풀어보겠습니다. 먼저 양변의 밑을 2로 통일해야 합니다. 우변의 8은 \$2^3\$이므로, 주어진 식은 \$2^{x+1} < (2^3)^{x-1}\$이 됩니다. 지수법칙에 의해 우변을 정리하면 \$2^{x+1} < 2^{3x-3}\$으로 쓸 수 있습니다.',
              '이제 밑이 2로 같아졌고, 2는 1보다 크므로 지수끼리 비교할 때 부등호 방향을 그대로 유지합니다. 따라서 \$x + 1 < 3x - 3\$이라는 일차부등식을 얻게 됩니다. 이 식을 정리하면 \$1 + 3 < 3x - x\$가 되어 \$4 < 2x\$가 되고, 양변을 2로 나누면 최종적으로 \$x > 2\$라는 해를 구할 수 있습니다.',
              '또 다른 유형으로 밑이 0과 1 사이인 경우를 살펴봅시다. 부등식 \$(\\frac{1}{3})^{2x-1} \\ge (\\frac{1}{3})^{x+2}\$를 풀어봅시다. 여기서는 밑이 \$\\frac{1}{3}\$로 0과 1 사이의 값이므로, 지수끼리 비교할 때 부등호의 방향이 반대로 바뀝니다. 즉, \$2x - 1 \\le x + 2\$가 성립합니다.',
              '마지막으로 이 일차부등식을 풀면 \$2x - x \\le 2 + 1\$이 되어 \$x \\le 3\$이라는 결과를 얻습니다. 이처럼 지수부등식을 풀 때는 항상 밑이 1보다 큰지, 아니면 0과 1 사이인지를 먼저 확인하여 부등호 방향을 결정하는 습관을 들이는 것이 실수를 줄이는 가장 좋은 방법입니다.',
            ],
          ),
        ],
      ),
