              '행렬의 크기를 나타낼 때는 보통 (행의 개수) \$\\times\$ (열의 개수)의 형태로 표기합니다. 만약 행이 \$m\$개이고 열이 \$n\$개인 행렬 \$A\$가 있다면, 이를 \$m \\times n\$ 행렬이라고 부릅니다. 행렬 \$A\$의 제\$i\$행 제\$j\$열에 있는 성분을 \$a_{ij}\$라고 할 때, 행의 번호인 \$i\$는 \$1\$부터 \$m\$까지, 열의 번호인 \$j\$는 \$1\$부터 \$n\$까지의 값을 가집니다. 즉, 행은 행렬 내에서 특정 성분의 위치를 지정하는 첫 번째 좌표 역할을 합니다.',
