              '로그부등식을 풀 때 가장 중요한 것은 로그의 밑 \$a\$의 크기입니다. 밑 \$a\$가 1보다 크면(\$a > 1\$) 부등호의 방향이 그대로 유지되지만, 밑이 0과 1 사이(\$0 < a < 1\$)라면 부등호의 방향이 반대로 바뀝니다. 즉, \$\\log_a f(x) > \\log_a g(x)\$일 때, \$a > 1\$이면 \$f(x) > g(x)\$가 되지만, \$0 < a < 1\$이면 \$f(x) < g(x)\$가 됩니다.',
              '로그부등식의 성질을 정리하면 다음과 같습니다. 첫째, \$\\log_a f(x) > b\$ 꼴은 \$b\$를 \$\\log_a a^b\$로 바꾸어 비교합니다. 둘째, 공통된 로그 식이 반복되는 경우에는 치환을 이용합니다. 이때 치환한 문자의 범위를 설정하는 것이 매우 중요합니다. 마지막으로, 모든 과정이 끝난 후에는 처음에 확인했던 진수 조건과 최종 해의 교집합을 구해야 비로소 정확한 답이 됩니다.',
              '예제: 부등식 \$\\log_2 (x-1) < 3\$을 풀어봅시다. 먼저 진수 조건에 의해 \$x-1 > 0\$, 즉 \$x > 1\$이어야 합니다. 우변의 3을 밑이 2인 로그로 바꾸면 \$3 = \\log_2 2^3 = \\log_2 8\$이 됩니다. 따라서 부등식은 \$\\log_2 (x-1) < \\log_2 8\$이 됩니다.',
              '이제 밑이 2로 1보다 크므로 부등호 방향을 그대로 유지하여 \$x-1 < 8\$을 얻습니다. 이를 풀면 \$x < 9\$가 됩니다. 마지막으로 진수 조건인 \$x > 1\$과 구한 해 \$x < 9\$를 동시에 만족해야 하므로, 최종적인 해는 \$1 < x < 9\$가 됩니다.',
