    chapters: [
      BookChapter(
        title: '정적분의선형성',
        intro: ['미적분Ⅰ > 정적분 > 정적분의성질 > 정적분의선형성 개념 학습'],
        sections: [
          BookSection(
            title: '정적분의선형성',
            paragraphs: [
              '정적분의 선형성이란, 정적분 기호 안에서 함수의 합이나 차, 그리고 실수배를 자유롭게 분리하거나 묶을 수 있는 성질을 의미합니다. 이는 마치 우리가 다항식을 계산할 때 동류항을 정리하거나 괄호를 푸는 것과 매우 유사한 논리입니다. 즉, 적분 기호 \$\\int_a^b\$는 함수들의 합이나 실수배에 대해 마치 연산자처럼 작용하여, 복잡한 식을 간단한 여러 개의 적분으로 나누어 계산할 수 있게 해줍니다.',
              '구체적으로 두 함수 \$f(x)\$와 \$g(x)\$가 구간 \$[a, b]\$에서 연속일 때, 임의의 실수 \$k\$와 \$l\$에 대하여 정적분의 선형성은 다음과 같은 공식으로 표현됩니다. 첫째, 함수에 곱해진 실수배는 적분 기호 밖으로 꺼낼 수 있습니다. \$\$\\int_a^b k f(x) dx = k \\int_a^b f(x) dx\$\$ 둘째, 두 함수의 합이나 차에 대한 정적분은 각각의 정적분의 합이나 차와 같습니다. \$\$\\int_a^b \\{f(x) \\pm g(x)\\} dx = \\int_a^b f(x) dx \\pm \\int_a^b g(x) dx\$\$ 이 두 가지 성질을 결합하면, \$\$\\int_a^b \\{k f(x) + l g(x)\\} dx = k \\int_a^b f(x) dx + l \\int_a^b g(x) dx\$\$ 와 같이 일반화할 수 있습니다.',
              '이제 예제를 통해 이 성질을 적용해 보겠습니다. 구간 \$[0, 1]\$에서 함수 \$f(x) = 3x^2 + 2x\$를 적분하는 문제를 생각해 봅시다. 정적분의 선형성을 이용하면 이 식을 두 개의 간단한 적분으로 분리할 수 있습니다. \$\$\\int_0^1 (3x^2 + 2x) dx = \\int_0^1 3x^2 dx + \\int_0^1 2x dx\$\$ 여기서 각 항의 계수를 밖으로 빼내면 계산이 더욱 명확해집니다. \$\$\\int_0^1 3x^2 dx + \\int_0^1 2x dx = 3 \\int_0^1 x^2 dx + 2 \\int_0^1 x dx\$\$',
              '마지막으로, 분리된 적분을 각각 계산하여 최종 답을 구합니다. 먼저 \$x^2\$의 부정적분은 \$\\frac{1}{3}x^3\$이고, \$x\$의 부정적분은 \$\\frac{1}{2}x^2\$임을 이용합니다. 이를 대입하면 다음과 같습니다. \$\$3 \\left[ \\frac{1}{3}x^3 \\right]_0^1 + 2 \\left[ \\frac{1}{2}x^2 \\right]_0^1 = 3 \\left( \\frac{1}{3} - 0 \\right) + 2 \\left( \\frac{1}{2} - 0 \\right)\$\$ 이 식을 정리하면 \$1 + 1 = 2\$라는 결과를 얻을 수 있습니다. 이처럼 선형성을 활용하면 복잡한 다항식의 정적분을 훨씬 체계적이고 실수 없이 해결할 수 있습니다.',
            ],
          ),
        ],
      ),
    ],
  ),
  '근과계수의관계': BookData(
    id: 'concept_근과계수의관계',
    title: '근과계수의관계',
    subtitle: '공통수학1 > 이차방정식 > 이차방정식의근과계수 > 근과계수의관계',
    category: 'common',
    tags: ['공통수학1', '이차방정식', '이차방정식의근과계수', '근과계수의관계'],
    chapters: [
      BookChapter(
        title: '근과계수의관계',
        intro: ['공통수학1 > 이차방정식 > 이차방정식의근과계수 > 근과계수의관계 개념 학습'],
        sections: [
          BookSection(
            title: '근과계수의관계',
            paragraphs: [
              '이차방정식 \$ax^2 + bx + c = 0\$ (단, \$a \\neq 0\$)에서 두 근을 \$\\alpha, \\beta\$라고 할 때, 근과 계수의 관계는 방정식의 해를 직접 구하지 않고도 계수들만으로 두 근의 합과 곱을 바로 알아낼 수 있는 매우 유용한 성질입니다. 이차방정식의 근의 공식에 의해 두 근은 \$\\frac{-b \\pm \\sqrt{b^2 - 4ac}}{2a}\$로 표현되는데, 이 두 값을 더하거나 곱하면 복잡한 근호 부분이 사라지고 계수들 사이의 간단한 관계식이 도출됩니다.',
              '구체적인 공식은 다음과 같습니다. 두 근의 합은 \$\$\\alpha + \\beta = -\\frac{b}{a}\$\$ 이고, 두 근의 곱은 \$\$\\alpha \\beta = \\frac{c}{a}\$\$ 입니다. 이 공식은 이차방정식의 두 근을 \$\\alpha, \\beta\$라고 할 때, 이차방정식이 \$a(x - \\alpha)(x - \\beta) = 0\$으로 인수분해된다는 점을 이용하면 쉽게 유도할 수 있습니다. 이를 전개하면 \$a(x^2 - (\\alpha + \\beta)x + \\alpha \\beta) = 0\$이 되며, 원래의 식 \$ax^2 + bx + c = 0\$과 비교하면 위 공식이 성립함을 알 수 있습니다.',
              '예제 문제: 이차방정식 \$x^2 - 5x + 6 = 0\$의 두 근을 \$\\alpha, \\beta\$라고 할 때, \$\\alpha^2 + \\beta^2\$의 값을 구하시오. 이 문제를 풀기 위해서는 먼저 근과 계수의 관계를 사용하여 두 근의 합과 곱을 구해야 합니다. 주어진 방정식에서 \$a=1, b=-5, c=6\$이므로, 합은 \$\$\\alpha + \\beta = -\\frac{-5}{1} = 5\$\$ 이고, 곱은 \$\$\\alpha \\beta = \\frac{6}{1} = 6\$\$ 입니다.',
              '이제 구하고자 하는 식 \$\\alpha^2 + \\beta^2\$을 곱셈 공식의 변형을 이용하여 나타냅니다. 곱셈 공식에 의해 \$\$\\alpha^2 + \\beta^2 = (\\alpha + \\beta)^2 - 2\\alpha \\beta\$\$ 가 성립합니다. 여기에 앞서 구한 합과 곱의 값을 대입하면 \$5^2 - 2 \\times 6\$이 됩니다. 따라서 최종 계산 결과는 \$25 - 12 = 13\$이 되어, 정답은 \$13\$입니다.',
            ],
          ),
        ],
      ),
