    title: '연속함수의성질',
    subtitle: '미적분Ⅰ > 함수의연속 > 연속함수의성질',
    category: 'common',
    tags: ['미적분Ⅰ', '함수의연속', '연속함수의성질'],
    chapters: [
      BookChapter(
        title: '연속함수의성질',
        intro: ['미적분Ⅰ > 함수의연속 > 연속함수의성질 개념 학습'],
        sections: [
          BookSection(
            title: '연속함수의성질',
            paragraphs: [
              '함수 \$f(x)\$가 어떤 구간에서 연속일 때, 그 구간 내의 모든 점에서 함숫값과 극한값이 일치합니다. 연속함수의 성질이란, 두 함수 \$f(x)\$와 \$g(x)\$가 \$x=a\$에서 연속일 때, 이 두 함수를 더하거나, 빼거나, 곱하거나, 나누어도 그 결과 역시 \$x=a\$에서 연속이 된다는 것을 의미합니다. 단, 나눗셈의 경우 분모가 되는 함수 \$g(a)\$가 \$0\$이 아니어야 한다는 조건이 반드시 필요합니다.',
              '이를 수학적으로 정리하면 다음과 같습니다. 두 함수 \$f(x)\$와 \$g(x)\$가 \$x=a\$에서 연속일 때, 다음 함수들도 모두 \$x=a\$에서 연속입니다. 첫째, 상수 \$k\$에 대하여 \$k f(x)\$가 연속입니다. 둘째, \$f(x) + g(x)\$와 \$f(x) - g(x)\$가 연속입니다. 셋째, \$f(x)g(x)\$가 연속입니다. 마지막으로, \$g(a) \\neq 0\$일 때, 몫인 \$\\frac{f(x)}{g(x)}\$도 \$x=a\$에서 연속입니다.',
              '이러한 성질은 다항함수나 유리함수와 같은 복잡한 함수의 연속성을 판별할 때 매우 유용합니다. 예를 들어, 모든 다항함수는 실수 전체의 집합에서 연속이므로, 두 다항함수의 합, 차, 곱 또한 실수 전체에서 연속입니다. 유리함수의 경우에는 분모가 \$0\$이 되는 점을 제외한 모든 구간에서 연속함수의 성질을 그대로 적용할 수 있습니다.',
              '이제 예제를 통해 확인해 봅시다. 두 함수 \$f(x) = x^2 + 1\$과 \$g(x) = x - 3\$이 주어졌을 때, 새로운 함수 \$h(x) = f(x)g(x)\$가 \$x=2\$에서 연속인지 확인해 봅시다. 먼저 \$f(2) = 2^2 + 1 = 5\$이고, \$g(2) = 2 - 3 = -1\$입니다. 두 함수는 다항함수이므로 \$x=2\$에서 각각 연속입니다.',
              '연속함수의 성질에 따라, 두 연속함수의 곱인 \$h(x) = (x^2 + 1)(x - 3)\$ 역시 \$x=2\$에서 연속입니다. 실제로 함숫값을 구해보면 \$h(2) = f(2) \\times g(2) = 5 \\times (-1) = -5\$가 됩니다. 극한값 \$\\lim_{x \\to 2} h(x)\$ 또한 \$\\lim_{x \\to 2} (x^2 + 1)(x - 3) = 5 \\times (-1) = -5\$로 일치하므로, \$h(x)\$는 \$x=2\$에서 연속임을 알 수 있습니다.',
              '마지막으로 나눗셈의 경우를 살펴봅시다. \$f(x) = x^2\$이고 \$g(x) = x - 1\$일 때, \$F(x) = \\frac{f(x)}{g(x)}\$가 \$x=2\$에서 연속인지 판단해 봅시다. \$f(2) = 4\$이고 \$g(2) = 1\$입니다. \$g(2) \\neq 0\$이므로 연속함수의 성질에 의해 \$F(x)\$는 \$x=2\$에서 연속입니다. 따라서 \$F(2) = \\frac{f(2)}{g(2)} = \\frac{4}{1} = 4\$가 되어, 이 함수는 \$x=2\$를 포함하는 어떤 열린 구간에서 연속성을 유지합니다.',
            ],
          ),
        ],
      ),
    ],
  ),
  '유리식의계산': BookData(
    id: 'concept_유리식의계산',
    title: '유리식의계산',
    subtitle: '공통수학2 > 유리식과유리함수 > 유리식 > 유리식의계산',
    category: 'common',
    tags: ['공통수학2', '유리식과유리함수', '유리식', '유리식의계산'],
    chapters: [
      BookChapter(
        title: '유리식의계산',
        intro: ['공통수학2 > 유리식과유리함수 > 유리식 > 유리식의계산 개념 학습'],
        sections: [
          BookSection(
            title: '유리식의계산',
            paragraphs: [
              '유리식이란 다항식 \$A\$와 \$B\$(\$B \\neq 0\$)에 대하여 분수 꼴인 \$\\frac{A}{B}\$로 나타낼 수 있는 식을 말합니다. 유리식의 계산은 우리가 초등학교 때 배운 분수의 계산 원리와 매우 유사합니다. 가장 먼저 기억해야 할 성질은 분모와 분자에 0이 아닌 같은 다항식을 곱하거나 나누어도 유리식의 값은 변하지 않는다는 점입니다. 이를 이용하여 복잡한 유리식을 약분하거나 통분하여 간단히 정리할 수 있습니다. 즉, \$\\frac{A \\times C}{B \\times C} = \\frac{A}{B}\$ (단, \$C \\neq 0\$)의 성질을 활용합니다.',
              '유리식의 덧셈과 뺄셈을 할 때는 분모가 다르면 분모의 최소공배수를 찾아 통분해야 합니다. 분모가 같을 때는 분자끼리 더하거나 빼면 됩니다. 곱셈은 분자는 분자끼리, 분모는 분모끼리 곱하여 정리하고, 나눗셈은 나누는 식의 분자와 분모를 뒤집어 역수를 취한 뒤 곱셈으로 바꾸어 계산합니다. 이때 모든 계산 과정에서 분모가 0이 되는 경우는 제외해야 한다는 점을 항상 유의해야 합니다.',
              '예제 1번입니다. 다음 식을 간단히 계산해 봅시다. \$\\frac{x}{x^2-1} + \\frac{1}{x+1}\$. 먼저 분모를 인수분해하면 \$x^2-1 = (x-1)(x+1)\$임을 알 수 있습니다. 따라서 두 분수의 분모를 \$(x-1)(x+1)\$로 통분합니다. 첫 번째 식은 그대로 두고, 두 번째 식의 분모와 분자에 \$(x-1)\$을 곱합니다.',
              '단계별 풀이를 진행하면 다음과 같습니다. \$\\frac{x}{(x-1)(x+1)} + \\frac{1(x-1)}{(x+1)(x-1)} = \\frac{x + x - 1}{(x-1)(x+1)}\$. 이를 정리하면 최종 결과는 \$\\frac{2x-1}{x^2-1}\$이 됩니다. 이처럼 분모를 인수분해하여 공통인수를 찾는 것이 유리식 계산의 핵심입니다.',
              '예제 2번입니다. 다음 곱셈과 나눗셈을 계산해 봅시다. \$\\frac{x^2}{x+2} \\div \\frac{x}{x^2-4}\$. 나눗셈은 역수의 곱셈으로 바꿀 수 있으므로 \$\\frac{x^2}{x+2} \\times \\frac{x^2-4}{x}\$가 됩니다. 여기서 \$x^2-4\$는 합차 공식에 의해 \$(x-2)(x+2)\$로 인수분해됩니다.',
              '이제 식을 다시 쓰면 \$\\frac{x^2}{x+2} \\times \\frac{(x-2)(x+2)}{x}\$입니다. 여기서 분모의 \$(x+2)\$와 분자의 \$(x+2)\$를 약분하고, 분자의 \$x^2\$과 분모의 \$x\$를 약분합니다. 남은 식을 정리하면 \$x(x-2)\$가 되어 최종 답은 \$x^2-2x\$가 됩니다. 이와 같이 유리식 계산에서는 인수분해와 약분을 적절히 활용하는 연습이 매우 중요합니다.',
            ],
          ),
        ],
      ),
    ],
  ),
  '원점대칭': BookData(
    id: 'concept_원점대칭',
    title: '원점대칭',
    subtitle: '공통수학2 > 원의방정식 > 대칭이동 > 원점대칭',
    category: 'common',
    tags: ['공통수학2', '원의방정식', '대칭이동', '원점대칭'],
    chapters: [
      BookChapter(
        title: '원점대칭',
        intro: ['공통수학2 > 원의방정식 > 대칭이동 > 원점대칭 개념 학습'],
        sections: [
          BookSection(
            title: '원점대칭',
            paragraphs: [
              '좌표평면에서 어떤 점이나 도형을 원점 \$(0, 0)\$을 중심으로 180도 회전시켰을 때, 그 위치를 원점대칭 이동이라고 합니다. 점 \$P(x, y)\$를 원점에 대하여 대칭이동한 점을 \$P\'(x\', y\')\$라고 하면, 원점은 선분 \$PP\'\$의 중점이 됩니다. 따라서 중점 공식에 의해 \$\\frac{x+x\'}{2} = 0\$이고 \$\\frac{y+y\'}{2} = 0\$이 성립하며, 이를 정리하면 \$x\' = -x\$, \$y\' = -y\$라는 결과를 얻을 수 있습니다.',
              '즉, 점 \$(x, y)\$를 원점에 대하여 대칭이동하면 그 좌표는 \$(-x, -y)\$가 됩니다. 이러한 성질은 도형의 방정식에서도 동일하게 적용됩니다. 방정식 \$f(x, y) = 0\$이 나타내는 도형을 원점에 대하여 대칭이동하면, \$x\$ 대신 \$-x\$를, \$y\$ 대신 \$-y\$를 대입하여 \$f(-x, -y) = 0\$이라는 새로운 방정식을 얻게 됩니다. 이는 원점대칭이 \$x\$축 대칭이동과 \$y\$축 대칭이동을 순서에 상관없이 연속으로 수행한 것과 같은 효과를 내기 때문입니다.',
              '예를 들어, 중심이 \$(a, b)\$이고 반지름의 길이가 \$r\$인 원의 방정식 \$(x-a)^2 + (y-b)^2 = r^2\$을 원점에 대하여 대칭이동해 봅시다. 위에서 배운 원리에 따라 \$x\$ 자리에 \$-x\$를, \$y\$ 자리에 \$-y\$를 대입하면 \$(-x-a)^2 + (-y-b)^2 = r^2\$이 됩니다. 식을 정리하면 \$(x+a)^2 + (y+b)^2 = r^2\$이 되어, 원의 중심이 \$(a, b)\$에서 \$(-a, -b)\$로 이동함을 확인할 수 있습니다.',
              '이제 구체적인 예제를 풀어보겠습니다. 점 \$A(3, -2)\$를 원점에 대하여 대칭이동한 점 \$A\'\$의 좌표를 구하는 문제입니다. 원점대칭의 정의에 따라 점 \$(x, y)\$는 \$(-x, -y)\$로 이동합니다. 따라서 \$x\$ 좌표인 \$3\$은 \$-3\$으로, \$y\$ 좌표인 \$-2\$는 \$-(-2) = 2\$로 바뀝니다. 그러므로 구하는 점 \$A\'\$의 좌표는 \$(-3, 2)\$가 됩니다.',
              '다음으로 도형의 방정식을 이용한 예제입니다. 직선 \$2x - 3y + 6 = 0\$을 원점에 대하여 대칭이동한 직선의 방정식을 구해 봅시다. 원점대칭을 위해서는 원래 식의 \$x\$에 \$-x\$를, \$y\$에 \$-y\$를 대입해야 합니다. 식에 대입하면 \$2(-x) - 3(-y) + 6 = 0\$이 됩니다. 이를 정리하면 \$-2x + 3y + 6 = 0\$이 되며, 양변에 \$-1\$을 곱하여 정리하면 \$2x - 3y - 6 = 0\$이라는 최종적인 직선의 방정식을 얻을 수 있습니다.',
            ],
          ),
        ],
      ),
    ],
  ),
  '행렬의덧셈': BookData(
    id: 'concept_행렬의덧셈',
    title: '행렬의덧셈',
    subtitle: '공통수학1 > 행렬 > 행렬의연산 > 행렬의덧셈',
    category: 'common',
    tags: ['공통수학1', '행렬', '행렬의연산', '행렬의덧셈'],
    chapters: [
      BookChapter(
        title: '행렬의덧셈',
        intro: ['공통수학1 > 행렬 > 행렬의연산 > 행렬의덧셈 개념 학습'],
        sections: [
          BookSection(
            title: '행렬의덧셈',
            paragraphs: [
              '행렬의 덧셈은 같은 크기를 가진 두 행렬 사이에서만 정의됩니다. 행렬의 크기가 같다는 것은 행의 개수와 열의 개수가 각각 서로 같다는 것을 의미합니다. 두 행렬 \$A\$와 \$B\$를 더할 때, 우리는 각 행렬의 같은 위치에 있는 성분끼리 서로 더하여 새로운 행렬을 만듭니다. 이때 결과로 나오는 행렬의 크기 또한 원래의 행렬들과 동일합니다.',
              '행렬 \$A = \\begin{pmatrix} a & b \\\\ c & d \\end{pmatrix}\$와 \$B = \\begin{pmatrix} e & f \\\\ g & h \\end{pmatrix}\$가 있을 때, 두 행렬의 합 \$A+B\$는 다음과 같이 정의됩니다. \$\$A+B = \\begin{pmatrix} a+e & b+f \\\\ c+g & d+h \\end{pmatrix}\$\$ 이처럼 행렬의 덧셈은 각 성분을 더하는 간단한 규칙을 따르며, 행렬의 크기가 다르면 덧셈을 수행할 수 없다는 점을 반드시 기억해야 합니다.',
              '행렬의 덧셈은 실수에서의 덧셈과 유사한 성질을 가집니다. 두 행렬 \$A, B\$에 대하여 \$A+B = B+A\$가 성립하는 \'교환법칙\'이 성립하며, 세 행렬 \$A, B, C\$에 대하여 \$(A+B)+C = A+(B+C)\$가 성립하는 \'결합법칙\'도 성립합니다. 이러한 성질들은 복잡한 행렬 계산을 효율적으로 처리할 수 있게 해줍니다.',
              '이제 구체적인 예제를 통해 행렬의 덧셈을 연습해 봅시다. 두 행렬 \$A = \\begin{pmatrix} 1 & 3 \\\\ -2 & 4 \\end{pmatrix}\$와 \$B = \\begin{pmatrix} 5 & -1 \\\\ 0 & 2 \\end{pmatrix}\$가 주어졌을 때, \$A+B\$를 구하는 과정은 다음과 같습니다. 먼저 각 위치에 대응하는 성분을 확인합니다.',
              '단계별 풀이를 적용하면 다음과 같습니다. 첫째, (1행, 1열) 성분끼리 더하면 \$1+5=6\$입니다. 둘째, (1행, 2열) 성분끼리 더하면 \$3+(-1)=2\$입니다. 셋째, (2행, 1열) 성분끼리 더하면 \$-2+0=-2\$입니다. 마지막으로 (2행, 2열) 성분끼리 더하면 \$4+2=6\$이 됩니다. 따라서 결과는 다음과 같습니다. \$\$A+B = \\begin{pmatrix} 1+5 & 3-1 \\\\ -2+0 & 4+2 \\end{pmatrix} = \\begin{pmatrix} 6 & 2 \\\\ -2 & 6 \\end{pmatrix}\$\$',
            ],
          ),
        ],
      ),
    ],
  ),
  '진수조건': BookData(
    id: 'concept_진수조건',
    title: '진수조건',
    subtitle: '대수 > 로그방정식과로그부등식 > 진수조건',
    category: 'common',
    tags: ['대수', '로그방정식과로그부등식', '진수조건'],
    chapters: [
      BookChapter(
        title: '진수조건',
        intro: ['대수 > 로그방정식과로그부등식 > 진수조건 개념 학습'],
        sections: [
          BookSection(
            title: '진수조건',
            paragraphs: [
              '로그 \$\\log_a b\$가 정의되기 위해서는 밑 \$a\$와 진수 \$b\$가 특정한 조건을 만족해야 합니다. 여기서 \'진수\'란 로그 기호 옆에 위치한 수 \$b\$를 의미합니다. 로그의 정의에 따라 진수 \$b\$는 반드시 \$0\$보다 커야 합니다. 즉, 진수 조건은 \$\$b > 0\$\$입니다. 만약 진수가 \$0\$이거나 음수라면, 어떤 수를 거듭제곱해도 그 결과가 음수나 \$0이 될 수 없으므로 로그 값 자체가 존재하지 않게 됩니다.',
              '로그 방정식이나 부등식을 풀 때 가장 흔히 하는 실수가 바로 이 진수 조건을 확인하지 않는 것입니다. 식을 변형하여 계산하는 과정에서 진수 조건이 사라지거나 바뀌는 경우가 많기 때문입니다. 따라서 로그를 포함한 식을 다룰 때는 문제를 풀기 시작하는 가장 첫 단계에서 반드시 \'진수 > 0\'이라는 조건을 먼저 적어두고, 최종적으로 구한 해가 이 조건을 만족하는지 확인하는 습관을 들여야 합니다.',
              '예를 들어, 로그 방정식 \$\\log_2(x-3) + \\log_2(x-5) = 3\$을 풀어봅시다. 먼저 진수 조건을 확인하면 \$x-3 > 0\$이고 \$x-5 > 0\$이어야 하므로, 공통 범위인 \$\$x > 5\$\$가 진수 조건이 됩니다. 이제 로그의 성질 \$\\log_M + \\log_N = \\log(MN)\$을 이용하여 식을 정리하면 \$\\log_2((x-3)(x-5)) = 3\$이 됩니다.',
              '위 식을 지수 형태로 바꾸면 \$(x-3)(x-5) = 2^3\$이 되어, \$x^2 - 8x + 15 = 8\$이라는 이차방정식이 나옵니다. 이를 정리하면 \$x^2 - 8x + 7 = 0\$이 되고, 인수분해하면 \$(x-1)(x-7) = 0\$이 되어 해는 \$x=1\$ 또는 \$x=7\$이 나옵니다. 여기서 앞서 구한 진수 조건 \$\$x > 5\$\$를 적용해 보면, \$x=1\$은 조건을 만족하지 않으므로 무연근이 되어 버립니다. 따라서 최종적인 해는 \$\$x=7\$\$만이 정답이 됩니다.',
              '또 다른 예로, 로그 부등식 \$\\log_{0.5}(x-2) > -1\$을 풀어보겠습니다. 먼저 진수 조건에 의해 \$\$x-2 > 0\$\$, 즉 \$\$x > 2\$\$가 성립해야 합니다. 그다음 부등식을 풀기 위해 \$-1\$을 로그 형태로 바꾸면 \$\\log_{0.5}(x-2) > \\log_{0.5}(0.5^{-1})\$이 됩니다. 밑이 \$0.5\$로 \$1\$보다 작으므로 부등호 방향이 바뀌어 \$\$x-2 < 0.5^{-1}\$\$이 됩니다.',
              '계산하면 \$x-2 < 2\$이므로 \$\$x < 4\$\$라는 결과를 얻습니다. 이제 처음에 구한 진수 조건 \$\$x > 2\$\$와 부등식의 해 \$\$x < 4\$\$를 동시에 만족하는 범위를 찾으면 최종적인 해는 \$\$2 < x < 4\$\$가 됩니다. 이처럼 진수 조건은 로그 문제의 정답을 결정짓는 필수적인 과정임을 항상 기억해야 합니다.',
            ],
          ),
        ],
      ),
    ],
  ),
  '구간의분할': BookData(
    id: 'concept_구간의분할',
    title: '구간의분할',
    subtitle: '미적분Ⅰ > 정적분 > 정적분의성질 > 구간의분할',
    category: 'common',
    tags: ['미적분Ⅰ', '정적분', '정적분의성질', '구간의분할'],
    chapters: [
      BookChapter(
        title: '구간의분할',
        intro: ['미적분Ⅰ > 정적분 > 정적분의성질 > 구간의분할 개념 학습'],
        sections: [
          BookSection(
            title: '구간의분할',
            paragraphs: [
              '정적분에서 \'구간의 분할\'이란, 적분 구간 \$[a, b]\$를 임의의 점 \$c\$를 기준으로 \$[a, c]\$와 \$[c, b]\$라는 두 개의 작은 구간으로 나누어 계산하는 성질을 말합니다. 이는 마치 긴 막대를 중간에서 자르는 것과 같은 원리로, 함수 \$f(x)\$가 구간 \$[a, b]\$에서 연속일 때, \$a, b, c\$의 대소 관계와 상관없이 항상 성립하는 매우 중요한 성질입니다.',
              '이 성질을 수학적 공식으로 나타내면 다음과 같습니다. 함수 \$f(x)\$가 구간 \$[a, b]\$에서 연속일 때, 구간 내의 임의의 점 \$c\$에 대하여 다음 등식이 성립합니다. \$\$ \\int_{a}^{b} f(x) \\, dx = \\int_{a}^{c} f(x) \\, dx + \\int_{c}^{b} f(x) \\, dx \$\$ 이 공식은 적분 구간이 서로 이어져 있을 때, 두 적분 값을 합쳐서 하나의 구간으로 표현하거나, 반대로 하나의 구간을 두 개로 쪼개어 계산할 수 있음을 의미합니다.',
              '구간의 분할 성질이 유용한 이유는 함수가 구간에 따라 다르게 정의되거나, 절댓값이 포함된 함수를 적분할 때 계산을 훨씬 간편하게 만들어주기 때문입니다. 특히 함수가 꺾이는 지점이나 불연속이 의심되는 지점에서 구간을 나누면, 각 구간별로 적분식을 세워 정적분 값을 정확하게 구할 수 있습니다.',
              '예제 문제: 함수 \$f(x) = \\begin{cases} 2x & (x < 1) \\\\ 3 & (x \\ge 1) \\end{cases}\$일 때, 정적분 \$\\int_{0}^{2} f(x) \\, dx\$의 값을 구하시오. 이 문제는 \$x=1\$을 기준으로 함수의 식이 바뀌므로, 구간의 분할 성질을 사용하여 적분 구간을 \$[0, 1]\$과 \$[1, 2]\$로 나누어 계산해야 합니다.',
              '단계별 풀이: 먼저 주어진 적분식을 구간의 분할 성질을 이용하여 다음과 같이 나눕니다. \$\$ \\int_{0}^{2} f(x) \\, dx = \\int_{0}^{1} 2x \\, dx + \\int_{1}^{2} 3 \\, dx \$\$ 이제 각 구간을 따로 계산합니다. 첫 번째 항은 \$\\int_{0}^{1} 2x \\, dx = [x^2]_{0}^{1} = 1^2 - 0^2 = 1\$이고, 두 번째 항은 \$\\int_{1}^{2} 3 \\, dx = [3x]_{1}^{2} = 3(2) - 3(1) = 6 - 3 = 3\$입니다.',
              '마지막으로 구한 두 값을 더하면 최종 정적분 값을 얻을 수 있습니다. \$\$ \\int_{0}^{2} f(x) \\, dx = 1 + 3 = 4 \$\$ 이처럼 구간의 분할을 이용하면 복잡한 함수도 각 구간별로 나누어 간단히 해결할 수 있습니다.',
            ],
          ),
        ],
      ),
    ],
  ),
  '약분': BookData(
    id: 'concept_약분',
    title: '약분',
    subtitle: '공통수학2 > 유리식과유리함수 > 유리식 > 약분',
    category: 'common',
    tags: ['공통수학2', '유리식과유리함수', '유리식', '약분'],
    chapters: [
      BookChapter(
        title: '약분',
        intro: ['공통수학2 > 유리식과유리함수 > 유리식 > 약분 개념 학습'],
        sections: [
          BookSection(
            title: '약분',
            paragraphs: [
              '유리식이란 다항식 \$A\$와 \$B\$(\$B \\neq 0\$)에 대하여 \$\\frac{A}{B}\$ 꼴로 나타낸 식을 말합니다. 유리식에서 \'약분\'이란 분수식의 분자와 분모를 그들의 공통인수로 나누어 식을 간단하게 만드는 과정을 의미합니다. 마치 분수에서 분자와 분모를 최대공약수로 나누어 기약분수로 만드는 것과 같은 원리입니다.',
              '약분을 수행하기 위해서는 먼저 분자와 분모를 각각 인수분해해야 합니다. 분자와 분모에 공통으로 들어있는 인수 \$C\$(\$C \\neq 0\$)가 있다면, 다음과 같은 성질을 이용하여 식을 간단히 할 수 있습니다. 즉, 분자와 분모를 공통인수 \$C\$로 나누면 식의 값은 변하지 않습니다. 공식으로 나타내면 다음과 같습니다. \$\$\\frac{A \\times C}{B \\times C} = \\frac{A}{B} \\quad (C \\neq 0)\$\$',
              '약분을 할 때 가장 중요한 주의사항은 분모가 0이 되는 값은 정의되지 않는다는 점입니다. 따라서 약분 전의 식에서 분모를 0으로 만드는 값은 약분 후의 식에서도 여전히 정의되지 않으므로, 항상 변수의 범위를 고려해야 합니다. 약분을 마친 후에는 더 이상 공통인수가 없는 상태, 즉 기약유리식의 형태가 되어야 합니다.',
              '예제: 유리식 \$\\frac{x^2 - 4}{x^2 + x - 6}\$을 약분하여 간단히 하시오. 먼저 분자와 분모를 각각 인수분해합니다. 분자 \$x^2 - 4\$는 합차 공식에 의해 \$(x-2)(x+2)\$가 되고, 분모 \$x^2 + x - 6\$은 곱해서 \$-6\$, 더해서 \$1\$이 되는 두 수를 찾아 \$(x-2)(x+3)\$으로 인수분해됩니다.',
              '이제 식을 다시 쓰면 다음과 같습니다. \$\$\\frac{x^2 - 4}{x^2 + x - 6} = \\frac{(x-2)(x+2)}{(x-2)(x+3)}\$\$ 여기서 분자와 분모에 공통으로 들어있는 인수 \$(x-2)\$를 찾을 수 있습니다. 단, 분모가 0이 되면 안 되므로 \$x-2 \\neq 0\$, 즉 \$x \\neq 2\$라는 조건이 필요합니다.',
              '공통인수인 \$(x-2)\$를 약분하면 최종적으로 다음과 같은 결과를 얻습니다. \$\$\\frac{x+2}{x+3} \\quad (x \\neq 2, x \\neq -3)\$\$ 이처럼 약분은 복잡한 유리식을 다루기 쉬운 형태로 바꾸어 주며, 유리함수의 그래프를 그리거나 방정식을 풀 때 매우 유용하게 사용되는 기초적인 도구입니다.',
            ],
          ),
        ],
      ),
    ],
  ),
  '중간값정리': BookData(
    id: 'concept_중간값정리',
    title: '중간값정리',
    subtitle: '미적분Ⅰ > 함수의연속 > 중간값정리',
    category: 'common',
    tags: ['미적분Ⅰ', '함수의연속', '중간값정리'],
    chapters: [
      BookChapter(
        title: '중간값정리',
        intro: ['미적분Ⅰ > 함수의연속 > 중간값정리 개념 학습'],
        sections: [
          BookSection(
            title: '중간값정리',
            paragraphs: [
              '중간값 정리(Intermediate Value Theorem)는 연속함수의 성질을 이해하는 데 매우 중요한 도구입니다. 함수 \$f(x)\$가 닫힌구간 \$[a, b]\$에서 연속이고, 양 끝점의 함숫값인 \$f(a)\$와 \$f(b)\$가 서로 다를 때, 그 사이의 임의의 값 \$k\$에 대하여 \$f(c) = k\$를 만족하는 점 \$c\$가 열린구간 \$(a, b)\$ 사이에 적어도 하나 존재한다는 정리입니다. 이는 그래프가 끊어지지 않고 이어져 있다면, 한 높이에서 다른 높이로 이동할 때 그 사이의 모든 높이를 반드시 거쳐야 한다는 직관적인 사실을 수학적으로 표현한 것입니다.',
              '이 정리를 수식으로 나타내면 다음과 같습니다. 함수 \$f(x)\$가 닫힌구간 \$[a, b]\$에서 연속이고 \$f(a) \\neq f(b)\$일 때, \$f(a)\$와 \$f(b)\$ 사이의 임의의 값 \$k\$에 대하여 \$\$f(c) = k\$\$를 만족하는 \$c\$가 \$a < c < b\$인 범위 내에 적어도 하나 존재합니다. 특히, \$f(a)\$와 \$f(b)\$의 부호가 서로 다를 때, 즉 \$f(a)f(b) < 0\$인 경우에는 \$k=0\$인 경우를 생각할 수 있습니다. 이때는 \$f(c) = 0\$이 되는 \$c\$가 존재하므로, 방정식 \$f(x) = 0\$이 구간 \$(a, b)\$에서 적어도 하나의 실근을 가짐을 알 수 있습니다.',
              '중간값 정리를 활용하여 방정식의 실근 존재 여부를 확인하는 예제를 풀어봅시다. 방정식 \$f(x) = x^3 + x - 1 = 0\$이 열린구간 \$(0, 1)\$에서 적어도 하나의 실근을 가짐을 보이시오. 먼저 함수 \$f(x) = x^3 + x - 1\$은 다항함수이므로 모든 실수 구간에서 연속입니다. 따라서 닫힌구간 \$[0, 1]\$에서도 연속임이 보장됩니다.',
              '이제 구간의 양 끝점에서의 함숫값을 각각 계산합니다. 먼저 \$x=0\$일 때, \$\$f(0) = 0^3 + 0 - 1 = -1\$\$이고, \$x=1\$일 때, \$\$f(1) = 1^3 + 1 - 1 = 1\$\$입니다. 여기서 \$f(0) = -1\$이고 \$f(1) = 1\$이므로, 두 함숫값의 곱을 구하면 \$\$f(0)f(1) = (-1) \\times 1 = -1 < 0\$\$이 성립합니다.',
              '마지막으로 중간값 정리에 의해 \$f(0) < 0 < f(1)\$을 만족하므로, \$f(c) = 0\$인 \$c\$가 \$0 < c < 1\$ 사이에 적어도 하나 존재합니다. 즉, 주어진 방정식 \$x^3 + x - 1 = 0\$은 열린구간 \$(0, 1)\$에서 적어도 하나의 실근을 갖습니다. 이처럼 중간값 정리는 복잡한 방정식의 해를 직접 구하지 않고도, 특정 구간 내에 해가 존재하는지 판별할 때 매우 유용하게 사용됩니다.',
            ],
          ),
        ],
      ),
    ],
  ),
  '두근의합': BookData(
    id: 'concept_두근의합',
    title: '두근의합',
    subtitle: '공통수학1 > 이차방정식 > 이차방정식의근과계수 > 두근의합',
    category: 'common',
    tags: ['공통수학1', '이차방정식', '이차방정식의근과계수', '두근의합'],
    chapters: [
      BookChapter(
        title: '두근의합',
        intro: ['공통수학1 > 이차방정식 > 이차방정식의근과계수 > 두근의합 개념 학습'],
        sections: [
          BookSection(
            title: '두근의합',
            paragraphs: [
              '이차방정식 \$ax^2 + bx + c = 0\$ (단, \$a \\neq 0\$)에서 두 근을 각각 \$\\alpha\$와 \$\\beta\$라고 할 때, 근과 계수 사이에는 아주 특별한 관계가 성립합니다. 이차방정식의 근의 공식에 의해 두 근은 \$\\frac{-b + \\sqrt{b^2 - 4ac}}{2a}\$와 \$\\frac{-b - \\sqrt{b^2 - 4ac}}{2a}\$가 되는데, 이 두 식을 직접 더해보면 복잡한 근호 부분이 서로 상쇄되어 매우 간단한 형태가 남게 됩니다.',
              '이 과정을 통해 얻어지는 \'근과 계수의 관계\' 중 두 근의 합에 관한 공식은 다음과 같습니다. 이차방정식 \$ax^2 + bx + c = 0\$의 두 근을 \$\\alpha, \\beta\$라 할 때, 두 근의 합은 이차항의 계수와 일차항의 계수만을 이용하여 다음과 같이 나타낼 수 있습니다. \$\$ \\alpha + \\beta = -\\frac{b}{a} \$\$ 이 공식은 방정식을 직접 풀지 않고도 계수만 알면 두 근의 합을 즉시 구할 수 있게 해주므로, 수학 문제를 해결할 때 시간을 획기적으로 줄여주는 매우 중요한 도구입니다.',
              '예를 들어, 이차방정식 \$x^2 - 5x + 6 = 0\$이 주어졌다고 가정해 봅시다. 이 방정식에서 \$a=1, b=-5, c=6\$입니다. 근의 공식을 쓰지 않고 공식에 바로 대입하면, 두 근의 합은 \$-( -5 ) / 1 = 5\$가 됩니다. 실제로 이 방정식을 인수분해하면 \$(x-2)(x-3)=0\$이 되어 근이 \$2\$와 \$3\$임을 알 수 있고, 두 근을 더하면 \$2+3=5\$가 되어 공식과 일치함을 확인할 수 있습니다.',
              '조금 더 복잡한 형태의 문제를 풀어보겠습니다. 이차방정식 \$2x^2 + 8x - 10 = 0\$의 두 근을 \$\\alpha, \\beta\$라고 할 때, \$\\alpha + \\beta\$의 값을 구하는 과정은 다음과 같습니다. 먼저 방정식의 계수를 확인합니다. 여기서 \$a=2, b=8, c=-10\$입니다. 두 근의 합 공식인 \$\\alpha + \\beta = -\\frac{b}{a}\$에 이 값들을 대입합니다. \$\$ \\alpha + \\beta = -\\frac{8}{2} = -4 \$\$ 따라서 구하고자 하는 두 근의 합은 \$-4\$가 됩니다.',
              '마지막으로, 이차항의 계수가 1이 아닌 경우에도 공식이 어떻게 적용되는지 다시 한번 정리해 봅시다. 방정식 \$3x^2 - 12x + 9 = 0\$에서 두 근의 합을 구하려면, 먼저 \$a=3, b=-12\$임을 파악합니다. 공식에 대입하면 \$\$ \\alpha + \\beta = -\\frac{-12}{3} = 4 \$\$ 가 됩니다. 이처럼 근과 계수의 관계를 활용하면 방정식을 직접 인수분해하기 어려운 상황에서도 두 근의 합을 정확하고 빠르게 계산할 수 있습니다.',
            ],
          ),
        ],
      ),
    ],
  ),
