        intro: ['공통수학2 > 원의방정식 > 대칭이동 > 직선대칭 개념 학습'],
        sections: [
          BookSection(
            title: '직선대칭',
            paragraphs: [
              '[   "좌표평면 위에서 어떤 도형을 직선 \$l\$에 대하여 대칭이동한다는 것은, 그 도형의 모든 점을 직선 \$l\$을 접는 선으로 하여 반대편으로 옮기는 것을 의미합니다. 점 \$P(x, y)\$를 직선 \$l\$에 대하여 대칭이동한 점을 \$P\'(x\', y\')\$라고 할 때, 두 점을 이은 선분 \$PP\'\$는 직선 \$l\$과 수직으로 만나야 하며, 선분 \$PP\'\$의 중점은 반드시 직선 \$l\$ 위에 있어야 합니다. 이 두 가지 기하학적 성질을 이용하면 대칭이동된 점의 좌표를 정확하게 구할 수 있습니다.",   "직선 \$l\$의 방정식이 \$ax + by + c = 0\$일 때, 점 \$P(x_1, y_1)\$을 대칭이동한 점 \$P\'(x\', y\')\$를 구하는 방법은 다음과 같습니다. 첫째, 선분 \$PP\'\$의 중점 \$M\\left(\\frac{x_1+x\'}{2}, \\frac{y_1+y\'}{2}\\right)\$이 직선 \$l\$ 위에 있으므로 \$\$a\\left(\\frac{x_1+x\'}{2}\\right) + b\\left(\\frac{y_1+y\'}{2}\\right) + c = 0\$\$을 만족합니다. 둘째, 직선 \$PP\'\$의 기울기와 직선 \$l\$의 기울기의 곱이 \$-1\$이 되어야 하므로, 직선 \$l\$의 기울기가 \$-\\frac{a}{b}\$일 때 선분 \$PP\'\$의 기울기는 \$\\frac{y\'-y_1}{x\'-x_1} = \\frac{b}{a}\$가 됩니다. 이 두 식을 연립하여 \$x\'\$와 \$y\'\$를 구할 수 있습니다.",   "특별한 경우로, 직선이 좌표축이나 \$y=x\$와 같이 간단한 형태일 때는 공식이 더욱 단순해집니다. 점 \$(x, y)\$를 \$x\$축에 대칭이동하면 \$(x, -y)\$가 되고, \$y\$축에 대칭이동하면 \$(-x, y)\$가 됩니다. 또한, 직선 \$y=x\$에 대칭이동하면 \$(y, x)\$가 되며, 직선 \$y=-x\$에 대칭이동하면 \$(-y, -x)\$가 됩니다. 이러한 기본 대칭 이동은 복잡한 직선 대칭을 이해하는 기초가 되므로 반드시 숙지해야 합니다.",   "예제: 점 \$A(2, 4)\$를 직선 \$y = x + 2\$에 대하여 대칭이동한 점 \$A\'(x\', y\')\$의 좌표를 구하시오. 먼저, 선분 \$AA\'\$의 중점 \$M\\left(\\frac{2+x\'}{2}, \\frac{4+y\'}{2}\\right)\$이 직선 \$y = x + 2\$ 위에 있어야 하므로, \$\\frac{4+y\'}{2} = \\frac{2+x\'}{2} + 2\$라는 식을 얻습니다. 이를 정리하면 \$4+y\' = 2+x\'+4\$, 즉 \$x\' - y\' = -2\$가 됩니다.",   "다음으로, 직선 \$AA\'\$의 기울기와 직선 \$y = x + 2\$의 기울기(\$1\$)의 곱은 \$-1\$이어야 합니다. 따라서 \$\\frac{y\'-4}{x\'-2} \\times 1 = -1\$이 성립하며, 이를 정리하면 \$y\'-4 = -x\'+2\$, 즉 \$x\' + y\' = 6\$이 됩니다. 이제 두 식 \$x\' - y\' = -2\$와 \$x\' + y\' = 6\$을 연립하여 풀면, 두 식을 더해 \$2x\' = 4\$에서 \$x\' = 2\$를 얻고, 이를 대입하여 \$y\' = 4\$를 얻습니다. 따라서 대칭이동된 점의 좌표는 \$(2, 4)\$입니다. (참고: 점 \$A\$가 직선 위에 있으므로 대칭이동해도 자기 자신이 됩니다.)" ]',
            ],
          ),
        ],
      ),
    ],
  ),
  '항': BookData(
