    category: 'common',
    tags: ['대수', '수열', '수열의정의', '항'],
    chapters: [
      BookChapter(
        title: '항',
        intro: ['대수 > 수열 > 수열의정의 > 항 개념 학습'],
        sections: [
          BookSection(
            title: '항',
            paragraphs: [
              '수학에서 \'항(term)\'이란 수열이나 다항식을 구성하는 각각의 개별적인 수나 식을 의미합니다. 수열을 나열할 때 첫 번째에 오는 수를 첫째항, 두 번째에 오는 수를 둘째항과 같이 부르며, 일반적으로 \$n\$번째에 위치한 항을 제\$n\$항이라고 합니다. 기호로는 보통 \$a_n\$과 같이 나타내며, 여기서 \$n\$은 항의 순서를 나타내는 자연수입니다.',
              '수열의 일반항 \$a_n\$은 항의 번호 \$n\$과 그 항의 값 사이의 관계를 나타내는 식입니다. 예를 들어, 수열 \$a_1, a_2, a_3, \\dots, a_n, \\dots\$에서 \$a_n\$은 \$n\$에 관한 식으로 표현됩니다. 이 식을 알면 수열의 어떤 번째 항이라도 바로 구할 수 있습니다. 예를 들어, 일반항이 \$\$a_n = 2n + 1\$\$인 수열이라면, \$n=1\$을 대입하여 첫째항 \$a_1 = 2(1) + 1 = 3\$을 얻고, \$n=2\$를 대입하여 둘째항 \$a_2 = 2(2) + 1 = 5\$를 얻는 방식입니다.',
              '항의 성질 중 중요한 것은 항의 번호인 \$n\$은 항상 1부터 시작하는 자연수라는 점입니다. 또한, 수열이 유한한 개수의 항으로 이루어져 있다면 이를 유한수열이라 하고, 끝없이 계속된다면 무한수열이라고 합니다. 항을 다룰 때는 각 항이 어떤 규칙으로 변화하는지를 파악하는 것이 핵심이며, 이를 통해 수열 전체의 흐름을 이해할 수 있습니다.',
              '예제 문제: 일반항이 \$\$a_n = n^2 - 2\$\$로 주어지는 수열이 있습니다. 이 수열의 제1항부터 제3항까지를 차례대로 구해보세요. 단계별 풀이는 다음과 같습니다. 먼저 제1항은 \$n=1\$을 대입하여 \$\$a_1 = 1^2 - 2 = 1 - 2 = -1\$\$입니다. 다음으로 제2항은 \$n=2\$를 대입하여 \$\$a_2 = 2^2 - 2 = 4 - 2 = 2\$\$입니다. 마지막으로 제3항은 \$n=3\$을 대입하여 \$\$a_3 = 3^2 - 2 = 9 - 2 = 7\$\$이 됩니다. 따라서 구하는 항들은 \$-1, 2, 7\$입니다.',
              '또 다른 예제로, 수열 \$5, 8, 11, 14, \\dots\$에서 제10항을 구하는 과정을 살펴봅시다. 이 수열은 앞의 항에 3씩 더해지는 규칙을 가지고 있습니다. 이를 일반항으로 나타내면 \$\$a_n = 3n + 2\$\$가 됩니다. 이제 제10항을 구하기 위해 \$n=10\$을 대입하면 \$\$a_{10} = 3(10) + 2 = 30 + 2 = 32\$\$가 됩니다. 이처럼 일반항을 구하면 복잡한 나열 없이도 원하는 순서의 항을 즉시 계산할 수 있습니다.',
            ],
          ),
        ],
      ),
    ],
  ),
  '곡선과x축사이의넓이': BookData(
    id: 'concept_곡선과x축사이의넓이',
    title: '곡선과x축사이의넓이',
    subtitle: '미적분Ⅰ > 정적분과넓이 > 곡선과x축사이의넓이',
    category: 'common',
    tags: ['미적분Ⅰ', '정적분과넓이', '곡선과x축사이의넓이'],
    chapters: [
      BookChapter(
        title: '곡선과x축사이의넓이',
        intro: ['미적분Ⅰ > 정적분과넓이 > 곡선과x축사이의넓이 개념 학습'],
        sections: [
          BookSection(
            title: '곡선과x축사이의넓이',
            paragraphs: [
              '[   "함수 \$f(x)\$가 닫힌구간 \$[a, b]\$에서 연속일 때, 곡선 \$y=f(x)\$와 \$x\$축 및 두 직선 \$x=a, x=b\$로 둘러싸인 도형의 넓이는 정적분을 이용하여 구할 수 있습니다. 만약 구간 \$[a, b]\$에서 \$f(x) \\ge 0\$이면, 이 도형의 넓이 \$S\$는 함수 \$f(x)\$를 \$a\$부터 \$b\$까지 정적분한 값과 같습니다. 즉, \$\$S = \\\\int_{a}^{b} f(x) \\\\, dx\$\$ 로 정의됩니다.",   "반대로 구간 \$[a, b]\$에서 \$f(x) \\\\le 0\$인 경우에는 정적분 값은 음수가 되지만, 넓이는 항상 양수여야 합니다. 따라서 이 경우에는 정적분 값에 마이너스를 붙여야 합니다. 이를 일반화하면 곡선과 \$x\$축 사이의 넓이는 함수에 절댓값을 씌운 정적분으로 표현할 수 있으며, 공식은 다음과 같습니다. \$\$S = \\\\int_{a}^{b} |f(x)| \\\\, dx\$\$ 이 식은 구간 내에서 함수가 \$x\$축 아래에 있을 때 그 부분을 양수로 뒤집어 계산한다는 의미를 담고 있습니다.",   "실제로 넓이를 구할 때는 함수 \$f(x)\$가 \$x\$축과 만나는 점을 기준으로 구간을 나누어 계산해야 합니다. 예를 들어, 구간 내에서 \$f(x)\$의 부호가 바뀌는 지점이 있다면, 그 지점을 기준으로 적분 구간을 분할하여 각각의 정적분 값의 절댓값을 더해주면 됩니다. 이렇게 하면 복잡한 곡선이라도 \$x\$축과의 교점을 찾아 정확한 넓이를 산출할 수 있습니다.",   "예제: 곡선 \$y = x^2 - 4\$와 \$x\$축 및 두 직선 \$x=0, x=3\$으로 둘러싸인 도형의 넓이를 구해 봅시다. 먼저 \$x^2 - 4 = 0\$을 풀면 \$x = \\\\pm 2\$이므로, 주어진 구간 \$[0, 3]\$ 내에서 \$x=2\$를 기준으로 함수가 \$x\$축 아래와 위로 나뉩니다. 따라서 넓이 \$S\$는 다음과 같이 식을 세울 수 있습니다. \$\$S = \\\\int_{0}^{2} |x^2 - 4| \\\\, dx + \\\\int_{2}^{3} |x^2 - 4| \\\\, dx\$\$",   "이제 각 구간별로 계산합니다. 구간 \$[0, 2]\$에서는 \$x^2 - 4 \\\\le 0\$이므로 \$-\\\\int_{0}^{2} (x^2 - 4) \\\\, dx\$를 계산하면, \$-\\\\left[ \\\\frac{1}{3}x^3 - 4x \\\\right]_{0}^{2} = -(\\\\frac{8}{3} - 8) = \\\\frac{16}{3}\$이 됩니다. 다음으로 구간 \$[2, 3]\$에서는 \$x^2 - 4 \\\\ge 0\$이므로 \$\\\\int_{2}^{3} (x^2 - 4) \\\\, dx\$를 계산하면, \$\\\\left[ \\\\frac{1}{3}x^3 - 4x \\\\right]_{2}^{3} = (9 - 12) - (\\\\frac{8}{3} - 8) = -3 + \\\\frac{16}{3} = \\\\frac{7}{3}\$이 나옵니다.",   "마지막으로 두 구간의 넓이를 합하면 전체 넓이 \$S\$를 구할 수 있습니다. \$\$S = \\\\frac{16}{3} + \\\\frac{7}{3} = \\\\frac{23}{3}\$\$ 이와 같이 곡선이 \$x\$축을 통과하는 경우, 반드시 교점을 찾아 구간을 나누어 계산하는 것이 넓이를 구하는 핵심 단계입니다." ]',
            ],
          ),
        ],
      ),
    ],
  ),
  '행렬의뺄셈': BookData(
    id: 'concept_행렬의뺄셈',
    title: '행렬의뺄셈',
    subtitle: '공통수학1 > 행렬 > 행렬의연산 > 행렬의뺄셈',
    category: 'common',
    tags: ['공통수학1', '행렬', '행렬의연산', '행렬의뺄셈'],
    chapters: [
      BookChapter(
        title: '행렬의뺄셈',
        intro: ['공통수학1 > 행렬 > 행렬의연산 > 행렬의뺄셈 개념 학습'],
        sections: [
          BookSection(
            title: '행렬의뺄셈',
            paragraphs: [
              '행렬의 뺄셈은 두 행렬의 크기가 같을 때, 각 성분끼리 빼서 새로운 행렬을 만드는 연산입니다. 두 행렬 \$A\$와 \$B\$가 있을 때, \$A\$에서 \$B\$를 뺀다는 것은 \$A\$의 각 성분에서 그에 대응하는 \$B\$의 성분을 빼는 것을 의미합니다. 이때 주의할 점은 두 행렬의 행의 개수와 열의 개수가 서로 일치해야만 연산이 가능하다는 것입니다.',
              '행렬 \$A = \\begin{pmatrix} a & b \\\\ c & d \\end{pmatrix}\$와 \$B = \\begin{pmatrix} e & f \\\\ g & h \\end{pmatrix}\$가 있을 때, 두 행렬의 뺄셈은 다음과 같이 정의됩니다. \$\$A - B = \\begin{pmatrix} a-e & b-f \\\\ c-g & d-h \\end{pmatrix}\$\$ 즉, 같은 위치에 있는 성분끼리 짝을 지어 뺄셈을 수행하면 됩니다. 이는 행렬의 덧셈과 마찬가지로 각 성분의 위치를 정확히 맞추는 것이 핵심입니다.',
              '행렬의 뺄셈은 행렬의 덧셈을 응용한 것으로 이해할 수 있습니다. 행렬 \$B\$의 모든 성분의 부호를 바꾼 행렬을 \$-B\$라고 할 때, \$A - B\$는 \$A + (-B)\$와 같은 결과를 줍니다. 따라서 뺄셈을 할 때 부호 실수만 주의한다면, 덧셈의 성질을 그대로 활용하여 문제를 해결할 수 있습니다.',
              '다음 예제를 통해 행렬의 뺄셈을 연습해 봅시다. 두 행렬 \$A = \\begin{pmatrix} 5 & 8 \\\\ 3 & 2 \\end{pmatrix}\$와 \$B = \\begin{pmatrix} 2 & 4 \\\\ 1 & 6 \\end{pmatrix}\$가 주어졌을 때, \$A - B\$를 구하는 과정입니다. 먼저 각 위치의 성분을 대응시킵니다. 첫 번째 행 첫 번째 열은 \$5-2\$, 첫 번째 행 두 번째 열은 \$8-4\$가 됩니다.',
              '이제 두 번째 행의 성분들을 계산합니다. 두 번째 행 첫 번째 열은 \$3-1\$, 두 번째 행 두 번째 열은 \$2-6\$이 됩니다. 이를 종합하여 행렬로 나타내면 다음과 같습니다. \$\$A - B = \\begin{pmatrix} 5-2 & 8-4 \\\\ 3-1 & 2-6 \\end{pmatrix} = \\begin{pmatrix} 3 & 4 \\\\ 2 & -4 \\end{pmatrix}\$\$ 이와 같이 각 성분을 순서대로 계산하면 복잡해 보이는 행렬 연산도 간단하게 해결할 수 있습니다.',
            ],
          ),
        ],
      ),
    ],
  ),
  '두근의곱': BookData(
    id: 'concept_두근의곱',
    title: '두근의곱',
    subtitle: '공통수학1 > 이차방정식 > 이차방정식의근과계수 > 두근의곱',
    category: 'common',
    tags: ['공통수학1', '이차방정식', '이차방정식의근과계수', '두근의곱'],
    chapters: [
      BookChapter(
        title: '두근의곱',
        intro: ['공통수학1 > 이차방정식 > 이차방정식의근과계수 > 두근의곱 개념 학습'],
        sections: [
          BookSection(
            title: '두근의곱',
            paragraphs: [
              '이차방정식 \$ax^2 + bx + c = 0\$ (단, \$a \\neq 0\$)에서 두 근을 각각 \$\\alpha\$와 \$\\beta\$라고 할 때, 근과 계수의 관계를 이용하면 두 근의 곱을 계수만으로 간단히 구할 수 있습니다. 이차방정식의 근의 공식에 의해 두 근은 \$\\frac{-b \\pm \\sqrt{b^2 - 4ac}}{2a}\$가 되는데, 이 두 값을 직접 곱하여 정리하면 놀랍게도 이차항의 계수와 상수항의 비율로 표현됩니다.',
              '두 근의 곱을 구하는 공식은 다음과 같습니다. 이차방정식 \$ax^2 + bx + c = 0\$의 두 근을 \$\\alpha, \\beta\$라 할 때, 두 근의 곱 \$\\alpha\\beta\$는 다음과 같이 정의됩니다. \$\$ \\alpha\\beta = \\frac{c}{a} \$\$ 이 공식은 이차방정식을 직접 풀어서 근을 구하지 않고도, 방정식의 계수(\$a, c\$)만 확인하면 즉시 두 근의 곱을 알아낼 수 있다는 점에서 매우 유용합니다.',
              '이 성질은 이차방정식의 인수분해 형태인 \$a(x-\\alpha)(x-\\beta) = 0\$을 전개했을 때, 상수항 부분이 \$a \\cdot \\alpha \\cdot \\beta\$가 된다는 원리에서 유도됩니다. 즉, \$ax^2 - a(\\alpha+\\beta)x + a\\alpha\\beta = 0\$과 원래의 식 \$ax^2 + bx + c = 0\$을 비교하면, 상수항 \$c\$가 \$a\\alpha\\beta\$와 같아야 하므로 \$\\alpha\\beta = \\frac{c}{a}\$라는 결론에 도달하게 됩니다.',
              '예제 문제: 이차방정식 \$2x^2 - 8x + 6 = 0\$의 두 근을 \$\\alpha, \\beta\$라고 할 때, 두 근의 곱 \$\\alpha\\beta\$의 값을 구하시오. 이 문제를 해결하기 위해 먼저 방정식의 계수를 확인합니다. 여기서 \$a=2, b=-8, c=6\$임을 알 수 있습니다.',
              '공식 \$\\alpha\\beta = \\frac{c}{a}\$에 위에서 확인한 계수들을 대입합니다. \$\$ \\alpha\\beta = \\frac{6}{2} = 3 \$\$ 따라서 주어진 이차방정식의 두 근의 곱은 \$3\$이 됩니다. 실제로 이 방정식을 인수분해하면 \$2(x-1)(x-3)=0\$이 되어 두 근이 \$1\$과 \$3\$임을 알 수 있고, 두 근의 곱 \$1 \\times 3 = 3\$이 되어 공식과 일치함을 확인할 수 있습니다.',
            ],
          ),
        ],
      ),
    ],
  ),
  '통분': BookData(
    id: 'concept_통분',
    title: '통분',
    subtitle: '공통수학2 > 유리식과유리함수 > 유리식 > 통분',
    category: 'common',
    tags: ['공통수학2', '유리식과유리함수', '유리식', '통분'],
    chapters: [
      BookChapter(
        title: '통분',
        intro: ['공통수학2 > 유리식과유리함수 > 유리식 > 통분 개념 학습'],
        sections: [
          BookSection(
            title: '통분',
            paragraphs: [
              '통분이란 분모가 서로 다른 여러 개의 분수나 유리식을 계산할 때, 분모를 같게 만드는 과정을 말합니다. 분모가 다르면 덧셈이나 뺄셈을 바로 할 수 없기 때문에, 분모의 최소공배수를 찾아 모든 분수의 분모를 그 값으로 일치시켜야 합니다. 이때 분모와 분자에 0이 아닌 같은 수를 곱해도 분수의 크기는 변하지 않는다는 성질을 이용합니다.',
              '유리식에서 통분을 할 때는 각 분모를 인수분해한 뒤, 모든 분모에 포함된 인수들을 고려하여 최소공배수를 구합니다. 만약 분모가 \$A\$와 \$B\$인 두 유리식 \$\\frac{C}{A}\$와 \$\\frac{D}{B}\$가 있다면, 두 분모의 최소공배수를 \$L\$이라고 할 때, 통분한 결과는 다음과 같습니다. \$\$ \\frac{C}{A} = \\frac{C \\times (L/A)}{L}, \\quad \\frac{D}{B} = \\frac{D \\times (L/B)}{L} \$\$ 이렇게 분모를 통일하면 분자끼리 더하거나 빼서 하나의 식으로 간단히 정리할 수 있습니다.',
              '통분을 할 때 가장 중요한 것은 분모의 최소공배수를 정확히 찾는 것입니다. 분모에 공통인 인수가 있다면 그 인수는 한 번만 곱하고, 공통이 아닌 인수들은 모두 곱하여 최소공배수를 만듭니다. 이렇게 통분된 식은 유리식의 사칙연산을 수행하는 가장 기초적이고 필수적인 단계가 됩니다.',
              '예제: 다음 두 유리식을 통분하여 계산해 봅시다. \$\$ \\frac{1}{x-1} + \\frac{1}{x+1} \$\$ 먼저 두 분모 \$x-1\$과 \$x+1\$을 살펴봅니다. 두 식은 서로 공통인 인수가 없으므로, 최소공배수는 두 식을 곱한 \$(x-1)(x+1)\$이 됩니다. 즉, \$x^2-1\$이 공통분모가 됩니다.',
              '이제 각 분수에 필요한 식을 곱하여 분모를 \$x^2-1\$로 맞춥니다. 첫 번째 식의 분모와 분자에 \$(x+1)\$을 곱하고, 두 번째 식의 분모와 분자에 \$(x-1)\$을 곱합니다. 과정은 다음과 같습니다. \$\$ \\frac{1(x+1)}{(x-1)(x+1)} + \\frac{1(x-1)}{(x+1)(x-1)} = \\frac{x+1}{x^2-1} + \\frac{x-1}{x^2-1} \$\$',
              '마지막으로 분모가 같아졌으므로 분자끼리 더하여 식을 정리합니다. \$\$ \\frac{(x+1) + (x-1)}{x^2-1} = \\frac{2x}{x^2-1} \$\$ 이처럼 통분을 이용하면 복잡해 보이는 유리식의 덧셈을 하나의 분수 형태로 깔끔하게 나타낼 수 있습니다.',
            ],
          ),
        ],
      ),
    ],
  ),
  '미분계수의정의': BookData(
    id: 'concept_미분계수의정의',
    title: '미분계수의정의',
    subtitle: '미적분Ⅰ > 미분계수 > 미분계수의정의',
    category: 'common',
    tags: ['미적분Ⅰ', '미분계수', '미분계수의정의'],
    chapters: [
      BookChapter(
        title: '미분계수의정의',
        intro: ['미적분Ⅰ > 미분계수 > 미분계수의정의 개념 학습'],
        sections: [
          BookSection(
            title: '미분계수의정의',
            paragraphs: [
              '미분계수란 함수 \$y=f(x)\$의 그래프 위에서 점 \$x=a\$에서의 \'순간적인 변화율\'을 의미합니다. 우리가 흔히 아는 평균변화율은 두 점 사이의 기울기를 나타내지만, 미분계수는 이 두 점 사이의 간격을 0에 한없이 가깝게 만들었을 때의 기울기, 즉 접선의 기울기를 뜻합니다. 이를 수학적으로 정의하면 점 \$a\$에서의 미분계수 \$f\'(a)\$는 다음과 같은 극한값으로 표현됩니다.',
              '미분계수의 정의를 공식으로 나타내면 \$\$f\'(a) = \\lim_{h \\to 0} \\frac{f(a+h) - f(a)}{h}\$\$ 입니다. 여기서 \$h\$는 \$x\$의 변화량인 증분을 의미하며, \$h\$가 0으로 다가갈 때 점 \$(a+h, f(a+h))\$가 점 \$(a, f(a))\$에 한없이 가까워지면서 두 점을 잇는 직선의 기울기가 점 \$a\$에서의 접선의 기울기로 수렴하게 됩니다. 또한, \$x=a+h\$로 치환하면 \$\$f\'(a) = \\lim_{x \\to a} \\frac{f(x) - f(a)}{x - a}\$\$ 와 같은 형태로도 나타낼 수 있습니다.',
              '미분계수가 존재한다는 것은 함수 \$f(x)\$가 \$x=a\$에서 미분가능하다는 것을 의미합니다. 미분계수가 존재하기 위해서는 좌미분계수와 우미분계수가 서로 같아야 하며, 기하학적으로는 그래프가 \$x=a\$에서 뾰족하지 않고 매끄럽게 이어져 있어야 합니다. 이 개념은 단순히 기울기를 구하는 것을 넘어, 함수의 변화 양상을 정밀하게 분석하는 미분법의 가장 기초가 되는 핵심 원리입니다.',
              '예제: 함수 \$f(x) = x^2\$에 대하여 \$x=3\$에서의 미분계수 \$f\'(3)\$을 미분계수의 정의를 이용하여 구해보겠습니다. 먼저 정의에 따라 식을 세우면 \$\$f\'(3) = \\lim_{h \\to 0} \\frac{f(3+h) - f(3)}{h}\$\$ 가 됩니다. 여기에 \$f(x)=x^2\$을 대입하면 \$\$f\'(3) = \\lim_{h \\to 0} \\frac{(3+h)^2 - 3^2}{h}\$\$ 가 됩니다.',
              '이제 분자를 전개하여 식을 정리합니다. \$\$(3+h)^2 - 3^2 = (9 + 6h + h^2) - 9 = 6h + h^2\$\$ 이므로, 이를 원래의 극한식에 대입하면 \$\$f\'(3) = \\lim_{h \\to 0} \\frac{6h + h^2}{h}\$\$ 가 됩니다. 분자와 분모를 \$h\$로 나누면 \$\$f\'(3) = \\lim_{h \\to 0} (6 + h)\$\$ 가 되며, \$h\$가 0으로 갈 때 이 값은 6에 수렴합니다. 따라서 \$x=3\$에서의 미분계수는 6입니다.',
            ],
          ),
        ],
      ),
    ],
  ),
  '원소나열법': BookData(
    id: 'concept_원소나열법',
    title: '원소나열법',
    subtitle: '공통수학2 > 집합 > 집합의표현 > 원소나열법',
    category: 'common',
    tags: ['공통수학2', '집합', '집합의표현', '원소나열법'],
    chapters: [
      BookChapter(
        title: '원소나열법',
        intro: ['공통수학2 > 집합 > 집합의표현 > 원소나열법 개념 학습'],
        sections: [
          BookSection(
            title: '원소나열법',
            paragraphs: [
              '집합이란 어떤 조건에 따라 대상을 분명하게 정할 수 있는 것들의 모임입니다. 집합을 표현하는 방법 중 가장 직관적인 방법이 바로 \'원소나열법\'입니다. 원소나열법은 집합에 속하는 모든 원소를 중괄호 { } 안에 쉼표(,)로 구분하여 일일이 나열하는 방식입니다. 예를 들어, 10보다 작은 소수의 집합을 \$A\$라고 할 때, 이를 원소나열법으로 나타내면 \$A = \\{2, 3, 5, 7\\}\$과 같이 씁니다.',
              '원소나열법을 사용할 때 반드시 지켜야 할 몇 가지 약속이 있습니다. 첫째, 원소의 순서는 집합의 성질에 영향을 주지 않으므로 나열하는 순서는 마음대로 바꾸어도 상관없습니다. 둘째, 같은 원소는 중복해서 쓰지 않고 한 번만 적습니다. 예를 들어, \'APPLE\'이라는 단어에 포함된 알파벳의 집합 \$B\$는 원소의 중복을 허용하지 않으므로 \$B = \\{A, P, L, E\\}\$가 됩니다.',
              '원소의 개수가 너무 많거나 원소가 일정한 규칙을 가지고 나열될 때는 생략 기호인 \'...\'을 사용하여 나타낼 수 있습니다. 예를 들어, 1부터 100까지의 자연수 집합 \$C\$는 \$C = \\{1, 2, 3, \\dots, 100\\}\$과 같이 표현합니다. 만약 원소가 무한히 많다면 \$D = \\{1, 2, 3, \\dots\\}\$와 같이 끝을 생략하여 자연수 전체의 집합을 나타낼 수도 있습니다. 이처럼 원소나열법은 집합의 구성원을 명확하게 보여준다는 큰 장점이 있습니다.',
              '이제 예제를 통해 원소나열법을 익혀봅시다. \'12의 양의 약수의 집합을 \$E\$라고 할 때, 이를 원소나열법으로 나타내시오.\'라는 문제를 풀어보겠습니다. 먼저 12를 나누어떨어지게 하는 자연수를 모두 찾습니다. 12의 약수는 1, 2, 3, 4, 6, 12입니다. 이 원소들을 중괄호 안에 쉼표로 구분하여 나열하면 집합 \$E\$가 완성됩니다.',
              '위 문제의 풀이 과정을 수식으로 정리하면 다음과 같습니다. 먼저 12의 약수를 구하는 식은 \$12 = 1 \\times 12 = 2 \\times 6 = 3 \\times 4\$입니다. 따라서 구하는 집합 \$E\$는 다음과 같이 표현할 수 있습니다. \$\$E = \\{1, 2, 3, 4, 6, 12\\}\$\$ 이처럼 원소나열법은 집합의 정의에 충실하여 원소를 하나하나 확인하며 작성하는 것이 가장 정확한 방법입니다.',
            ],
          ),
        ],
      ),
    ],
  ),
  '일반항': BookData(
    id: 'concept_일반항',
    title: '일반항',
    subtitle: '대수 > 수열 > 수열의정의 > 일반항',
    category: 'common',
    tags: ['대수', '수열', '수열의정의', '일반항'],
    chapters: [
      BookChapter(
        title: '일반항',
        intro: ['대수 > 수열 > 수열의정의 > 일반항 개념 학습'],
        sections: [
          BookSection(
            title: '일반항',
            paragraphs: [
              '수열이란 일정한 규칙에 따라 차례대로 나열된 수의 열을 의미합니다. 이때 수열을 구성하는 각각의 수를 항이라고 하며, 첫 번째 항을 제1항, 두 번째 항을 제2항과 같이 부릅니다. 수열에서 제\$n\$항을 \$a_n\$이라고 나타낼 때, 이 \$a_n\$을 수열의 일반항이라고 합니다. 일반항은 수열의 모든 항을 대표하는 식으로, \$n\$에 자연수를 대입하면 해당 순서의 항의 값을 바로 구할 수 있게 해주는 수열의 \'설계도\'와 같은 역할을 합니다.',
              '일반항 \$a_n\$을 구한다는 것은 수열의 규칙성을 \$n\$에 관한 식으로 표현하는 것을 의미합니다. 예를 들어, 수열 \$2, 4, 6, 8, \\dots\$와 같이 각 항이 2씩 커지는 경우, 제\$n\$항은 \$2 \\times n\$으로 나타낼 수 있으므로 일반항은 \$\$a_n = 2n\$\$이 됩니다. 이처럼 일반항을 알면 수열의 제100항이 무엇인지 계산하기 위해 일일이 나열할 필요 없이, \$n=100\$을 대입하여 \$a_{100} = 2 \\times 100 = 200\$임을 즉시 알아낼 수 있습니다.',
              '일반항을 구하는 과정에서는 수열의 앞뒤 항 사이의 관계나 변화의 폭을 관찰하는 것이 중요합니다. 만약 수열의 항들이 \$a_1, a_2, a_3, \\dots, a_n, \\dots\$로 나열되어 있다면, 각 항의 번호 \$n\$과 그 항의 값 \$a_n\$ 사이의 대응 관계를 찾아야 합니다. 때로는 등차수열이나 등비수열처럼 정형화된 공식이 존재하기도 하지만, 복잡한 수열의 경우 항들의 차이나 비율을 분석하여 \$n\$에 대한 식을 유도해내는 논리적 사고력이 필요합니다.',
              '예제 문제: 수열 \$3, 5, 7, 9, 11, \\dots\$의 일반항 \$a_n\$을 구하고, 이 수열의 제20항을 구하시오. [풀이 단계 1] 먼저 항들의 변화를 관찰합니다. 제1항은 3, 제2항은 5, 제3항은 7로 각 항이 2씩 커지고 있습니다. 이는 \$2n\$이라는 식을 기본으로 하되, \$n=1\$일 때 3이 되어야 하므로 1을 더해주어야 함을 알 수 있습니다. 따라서 일반항은 \$\$a_n = 2n + 1\$\$입니다.',
              '[풀이 단계 2] 구한 일반항 식에 \$n=20\$을 대입하여 제20항을 계산합니다. 일반항 공식 \$a_n = 2n + 1\$에 \$n=20\$을 대입하면 \$\$a_{20} = 2(20) + 1 = 40 + 1 = 41\$\$이 됩니다. 따라서 이 수열의 일반항은 \$a_n = 2n + 1\$이며, 제20항의 값은 41입니다.',
            ],
          ),
        ],
      ),
    ],
  ),
