  '미분계수의기하적의미': BookData(
    id: 'concept_미분계수의기하적의미',
    title: '미분계수의기하적의미',
    subtitle: '미적분Ⅰ > 미분계수 > 미분계수의기하적의미',
    category: 'common',
    tags: ['미적분Ⅰ', '미분계수', '미분계수의기하적의미'],
    chapters: [
      BookChapter(
        title: '미분계수의기하적의미',
        intro: ['미적분Ⅰ > 미분계수 > 미분계수의기하적의미 개념 학습'],
        sections: [
          BookSection(
            title: '미분계수의기하적의미',
            paragraphs: [
              '미분계수의 기하적 의미를 이해하기 위해서는 먼저 \'평균변화율\'과 \'접선\'의 개념을 연결해야 합니다. 함수 \$y=f(x)\$의 그래프 위의 두 점 \$A(a, f(a))\$와 \$B(a+h, f(a+h))\$를 지나는 직선의 기울기는 두 점 사이의 평균변화율로, 그 식은 \$\$\\frac{f(a+h)-f(a)}{h}\$\$와 같습니다. 여기서 \$h\$의 값을 0에 한없이 가깝게 만들면, 점 \$B\$는 곡선을 따라 점 \$A\$로 한없이 다가가게 됩니다.',
              '이때 점 \$B\$가 점 \$A\$에 한없이 가까워질 때, 두 점을 잇는 직선은 점 \$A\$에서의 \'접선\'으로 변하게 됩니다. 즉, 미분계수 \$f\'(a)\$는 함수 \$y=f(x)\$의 그래프 위의 점 \$(a, f(a))\$에서의 접선의 기울기를 의미합니다. 이를 수학적 극한 기호로 나타내면 다음과 같은 공식이 성립합니다. \$\$f\'(a) = \\lim_{h \\to 0} \\frac{f(a+h)-f(a)}{h}\$\$ 이 식은 곡선 위의 특정 지점에서 그래프가 얼마나 가파르게 변하는지를 나타내는 지표가 됩니다.',
              '미분계수의 기하적 의미를 활용하면 곡선 위의 한 점 \$(a, f(a))\$를 지나는 접선의 방정식을 쉽게 구할 수 있습니다. 접선의 기울기가 \$f\'(a)\$이고 점 \$(a, f(a))\$를 지나므로, 직선의 방정식 기본 원리에 따라 접선의 방정식은 다음과 같이 표현됩니다. \$\$y - f(a) = f\'(a)(x - a)\$\$ 이처럼 미분계수는 단순히 수치적인 계산을 넘어, 곡선의 모양을 파악하고 접선을 그리는 데 핵심적인 도구로 사용됩니다.',
              '예제 문제를 통해 이를 적용해 봅시다. 함수 \$f(x) = x^2\$의 그래프 위의 점 \$(2, 4)\$에서의 접선의 기울기를 구하고, 접선의 방정식을 세워보겠습니다. 먼저 점 \$x=2\$에서의 미분계수를 구하기 위해 도함수 \$f\'(x) = 2x\$를 이용합니다. 따라서 \$x=2\$일 때의 접선의 기울기는 \$\$f\'(2) = 2 \\times 2 = 4\$\$가 됩니다.',
              '이제 구한 기울기 \$4\$와 점 \$(2, 4)\$를 접선의 방정식 공식에 대입합니다. \$\$y - 4 = 4(x - 2)\$\$ 이 식을 정리하면 \$\$y - 4 = 4x - 8\$\$이 되며, 최종적으로 접선의 방정식은 \$\$y = 4x - 4\$\$가 됩니다. 이 결과는 이차함수 \$y=x^2\$의 그래프가 점 \$(2, 4)\$에서 기울기가 4인 직선과 접하고 있음을 기하학적으로 보여줍니다.',
            ],
          ),
        ],
      ),
    ],
  ),
