    chapters: [
      BookChapter(
        title: '조건제시법',
        intro: ['공통수학2 > 집합 > 집합의표현 > 조건제시법 개념 학습'],
        sections: [
          BookSection(
            title: '조건제시법',
            paragraphs: [
              '집합을 표현하는 방법 중 하나인 \'조건제시법\'은 집합에 속하는 원소들을 일일이 나열하는 대신, 그 원소들이 공통으로 만족하는 성질(조건)을 기술하여 집합을 정의하는 방식입니다. 이 방법은 원소의 개수가 너무 많거나 무한히 많은 경우, 혹은 원소의 규칙을 명확하게 밝히고 싶을 때 매우 유용하게 사용됩니다.',
              '조건제시법의 기본 형식은 \$\$ \\{ x \\mid P(x) \\} \$\$ 와 같습니다. 여기서 중괄호(\$\\{ \\}\$)는 집합을 나타내고, 세로 막대(\$\\mid\$)는 \'바(bar)\'라고 읽으며 \'이 조건을 만족하는\'이라는 뜻을 가집니다. 왼쪽의 \$x\$는 집합의 대표 원소를 의미하며, 오른쪽의 \$P(x)\$는 그 원소가 갖추어야 할 구체적인 조건입니다. 즉, 이 식은 \'\$P(x)\$라는 조건을 만족하는 모든 \$x\$들의 모임\'이라는 뜻입니다.',
              '조건제시법을 작성할 때는 대표 원소의 범위나 성질을 명확히 명시해야 합니다. 예를 들어, \'10 이하의 자연수\'라는 조건은 \$\$ \\{ x \\mid x \\text{는 } 10 \\text{ 이하의 자연수} \\} \$\$ 로 표현할 수 있습니다. 이때 원소의 조건이 복잡하다면 쉼표(,)를 사용하여 여러 조건을 나열할 수 있으며, 대표 원소가 수식의 형태를 띠는 경우 \$\$ \\{ 2n \\mid n \\text{은 } 5 \\text{ 이하의 자연수} \\} \$\$ 와 같이 표현하여 원소의 생성 규칙을 직접 보여줄 수도 있습니다.',
              '예제 문제: 다음 조건제시법으로 나타낸 집합 \$A\$를 원소나열법으로 나타내시오. \$\$ A = \\{ x \\mid x \\text{는 } 12 \\text{의 양의 약수} \\} \$\$',
              '단계별 풀이: 1단계, 주어진 조건인 \'12의 양의 약수\'가 무엇인지 생각합니다. 12를 나누었을 때 나머지가 0이 되는 자연수를 찾으면 1, 2, 3, 4, 6, 12입니다. 2단계, 이 수들을 중괄호 안에 쉼표로 구분하여 나열합니다. 따라서 구하는 집합은 \$\$ A = \\{ 1, 2, 3, 4, 6, 12 \\} \$\$ 가 됩니다.',
              '예제 문제: 다음 조건제시법으로 나타낸 집합 \$B\$의 모든 원소의 합을 구하시오. \$\$ B = \\{ 2n-1 \\mid n \\in \\{1, 2, 3, 4\\} \\} \$\$ 단계별 풀이: 1단계, \$n\$에 주어진 집합의 원소들을 하나씩 대입합니다. \$n=1\$일 때 \$2(1)-1=1\$, \$n=2\$일 때 \$2(2)-1=3\$, \$n=3\$일 때 \$2(3)-1=5\$, \$n=4\$일 때 \$2(4)-1=7\$입니다. 2단계, 계산된 결과값들을 모아 집합 \$B = \\{ 1, 3, 5, 7 \\}\$을 완성합니다. 3단계, 모든 원소의 합을 구하면 \$1+3+5+7 = 16\$이 됩니다.',
