    subtitle: '공통수학1 > 이차함수 > 이차함수의그래프 > 포물선',
    category: 'common',
    tags: ['공통수학1', '이차함수', '이차함수의그래프', '포물선'],
    chapters: [
      BookChapter(
        title: '포물선',
        intro: ['공통수학1 > 이차함수 > 이차함수의그래프 > 포물선 개념 학습'],
        sections: [
          BookSection(
            title: '포물선',
            paragraphs: [
              '포물선이란 평면 위의 한 점인 \'초점\'과 그 점을 지나지 않는 한 직선인 \'준선\'으로부터 같은 거리에 있는 점들의 집합을 말합니다. 이차함수의 그래프로 잘 알려진 포물선은 대칭축을 중심으로 좌우가 완벽하게 대칭을 이루는 곡선입니다. 이차함수 \$y = ax^2 + bx + c\$ (\$a \\neq 0\$)의 그래프는 가장 대표적인 포물선이며, 이 곡선은 어느 방향에서 들어오는 빛이라도 초점에 모이게 하는 특별한 성질을 가지고 있어 안테나나 자동차 전조등 설계에 널리 활용됩니다.',
              '이차함수의 기본형인 \$y = ax^2\$의 그래프에서 \$a\$의 값은 포물선의 모양을 결정합니다. \$|a|\$가 클수록 그래프의 폭은 좁아지고, \$|a|\$가 작을수록 폭은 넓어집니다. 또한 \$a > 0\$이면 아래로 볼록한 모양이 되고, \$a < 0\$이면 위로 볼록한 모양이 됩니다. 포물선의 가장 뾰족하거나 오목한 지점을 \'꼭짓점\'이라고 하며, 이차함수 \$y = a(x-p)^2 + q\$의 꼴로 식을 변형하면 꼭짓점의 좌표를 \$(p, q)\$로 쉽게 찾을 수 있습니다.',
              '포물선의 핵심적인 성질 중 하나는 꼭짓점을 지나는 직선인 \'축\'에 대한 대칭성입니다. 이차함수 \$y = ax^2 + bx + c\$에서 축의 방정식은 \$\$x = -\\frac{b}{2a}\$\$ 입니다. 이 축을 기준으로 그래프의 왼쪽과 오른쪽이 포개어지며, 꼭짓점의 \$x\$좌표가 바로 이 축의 방정식과 일치합니다. 이러한 대칭성을 이해하면 그래프를 그릴 때 몇 개의 점만으로도 전체적인 형태를 정확하게 파악할 수 있습니다.',
              '이제 예제를 통해 포물선의 그래프를 그려봅시다. 이차함수 \$y = 2x^2 - 8x + 5\$의 꼭짓점과 축의 방정식을 구해보세요. 먼저 식을 완전제곱식 꼴로 변형해야 합니다. 상수항을 분리한 뒤 \$x\$항을 묶어주면 \$\$y = 2(x^2 - 4x) + 5\$\$가 됩니다. 괄호 안을 완전제곱식으로 만들기 위해 \$x\$ 계수의 절반의 제곱인 \$4\$를 더하고 빼주면 \$\$y = 2(x^2 - 4x + 4 - 4) + 5 = 2(x-2)^2 - 8 + 5\$\$가 되어 최종적으로 \$\$y = 2(x-2)^2 - 3\$\$이라는 식을 얻을 수 있습니다.',
              '위에서 구한 식 \$y = 2(x-2)^2 - 3\$을 분석하면, 이 포물선의 꼭짓점 좌표는 \$(2, -3)\$임을 알 수 있습니다. 또한, 꼭짓점의 \$x\$좌표가 축의 방정식이 되므로 이 포물선의 축은 직선 \$\$x = 2\$\$입니다. \$a=2\$로 양수이므로 아래로 볼록한 모양이며, \$x=0\$을 대입하면 \$y=5\$가 되어 \$y\$축과 \$(0, 5)\$에서 만난다는 사실까지 알 수 있습니다. 이처럼 식을 변형하면 포물선의 위치와 모양을 완벽하게 파악할 수 있습니다.',
            ],
          ),
        ],
      ),
    ],
