  '수열의표현': BookData(
    id: 'concept_수열의표현',
    title: '수열의표현',
    subtitle: '대수 > 수열 > 수열의정의 > 수열의표현',
    category: 'common',
    tags: ['대수', '수열', '수열의정의', '수열의표현'],
    chapters: [
      BookChapter(
        title: '수열의표현',
        intro: ['대수 > 수열 > 수열의정의 > 수열의표현 개념 학습'],
        sections: [
          BookSection(
            title: '수열의표현',
            paragraphs: [
              '[   "수열이란 자연수의 집합에서 정의된 함수로, 일정한 규칙에 따라 수들을 차례대로 나열한 것을 말합니다. 이때 나열된 각각의 수를 그 수열의 \'항\'이라고 하며, 앞에서부터 첫 번째 항을 제1항, 두 번째 항을 제2항, n번째 항을 제n항이라고 부릅니다. 보통 수열을 나타낼 때는 수열의 이름을 붙여 \$\\{a_n\\}\$과 같이 표현하며, 제n항 \$a_n\$을 그 수열의 \'일반항\'이라고 합니다.",   "일반항 \$a_n\$은 수열의 모든 항을 \$n\$에 관한 식으로 나타낸 것으로, \$n\$에 자연수를 대입하면 수열의 각 항을 구할 수 있습니다. 예를 들어, 일반항이 \$\$a_n = 2n - 1\$\$인 수열은 \$n=1, 2, 3, \\dots\$을 차례로 대입하여 \$1, 3, 5, \\dots\$과 같이 나열할 수 있습니다. 이처럼 일반항을 알면 수열의 어떤 번째 항이라도 바로 찾아낼 수 있다는 점이 수열 표현의 핵심입니다.",   "수열을 표현하는 또 다른 방법으로는 \'귀납적 정의\'가 있습니다. 이는 첫째항 \$a_1\$의 값과 이웃하는 두 항 사이의 관계식(점화식)을 이용하여 수열을 정의하는 방식입니다. 예를 들어, \$\$a_1 = 1, a_{n+1} = a_n + 2\$\$와 같이 표현하면, 첫째항부터 차례대로 다음 항을 결정해 나가는 방식으로 수열 전체를 구성할 수 있습니다.",   "예제 1: 일반항이 \$\$a_n = n^2 + 1\$\$로 주어질 때, 이 수열의 제1항부터 제4항까지를 구하시오. [풀이] 일반항의 식에 \$n\$ 대신 \$1, 2, 3, 4\$를 차례로 대입합니다. \$n=1\$일 때 \$a_1 = 1^2 + 1 = 2\$, \$n=2\$일 때 \$a_2 = 2^2 + 1 = 5\$, \$n=3\$일 때 \$a_3 = 3^2 + 1 = 10\$, \$n=4\$일 때 \$a_4 = 4^2 + 1 = 17\$입니다. 따라서 구하는 항은 \$2, 5, 10, 17\$입니다.",   "예제 2: 첫째항이 \$a_1 = 3\$이고, 이웃하는 두 항의 관계가 \$\$a_{n+1} = 2a_n\$\$일 때, 제3항 \$a_3\$를 구하시오. [풀이] 주어진 관계식을 이용하여 차례대로 항을 구합니다. 먼저 \$n=1\$을 대입하면 \$a_2 = 2a_1 = 2 \\times 3 = 6\$이 됩니다. 이어서 \$n=2\$를 대입하면 \$a_3 = 2a_2 = 2 \\times 6 = 12\$가 됩니다. 따라서 제3항은 \$12\$입니다." ]',
            ],
          ),
        ],
      ),
    ],
  ),
  '속도와거리': BookData(
    id: 'concept_속도와거리',
    title: '속도와거리',
    subtitle: '미적분Ⅰ > 정적분과속도 > 속도와거리',
    category: 'common',
    tags: ['미적분Ⅰ', '정적분과속도', '속도와거리'],
    chapters: [
      BookChapter(
        title: '속도와거리',
        intro: ['미적분Ⅰ > 정적분과속도 > 속도와거리 개념 학습'],
        sections: [
          BookSection(
            title: '속도와거리',
            paragraphs: [
              '수직선 위를 움직이는 점 \$P\$의 시각 \$t\$에서의 위치를 \$x(t)\$라고 할 때, 시각 \$t\$에서의 속도를 \$v(t)\$라고 합니다. 위치의 변화율이 곧 속도이므로, 위치를 시간으로 미분하면 속도가 됩니다. 반대로 속도를 시간으로 적분하면 위치의 변화량을 구할 수 있습니다. 시각 \$t=a\$에서 \$t=b\$까지 점 \$P\$의 위치의 변화량은 속도 함수 \$v(t)\$를 정적분하여 다음과 같이 구할 수 있습니다.',
              '위치의 변화량과 달리, 실제로 점 \$P\$가 움직인 총 거리는 속도의 절댓값을 적분하여 구합니다. 속도의 절댓값 \$|v(t)|\$는 \'속력\'을 의미하며, 이는 항상 0보다 크거나 같습니다. 따라서 시각 \$t=a\$에서 \$t=b\$까지 점 \$P\$가 움직인 총 거리는 다음과 같은 공식으로 계산합니다. \$\$ \\text{위치의 변화량} = \\int_{a}^{b} v(t) dt, \\quad \\text{움직인 거리} = \\int_{a}^{b} |v(t)| dt \$\$',
              '예를 들어, 수직선 위를 움직이는 점 \$P\$의 시각 \$t\$에서의 속도가 \$v(t) = 3t^2 - 6t\$라고 가정해 봅시다. 시각 \$t=0\$에서 \$t=3\$까지 점 \$P\$가 움직인 총 거리를 구하려면 먼저 속도 함수 \$v(t)\$의 부호를 확인해야 합니다. \$3t^2 - 6t = 3t(t-2)\$이므로, \$0 \\le t < 2\$일 때는 \$v(t) < 0\$이고, \$2 < t \\le 3\$일 때는 \$v(t) > 0\$임을 알 수 있습니다.',
              '이제 구간을 나누어 정적분을 계산합니다. 움직인 거리는 속력의 적분이므로, \$v(t)\$가 음수인 구간에서는 부호를 바꾸어 적분해야 합니다. 즉, 총 이동 거리는 다음과 같이 계산합니다. \$\$ \\int_{0}^{3} |3t^2 - 6t| dt = \\int_{0}^{2} -(3t^2 - 6t) dt + \\int_{2}^{3} (3t^2 - 6t) dt \$\$',
              '각 구간의 정적분을 단계별로 계산하면 다음과 같습니다. 첫 번째 구간인 \$0\$부터 \$2\$까지는 \$\\int_{0}^{2} (-3t^2 + 6t) dt = [-t^3 + 3t^2]_{0}^{2} = (-8 + 12) - 0 = 4\$입니다. 두 번째 구간인 \$2\$부터 \$3\$까지는 \$\\int_{2}^{3} (3t^2 - 6t) dt = [t^3 - 3t^2]_{2}^{3} = (27 - 27) - (8 - 12) = 0 - (-4) = 4\$입니다.',
              '따라서 시각 \$t=0\$에서 \$t=3\$까지 점 \$P\$가 움직인 총 거리는 \$4 + 4 = 8\$이 됩니다. 이처럼 속도 함수가 중간에 부호가 바뀌는 경우에는 반드시 그래프를 그려 속력이 양수가 되도록 구간을 나누어 적분하는 것이 핵심입니다. 이 과정을 통해 우리는 물체의 운동 경로와 실제 이동 거리를 정확하게 파악할 수 있습니다.',
            ],
          ),
        ],
      ),
    ],
  ),
  '다항식의뺄셈': BookData(
    id: 'concept_다항식의뺄셈',
    title: '다항식의뺄셈',
    subtitle: '공통수학1 > 다항식 > 다항식의연산 > 다항식의뺄셈',
    category: 'common',
    tags: ['공통수학1', '다항식', '다항식의연산', '다항식의뺄셈'],
    chapters: [
      BookChapter(
        title: '다항식의뺄셈',
        intro: ['공통수학1 > 다항식 > 다항식의연산 > 다항식의뺄셈 개념 학습'],
        sections: [
          BookSection(
            title: '다항식의뺄셈',
            paragraphs: [
              '[   "다항식의 뺄셈은 기본적으로 다항식의 덧셈과 같은 원리로 이루어집니다. 어떤 다항식에서 다른 다항식을 뺄 때, 빼는 다항식의 각 항의 부호를 모두 반대로 바꾼 뒤 더해주면 됩니다. 즉, 다항식 \$A\$에서 다항식 \$B\$를 빼는 것은 \$A\$에 \$B\$의 각 항의 부호를 바꾼 \$-B\$를 더하는 것과 같습니다. 이를 기호로 나타내면 \$A - B = A + (-B)\$가 됩니다.",   "다항식의 뺄셈을 계산할 때는 먼저 괄호를 풀어야 합니다. 이때 괄호 앞에 마이너스(\$-\$) 기호가 있다면, 괄호 안의 모든 항의 부호를 바꾸어 괄호를 없앱니다. 예를 들어 \$-(ax^2 + bx + c)\$는 \$-ax^2 - bx - c\$가 됩니다. 괄호를 모두 푼 다음에는 차수가 같은 항끼리 모으는 \'동류항 정리\' 과정을 거쳐야 합니다. 동류항이란 문자와 차수가 각각 같은 항을 말하며, 이들의 계수끼리 더하거나 빼서 식을 간단히 정리합니다.",   "다항식의 뺄셈을 수행하는 핵심 공식과 성질은 다음과 같습니다. 두 다항식 \$A, B\$에 대하여 \$A - B\$를 계산할 때, \$A\$의 각 항을 \$a_n x^n + \\dots + a_0\$라 하고 \$B\$의 각 항을 \$b_n x^n + \\dots + b_0\$라고 하면, 결과는 다음과 같이 각 차수의 계수끼리 뺀 값으로 나타납니다. \$\$A - B = \\sum_{i=0}^{n} (a_i - b_i)x^i\$\$ 이처럼 다항식의 뺄셈은 각 동류항의 계수를 빼는 연산으로 귀결됩니다.",   "이제 구체적인 예제를 통해 다항식의 뺄셈을 연습해 봅시다. 두 다항식 \$A = 3x^2 - 2x + 5\$와 \$B = x^2 + 4x - 1\$이 있을 때, \$A - B\$를 계산해 보겠습니다. 먼저 식을 세우면 \$(3x^2 - 2x + 5) - (x^2 + 4x - 1)\$이 됩니다. 여기서 괄호 앞의 마이너스를 분배하여 괄호를 풀면 \$3x^2 - 2x + 5 - x^2 - 4x + 1\$이 됩니다.",   "다음 단계는 동류항끼리 모아서 계산하는 것입니다. \$x^2\$항은 \$3x^2 - x^2 = 2x^2\$이 되고, \$x\$항은 \$-2x - 4x = -6x\$가 되며, 상수항은 \$5 + 1 = 6\$이 됩니다. 이 결과들을 모두 합치면 최종적으로 \$2x^2 - 6x + 6\$이라는 결과를 얻을 수 있습니다. 이처럼 다항식의 뺄셈은 부호 변화에 주의하며 동류항을 차근차근 정리하는 것이 가장 중요합니다." ]',
            ],
          ),
        ],
      ),
    ],
  ),
  '쌍곡선': BookData(
    id: 'concept_쌍곡선',
    title: '쌍곡선',
    subtitle: '공통수학2 > 유리식과유리함수 > 유리함수의그래프 > 쌍곡선',
    category: 'common',
    tags: ['공통수학2', '유리식과유리함수', '유리함수의그래프', '쌍곡선'],
    chapters: [
      BookChapter(
        title: '쌍곡선',
        intro: ['공통수학2 > 유리식과유리함수 > 유리함수의그래프 > 쌍곡선 개념 학습'],
        sections: [
          BookSection(
            title: '쌍곡선',
            paragraphs: [
              '쌍곡선이란 평면 위의 두 정점으로부터의 거리의 차가 일정한 점들의 집합을 말합니다. 이때 두 정점을 쌍곡선의 초점이라고 하며, 두 초점을 지나는 직선과 쌍곡선이 만나는 두 점을 꼭짓점이라고 합니다. 두 꼭짓점의 중점을 쌍곡선의 중심이라고 부르며, 쌍곡선은 이 중심에 대하여 대칭인 두 개의 곡선으로 이루어져 있습니다.',
              '좌표평면 위에서 중심이 원점 \$(0, 0)\$이고 초점이 \$x\$축 위의 점 \$F(c, 0)\$, \$F\'(-c, 0)\$인 쌍곡선의 방정식은 다음과 같습니다. 이때 거리의 차를 \$2a\$라고 하면, 쌍곡선의 방정식은 \$\$ \\frac{x^2}{a^2} - \\frac{y^2}{b^2} = 1 \\quad (단, b^2 = c^2 - a^2) \$\$ 과 같이 나타낼 수 있습니다. 여기서 \$a\$는 꼭짓점의 \$x\$좌표를 결정하며, \$b\$는 쌍곡선이 점근선에 가까워지는 정도를 결정하는 중요한 상수입니다.',
              '쌍곡선의 중요한 특징 중 하나는 \'점근선\'의 존재입니다. 쌍곡선은 곡선이 뻗어 나가면서 점점 가까워지는 두 직선을 가지는데, 위 방정식의 경우 점근선의 방정식은 \$\$ y = \\frac{b}{a}x \\quad \\text{또는} \\quad y = -\\frac{b}{a}x \$\$ 가 됩니다. 쌍곡선은 이 두 직선 사이의 영역에 그려지며, 곡선이 직선에 한없이 가까워지지만 결코 만나지는 않는다는 성질을 가집니다.',
              '예제: 방정식 \$\\frac{x^2}{16} - \\frac{y^2}{9} = 1\$이 나타내는 쌍곡선의 꼭짓점과 점근선의 방정식을 구해보겠습니다. 먼저 주어진 식을 표준형 \$\\frac{x^2}{a^2} - \\frac{y^2}{b^2} = 1\$과 비교하면 \$a^2 = 16\$, \$b^2 = 9\$임을 알 수 있습니다. 따라서 \$a=4\$, \$b=3\$입니다.',
              '단계별 풀이로 첫째, 꼭짓점은 \$x\$축 위에 있으므로 \$(\\pm a, 0)\$인 \$(\\pm 4, 0)\$이 됩니다. 둘째, 점근선의 방정식은 공식 \$y = \\pm \\frac{b}{a}x\$에 대입하여 구합니다. \$a=4, b=3\$을 대입하면 점근선은 \$\$ y = \\frac{3}{4}x \\quad \\text{와} \\quad y = -\\frac{3}{4}x \$\$ 가 됩니다. 이처럼 쌍곡선은 \$a\$와 \$b\$의 값만 알면 그 형태와 점근선을 쉽게 파악할 수 있습니다.',
            ],
          ),
        ],
      ),
    ],
  ),
  '스칼라곱': BookData(
    id: 'concept_스칼라곱',
    title: '스칼라곱',
    subtitle: '공통수학1 > 행렬 > 행렬의연산 > 스칼라곱',
    category: 'common',
    tags: ['공통수학1', '행렬', '행렬의연산', '스칼라곱'],
    chapters: [
      BookChapter(
        title: '스칼라곱',
        intro: ['공통수학1 > 행렬 > 행렬의연산 > 스칼라곱 개념 학습'],
        sections: [
          BookSection(
            title: '스칼라곱',
            paragraphs: [
              '행렬의 스칼라곱이란 행렬의 각 성분에 특정한 실수(스칼라)를 곱하는 연산을 의미합니다. 행렬 \$A\$의 모든 성분에 실수 \$k\$를 곱하여 얻은 새로운 행렬을 \$kA\$라고 표기하며, 이는 행렬의 크기를 변화시키지 않고 각 성분의 값을 \$k\$배만큼 확대하거나 축소하는 효과를 가집니다. 예를 들어, \$m \\times n\$ 행렬 \$A\$의 \$(i, j)\$ 성분을 \$a_{ij}\$라고 할 때, 스칼라곱 \$kA\$의 \$(i, j)\$ 성분은 \$k \\times a_{ij}\$가 됩니다.',
              '스칼라곱은 행렬의 덧셈 및 뺄셈과 함께 결합하여 다양한 성질을 만족합니다. 실수 \$k, l\$과 행렬 \$A, B\$에 대하여, 스칼라곱은 분배법칙 \$(k+l)A = kA + lA\$ 및 \$k(A+B) = kA + kB\$를 따르며, 결합법칙 \$k(lA) = (kl)A\$ 또한 성립합니다. 이러한 성질들은 복잡한 행렬식을 간단히 정리하거나 미지수 행렬을 구할 때 매우 유용하게 사용됩니다.',
              '이제 구체적인 예제를 통해 스칼라곱을 계산해 봅시다. 행렬 \$A = \\begin{pmatrix} 2 & -1 \\\\ 0 & 3 \\end{pmatrix}\$일 때, \$3A\$를 구하는 과정은 다음과 같습니다. 행렬 \$A\$의 각 성분에 실수 \$3\$을 곱하면, \$3A = \\begin{pmatrix} 3 \\times 2 & 3 \\times (-1) \\\\ 3 \\times 0 & 3 \\times 3 \\end{pmatrix}\$이 됩니다.',
              '위의 계산을 마무리하면 최종 결과는 \$3A = \\begin{pmatrix} 6 & -3 \\\\ 0 & 9 \\end{pmatrix}\$가 됩니다. 이처럼 스칼라곱은 행렬 내부의 모든 요소에 동일한 배수를 적용하는 간단한 연산이지만, 선형대수학의 기초가 되는 매우 중요한 개념입니다.',
              '조금 더 응용된 문제를 풀어보겠습니다. 행렬 \$A = \\begin{pmatrix} 1 & 2 \\\\ 3 & 4 \\end{pmatrix}\$와 \$B = \\begin{pmatrix} 0 & 1 \\\\ -1 & 2 \\end{pmatrix}\$에 대하여 \$2A - 3B\$를 계산해 봅시다. 먼저 각 행렬에 스칼라곱을 적용하면 \$2A = \\begin{pmatrix} 2 & 4 \\\\ 6 & 8 \\end{pmatrix}\$, \$3B = \\begin{pmatrix} 0 & 3 \\\\ -3 & 6 \\end{pmatrix}\$이 됩니다.',
              '마지막으로 두 행렬의 차를 구하면 \$2A - 3B = \\begin{pmatrix} 2-0 & 4-3 \\\\ 6-(-3) & 8-6 \\end{pmatrix} = \\begin{pmatrix} 2 & 1 \\\\ 9 & 2 \\end{pmatrix}\$가 됩니다. 이와 같이 스칼라곱을 먼저 수행한 뒤 행렬의 덧셈이나 뺄셈을 진행하면 복잡한 식도 단계별로 정확하게 해결할 수 있습니다.',
            ],
          ),
        ],
      ),
    ],
  ),
  '도함수의정의': BookData(
    id: 'concept_도함수의정의',
    title: '도함수의정의',
    subtitle: '미적분Ⅰ > 도함수 > 도함수의정의',
    category: 'common',
    tags: ['미적분Ⅰ', '도함수', '도함수의정의'],
    chapters: [
      BookChapter(
        title: '도함수의정의',
        intro: ['미적분Ⅰ > 도함수 > 도함수의정의 개념 학습'],
        sections: [
          BookSection(
            title: '도함수의정의',
            paragraphs: [
              '미분계수의 개념을 확장하면 함수 \$f(x)\$의 각 점에서의 순간변화율을 나타내는 새로운 함수를 얻을 수 있는데, 이를 \'도함수\'라고 합니다. 어떤 함수 \$f(x)\$의 정의역에 속하는 모든 \$x\$에 대하여 미분계수 \$f\'(x)\$가 존재할 때, 이 미분계수를 \$x\$의 함수로 나타낸 것을 도함수라 하며, 기호로는 \$f\'(x)\$, \$\\frac{dy}{dx}\$, \$y\'\$ 등으로 나타냅니다.',
              '도함수의 정의는 미분계수의 정의를 일반화한 것으로, 다음과 같은 극한의 식을 통해 구할 수 있습니다. 함수 \$f(x)\$에 대하여 도함수 \$f\'(x)\$는 \$\$f\'(x) = \\lim_{h \\to 0} \\frac{f(x+h) - f(x)}{h}\$\$ 로 정의됩니다. 이 식은 함수 위의 임의의 점 \$(x, f(x))\$에서의 접선의 기울기를 구하는 과정과 같으며, 이 극한값이 존재할 때 함수 \$f(x)\$는 \'미분가능하다\'고 말합니다.',
              '도함수를 구하는 과정을 \'미분한다\'라고 하며, 도함수의 정의를 이용하면 다항함수의 미분법을 유도할 수 있습니다. 예를 들어 \$f(x) = x^n\$일 때, 도함수의 정의를 적용하면 \$f\'(x) = nx^{n-1}\$이라는 매우 유용한 공식을 얻게 됩니다. 이처럼 도함수는 함수가 변화하는 정도를 수치화하여, 복잡한 함수의 그래프 개형을 파악하거나 최댓값과 최솟값을 찾는 데 핵심적인 도구가 됩니다.',
              '예제: 함수 \$f(x) = x^2 + 3x\$의 도함수를 정의를 이용하여 구해보겠습니다. 먼저 도함수의 정의식에 \$f(x)\$를 대입하면 \$\$f\'(x) = \\lim_{h \\to 0} \\frac{\\{(x+h)^2 + 3(x+h)\\} - (x^2 + 3x)}{h}\$\$ 가 됩니다. 이제 분자를 전개하여 식을 정리합니다.',
              '분자를 전개하면 \$x^2 + 2xh + h^2 + 3x + 3h - x^2 - 3x\$가 되며, 이를 정리하면 \$2xh + h^2 + 3h\$만 남게 됩니다. 따라서 식은 \$\$f\'(x) = \\lim_{h \\to 0} \\frac{2xh + h^2 + 3h}{h}\$\$ 가 됩니다. 분모와 분자를 \$h\$로 약분하면 \$\$f\'(x) = \\lim_{h \\to 0} (2x + h + 3)\$\$ 이 됩니다.',
              '마지막으로 \$h\$를 \$0\$으로 보내는 극한을 취하면, \$h\$가 포함된 항은 \$0\$으로 사라지게 되어 최종적으로 \$\$f\'(x) = 2x + 3\$\$ 이라는 결과를 얻습니다. 이처럼 도함수의 정의를 이용하면 어떤 다항함수라도 그 변화율을 나타내는 식을 정확하게 찾아낼 수 있습니다.',
            ],
          ),
        ],
      ),
    ],
  ),
  '축': BookData(
    id: 'concept_축',
    title: '축',
    subtitle: '공통수학1 > 이차함수 > 이차함수의그래프 > 축',
    category: 'common',
    tags: ['공통수학1', '이차함수', '이차함수의그래프', '축'],
    chapters: [
      BookChapter(
        title: '축',
        intro: ['공통수학1 > 이차함수 > 이차함수의그래프 > 축 개념 학습'],
        sections: [
          BookSection(
            title: '축',
            paragraphs: [
              '이차함수 \$y = ax^2 + bx + c\$ (\$a \\neq 0\$)의 그래프는 포물선이라고 부르는 대칭적인 곡선 모양을 가집니다. 이때 포물선이 좌우로 대칭을 이루게 하는 기준이 되는 직선을 \'축\'이라고 합니다. 축은 포물선의 꼭짓점을 지나며, 그래프 위의 모든 점은 이 축을 중심으로 서로 대응되는 위치에 존재합니다. 따라서 축의 방정식을 알면 이차함수의 그래프가 어느 위치를 중심으로 대칭인지 명확하게 파악할 수 있습니다.',
              '이차함수의 식을 완전제곱식 꼴인 \$y = a(x - p)^2 + q\$로 변형하면, 꼭짓점의 좌표는 \$(p, q)\$가 됩니다. 이때 포물선은 직선 \$x = p\$를 기준으로 좌우가 완벽하게 대칭이 됩니다. 따라서 이차함수의 축의 방정식은 \$\$x = p\$\$가 됩니다. 만약 일반형 \$y = ax^2 + bx + c\$가 주어졌다면, 이를 완전제곱식으로 변형하는 과정을 통해 \$\$x = -\\frac{b}{2a}\$\$라는 축의 방정식을 유도할 수 있습니다.',
              '축의 성질은 이차함수의 최댓값과 최솟값을 구할 때 매우 중요합니다. 축을 기준으로 \$x\$의 값이 커질 때와 작아질 때 함수의 증가와 감소 상태가 바뀌기 때문입니다. 또한, 축은 그래프의 모양을 결정하는 \$a\$의 값과 함께 이차함수의 성질을 이해하는 가장 핵심적인 요소입니다. 축의 방정식을 구하는 것은 그래프를 그리기 위한 첫걸음이자, 문제 해결의 실마리를 찾는 과정입니다.',
              '예제: 이차함수 \$y = 2x^2 - 8x + 5\$의 축의 방정식을 구해보세요. 먼저 식을 완전제곱식 꼴로 변형해야 합니다. \$x^2\$항과 \$x\$항을 \$2\$로 묶으면 \$y = 2(x^2 - 4x) + 5\$가 됩니다. 괄호 안을 완전제곱식으로 만들기 위해 \$x\$ 계수의 절반의 제곱인 \$(-2)^2 = 4\$를 더하고 뺍니다. 즉, \$y = 2(x^2 - 4x + 4 - 4) + 5\$가 됩니다.',
              '이제 식을 정리하면 \$y = 2(x - 2)^2 - 8 + 5\$가 되어 최종적으로 \$y = 2(x - 2)^2 - 3\$이라는 식을 얻을 수 있습니다. 이 식에서 꼭짓점의 \$x\$좌표가 \$2\$임을 알 수 있으므로, 구하는 축의 방정식은 \$\$x = 2\$\$입니다. 공식 \$x = -\\frac{b}{2a}\$를 이용하면 \$x = -\\frac{-8}{2 \\times 2} = \\frac{8}{4} = 2\$가 되어 동일한 결과를 빠르게 확인할 수 있습니다.',
            ],
          ),
        ],
      ),
    ],
  ),
