        title: '합집합',
        intro: ['공통수학2 > 집합 > 집합의연산 > 합집합 개념 학습'],
        sections: [
          BookSection(
            title: '합집합',
            paragraphs: [
              '두 집합 \$A\$와 \$B\$가 있을 때, 집합 \$A\$에 속하거나 집합 \$B\$에 속하는 모든 원소로 이루어진 집합을 \$A\$와 \$B\$의 \'합집합\'이라고 합니다. 기호로는 \$A \\cup B\$와 같이 나타내며, 이를 조건제시법으로 표현하면 \$\$A \\cup B = \\{x \\mid x \\in A \\text{ 또는 } x \\in B\\}\$\$가 됩니다. 즉, 어느 한쪽이라도 포함되어 있다면 합집합의 구성원이 될 수 있습니다.',
              '합집합의 성질을 살펴보면, 자기 자신과의 합집합은 자기 자신(\$A \\cup A = A\$)이 되며, 공집합과의 합집합 또한 자기 자신(\$A \\cup \\emptyset = A\$)이 됩니다. 또한, 합집합은 순서를 바꾸어도 결과가 같다는 교환법칙(\$A \\cup B = B \\cup A\$)과 세 집합 이상일 때 묶는 순서를 바꾸어도 결과가 같은 결합법칙(\$(A \\cup B) \\cup C = A \\cup (B \\cup C)\$)이 성립합니다. 특히 \$A \\subset B\$이면 \$A \\cup B = B\$가 된다는 점은 문제 풀이에서 매우 자주 활용되는 중요한 성질입니다.',
              '이제 구체적인 예제를 통해 합집합을 구해봅시다. 두 집합 \$A = \\{1, 2, 3\\}\$과 \$B = \\{3, 4, 5\\}\$가 있을 때, 이들의 합집합 \$A \\cup B\$를 구하는 과정은 다음과 같습니다. 먼저 두 집합에 있는 모든 원소를 나열합니다. 이때 중복되는 원소인 \$3\$은 한 번만 씁니다.',
              '단계별 풀이를 적용하면, 우선 \$A\$의 원소인 \$1, 2, 3\$을 적고, \$B\$의 원소 중 \$A\$에 없는 \$4, 5\$를 추가합니다. 따라서 합집합은 \$\$A \\cup B = \\{1, 2, 3, 4, 5\\}\$\$가 됩니다. 이처럼 합집합은 두 집합을 합치되, 공통된 원소는 중복해서 쓰지 않는다는 점을 항상 유의해야 합니다.',
              '마지막으로 조금 더 복잡한 예제를 살펴봅시다. 집합 \$P\$는 \$10\$ 이하의 소수들의 집합이고, 집합 \$Q\$는 \$10\$ 이하의 짝수들의 집합이라고 할 때, \$P \\cup Q\$를 구해봅시다. 먼저 각 집합을 원소나열법으로 나타내면 \$P = \\{2, 3, 5, 7\\}\$, \$Q = \\{2, 4, 6, 8, 10\\}\$입니다.',
              '이제 두 집합의 원소를 모두 모아보면 \$2, 3, 5, 7, 2, 4, 6, 8, 10\$이 됩니다. 여기서 중복되는 원소인 \$2\$를 하나만 남기고 크기순으로 정리하면 최종적인 합집합은 \$\$P \\cup Q = \\{2, 3, 4, 5, 6, 7, 8, 10\\}\$\$이 됩니다. 이와 같이 집합의 연산은 원소를 빠짐없이 나열하고 중복을 제거하는 과정임을 기억하세요.',
            ],
          ),
        ],
      ),
    ],
  ),
  '다항식의곱셈': BookData(
    id: 'concept_다항식의곱셈',
    title: '다항식의곱셈',
    subtitle: '공통수학1 > 다항식 > 다항식의연산 > 다항식의곱셈',
    category: 'common',
    tags: ['공통수학1', '다항식', '다항식의연산', '다항식의곱셈'],
    chapters: [
      BookChapter(
        title: '다항식의곱셈',
        intro: ['공통수학1 > 다항식 > 다항식의연산 > 다항식의곱셈 개념 학습'],
        sections: [
          BookSection(
            title: '다항식의곱셈',
            paragraphs: [
              '다항식의 곱셈은 분배법칙을 이용하여 하나의 다항식의 각 항을 다른 다항식의 모든 항에 각각 곱하여 더하는 연산입니다. 예를 들어, 두 다항식 \$(ax+b)\$와 \$(cx+d)\$를 곱할 때는 분배법칙을 적용하여 \$a(cx+d) + b(cx+d)\$와 같이 전개한 뒤, 동류항끼리 모아서 정리합니다. 이 과정에서 지수법칙인 \$x^m \\times x^n = x^{m+n}\$이 핵심적으로 사용됩니다.',
              '다항식의 곱셈에서 자주 등장하는 형태는 곱셈 공식으로 정리하여 계산의 효율을 높입니다. 가장 대표적인 공식으로 합의 제곱과 차의 제곱, 그리고 합차 공식이 있습니다. 이 공식들은 다음과 같습니다. \$\$(a+b)^2 = a^2 + 2ab + b^2\$\$, \$\$(a-b)^2 = a^2 - 2ab + b^2\$\$, \$\$(a+b)(a-b) = a^2 - b^2\$\$. 이러한 공식들을 숙지하면 복잡한 식을 일일이 전개하지 않고도 빠르게 결과를 얻을 수 있습니다.',
              '또한, 다항식의 곱셈은 실수의 곱셈과 마찬가지로 교환법칙, 결합법칙, 분배법칙이 성립합니다. 즉, 세 다항식 \$A, B, C\$에 대하여 \$A \\times B = B \\times A\$가 성립하며, \$(A \\times B) \\times C = A \\times (B \\times C)\$가 성립합니다. 이러한 성질들은 다항식을 전개하거나 식을 변형할 때 매우 유용하게 활용됩니다.',
              '이제 예제를 통해 직접 계산해 봅시다. 문제: \$(2x + 3)(x - 4)\$를 전개하시오. 먼저 분배법칙을 사용하여 각 항을 곱합니다. \$2x(x) + 2x(-4) + 3(x) + 3(-4)\$와 같이 식을 세울 수 있습니다. 이를 계산하면 \$\$2x^2 - 8x + 3x - 12\$\$가 됩니다.',
              '마지막으로 동류항을 정리하여 최종 결과를 도출합니다. 위 식에서 \$-8x\$와 \$3x\$는 \$x\$에 대한 동류항이므로, 이 둘을 더하면 \$-5x\$가 됩니다. 따라서 최종 결과는 \$\$2x^2 - 5x - 12\$\$입니다. 이처럼 다항식의 곱셈은 분배법칙을 차근차근 적용한 뒤, 마지막에 동류항을 정리하는 습관을 들이는 것이 중요합니다.',
            ],
          ),
        ],
      ),
    ],
  ),
  '위치변화량': BookData(
    id: 'concept_위치변화량',
    title: '위치변화량',
    subtitle: '미적분Ⅰ > 정적분과속도 > 위치변화량',
    category: 'common',
    tags: ['미적분Ⅰ', '정적분과속도', '위치변화량'],
    chapters: [
      BookChapter(
        title: '위치변화량',
        intro: ['미적분Ⅰ > 정적분과속도 > 위치변화량 개념 학습'],
        sections: [
          BookSection(
            title: '위치변화량',
            paragraphs: [
              '수직선 위를 움직이는 점 \$P\$의 시각 \$t\$에서의 속도를 \$v(t)\$라고 할 때, 시각 \$t=a\$에서 \$t=b\$까지 점 \$P\$의 위치변화량은 속도 함수를 해당 구간에서 정적분하여 구할 수 있습니다. 위치변화량은 단순히 처음 위치와 나중 위치의 차이를 의미하며, 이동 거리와는 달리 방향성을 포함합니다. 즉, 속도가 양수이면 양의 방향으로, 음수이면 음의 방향으로 이동한 것을 모두 고려하여 최종적으로 위치가 얼마나 변했는지를 나타내는 값입니다.',
              '시각 \$t=a\$에서의 점 \$P\$의 위치를 \$x(a)\$라고 하고, 시각 \$t=b\$에서의 위치를 \$x(b)\$라고 할 때, 위치변화량은 다음과 같은 공식으로 정의됩니다. \$\$ \\int_{a}^{b} v(t) dt = x(b) - x(a) \$\$ 이 식에서 알 수 있듯이, 위치변화량은 나중 위치에서 처음 위치를 뺀 값과 같습니다. 만약 위치변화량이 양수라면 점 \$P\$는 처음보다 양의 방향으로 이동한 것이고, 음수라면 음의 방향으로 이동한 것이며, 0이라면 처음 위치와 나중 위치가 같음을 의미합니다.',
              '위치변화량의 성질은 정적분의 성질을 그대로 따릅니다. 속도 함수 \$v(t)\$가 연속일 때, 구간 \$[a, b]\$에서의 위치변화량은 속도 그래프와 \$t\$축 사이의 넓이에서 \$t\$축 아래 부분의 넓이를 뺀 값과 같습니다. 이는 물리학적으로 점이 이동한 경로의 총 길이가 아니라, 시작점과 끝점 사이의 변위(displacement)를 계산하는 과정임을 이해하는 것이 중요합니다.',
              '예제: 수직선 위를 움직이는 점 \$P\$의 시각 \$t\$에서의 속도가 \$v(t) = 3t^2 - 4t\$일 때, 시각 \$t=1\$에서 \$t=3\$까지 점 \$P\$의 위치변화량을 구하시오. [풀이] 위치변화량은 속도 함수를 \$t=1\$부터 \$t=3\$까지 정적분하여 구할 수 있습니다. 식을 세우면 다음과 같습니다. \$\$ \\int_{1}^{3} (3t^2 - 4t) dt \$\$',
              '이제 위 정적분을 계산합니다. 먼저 피적분함수의 부정적분을 구하면 \$t^3 - 2t^2\$이 됩니다. 이를 정적분 공식에 대입하여 계산하면 다음과 같습니다. \$\$ \\left[ t^3 - 2t^2 \\right]_{1}^{3} = (3^3 - 2 \\cdot 3^2) - (1^3 - 2 \\cdot 1^2) \$\$ 이를 정리하면 \$\$(27 - 18) - (1 - 2) = 9 - (-1) = 10\$\$ 이 됩니다. 따라서 점 \$P\$의 위치변화량은 \$10\$입니다.',
            ],
          ),
        ],
      ),
    ],
  ),
  '공차': BookData(
    id: 'concept_공차',
    title: '공차',
    subtitle: '대수 > 수열 > 등차수열 > 공차',
    category: 'common',
    tags: ['대수', '수열', '등차수열', '공차'],
    chapters: [
      BookChapter(
        title: '공차',
        intro: ['대수 > 수열 > 등차수열 > 공차 개념 학습'],
        sections: [
          BookSection(
            title: '공차',
            paragraphs: [
              '등차수열이란 첫 번째 항부터 차례대로 일정한 수를 더하여 만들어지는 수열을 말합니다. 이때, 각 항에서 바로 앞의 항을 뺐을 때 항상 일정하게 유지되는 그 \'일정한 수\'를 바로 \'공차(common difference)\'라고 부릅니다. 공차는 보통 알파벳 \$d\$로 나타내며, 수열의 규칙성을 결정짓는 가장 핵심적인 요소입니다. 만약 공차가 양수라면 수열의 값은 점점 커지고, 음수라면 점점 작아지며, 0이라면 모든 항이 같은 상수가 됩니다.',
              '공차 \$d\$를 구하는 방법은 매우 간단합니다. 수열의 제\$n\$항을 \$a_n\$이라고 할 때, 공차는 이웃한 두 항의 차이인 \$\$d = a_{n+1} - a_n\$\$이라는 공식으로 정의됩니다. 이 성질을 이용하면 등차수열의 일반항 \$a_n\$을 첫째항 \$a_1\$과 공차 \$d\$를 사용하여 \$\$a_n = a_1 + (n-1)d\$\$와 같이 나타낼 수 있습니다. 즉, 첫째항에 공차를 \$(n-1)\$번 더하면 \$n\$번째 항에 도달한다는 논리입니다.',
              '예를 들어, 수열 \$3, 7, 11, 15, \\dots\$가 있다고 가정해 봅시다. 이 수열에서 공차 \$d\$를 구하려면 이웃한 두 항을 골라 뒤의 항에서 앞의 항을 빼면 됩니다. 예를 들어 두 번째 항에서 첫 번째 항을 빼면 \$7 - 3 = 4\$가 되고, 세 번째 항에서 두 번째 항을 빼도 \$11 - 7 = 4\$가 됩니다. 따라서 이 수열의 공차는 \$d = 4\$입니다.',
              '이제 이 공차를 활용하여 특정 항을 구하는 문제를 풀어보겠습니다. 첫째항이 \$5\$이고 공차가 \$3\$인 등차수열에서 제10항을 구하는 과정은 다음과 같습니다. 먼저 일반항 공식 \$a_n = a_1 + (n-1)d\$에 주어진 값들을 대입합니다. 여기서 \$a_1 = 5\$, \$d = 3\$, \$n = 10\$이므로, 식은 \$\$a_{10} = 5 + (10-1) \\times 3\$\$이 됩니다.',
              '마지막으로 계산을 수행하면, \$a_{10} = 5 + 9 \\times 3\$이 되어 \$a_{10} = 5 + 27 = 32\$라는 결과를 얻을 수 있습니다. 이처럼 공차의 개념을 정확히 이해하고 일반항 공식에 적용하면, 수열의 어떤 항이라도 쉽게 찾아낼 수 있습니다. 공차는 등차수열의 변화율을 나타내는 지표이므로, 항상 이웃한 항들의 차이가 일정하게 유지되는지 확인하는 습관을 들이는 것이 중요합니다.',
            ],
          ),
        ],
      ),
    ],
  ),
  '역행렬의정의': BookData(
