    category: 'common',
    tags: ['공통수학1', '행렬', '역행렬', '역행렬의정의'],
    chapters: [
      BookChapter(
        title: '역행렬의정의',
        intro: ['공통수학1 > 행렬 > 역행렬 > 역행렬의정의 개념 학습'],
        sections: [
          BookSection(
            title: '역행렬의정의',
            paragraphs: [
              '행렬에서 \'역행렬\'이란, 마치 숫자의 곱셈에서 어떤 수에 곱하여 1이 되게 하는 \'역수\'와 같은 역할을 하는 행렬을 말합니다. 정사각행렬 \$A\$에 대하여 \$AX = XA = I\$를 만족하는 행렬 \$X\$가 존재할 때, 이 행렬 \$X\$를 \$A\$의 역행렬이라 하며 기호로 \$A^{-1}\$와 같이 나타냅니다. 여기서 \$I\$는 단위행렬을 의미합니다.',
              '역행렬이 존재하기 위해서는 행렬 \$A\$가 반드시 정사각행렬이어야 하며, 특히 \$2 \\times 2\$ 행렬 \$A = \\begin{pmatrix} a & b \\\\ c & d \\end{pmatrix}\$의 경우, 행렬식(determinant)이라 불리는 값인 \$ad - bc\$가 \$0\$이 아니어야 합니다. 이때 역행렬을 구하는 공식은 다음과 같습니다. \$\$A^{-1} = \\frac{1}{ad - bc} \\begin{pmatrix} d & -b \\\\ -c & a \\end{pmatrix}\$\$ 만약 \$ad - bc = 0\$이라면, 이 행렬은 역행렬을 갖지 않으며 이를 \'특이행렬\'이라고 부릅니다.',
              '역행렬의 주요 성질로는 \$(A^{-1})^{-1} = A\$가 성립하며, 두 행렬의 곱의 역행렬은 \$(AB)^{-1} = B^{-1}A^{-1}\$와 같이 순서가 바뀐다는 점이 매우 중요합니다. 또한, 단위행렬의 역행렬은 자기 자신인 \$I^{-1} = I\$가 됩니다. 이러한 성질들은 복잡한 행렬 방정식을 풀거나 행렬의 연산을 단순화할 때 핵심적인 도구로 사용됩니다.',
              '예제: 행렬 \$A = \\begin{pmatrix} 3 & 1 \\\\ 5 & 2 \\end{pmatrix}\$의 역행렬을 구하시오. 먼저 행렬식의 값을 계산합니다. \$ad - bc = (3 \\times 2) - (1 \\times 5) = 6 - 5 = 1\$입니다. 행렬식의 값이 \$0\$이 아니므로 역행렬이 존재합니다.',
              '이제 공식에 대입하여 역행렬을 구합니다. 공식 \$A^{-1} = \\frac{1}{ad - bc} \\begin{pmatrix} d & -b \\\\ -c & a \\end{pmatrix}\$에 따라, \$A^{-1} = \\frac{1}{1} \\begin{pmatrix} 2 & -1 \\\\ -5 & 3 \\end{pmatrix}\$이 됩니다. 따라서 구하는 역행렬은 \$A^{-1} = \\begin{pmatrix} 2 & -1 \\\\ -5 & 3 \\end{pmatrix}\$입니다.',
              '검산 단계로 원래 행렬과 구한 역행렬을 곱해봅니다. \$AA^{-1} = \\begin{pmatrix} 3 & 1 \\\\ 5 & 2 \\end{pmatrix} \\begin{pmatrix} 2 & -1 \\\\ -5 & 3 \\end{pmatrix} = \\begin{pmatrix} 6-5 & -3+3 \\\\ 10-10 & -5+6 \\end{pmatrix} = \\begin{pmatrix} 1 & 0 \\\\ 0 & 1 \\end{pmatrix} = I\$가 성립함을 확인할 수 있습니다. 이처럼 역행렬을 곱하여 단위행렬이 나오면 정확하게 계산된 것입니다.',
            ],
          ),
        ],
      ),
    ],
  ),
  '유리함수의평행이동': BookData(
    id: 'concept_유리함수의평행이동',
    title: '유리함수의평행이동',
    subtitle: '공통수학2 > 유리식과유리함수 > 유리함수의그래프 > 유리함수의평행이동',
    category: 'common',
    tags: ['공통수학2', '유리식과유리함수', '유리함수의그래프', '유리함수의평행이동'],
    chapters: [
      BookChapter(
        title: '유리함수의평행이동',
        intro: ['공통수학2 > 유리식과유리함수 > 유리함수의그래프 > 유리함수의평행이동 개념 학습'],
        sections: [
          BookSection(
            title: '유리함수의평행이동',
            paragraphs: [
              '유리함수의 평행이동이란 가장 기본적인 유리함수인 \$y = \\frac{k}{x}\$ (\$k \\neq 0\$)의 그래프를 좌표평면 위에서 가로 방향(x축)으로 \$p\$만큼, 세로 방향(y축)으로 \$q\$만큼 이동시키는 것을 의미합니다. 평행이동의 원리에 따라 \$x\$ 대신 \$x-p\$를, \$y\$ 대신 \$y-q\$를 대입하면, 평행이동된 유리함수의 식은 \$\$y = \\frac{k}{x-p} + q\$\$와 같이 나타낼 수 있습니다.',
              '이 그래프의 가장 큰 특징은 점근선과 대칭성에 있습니다. 원래 \$y = \\frac{k}{x}\$의 점근선은 \$x=0\$과 \$y=0\$이었지만, 평행이동을 거치면 점근선은 각각 \$\$x = p, \\quad y = q\$\$로 변하게 됩니다. 또한, 이 그래프는 두 점근선의 교점인 \$(p, q)\$에 대하여 점대칭이며, 기울기가 \$1\$ 또는 \$-1\$이면서 점 \$(p, q)\$를 지나는 두 직선에 대하여 선대칭인 성질을 그대로 유지합니다.',
              '일반적으로 유리함수가 \$y = \\frac{ax+b}{cx+d}\$ (\$c \\neq 0\$) 꼴로 주어질 때, 분자를 분모로 나누어 정리하면 위와 같은 표준형으로 변형할 수 있습니다. 즉, \$\$y = \\frac{a(x + \\frac{d}{c}) - \\frac{ad}{c} + b}{c(x + \\frac{d}{c})} = \\frac{k}{x-p} + q\$\$의 형태로 바꾸면, 그래프의 모양을 결정하는 \$k\$값과 평행이동된 위치인 점근선 \$p, q\$를 쉽게 파악할 수 있습니다.',
              '예제: 함수 \$y = \\frac{2x+3}{x-1}\$의 그래프를 그리고 점근선의 방정식을 구해보세요. 먼저 분자를 분모의 식으로 나누어 표준형으로 변형합니다. 분자 \$2x+3\$을 \$2(x-1) + 5\$로 고치면, \$\$y = \\frac{2(x-1)+5}{x-1} = \\frac{5}{x-1} + 2\$\$가 됩니다.',
              '이제 이 식을 분석해 봅시다. 위 식은 \$y = \\frac{5}{x}\$의 그래프를 \$x\$축의 방향으로 \$1\$만큼, \$y\$축의 방향으로 \$2\$만큼 평행이동한 것입니다. 따라서 이 유리함수의 점근선은 \$x=1\$과 \$y=2\$가 됩니다. 그래프를 그릴 때는 먼저 두 점근선 \$x=1, y=2\$를 점선으로 그리고, \$k=5 > 0\$이므로 제1사분면과 제3사분면의 위치(점근선 기준)에 매끄러운 곡선을 그리면 완성됩니다.',
            ],
          ),
        ],
      ),
    ],
  ),
  '미분가능': BookData(
    id: 'concept_미분가능',
    title: '미분가능',
    subtitle: '미적분Ⅰ > 도함수 > 미분가능',
    category: 'common',
    tags: ['미적분Ⅰ', '도함수', '미분가능'],
    chapters: [
      BookChapter(
        title: '미분가능',
        intro: ['미적분Ⅰ > 도함수 > 미분가능 개념 학습'],
        sections: [
          BookSection(
            title: '미분가능',
            paragraphs: [
              '함수 \$f(x)\$가 어떤 구간에서 미분가능하다는 것은, 그 구간의 모든 점에서 함수가 \'부드럽게\' 연결되어 있고, 각 점에서의 접선의 기울기를 구할 수 있다는 뜻입니다. 수학적으로는 어떤 점 \$x=a\$에서 미분계수 \$f\'(a)\$가 존재할 때, 함수 \$f(x)\$는 \$x=a\$에서 미분가능하다고 합니다. 미분계수는 평균변화율의 극한값으로 정의되며, 다음과 같은 식을 만족해야 합니다.',
              '미분계수가 존재하기 위해서는 두 가지 조건이 반드시 충족되어야 합니다. 첫째, 함수 \$f(x)\$가 \$x=a\$에서 연속이어야 합니다. 둘째, \$x=a\$에서의 좌미분계수와 우미분계수가 서로 같아야 합니다. 이를 식으로 나타내면 다음과 같습니다. \$\$f\'(a) = \\lim_{h \\to 0^+} \\frac{f(a+h)-f(a)}{h} = \\lim_{h \\to 0^-} \\frac{f(a+h)-f(a)}{h}\$\$ 만약 좌우의 극한값이 다르거나, 함수가 끊어져 있다면 그 점에서는 미분이 불가능합니다.',
              '예를 들어, 함수 \$f(x) = |x|\$를 생각해 봅시다. 이 함수는 \$x=0\$에서 연속이지만, \$x=0\$을 기준으로 왼쪽에서는 기울기가 \$-1\$이고 오른쪽에서는 기울기가 \$1\$입니다. 좌미분계수와 우미분계수가 다르기 때문에 \$x=0\$에서 뾰족한 점(첨점)이 생기며, 따라서 이 함수는 \$x=0\$에서 미분가능하지 않습니다. 즉, 그래프가 꺾이거나 끊어지지 않고 매끄럽게 이어져야 미분가능하다고 이해하면 쉽습니다.',
              '이제 구체적인 예제를 풀어봅시다. 함수 \$f(x) = \\begin{cases} x^2+ax & (x \\ge 1) \\\\ 2x+b & (x < 1) \\end{cases}\$가 모든 실수에서 미분가능할 때, 상수 \$a, b\$의 값을 구하는 문제입니다. 먼저 \$x=1\$에서 연속이어야 하므로, 좌극한과 우극한, 그리고 함숫값이 같아야 합니다. 즉, \$\\lim_{x \\to 1^+} (x^2+ax) = \\lim_{x \\to 1^-} (2x+b)\$가 성립해야 하므로 \$1+a = 2+b\$, 즉 \$a-b=1\$이라는 식을 얻습니다.',
              '다음으로 \$x=1\$에서 미분가능하려면 좌미분계수와 우미분계수가 같아야 합니다. 각 구간을 미분하면 \$f\'(x) = \\begin{cases} 2x+a & (x > 1) \\\\ 2 & (x < 1) \\end{cases}\$가 됩니다. \$x=1\$에서의 우미분계수는 \$2(1)+a = 2+a\$이고, 좌미분계수는 \$2\$입니다. 두 값이 같아야 하므로 \$2+a=2\$에서 \$a=0\$을 얻습니다. 이를 앞서 구한 \$a-b=1\$에 대입하면 \$0-b=1\$이 되어 \$b=-1\$이 됩니다. 따라서 구하는 값은 \$a=0, b=-1\$입니다.',
            ],
          ),
        ],
      ),
    ],
  ),
  '꼭짓점': BookData(
    id: 'concept_꼭짓점',
    title: '꼭짓점',
    subtitle: '공통수학1 > 이차함수 > 이차함수의그래프 > 꼭짓점',
    category: 'common',
    tags: ['공통수학1', '이차함수', '이차함수의그래프', '꼭짓점'],
    chapters: [
      BookChapter(
        title: '꼭짓점',
        intro: ['공통수학1 > 이차함수 > 이차함수의그래프 > 꼭짓점 개념 학습'],
        sections: [
          BookSection(
            title: '꼭짓점',
            paragraphs: [
              '이차함수의 그래프에서 \'꼭짓점\'이란 포물선 모양의 그래프가 꺾이는 단 하나의 점을 의미합니다. 이차함수의 식을 \$y = a(x-p)^2 + q\$ 꼴로 나타냈을 때, 이 그래프의 꼭짓점의 좌표는 \$(p, q)\$가 됩니다. 꼭짓점은 그래프가 아래로 볼록하거나 위로 볼록할 때 그 방향이 바뀌는 기준점이 되며, 그래프의 모양을 결정하는 가장 중요한 요소입니다.',
              '이차함수의 일반형인 \$y = ax^2 + bx + c\$를 꼭짓점을 쉽게 찾을 수 있는 표준형으로 바꾸려면 \'완전제곱식\'을 이용해야 합니다. 식을 변형하면 \$y = a(x + \\frac{b}{2a})^2 - \\frac{b^2-4ac}{4a}\$가 되는데, 여기서 꼭짓점의 좌표는 \$(-\\frac{b}{2a}, -\\frac{D}{4a})\$ (단, \$D=b^2-4ac\$)가 됨을 알 수 있습니다. 이 공식은 이차함수의 대칭축인 \$x = -\\frac{b}{2a}\$를 찾는 데에도 매우 유용하게 사용됩니다.',
              '이제 구체적인 예제를 통해 꼭짓점을 구하는 방법을 알아봅시다. 이차함수 \$y = x^2 - 4x + 5\$의 꼭짓점을 구해 보겠습니다. 먼저 \$x\$가 포함된 항들을 묶어 완전제곱식으로 만들기 위해 \$x^2 - 4x\$를 봅니다. 완전제곱식이 되려면 상수항으로 \$(-4 \\div 2)^2 = 4\$가 필요하므로, 식을 다음과 같이 변형합니다.',
              '식의 변형 과정은 다음과 같습니다. \$y = (x^2 - 4x + 4) - 4 + 5\$입니다. 여기서 \$x^2 - 4x + 4\$는 \$(x-2)^2\$으로 인수분해되므로, 전체 식은 \$y = (x-2)^2 + 1\$이 됩니다. 이 식을 표준형 \$y = a(x-p)^2 + q\$와 비교하면 \$p=2, q=1\$임을 알 수 있습니다.',
              '따라서 주어진 이차함수 \$y = x^2 - 4x + 5\$의 꼭짓점 좌표는 \$(2, 1)\$입니다. 이 점은 그래프의 가장 낮은 지점이 되며, 직선 \$x=2\$를 대칭축으로 하여 좌우가 대칭인 포물선이 그려집니다. 이처럼 완전제곱식을 이용하면 어떤 이차함수라도 꼭짓점을 정확하게 찾아낼 수 있습니다.',
            ],
          ),
        ],
      ),
    ],
  ),
