            paragraphs: [
              '집합에서 \'교집합\'이란 두 집합 A와 B에 공통으로 속하는 모든 원소로 이루어진 집합을 말합니다. 쉽게 말해, 두 집합이 겹쳐지는 부분만을 모아놓은 것이라고 생각하면 됩니다. 기호로는 ∩를 사용하여 나타내며, 집합 A와 집합 B의 교집합은 A ∩ B라고 씁니다.',
              '교집합을 조건제시법으로 나타내면 다음과 같습니다. 즉, 원소 x가 집합 A의 원소이면서 동시에 집합 B의 원소인 경우를 의미합니다. 이를 수학적 기호로 표현하면 다음과 같습니다. \$\$A \\cap B = \\{x \\mid x \\in A \\text{ 이고 } x \\in B\\}\$\$ 만약 두 집합 A와 B에 공통인 원소가 하나도 없다면, 두 집합의 교집합은 공집합이 되며 이를 \$\$A \\cap B = \\emptyset\$\$이라고 표현합니다.',
              '교집합은 몇 가지 중요한 성질을 가집니다. 첫째, 교환법칙이 성립하여 \$\$A \\cap B = B \\cap A\$\$가 됩니다. 둘째, 결합법칙이 성립하여 세 집합 A, B, C에 대해 \$\$(A \\cap B) \\cap C = A \\cap (B \\cap C)\$\$가 성립합니다. 또한, 어떤 집합 A와 전체집합 U의 교집합은 항상 A가 되며(\$\$A \\cap U = A\$\$), 자기 자신과의 교집합은 자기 자신이 됩니다(\$\$A \\cap A = A\$\$).',
              '이제 예제를 통해 교집합을 구하는 방법을 알아봅시다. 두 집합 \$\$A = \\{1, 2, 3, 4\\}\$\$와 \$\$B = \\{3, 4, 5, 6\\}\$\$이 있을 때, 두 집합의 교집합 \$\$A \\cap B\$\$를 구해봅시다. 먼저 집합 A의 원소 중 집합 B에도 포함되어 있는 원소를 찾아봅니다. 1과 2는 B에 없고, 3과 4는 B에도 포함되어 있습니다.',
              '따라서 공통된 원소는 3과 4입니다. 이를 집합의 형태로 나타내면 \$\$A \\cap B = \\{3, 4\\}\$\$가 됩니다. 이처럼 두 집합을 비교하여 양쪽 모두에 들어있는 원소만을 골라내는 과정이 교집합을 구하는 핵심입니다.',
              '마지막으로 조금 더 복잡한 경우를 살펴봅시다. 집합 \$\$P = \\{x \\mid x\\text{는 } 10 \\text{ 이하의 소수}\\}\$\$이고, 집합 \$\$Q = \\{x \\mid x\\text{는 } 5 \\text{ 의 배수}\\}\$\$일 때 \$\$P \\cap Q\$\$를 구해보겠습니다. 먼저 각 집합을 원소나열법으로 나타내면 \$\$P = \\{2, 3, 5, 7\\}\$\$이고 \$\$Q = \\{5, 10, 15, \\dots\\}\$\$입니다. 두 집합을 비교하면 공통으로 들어있는 원소는 5뿐이므로, 최종 결과는 \$\$P \\cap Q = \\{5\\}\$\$가 됩니다.',
            ],
          ),
        ],
      ),
    ],
  ),
