        title: '등차수열의일반항',
        intro: ['대수 > 수열 > 등차수열 > 등차수열의일반항 개념 학습'],
        sections: [
          BookSection(
            title: '등차수열의일반항',
            paragraphs: [
              '등차수열이란 첫째항부터 차례대로 일정한 수를 더하여 만들어지는 수열을 말합니다. 이때 더해지는 일정한 수를 \'공차\'라고 부르며, 첫째항을 \$a\$, 공차를 \$d\$라고 할 때 수열은 \$a, a+d, a+2d, a+3d, \\dots\$와 같은 형태를 띱니다. 즉, 등차수열은 앞의 항에 공차를 더하면 바로 다음 항이 되는 규칙을 가지고 있습니다.',
              '등차수열의 일반항 \$a_n\$은 첫째항 \$a\$에 \$(n-1)\$번만큼 공차 \$d\$를 더한 값으로 정의됩니다. 이를 공식으로 나타내면 다음과 같습니다. \$\$a_n = a + (n-1)d\$\$ 이 공식에서 \$n\$은 항의 순서를 나타내는 자연수이며, 일반항을 알면 수열의 어떤 번째 항이라도 바로 구할 수 있다는 매우 중요한 성질을 가집니다.',
              '등차수열의 일반항은 \$n\$에 대한 일차식의 형태를 띱니다. 식을 정리하면 \$a_n = dn + (a-d)\$가 되는데, 여기서 \$n\$의 계수인 \$d\$는 항상 공차와 일치한다는 점을 기억하면 문제를 훨씬 빠르게 해결할 수 있습니다. 또한, 공차가 양수이면 수열은 점점 커지고, 공차가 음수이면 점점 작아지며, 공차가 0이면 모든 항이 같은 상수수열이 됩니다.',
              '예제 문제: 첫째항이 3이고 공차가 5인 등차수열에서 제10항을 구하시오. 풀이 단계는 다음과 같습니다. 먼저 일반항 공식 \$a_n = a + (n-1)d\$에 주어진 값 \$a=3, d=5\$를 대입합니다. 그러면 일반항은 \$\$a_n = 3 + (n-1) \\times 5 = 5n - 2\$\$가 됩니다.',
              '이제 제10항을 구하기 위해 \$n=10\$을 위에서 구한 일반항 식에 대입합니다. \$\$a_{10} = 5 \\times 10 - 2 = 50 - 2 = 48\$\$ 따라서 이 등차수열의 제10항은 48임을 알 수 있습니다. 이처럼 일반항을 먼저 구해두면 수열의 규칙을 명확히 파악하고 원하는 항의 값을 쉽게 계산할 수 있습니다.',
