  '완전제곱식': BookData(
    id: 'concept_완전제곱식',
    title: '완전제곱식',
    subtitle: '공통수학1 > 다항식 > 곱셈공식 > 완전제곱식',
    category: 'common',
    tags: ['공통수학1', '다항식', '곱셈공식', '완전제곱식'],
    chapters: [
      BookChapter(
        title: '완전제곱식',
        intro: ['공통수학1 > 다항식 > 곱셈공식 > 완전제곱식 개념 학습'],
        sections: [
          BookSection(
            title: '완전제곱식',
            paragraphs: [
              '완전제곱식이란 다항식의 제곱으로 이루어진 식을 의미합니다. 즉, 어떤 다항식을 두 번 곱한 형태인 \$(a+b)^2\$이나 \$(a-b)^2\$과 같이 나타낼 수 있는 식을 말합니다. 이는 다항식의 곱셈에서 가장 기본이 되는 공식으로, 복잡한 식을 간단하게 전개하거나 반대로 식을 인수분해할 때 매우 자주 사용되는 핵심 개념입니다.',
              '완전제곱식의 전개 공식은 다음과 같습니다. 합의 제곱은 \$\$ (a+b)^2 = a^2 + 2ab + b^2 \$\$ 이며, 차의 제곱은 \$\$ (a-b)^2 = a^2 - 2ab + b^2 \$\$ 입니다. 여기서 중요한 성질은 결과식의 첫 번째 항은 앞의 항의 제곱, 마지막 항은 뒤의 항의 제곱이 되며, 가운데 항은 두 항의 곱의 2배가 된다는 점입니다.',
              '예를 들어, \$(x+3)^2\$을 전개해 봅시다. 공식에 따라 앞의 항 \$x\$를 제곱하면 \$x^2\$, 두 항의 곱 \$3x\$의 2배를 하면 \$6x\$, 뒤의 항 \$3\$을 제곱하면 \$9\$가 됩니다. 따라서 \$\$ (x+3)^2 = x^2 + 6x + 9 \$\$ 가 됩니다. 이처럼 공식의 구조를 이해하면 복잡한 곱셈을 일일이 분배법칙으로 계산하지 않아도 빠르게 결과를 얻을 수 있습니다.',
              '다음으로, 이차식 \$x^2 - 8x + 16\$이 완전제곱식이 되는지 확인하고 인수분해하는 과정을 살펴봅시다. 먼저 첫 번째 항 \$x^2\$은 \$x\$의 제곱이고, 마지막 항 \$16\$은 \$4^2\$ 또는 \$(-4)^2\$입니다. 이때 가운데 항인 \$-8x\$가 두 항의 곱 \$x\$와 \$-4\$를 곱한 것의 2배인 \$2 	imes (x) 	imes (-4) = -8x\$와 일치하는지 확인합니다.',
              '가운데 항이 일치하므로 이 식은 완전제곱식의 형태를 갖추고 있습니다. 따라서 다음과 같이 인수분해할 수 있습니다. \$\$ x^2 - 8x + 16 = (x-4)^2 \$\$ 이처럼 주어진 이차식이 완전제곱식인지 판단할 때는 \'마지막 항이 어떤 수의 제곱인가\'와 \'가운데 항이 그 수와 \$x\$를 곱한 것의 2배인가\'를 확인하는 것이 핵심입니다.',
            ],
          ),
        ],
      ),
    ],
  ),
  '무리식의계산': BookData(
    id: 'concept_무리식의계산',
    title: '무리식의계산',
    subtitle: '공통수학2 > 무리식과무리함수 > 무리식 > 무리식의계산',
    category: 'common',
    tags: ['공통수학2', '무리식과무리함수', '무리식', '무리식의계산'],
    chapters: [
      BookChapter(
        title: '무리식의계산',
        intro: ['공통수학2 > 무리식과무리함수 > 무리식 > 무리식의계산 개념 학습'],
        sections: [
          BookSection(
            title: '무리식의계산',
            paragraphs: [
              '무리식이란 근호(루트, \$\\sqrt{}\$) 안에 변수 \$x\$가 포함되어 있는 식을 말합니다. 예를 들어 \$\\sqrt{x+1}\$이나 \$\\sqrt{x^2-3}\$과 같은 식들이 이에 해당합니다. 무리식의 값이 실수가 되기 위해서는 근호 안의 식의 값이 항상 \$0\$보다 크거나 같아야 한다는 조건이 매우 중요합니다. 즉, \$\\sqrt{A}\$가 정의되기 위해서는 \$A \\ge 0\$이어야 합니다.',
              '무리식을 계산할 때 가장 기본이 되는 성질은 근호의 성질을 이용하는 것입니다. \$A \\ge 0, B > 0\$일 때, 다음의 공식들이 성립합니다. 특히 분모에 무리식이 있을 때는 분모를 유리화하여 계산을 간편하게 만듭니다. 유리화는 분모와 분자에 적절한 식을 곱하여 근호를 없애는 과정으로, 합차 공식 \$(a+b)(a-b) = a^2-b^2\$을 주로 활용합니다.',
              '주요 공식은 다음과 같습니다. 첫째, 근호의 곱셈과 나눗셈은 \$\$\\sqrt{A} \\cdot \\sqrt{B} = \\sqrt{AB} \\quad (A \\ge 0, B \\ge 0)\$\$, \$\$\\frac{\\sqrt{A}}{\\sqrt{B}} = \\sqrt{\\frac{A}{B}} \\quad (A \\ge 0, B > 0)\$\$ 입니다. 둘째, 분모의 유리화는 \$\$\\frac{1}{\\sqrt{A} + \\sqrt{B}} = \\frac{\\sqrt{A} - \\sqrt{B}}{A - B}\$\$ 와 같이 분모와 분자에 \$\\sqrt{A} - \\sqrt{B}\$를 곱하여 계산합니다.',
              '예제: 다음 식을 간단히 하시오. \$\$\\frac{1}{\\sqrt{x+1} + \\sqrt{x}} + \\frac{1}{\\sqrt{x} + \\sqrt{x-1}}\$\$. 이 문제를 풀기 위해서는 각 항의 분모를 유리화해야 합니다. 첫 번째 항의 분모와 분자에 \$\\sqrt{x+1} - \\sqrt{x}\$를 곱하고, 두 번째 항의 분모와 분자에 \$\\sqrt{x} - \\sqrt{x-1}\$을 곱합니다.',
              '단계별 풀이: 첫 번째 항은 \$\$\\frac{(\\sqrt{x+1} - \\sqrt{x})}{(\\sqrt{x+1} + \\sqrt{x})(\\sqrt{x+1} - \\sqrt{x})} = \\frac{\\sqrt{x+1} - \\sqrt{x}}{(x+1) - x} = \\sqrt{x+1} - \\sqrt{x}\$\$ 가 됩니다. 같은 방식으로 두 번째 항은 \$\$\\frac{(\\sqrt{x} - \\sqrt{x-1})}{(\\sqrt{x} + \\sqrt{x-1})(\\sqrt{x} - \\sqrt{x-1})} = \\frac{\\sqrt{x} - \\sqrt{x-1}}{x - (x-1)} = \\sqrt{x} - \\sqrt{x-1}\$\$ 이 됩니다.',
              '최종 계산: 위에서 구한 두 식을 더하면 \$\$\\sqrt{x+1} - \\sqrt{x} + \\sqrt{x} - \\sqrt{x-1}\$\$ 이 됩니다. 여기서 \$-\\sqrt{x}\$와 \$+\\sqrt{x}\$가 서로 소거되므로, 최종 결과는 \$\$\\sqrt{x+1} - \\sqrt{x-1}\$\$ 입니다. 이처럼 유리화 과정을 거치면 복잡한 무리식의 덧셈도 간단하게 해결할 수 있습니다.',
            ],
          ),
        ],
      ),
    ],
  ),
  '역행렬의성질': BookData(
    id: 'concept_역행렬의성질',
    title: '역행렬의성질',
    subtitle: '공통수학1 > 행렬 > 역행렬 > 역행렬의성질',
    category: 'common',
    tags: ['공통수학1', '행렬', '역행렬', '역행렬의성질'],
    chapters: [
      BookChapter(
        title: '역행렬의성질',
        intro: ['공통수학1 > 행렬 > 역행렬 > 역행렬의성질 개념 학습'],
        sections: [
          BookSection(
            title: '역행렬의성질',
            paragraphs: [
              '행렬 \$A\$에 대하여 \$AX = XA = I\$를 만족하는 행렬 \$X\$를 \$A\$의 역행렬이라 하며, 이를 \$A^{-1}\$로 나타냅니다. 이때 \$I\$는 단위행렬입니다. 역행렬이 존재하기 위해서는 행렬 \$A\$가 정사각행렬이어야 하며, 행렬식(determinant)이 0이 아니어야 합니다. 역행렬의 가장 기본적인 성질은 \$(A^{-1})^{-1} = A\$이며, 이는 역행렬의 역행렬은 원래의 행렬 자신임을 의미합니다.',
              '역행렬의 곱셈과 관련된 중요한 성질로는 \$(AB)^{-1} = B^{-1}A^{-1}\$이 있습니다. 이는 두 행렬의 곱의 역행렬을 구할 때, 순서가 뒤바뀌어 각 행렬의 역행렬을 곱해야 한다는 점이 핵심입니다. 또한, 실수배에 대한 성질로 \$(kA)^{-1} = rac{1}{k}A^{-1}\$ (\$k  eq 0\$)이 성립하며, 거듭제곱에 대해서는 \$(A^n)^{-1} = (A^{-1})^n\$이라는 성질이 성립합니다. 이러한 성질들은 복잡한 행렬 방정식을 간단히 정리하는 데 매우 유용하게 사용됩니다.',
              '전치행렬과 역행렬의 관계도 중요합니다. 행렬 \$A\$의 전치행렬을 \$A^T\$라고 할 때, \$(A^T)^{-1} = (A^{-1})^T\$가 성립합니다. 즉, 행렬을 먼저 뒤집고 역행렬을 구하는 것과, 역행렬을 구한 뒤 뒤집는 결과가 서로 같다는 뜻입니다. 이러한 성질들은 행렬의 연산을 효율적으로 수행하고, 행렬의 구조를 파악하는 데 필수적인 도구가 됩니다.',
              '예제: 두 행렬 \$A = \\begin{pmatrix} 1 & 2 \\\\ 1 & 1 \\end{pmatrix}\$, \$B = \\begin{pmatrix} 2 & 1 \\\\ 1 & 1 \\end{pmatrix}\$에 대하여 \$(AB)^{-1}\$을 구하시오. 먼저 성질 \$(AB)^{-1} = B^{-1}A^{-1}\$을 이용하기 위해 각각의 역행렬을 구합니다. \$2 \\times 2\$ 행렬 \$\\begin{pmatrix} a & b \\\\ c & d \\end{pmatrix}\$의 역행렬은 \$\\frac{1}{ad-bc} \\begin{pmatrix} d & -b \\\\ -c & a \\end{pmatrix}\$임을 이용합니다.',
              '단계별 풀이: 먼저 \$A^{-1} = \\frac{1}{1-2} \\begin{pmatrix} 1 & -2 \\\\ -1 & 1 \\end{pmatrix} = \\begin{pmatrix} -1 & 2 \\\\ 1 & -1 \\end{pmatrix}\$입니다. 다음으로 \$B^{-1} = \\frac{1}{2-1} \\begin{pmatrix} 1 & -1 \\\\ -1 & 2 \\end{pmatrix} = \\begin{pmatrix} 1 & -1 \\\\ -1 & 2 \\end{pmatrix}\$입니다. 이제 성질에 따라 \$B^{-1}A^{-1}\$을 계산합니다.',
              '최종 계산: \$(AB)^{-1} = B^{-1}A^{-1} = \\begin{pmatrix} 1 & -1 \\\\ -1 & 2 \\end{pmatrix} \\begin{pmatrix} -1 & 2 \\\\ 1 & -1 \\end{pmatrix} = \\begin{pmatrix} 1(-1)+(-1)(1) & 1(2)+(-1)(-1) \\\\ (-1)(-1)+2(1) & (-1)(2)+2(-1) \\end{pmatrix} = \\begin{pmatrix} -2 & 3 \\\\ 3 & -4 \\end{pmatrix}\$입니다. 이처럼 역행렬의 성질을 이용하면 직접 곱한 후 역행렬을 구하는 것보다 계산 과정을 훨씬 간결하게 만들 수 있습니다.',
            ],
          ),
