  '거듭제곱의미분': BookData(
    id: 'concept_거듭제곱의미분',
    title: '거듭제곱의미분',
    subtitle: '미적분Ⅰ > 도함수 > 도함수공식 > 거듭제곱의미분',
    category: 'common',
    tags: ['미적분Ⅰ', '도함수', '도함수공식', '거듭제곱의미분'],
    chapters: [
      BookChapter(
        title: '거듭제곱의미분',
        intro: ['미적분Ⅰ > 도함수 > 도함수공식 > 거듭제곱의미분 개념 학습'],
        sections: [
          BookSection(
            title: '거듭제곱의미분',
            paragraphs: [
              '[   "거듭제곱의 미분법은 미분 단원에서 가장 기본이 되면서도 매우 강력한 도구입니다. 함수 \$f(x) = x^n\$ (단, \$n\$은 양의 정수)을 미분하면 지수 \$n\$이 앞으로 내려와 계수가 되고, 원래의 지수에서 1을 뺀 값이 새로운 지수가 됩니다. 이를 공식으로 나타내면 다음과 같습니다. \$\$ \\\\frac{d}{dx}(x^n) = nx^{n-1} \$\$ 이 공식은 다항함수를 미분할 때 핵심적인 역할을 하며, 복잡한 함수를 간단하게 계산할 수 있게 해줍니다.",   "이 공식이 성립하는 원리는 도함수의 정의인 \$\$ f\'(x) = \\\\lim_{h \\\\to 0} \\\\frac{f(x+h) - f(x)}{h} \$\$ 를 이용합니다. \$f(x) = x^n\$을 대입하여 전개하면 \$(x+h)^n\$ 항에서 이항정리를 통해 \$x^n + nx^{n-1}h + \\\\dots + h^n\$으로 풀리게 됩니다. 여기서 \$x^n\$을 빼고 \$h\$로 나눈 뒤 \$h\$를 0으로 보내면, \$h\$가 포함된 모든 항은 0이 되고 오직 \$nx^{n-1}\$만 남게 됩니다. 이 성질은 \$n\$이 자연수일 때뿐만 아니라, 실수 범위까지 확장하여 적용할 수 있습니다.",   "이제 구체적인 예제를 통해 거듭제곱의 미분법을 적용해 봅시다. 함수 \$f(x) = x^5\$를 미분하는 과정을 단계별로 살펴보겠습니다. 먼저, 미분 공식 \$\\\\frac{d}{dx}(x^n) = nx^{n-1}\$에서 \$n=5\$를 대입합니다. 그러면 지수인 5가 앞으로 내려오고, 새로운 지수는 \$5-1=4\$가 됩니다. 따라서 결과는 다음과 같습니다. \$\$ f\'(x) = 5x^{5-1} = 5x^4 \$\$ 이처럼 공식에 대입하기만 하면 복잡한 극한 계산 없이도 도함수를 즉시 구할 수 있습니다.",   "조금 더 응용된 예제로, 계수가 포함된 다항식 \$g(x) = 3x^4\$를 미분해 보겠습니다. 미분의 선형성 성질에 의해 상수는 미분 기호 밖으로 나올 수 있습니다. 즉, \$\\\\frac{d}{dx}\\{cf(x)\\} = c \\\\cdot f\'(x)\$가 성립합니다. 이를 적용하면 다음과 같이 계산할 수 있습니다. \$\$ g\'(x) = 3 \\\\cdot \\\\frac{d}{dx}(x^4) = 3 \\\\cdot (4x^{4-1}) = 3 \\\\cdot 4x^3 = 12x^3 \$\$ 이와 같이 상수와 거듭제곱이 곱해진 형태도 공식을 활용하여 단계적으로 해결할 수 있습니다.",   "마지막으로 여러 항이 더해진 다항함수 \$h(x) = x^3 + 2x^2 + 5\$를 미분해 봅시다. 다항함수의 미분은 각 항을 따로 미분하여 더하면 됩니다. 이때 상수항 5는 \$5x^0\$으로 볼 수 있으며, 미분하면 0이 됩니다. 계산 과정은 다음과 같습니다. \$\$ h\'(x) = \\\\frac{d}{dx}(x^3) + \\\\frac{d}{dx}(2x^2) + \\\\frac{d}{dx}(5) = 3x^2 + 4x + 0 = 3x^2 + 4x \$\$ 이처럼 거듭제곱의 미분법은 모든 다항함수를 미분하는 가장 기초적이고 필수적인 방법입니다." ]',
            ],
          ),
        ],
      ),
    ],
  ),
  'y절편': BookData(
    id: 'concept_y절편',
    title: 'y절편',
    subtitle: '공통수학1 > 이차함수 > 이차함수의그래프 > y절편',
    category: 'common',
    tags: ['공통수학1', '이차함수', '이차함수의그래프', 'y절편'],
    chapters: [
      BookChapter(
        title: 'y절편',
        intro: ['공통수학1 > 이차함수 > 이차함수의그래프 > y절편 개념 학습'],
        sections: [
          BookSection(
            title: 'y절편',
            paragraphs: [
              '좌표평면에서 함수 \$y=f(x)\$의 그래프가 \$y\$축과 만나는 점의 좌표를 \$(0, b)\$라고 할 때, 이때의 \$y\$값인 \$b\$를 그 함수의 \'\$y\$절편\'이라고 합니다. 쉽게 말해, 그래프가 세로축인 \$y\$축을 통과하는 지점의 높이를 의미합니다. 이차함수의 일반형인 \$y=ax^2+bx+c\$에서 \$x=0\$을 대입하면 \$y=c\$가 되므로, 이차함수의 \$y\$절편은 항상 상수항인 \$c\$와 같습니다.',
              '이차함수 \$y=ax^2+bx+c\$의 그래프에서 \$y\$절편 \$c\$는 그래프가 \$y\$축의 어느 위치를 지나는지를 결정하는 중요한 요소입니다. \$c > 0\$이면 \$y\$축의 양의 부분에서 만나고, \$c < 0\$이면 \$y\$축의 음의 부분에서 만나며, \$c = 0\$이면 원점을 지납니다. 이처럼 \$y\$절편은 그래프의 위치를 파악하는 가장 빠르고 기초적인 기준이 됩니다.',
              '예를 들어, 이차함수 \$y=2x^2-4x+3\$의 \$y\$절편을 구해봅시다. \$y\$절편을 구하기 위해서는 함수식에 \$x=0\$을 대입하면 됩니다. 식에 \$x=0\$을 넣으면 \$y=2(0)^2-4(0)+3\$이 되어 \$y=3\$이라는 결과를 얻습니다. 따라서 이 함수의 \$y\$절편은 \$3\$이며, 그래프는 \$y\$축 위의 점 \$(0, 3)\$을 지납니다.',
              '조금 더 복잡한 형태인 \$y=-(x-1)^2+5\$의 \$y\$절편을 구하는 과정을 살펴봅시다. 이 식은 꼭짓점 형태이지만, \$y\$절편을 구하는 원리는 동일하게 \$x=0\$을 대입하는 것입니다. 먼저 식에 \$x=0\$을 대입하면 \$y=-(0-1)^2+5\$가 됩니다. 이를 계산하면 \$y=-(-1)^2+5 = -1+5 = 4\$가 나옵니다. 따라서 이 함수의 \$y\$절편은 \$4\$이고, 그래프는 점 \$(0, 4)\$를 통과합니다.',
              '마지막으로 \$y=ax^2+bx+c\$ 꼴이 아닌 경우를 확인해 봅시다. 만약 \$y=3x^2+6x\$라는 이차함수가 있다면, 상수항 \$c\$가 보이지 않으므로 \$c=0\$이라고 생각할 수 있습니다. 실제로 \$x=0\$을 대입하면 \$y=3(0)^2+6(0)=0\$이 되어 \$y\$절편은 \$0\$입니다. 이는 그래프가 원점 \$(0, 0)\$을 지난다는 것을 의미하며, \$y\$절편을 통해 그래프의 시작점이나 위치를 정확히 파악할 수 있습니다.',
            ],
          ),
        ],
      ),
    ],
  ),
  '차집합': BookData(
    id: 'concept_차집합',
    title: '차집합',
    subtitle: '공통수학2 > 집합 > 집합의연산 > 차집합',
    category: 'common',
    tags: ['공통수학2', '집합', '집합의연산', '차집합'],
    chapters: [
      BookChapter(
        title: '차집합',
        intro: ['공통수학2 > 집합 > 집합의연산 > 차집합 개념 학습'],
        sections: [
          BookSection(
            title: '차집합',
            paragraphs: [
              '[   "차집합이란 두 집합 \$A\$와 \$B\$에 대하여, 집합 \$A\$의 원소 중에서 집합 \$B\$의 원소를 제외하고 남은 원소들로만 이루어진 집합을 말합니다. 기호로는 \$A - B\$ 또는 \$A \\\\setminus B\$라고 쓰며, 이를 \'A 차집합 B\'라고 읽습니다. 즉, 차집합은 \'A에는 속하지만 B에는 속하지 않는 원소들의 모임\'이라고 이해하면 쉽습니다.",   "이를 조건제시법으로 나타내면 다음과 같습니다. \$\$A - B = \\\\{x \\\\mid x \\\\in A \\\\text{ 이고 } x \\\\notin B\\\\}\$\$ 또한, 차집합은 교집합과 여집합을 이용하여 표현할 수도 있습니다. 집합 \$A\$에서 \$A\$와 \$B\$의 공통 부분인 교집합 \$A \\\\cap B\$를 덜어내는 것과 같으므로, 다음의 핵심 공식이 성립합니다. \$\$A - B = A \\\\cap B^c\$\$ 이 공식은 집합의 연산 법칙을 증명하거나 복잡한 집합 문제를 해결할 때 매우 유용하게 사용됩니다.",   "차집합의 성질 중 주의할 점은 교환법칙이 성립하지 않는다는 것입니다. 일반적으로 \$A - B\$와 \$B - A\$는 서로 다른 집합입니다. 또한, \$A - B = \\\\emptyset\$이면 \$A \\\\subset B\$가 성립하고, \$A - B = A\$이면 \$A \\\\cap B = \\\\emptyset\$이라는 성질도 함께 기억해 두면 좋습니다. 벤 다이어그램을 그려보면 \$A\$ 영역에서 \$B\$와 겹치는 부분을 지우는 과정이므로 직관적으로 이해하기 훨씬 수월합니다.",   "이제 예제를 통해 차집합을 계산해 봅시다. 두 집합 \$A = \\\\{1, 2, 3, 4, 5\\\\}\$와 \$B = \\\\{3, 4, 6\\\\}\$이 있을 때, \$A - B\$를 구하는 과정은 다음과 같습니다. 먼저 두 집합의 공통된 원소를 찾습니다. \$A\$와 \$B\$에 공통으로 들어있는 원소는 \$3\$과 \$4\$입니다. 따라서 집합 \$A\$의 원소인 \$\\{1, 2, 3, 4, 5\\}\$에서 \$3\$과 \$4\$를 제외하면 남는 원소는 \$1, 2, 5\$가 됩니다. 결과적으로 \$\$A - B = \\\\{1, 2, 5\\\\}\$\$가 됩니다.",   "다음으로 조금 더 응용된 문제를 풀어보겠습니다. 전체집합 \$U = \\\\{1, 2, 3, 4, 5, 6\\\\}\$의 두 부분집합 \$A = \\\\{1, 2, 3\\\\}\$, \$B = \\\\{2, 4, 6\\\\}\$에 대하여 \$(A \\\\cup B) - (A \\\\cap B)\$를 구해보겠습니다. 먼저 합집합 \$A \\\\cup B = \\\\{1, 2, 3, 4, 6\\\\}\$을 구하고, 교집합 \$A \\\\cap B = \\\\{2\\\\}\$를 구합니다. 이제 합집합에서 교집합을 빼면 \$A \\\\cup B\$의 원소 중 \$2\$를 제외한 나머지 원소들만 남게 됩니다. 따라서 최종 결과는 다음과 같습니다. \$\$(A \\\\cup B) - (A \\\\cap B) = \\\\{1, 3, 4, 6\\\\}\$\$ 이처럼 차집합은 집합 간의 관계를 명확히 파악하는 데 매우 중요한 도구입니다." ]',
            ],
          ),
        ],
      ),
    ],
  ),
  '등차수열의합': BookData(
    id: 'concept_등차수열의합',
    title: '등차수열의합',
    subtitle: '대수 > 수열 > 등차수열 > 등차수열의합',
    category: 'common',
    tags: ['대수', '수열', '등차수열', '등차수열의합'],
    chapters: [
      BookChapter(
        title: '등차수열의합',
        intro: ['대수 > 수열 > 등차수열 > 등차수열의합 개념 학습'],
        sections: [
          BookSection(
            title: '등차수열의합',
            paragraphs: [
              '[   "등차수열의 합이란 등차수열의 첫째항부터 제n항까지의 모든 항을 더한 값을 의미합니다. 첫째항을 \$a\$, 공차를 \$d\$라고 할 때, 제n항까지의 합을 \$S_n\$이라 하면 \$S_n = a + (a+d) + (a+2d) + \\\\cdots + \\{a+(n-1)d\\}\$와 같이 나타낼 수 있습니다. 이 합을 구할 때는 수열의 순서를 거꾸로 뒤집어 더하는 방식을 사용하는데, 이렇게 하면 각 항의 합이 모두 일정하다는 성질을 이용해 매우 효율적으로 계산할 수 있습니다.",   "이러한 원리를 바탕으로 유도된 등차수열의 합 공식은 크게 두 가지 형태로 나뉩니다. 첫째항을 \$a\$, 제n항을 \$l\$ (즉, \$l = a_n\$)이라고 할 때, 합 \$S_n\$은 \$\$S_n = \\\\frac{n(a+l)}{2}\$\$입니다. 또한, 제n항 \$l\$ 대신 첫째항 \$a\$와 공차 \$d\$를 사용하여 나타내면 \$\$S_n = \\\\frac{n\\{2a+(n-1)d\\}}{2}\$\$가 됩니다. 이 공식들은 수열의 항의 개수와 첫째항, 그리고 마지막 항이나 공차를 알면 언제든지 합을 구할 수 있게 해줍니다.",   "등차수열의 합에서 중요한 성질 중 하나는 \$S_n\$이 \$n\$에 대한 이차식 형태를 띤다는 점입니다. 특히 상수항이 없는 이차식 \$S_n = An^2 + Bn\$ 꼴로 나타나면, 이 수열은 첫째항부터 등차수열을 이룬다는 것을 알 수 있습니다. 또한, 수열의 합 \$S_n\$과 일반항 \$a_n\$ 사이에는 \$a_1 = S_1\$이고, \$n \\\\ge 2\$일 때 \$a_n = S_n - S_{n-1}\$이라는 관계가 성립합니다. 이는 합을 알면 수열의 각 항을 찾아낼 수 있음을 의미합니다.",   "이제 구체적인 예제를 풀어봅시다. 첫째항이 3이고 공차가 4인 등차수열의 첫째항부터 제10항까지의 합을 구해보겠습니다. 여기서 \$a=3, d=4, n=10\$입니다. 합의 공식을 사용하면 \$\$S_{10} = \\\\frac{10 \\\\{2 \\\\times 3 + (10-1) \\\\times 4\\\\}}{2}\$\$가 됩니다. 이를 단계별로 계산하면, 중괄호 안의 값은 \$6 + 9 \\\\times 4 = 6 + 36 = 42\$가 됩니다. 따라서 \$\$S_{10} = \\\\frac{10 \\\\times 42}{2} = 5 \\\\times 42 = 210\$\$이 되어, 구하는 합은 210입니다.",   "마지막으로, 첫째항이 5이고 제10항이 23인 등차수열의 합을 구해봅시다. 이 경우에는 첫째항 \$a=5\$와 마지막 항 \$l=23\$, 항의 개수 \$n=10\$을 알고 있으므로 첫 번째 공식을 사용하는 것이 편리합니다. 공식에 대입하면 \$\$S_{10} = \\\\frac{10(5+23)}{2}\$\$가 됩니다. 괄호 안의 값을 먼저 더하면 \$5+23=28\$이므로, \$\$S_{10} = \\\\frac{10 \\\\times 28}{2} = 5 \\\\times 28 = 140\$\$이 됩니다. 이처럼 주어진 조건에 따라 적절한 공식을 선택하면 복잡한 계산 없이도 등차수열의 합을 쉽게 구할 수 있습니다." ]',
            ],
          ),
        ],
      ),
    ],
  ),
  '합차공식': BookData(
    id: 'concept_합차공식',
    title: '합차공식',
    subtitle: '공통수학1 > 다항식 > 곱셈공식 > 합차공식',
    category: 'common',
    tags: ['공통수학1', '다항식', '곱셈공식', '합차공식'],
    chapters: [
      BookChapter(
        title: '합차공식',
        intro: ['공통수학1 > 다항식 > 곱셈공식 > 합차공식 개념 학습'],
        sections: [
          BookSection(
            title: '합차공식',
            paragraphs: [
              '합차공식은 두 다항식의 곱을 전개할 때, 두 항의 합과 두 항의 차가 곱해진 형태를 간편하게 계산하는 공식입니다. 어떤 두 수 또는 식 \$a\$와 \$b\$에 대하여, \$(a+b)\$와 \$(a-b)\$를 곱하면 그 결과는 각 항의 제곱의 차가 됩니다. 이 공식은 다항식의 곱셈에서 매우 자주 등장하며, 계산 과정을 획기적으로 줄여주는 핵심적인 도구입니다.',
              '합차공식을 수학적 식으로 나타내면 다음과 같습니다. \$\$ (a+b)(a-b) = a^2 - b^2 \$\$ 이 공식이 성립하는 이유는 분배법칙을 이용해 전개해 보면 알 수 있습니다. \$(a+b)(a-b) = a^2 - ab + ba - b^2\$이 되는데, 여기서 \$-ab\$와 \$+ba\$는 서로 더하면 \$0\$이 되어 사라지기 때문에 최종적으로 \$a^2 - b^2\$만 남게 됩니다. 따라서 합차공식은 \'앞의 것의 제곱에서 뒤의 것의 제곱을 뺀다\'라고 기억하면 편리합니다.',
              '합차공식의 성질은 단순히 다항식의 전개뿐만 아니라, 복잡한 수의 계산이나 인수분해에서도 유용하게 활용됩니다. 예를 들어, \$102 \\times 98\$과 같은 계산을 할 때 이를 \$(100+2)(100-2)\$로 바꾸어 생각하면 \$100^2 - 2^2 = 10000 - 4 = 9996\$과 같이 암산으로도 빠르게 값을 구할 수 있습니다. 이처럼 합차공식은 수의 구조를 파악하여 효율적인 계산을 가능하게 합니다.',
              '예제 문제: 다음 식을 합차공식을 이용하여 전개하시오. \$\$(2x + 3y)(2x - 3y)\$\$ 단계별 풀이: 첫째, 공식 \$(a+b)(a-b) = a^2 - b^2\$에서 \$a\$에 해당하는 항이 \$2x\$이고, \$b\$에 해당하는 항이 \$3y\$임을 확인합니다. 둘째, 공식에 대입하여 각 항을 제곱합니다. 즉, \$(2x)^2 - (3y)^2\$이 됩니다. 셋째, 제곱을 계산하면 \$(2x)^2 = 4x^2\$이고 \$(3y)^2 = 9y^2\$이므로, 최종 결과는 \$4x^2 - 9y^2\$이 됩니다.',
              '예제 문제: 다음 식을 합차공식을 이용하여 전개하시오. \$\$(x^2 + 5)(x^2 - 5)\$\$ 단계별 풀이: 첫째, 이 식은 \$a=x^2\$, \$b=5\$인 합차공식의 형태임을 파악합니다. 둘째, 공식에 따라 앞의 항의 제곱에서 뒤의 항의 제곱을 뺍니다. 즉, \$(x^2)^2 - 5^2\$으로 식을 세웁니다. 셋째, 지수법칙에 의해 \$(x^2)^2 = x^4\$이고 \$5^2 = 25\$이므로, 최종 결과는 \$x^4 - 25\$가 됩니다.',
            ],
          ),
        ],
      ),
    ],
  ),
