    category: 'common',
    tags: ['공통수학1', '행렬', '역행렬', '역행렬구하기'],
    chapters: [
      BookChapter(
        title: '역행렬구하기',
        intro: ['공통수학1 > 행렬 > 역행렬 > 역행렬구하기 개념 학습'],
        sections: [
          BookSection(
            title: '역행렬구하기',
            paragraphs: [
              '행렬의 역행렬이란, 어떤 행렬 \$A\$에 곱했을 때 단위행렬 \$I\$가 되게 하는 행렬을 말합니다. 즉, \$A\$와 \$X\$를 곱해서 \$AX = XA = I\$를 만족하는 행렬 \$X\$를 \$A\$의 역행렬이라 하며, 기호로는 \$A^{-1}\$로 나타냅니다. 다만, 모든 행렬이 역행렬을 가지는 것은 아니며, 행렬식(determinant)의 값이 0이 아닐 때만 역행렬이 존재합니다.',
              '2차 정사각행렬 \$A = \\begin{pmatrix} a & b \\\\ c & d \\end{pmatrix}\$에 대하여, 역행렬이 존재하기 위한 조건은 \$ad - bc \\neq 0\$입니다. 이때 역행렬을 구하는 공식은 다음과 같습니다. \$\$A^{-1} = \\frac{1}{ad-bc} \\begin{pmatrix} d & -b \\\\ -c & a \\end{pmatrix}\$\$ 이 공식에서 \$ad-bc\$는 행렬 \$A\$의 행렬식이라 부르며, 이 값이 0이면 역행렬은 존재하지 않습니다.',
              '역행렬의 성질을 이해하면 계산이 훨씬 수월해집니다. 역행렬의 역행렬은 자기 자신인 \$(A^{-1})^{-1} = A\$가 성립하며, 두 행렬의 곱의 역행렬은 순서가 바뀌어 \$(AB)^{-1} = B^{-1}A^{-1}\$이 됩니다. 또한, 단위행렬의 역행렬은 자기 자신인 \$I^{-1} = I\$라는 점도 기억해 두면 좋습니다.',
              '이제 구체적인 예제를 통해 역행렬을 직접 구해봅시다. 행렬 \$A = \\begin{pmatrix} 3 & 1 \\\\ 5 & 2 \\end{pmatrix}\$의 역행렬을 구하는 과정입니다. 먼저 행렬식의 값을 계산하면 \$ad - bc = (3 \\times 2) - (1 \\times 5) = 6 - 5 = 1\$입니다. 행렬식의 값이 0이 아니므로 역행렬이 존재합니다.',
              '공식에 대입하기 위해 행렬의 성분을 조정합니다. 주대각선 성분인 3과 2는 서로 자리를 바꾸고, 나머지 성분인 1과 5는 부호를 바꾸어 -1과 -5로 만듭니다. 이를 공식에 적용하면 \$\$A^{-1} = \\frac{1}{1} \\begin{pmatrix} 2 & -1 \\\\ -5 & 3 \\end{pmatrix} = \\begin{pmatrix} 2 & -1 \\\\ -5 & 3 \\end{pmatrix}\$\$ 이 됩니다. 실제로 \$A\$와 \$A^{-1}\$를 곱해보면 단위행렬 \$I\$가 나옴을 확인할 수 있습니다.',
            ],
          ),
        ],
      ),
