  '인수정리활용': BookData(
    id: 'concept_인수정리활용',
    title: '인수정리활용',
    subtitle: '공통수학1 > 다항식 > 인수정리 > 인수정리활용',
    category: 'common',
    tags: ['공통수학1', '다항식', '인수정리', '인수정리활용'],
    chapters: [
      BookChapter(
        title: '인수정리활용',
        intro: ['공통수학1 > 다항식 > 인수정리 > 인수정리활용 개념 학습'],
        sections: [
          BookSection(
            title: '인수정리활용',
            paragraphs: [
              '인수정리란 다항식 \$P(x)\$에 대하여 \$P(a)=0\$이면, 다항식 \$P(x)\$는 일차식 \$(x-a)\$를 인수로 갖는다는 정리입니다. 이는 나머지정리의 특수한 경우로, 나머지가 0이 될 때 다항식이 나누어떨어지는 성질을 이용합니다. 인수정리를 활용하면 복잡한 다항식을 인수분해하거나, 다항식의 미정계수를 결정하는 데 매우 유용하게 사용할 수 있습니다.',
              '다항식 \$P(x)\$가 \$(x-a)(x-b)\$로 나누어떨어진다면, 인수정리에 의해 \$P(a)=0\$이고 \$P(b)=0\$이 성립해야 합니다. 만약 다항식 \$P(x)\$가 \$n\$차식이고 \$P(a_1)=P(a_2)=\\dots=P(a_n)=0\$이라면, \$P(x)\$는 최고차항의 계수를 \$k\$라고 할 때 \$\$P(x) = k(x-a_1)(x-a_2)\\dots(x-a_n)\$\$과 같이 인수분해할 수 있습니다. 이처럼 다항식의 함숫값이 0이 되는 지점을 찾아 식을 구성하는 것이 인수정리 활용의 핵심입니다.',
              '예를 들어, 삼차다항식 \$P(x)\$가 \$P(1)=0, P(2)=0, P(3)=0\$을 만족하고 최고차항의 계수가 1이라면, 인수정리에 의해 \$P(x)\$는 \$(x-1), (x-2), (x-3)\$을 각각 인수로 가집니다. 따라서 이 다항식은 \$\$P(x) = (x-1)(x-2)(x-3)\$\$으로 바로 표현할 수 있습니다. 이 성질을 이용하면 미지수가 포함된 다항식에서 특정 값을 대입하여 미지수의 값을 빠르게 구할 수 있습니다.',
              '이제 구체적인 예제를 풀어봅시다. 문제: 삼차다항식 \$P(x)\$가 \$P(1)=0, P(2)=0\$이고 \$P(3)=4\$를 만족할 때, \$P(x)\$를 구하시오. 먼저 \$P(1)=0, P(2)=0\$이므로 인수정리에 의해 \$P(x)\$는 \$(x-1)(x-2)\$를 인수로 가집니다. 따라서 \$P(x)\$를 다음과 같이 설정할 수 있습니다. \$\$P(x) = (x-1)(x-2)(ax+b)\$\$ 또는 최고차항을 \$k\$라 할 때 \$\$P(x) = k(x-1)(x-2)(x-c)\$\$와 같이 놓을 수 있습니다.',
              '위 식에서 \$P(x)\$가 삼차다항식이므로 \$P(x) = (ax+b)(x-1)(x-2)\$로 둡니다. 여기에 \$P(3)=4\$를 대입하면 \$\$P(3) = (3a+b)(3-1)(3-2) = (3a+b) \\times 2 \\times 1 = 4\$\$가 됩니다. 즉, \$3a+b=2\$라는 관계식을 얻습니다. 만약 문제에서 최고차항의 계수가 1이라는 조건이 추가된다면 \$a=1\$이 되어 \$3(1)+b=2\$로부터 \$b=-1\$을 얻게 됩니다. 결과적으로 구하는 다항식은 \$\$P(x) = (x-1)(x-1)(x-2) = (x-1)^2(x-2)\$\$가 됩니다.',
            ],
          ),
        ],
      ),
    ],
  ),
  '유리화': BookData(
    id: 'concept_유리화',
    title: '유리화',
    subtitle: '공통수학2 > 무리식과무리함수 > 무리식 > 유리화',
    category: 'common',
    tags: ['공통수학2', '무리식과무리함수', '무리식', '유리화'],
    chapters: [
      BookChapter(
        title: '유리화',
        intro: ['공통수학2 > 무리식과무리함수 > 무리식 > 유리화 개념 학습'],
        sections: [
          BookSection(
            title: '유리화',
            paragraphs: [
              '유리화란 분모에 무리수가 포함된 식에서 분모와 분자에 적절한 수를 곱하여 분모를 유리수로 만드는 과정을 말합니다. 분모에 루트(\$\\sqrt{}\$)가 포함되어 있으면 식의 값을 계산하거나 대소 관계를 비교하기 어렵기 때문에, 분모를 유리수로 바꾸어 식을 더 간결하게 정리하는 것입니다. 이는 분수의 성질인 \'분모와 분자에 0이 아닌 같은 수를 곱해도 분수의 값은 변하지 않는다\'는 원리를 이용합니다.',
              '분모가 단항식인 경우, 예를 들어 \$\\frac{a}{\\sqrt{b}}\$ 꼴이라면 분모와 분자에 각각 \$\\sqrt{b}\$를 곱하여 분모를 \$b\$로 만듭니다. 즉, \$\$\\frac{a}{\\sqrt{b}} = \\frac{a \\times \\sqrt{b}}{\\sqrt{b} \\times \\sqrt{b}} = \\frac{a\\sqrt{b}}{b}\$\$와 같이 계산합니다. 분모에 근호가 하나만 있을 때는 그 근호 자체를 곱해주면 간단히 유리화가 가능합니다.',
              '분모가 \$\\sqrt{a} + \\sqrt{b}\$ 또는 \$\\sqrt{a} - \\sqrt{b}\$와 같이 두 항으로 이루어진 경우에는 \'합차 공식\'을 활용합니다. \$\$(x+y)(x-y) = x^2 - y^2\$\$이라는 공식을 이용하면 근호를 제곱하여 없앨 수 있습니다. 따라서 분모가 \$\\sqrt{a} + \\sqrt{b}\$라면 분모와 분자에 \$\\sqrt{a} - \\sqrt{b}\$를 곱하고, 분모가 \$\\sqrt{a} - \\sqrt{b}\$라면 \$\\sqrt{a} + \\sqrt{b}\$를 곱하여 분모를 \$a-b\$라는 유리수로 만듭니다.',
              '예제 1: 분모가 단항식인 경우 \$\\frac{6}{\\sqrt{3}}\$을 유리화해 봅시다. 분모인 \$\\sqrt{3}\$을 없애기 위해 분모와 분자에 똑같이 \$\\sqrt{3}\$을 곱합니다. 계산 과정은 다음과 같습니다. \$\$\\frac{6}{\\sqrt{3}} = \\frac{6 \\times \\sqrt{3}}{\\sqrt{3} \\times \\sqrt{3}} = \\frac{6\\sqrt{3}}{3} = 2\\sqrt{3}\$\$ 이처럼 분모를 유리수로 만들면 식의 값을 훨씬 쉽게 파악할 수 있습니다.',
              '예제 2: 분모가 다항식인 경우 \$\\frac{2}{\\sqrt{5} - 1}\$을 유리화해 봅시다. 분모에 \$\\sqrt{5} - 1\$이 있으므로, 합차 공식을 적용하기 위해 분모와 분자에 \$\\sqrt{5} + 1\$을 곱합니다. 단계별 풀이는 다음과 같습니다. \$\$\\frac{2}{\\sqrt{5} - 1} = \\frac{2(\\sqrt{5} + 1)}{(\\sqrt{5} - 1)(\\sqrt{5} + 1)} = \\frac{2(\\sqrt{5} + 1)}{5 - 1} = \\frac{2(\\sqrt{5} + 1)}{4} = \\frac{\\sqrt{5} + 1}{2}\$\$ 이와 같이 유리화를 수행하면 복잡한 분수식을 간단한 형태로 나타낼 수 있습니다.',
            ],
          ),
        ],
      ),
    ],
  ),
  '상수배의미분': BookData(
    id: 'concept_상수배의미분',
    title: '상수배의미분',
    subtitle: '미적분Ⅰ > 도함수 > 도함수공식 > 상수배의미분',
    category: 'common',
    tags: ['미적분Ⅰ', '도함수', '도함수공식', '상수배의미분'],
    chapters: [
      BookChapter(
        title: '상수배의미분',
        intro: ['미적분Ⅰ > 도함수 > 도함수공식 > 상수배의미분 개념 학습'],
        sections: [
          BookSection(
            title: '상수배의미분',
            paragraphs: [
              '미분법에서 \'상수배의 미분\'이란 어떤 함수에 상수 \$c\$가 곱해져 있을 때, 그 전체를 미분하는 방법을 의미합니다. 함수 \$f(x)\$가 미분가능할 때, \$f(x)\$에 상수 \$c\$를 곱한 함수 \$cf(x)\$의 도함수는 원래 함수 \$f(x)\$를 미분한 \$f\'(x)\$에 상수 \$c\$를 그대로 곱한 것과 같습니다. 즉, 상수는 미분 기호 밖으로 자유롭게 꺼낼 수 있다는 성질을 가지고 있습니다.',
              '이를 수학적인 공식으로 나타내면 다음과 같습니다. 함수 \$f(x)\$가 미분가능할 때, 상수 \$c\$에 대하여 다음 식이 성립합니다. \$\$ \\frac{d}{dx} \\{c f(x)\\} = c f\'(x) \$\$ 이 공식은 도함수의 정의인 미분계수의 극한식을 이용하면 쉽게 증명할 수 있습니다. 극한의 성질에 의해 상수 \$c\$는 극한 기호 밖으로 나갈 수 있기 때문에, 결과적으로 미분 결과에도 상수가 그대로 유지되는 것입니다.',
              '이 성질은 다항함수를 미분할 때 매우 유용하게 사용됩니다. 예를 들어 \$3x^2\$을 미분할 때, 상수 3은 그대로 두고 \$x^2\$만 미분하여 \$2x\$를 얻은 뒤, 이를 곱하여 \$3 \\times 2x = 6x\$와 같이 계산할 수 있습니다. 이처럼 상수배의 미분법을 익히면 복잡한 다항식의 도함수를 훨씬 빠르고 정확하게 구할 수 있습니다.',
              '이제 구체적인 예제를 통해 확인해 보겠습니다. 함수 \$f(x) = 5x^3\$의 도함수 \$f\'(x)\$를 구하는 과정을 단계별로 살펴보겠습니다. 먼저 미분 공식 \$\\frac{d}{dx} \\{c f(x)\\} = c f\'(x)\$에 따라 상수 5를 미분 기호 밖으로 꺼냅니다. 즉, \$f\'(x) = 5 \\times \\frac{d}{dx}(x^3)\$으로 식을 변형합니다.',
              '다음 단계로 \$x^n\$의 미분 공식인 \$\\frac{d}{dx}(x^n) = nx^{n-1}\$을 적용합니다. \$x^3\$을 미분하면 \$3x^{3-1} = 3x^2\$이 됩니다. 이제 앞서 꺼내두었던 상수 5와 이 결과를 곱하면 최종적인 도함수를 얻을 수 있습니다. 계산식은 다음과 같습니다. \$\$ f\'(x) = 5 \\times (3x^2) = 15x^2 \$\$ 따라서 함수 \$5x^3\$의 도함수는 \$15x^2\$입니다.',
            ],
          ),
        ],
      ),
