        intro: ['공통수학1 > 이차함수 > 이차함수의평행이동 개념 학습'],
        sections: [
          BookSection(
            title: '이차함수의평행이동',
            paragraphs: [
              '이차함수의 평행이동이란 이차함수의 그래프를 모양과 크기는 그대로 유지한 채, 좌표평면 위에서 가로 방향(x축)이나 세로 방향(y축)으로 밀어서 옮기는 것을 말합니다. 이차함수 \$y = ax^2\$의 그래프를 \$x\$축의 방향으로 \$p\$만큼, \$y\$축의 방향으로 \$q\$만큼 평행이동하면, 새로운 이차함수의 식은 \$y = a(x-p)^2 + q\$가 됩니다. 여기서 \$a\$는 그래프의 폭과 모양을 결정하며, 평행이동 후에도 변하지 않는다는 점이 핵심입니다.',
              '평행이동의 원리를 구체적으로 살펴보면, \$x\$축으로 \$p\$만큼 이동할 때는 식에서 \$x\$ 대신 \$(x-p)\$를 대입하고, \$y\$축으로 \$q\$만큼 이동할 때는 식 전체에 \$q\$를 더해줍니다. 이를 통해 얻은 \$y = a(x-p)^2 + q\$ 형태를 이차함수의 \'표준형\'이라고 부릅니다. 이 식을 보면 그래프의 꼭짓점 좌표가 \$(p, q)\$라는 사실을 바로 알 수 있는데, 이는 평행이동 전의 꼭짓점인 \$(0, 0)\$이 이동한 결과와 일치합니다.',
              '예를 들어, 이차함수 \$y = 2x^2\$의 그래프를 \$x\$축의 방향으로 \$3\$만큼, \$y\$축의 방향으로 \$-1\$만큼 평행이동한 식을 구해봅시다. 평행이동의 원리에 따라 \$x\$ 대신 \$(x-3)\$을 대입하고, 식 전체에 \$-1\$을 더해주면 됩니다. 따라서 구하는 이차함수의 식은 \$y = 2(x-3)^2 - 1\$이 됩니다. 이 그래프의 꼭짓점은 원래 \$(0, 0)\$에서 \$(3, -1)\$로 옮겨졌음을 확인할 수 있습니다.',
              '다음으로, 주어진 이차함수 식에서 평행이동 정보를 찾아내는 연습을 해보겠습니다. 이차함수 \$y = -(x+2)^2 + 5\$는 \$y = -x^2\$의 그래프를 어떻게 평행이동한 것일까요? 먼저 식을 \$y = a(x-p)^2 + q\$ 꼴과 비교합니다. 여기서 \$x+2\$는 \$x-(-2)\$로 생각할 수 있으므로 \$p = -2\$이고, \$q = 5\$임을 알 수 있습니다. 따라서 이 그래프는 \$y = -x^2\$을 \$x\$축의 방향으로 \$-2\$만큼, \$y\$축의 방향으로 \$5\$만큼 평행이동한 것입니다.',
              '마지막으로, 평행이동을 이용한 응용 문제를 풀어봅시다. 이차함수 \$y = 3(x-1)^2 + 2\$의 그래프를 \$x\$축의 방향으로 \$2\$만큼, \$y\$축의 방향으로 \$-4\$만큼 평행이동한 식을 구하고, 그 꼭짓점을 찾아보겠습니다. 먼저 \$x\$ 대신 \$(x-2)\$를 대입하면 \$y = 3((x-2)-1)^2 + 2\$가 되고, 여기에 \$y\$축으로 \$-4\$만큼 이동하므로 뒤에 \$-4\$를 더합니다. 식을 정리하면 \$y = 3(x-3)^2 - 2\$가 되며, 이 이차함수의 꼭짓점은 \$(3, -2)\$가 됩니다.',
            ],
          ),
        ],
      ),
    ],
