            title: '여집합',
            paragraphs: [
              '전체집합 \$U\$의 부분집합 \$A\$에 대하여, \$U\$의 원소 중에서 \$A\$에는 속하지 않는 모든 원소로 이루어진 집합을 \$A\$의 여집합이라 하고, 기호로 \$A^c\$와 같이 나타냅니다. 이를 조건제시법으로 표현하면 \$A^c = \\{x \\mid x \\in U \\text{ 이고 } x \\notin A\\}\$가 됩니다. 즉, 여집합은 전체집합이라는 큰 울타리 안에서 특정 집합 \$A\$를 제외한 나머지 부분을 의미합니다.',
              '여집합의 성질을 살펴보면, 어떤 집합 \$A\$와 그 여집합 \$A^c\$를 합치면 전체집합 \$U\$가 되고(\$A \\cup A^c = U\$), 공통된 원소는 존재하지 않습니다(\$A \\cap A^c = \\emptyset\$). 또한, 전체집합의 여집합은 공집합이고(\$U^c = \\emptyset\$), 공집합의 여집합은 전체집합이 됩니다(\$\\emptyset^c = U\$). 마지막으로, 여집합의 여집합은 원래의 집합으로 돌아오는 성질이 있습니다. 이를 수식으로 나타내면 \$\$(A^c)^c = A\$\$와 같습니다.',
              '이제 구체적인 예제를 통해 여집합을 이해해 봅시다. 전체집합 \$U = \\{1, 2, 3, 4, 5, 6\\}\$이고, 그 부분집합 \$A = \\{1, 3, 5\\}\$라고 할 때, \$A\$의 여집합 \$A^c\$를 구하는 과정을 단계별로 설명하겠습니다. 먼저, \$A^c\$는 전체집합 \$U\$의 원소 중 \$A\$에 포함된 원소인 \$1, 3, 5\$를 제외한 나머지 원소들을 모은 집합입니다.',
              '따라서 \$A^c\$를 구하는 과정은 다음과 같습니다. 전체집합 \$U\$에서 집합 \$A\$의 원소를 하나씩 제거해 나갑니다. \$U = \\{1, 2, 3, 4, 5, 6\\}\$에서 \$1\$을 제거하고, \$3\$을 제거하고, \$5\$를 제거하면 남는 원소는 \$2, 4, 6\$입니다. 이를 집합 기호로 정리하면 \$\$A^c = \\{2, 4, 6\\}\$\$이 됩니다. 이처럼 여집합은 전체집합 안에서 특정 조건을 만족하지 않는 대상을 찾는 유용한 도구입니다.',
