        sections: [
          BookSection(
            title: '공비',
            paragraphs: [
              '등비수열이란 첫째항부터 차례대로 일정한 수를 곱하여 만들어지는 수열을 말합니다. 이때, 각 항에서 바로 앞의 항을 나누었을 때 얻어지는 일정한 값을 \'공비(common ratio)\'라고 부르며, 보통 영어 알파벳 \$r\$로 나타냅니다. 즉, 등비수열의 첫째항을 \$a\$, 공비를 \$r\$이라고 할 때, 이 수열은 \$a, ar, ar^2, ar^3, \\dots\$와 같은 형태로 나열됩니다.',
              '공비 \$r\$을 구하는 방법은 간단합니다. 수열의 제\$n\$항을 \$a_n\$이라고 할 때, 인접한 두 항의 관계는 \$a_{n+1} = a_n \\times r\$로 표현됩니다. 따라서 공비는 \$r = \\frac{a_{n+1}}{a_n}\$ (\$a_n \\neq 0\$)이라는 공식을 통해 구할 수 있습니다. 만약 공비 \$r\$이 1보다 크면 항의 절댓값이 점점 커지고, \$0\$과 \$1\$ 사이라면 항의 절댓값이 점점 \$0\$에 가까워지며, \$r\$이 음수라면 항의 부호가 양수와 음수로 번갈아 나타나는 특징이 있습니다.',
              '예를 들어, 수열 \$3, 6, 12, 24, \\dots\$가 있다고 가정해 봅시다. 이 수열에서 공비를 구하려면 두 번째 항을 첫 번째 항으로 나누면 됩니다. 즉, \$r = \\frac{6}{3} = 2\$입니다. 실제로 세 번째 항과 두 번째 항을 나누어도 \$r = \\frac{12}{6} = 2\$가 되어 일정함을 확인할 수 있습니다. 따라서 이 수열의 공비는 \$2\$이며, 제\$n\$항은 일반항 공식 \$a_n = a \\times r^{n-1}\$에 따라 \$a_n = 3 \\times 2^{n-1}\$로 나타낼 수 있습니다.',
              '다음으로 조금 더 복잡한 예제를 풀어보겠습니다. 첫째항이 \$81\$이고 제4항이 \$3\$인 등비수열에서 공비 \$r\$을 구하는 문제입니다. 등비수열의 일반항 공식 \$a_n = a \\times r^{n-1}\$을 이용하면, 제4항은 \$a_4 = a \\times r^{4-1} = a \\times r^3\$이 됩니다. 여기에 주어진 값들을 대입하면 \$81 \\times r^3 = 3\$이라는 방정식을 세울 수 있습니다.',
              '이제 이 방정식을 단계별로 풀어봅시다. 먼저 양변을 \$81\$로 나누면 \$r^3 = \\frac{3}{81}\$이 되고, 이를 약분하면 \$r^3 = \\frac{1}{27}\$이 됩니다. 어떤 수를 세 번 곱해서 \$\\frac{1}{27}\$이 되는 수를 찾으면 \$r = \\frac{1}{3}\$임을 알 수 있습니다. 따라서 이 등비수열의 공비는 \$\\frac{1}{3}\$이며, 수열은 \$81, 27, 9, 3, \\dots\$와 같이 진행됨을 확인할 수 있습니다.',
            ],
          ),
        ],
      ),
    ],
  ),
  '가우스소거법': BookData(
    id: 'concept_가우스소거법',
    title: '가우스소거법',
    subtitle: '공통수학1 > 행렬 > 연립일차방정식과행렬 > 가우스소거법',
    category: 'common',
    tags: ['공통수학1', '행렬', '연립일차방정식과행렬', '가우스소거법'],
    chapters: [
      BookChapter(
        title: '가우스소거법',
        intro: ['공통수학1 > 행렬 > 연립일차방정식과행렬 > 가우스소거법 개념 학습'],
        sections: [
          BookSection(
            title: '가우스소거법',
            paragraphs: [
              '가우스 소거법(Gaussian elimination)은 연립일차방정식을 체계적으로 풀기 위한 가장 대표적인 알고리즘입니다. 이 방법의 핵심은 연립방정식의 계수들을 행렬로 나타낸 뒤, \'기본 행 연산\'을 반복하여 행렬을 \'행 사다리꼴(row echelon form)\' 형태로 만드는 것입니다. 행 사다리꼴이란, 각 행의 첫 번째 0이 아닌 성분이 오른쪽 아래로 계단식으로 배열된 형태를 말하며, 이 과정을 거치면 마지막 행부터 차례대로 미지수의 값을 구할 수 있습니다.',
              '기본 행 연산에는 세 가지 규칙이 있습니다. 첫째, 두 행의 위치를 서로 바꿀 수 있습니다. 둘째, 한 행에 0이 아닌 상수를 곱할 수 있습니다. 셋째, 한 행에 다른 행의 상수배를 더하거나 뺄 수 있습니다. 이러한 연산들은 방정식의 해를 변화시키지 않으므로, 복잡한 연립방정식을 훨씬 다루기 쉬운 형태로 변형하여 최종적으로 \$\$x_1, x_2, \\dots, x_n\$\$의 값을 명확하게 찾아낼 수 있게 해줍니다.',
              '예를 들어, 다음 연립방정식을 가우스 소거법으로 풀어봅시다.  \$\$x + y = 3\$\$ \$\$2x - y = 0\$\$ 먼저 이를 첨가행렬로 나타내면 다음과 같습니다. \$\$\\begin{pmatrix} 1 & 1 & | & 3 \\\\ 2 & -1 & | & 0 \\end{pmatrix}\$\$',
              '이제 첫 번째 행의 2배를 두 번째 행에서 빼서 두 번째 행의 첫 번째 성분을 0으로 만듭니다. 즉, (2행) - 2 × (1행)을 수행합니다. 그러면 행렬은 다음과 같이 변합니다. \$\$\\begin{pmatrix} 1 & 1 & | & 3 \\\\ 0 & -3 & | & -6 \\end{pmatrix}\$\$ 이제 두 번째 행을 -3으로 나누면,  \$\$\\begin{pmatrix} 1 & 1 & | & 3 \\\\ 0 & 1 & | & 2 \\end{pmatrix}\$\$ 이 됩니다.',
              '마지막으로, 두 번째 행의 값을 첫 번째 행에서 빼주면(1행 - 2행) 미지수를 모두 구할 수 있습니다. \$\$\\begin{pmatrix} 1 & 0 & | & 1 \\\\ 0 & 1 & | & 2 \\end{pmatrix}\$\$ 이 행렬은 최종적으로 \$\$x = 1\$\$, \$\$y = 2\$\$라는 해를 의미합니다. 이처럼 가우스 소거법을 활용하면 복잡한 연립방정식도 단계적인 계산을 통해 정확하고 빠르게 해결할 수 있습니다.',
            ],
          ),
        ],
      ),
    ],
  ),
  '몫과나머지': BookData(
    id: 'concept_몫과나머지',
    title: '몫과나머지',
    subtitle: '공통수학1 > 다항식 > 다항식의나눗셈 > 몫과나머지',
    category: 'common',
    tags: ['공통수학1', '다항식', '다항식의나눗셈', '몫과나머지'],
    chapters: [
      BookChapter(
        title: '몫과나머지',
        intro: ['공통수학1 > 다항식 > 다항식의나눗셈 > 몫과나머지 개념 학습'],
        sections: [
          BookSection(
            title: '몫과나머지',
            paragraphs: [
              '다항식의 나눗셈은 자연수의 나눗셈과 매우 유사한 원리로 작동합니다. 다항식 \$A\$를 다항식 \$B\$(\$B \\neq 0\$)로 나눌 때, 몫을 \$Q\$, 나머지를 \$R\$이라고 하면 \$A = BQ + R\$의 형태로 나타낼 수 있습니다. 이때 나머지 \$R\$의 차수는 나누는 식 \$B\$의 차수보다 항상 낮아야 하며, 만약 \$R=0\$이면 다항식 \$A\$는 다항식 \$B\$로 나누어떨어진다고 합니다.',
              '이 관계식을 항등식의 성질을 이용하여 표현하면 \$\$A(x) = B(x)Q(x) + R(x)\$\$와 같이 쓸 수 있습니다. 여기서 \$B(x)\$가 \$n\$차 다항식이라면, 나머지 \$R(x)\$는 최대 \$n-1\$차 이하의 다항식이 됩니다. 특히 \$B(x)\$가 일차식인 경우에는 나머지가 상수항이 된다는 점을 기억하면 문제를 해결할 때 매우 유용합니다.',
              '다항식의 나눗셈을 직접 수행할 때는 자연수의 나눗셈처럼 각 다항식을 내림차순으로 정리한 뒤, 최고차항을 맞추어 나가는 과정을 반복합니다. 이 과정에서 각 단계마다 뺄셈을 정확히 수행하는 것이 핵심이며, 나누어지는 식의 차수가 나누는 식의 차수보다 작아질 때까지 계산을 계속하면 됩니다.',
              '예제: 다항식 \$x^3 - 2x^2 + 3x + 1\$을 \$x - 2\$로 나누었을 때의 몫과 나머지를 구해보겠습니다. 먼저 \$x^3\$을 만들기 위해 \$x^2\$을 곱하여 \$(x^3 - 2x^2)\$을 빼줍니다. 그러면 남은 식은 \$3x + 1\$이 됩니다. 이어서 \$3x\$를 만들기 위해 \$3\$을 곱하여 \$(3x - 6)\$을 빼주면 최종적으로 나머지는 \$7\$이 됩니다.',
              '위의 과정을 수식으로 정리하면 다음과 같습니다. \$\$x^3 - 2x^2 + 3x + 1 = (x - 2)(x^2 + 3) + 7\$\$ 따라서 이 나눗셈의 몫 \$Q(x)\$는 \$x^2 + 3\$이고, 나머지 \$R\$은 \$7\$입니다. 이처럼 다항식의 나눗셈은 각 항의 계수를 맞추어 소거해 나가는 과정임을 이해하면 어떤 복잡한 다항식도 쉽게 나눌 수 있습니다.',
            ],
          ),
        ],
      ),
    ],
  ),
  '무리함수의평행이동': BookData(
    id: 'concept_무리함수의평행이동',
    title: '무리함수의평행이동',
    subtitle: '공통수학2 > 무리식과무리함수 > 무리함수의그래프 > 무리함수의평행이동',
    category: 'common',
    tags: ['공통수학2', '무리식과무리함수', '무리함수의그래프', '무리함수의평행이동'],
    chapters: [
      BookChapter(
        title: '무리함수의평행이동',
        intro: ['공통수학2 > 무리식과무리함수 > 무리함수의그래프 > 무리함수의평행이동 개념 학습'],
        sections: [
          BookSection(
            title: '무리함수의평행이동',
            paragraphs: [
              '무리함수의 평행이동이란 기본형인 \$y = \\sqrt{ax}\$의 그래프를 좌표평면 위에서 가로 방향(x축)으로 \$p\$만큼, 세로 방향(y축)으로 \$q\$만큼 밀어서 옮기는 것을 의미합니다. 이렇게 평행이동을 하면 그래프의 모양은 변하지 않으면서 위치만 바뀌게 되는데, 이때 함수식은 \$x\$ 대신 \$x-p\$를, \$y\$ 대신 \$y-q\$를 대입하여 얻을 수 있습니다. 즉, 평행이동된 무리함수의 일반적인 형태는 \$\$y = \\sqrt{a(x-p)} + q\$\$와 같이 나타낼 수 있습니다.',
              '이 식에서 중요한 점은 그래프의 시작점과 정의역, 치역의 변화입니다. 원래 \$y = \\sqrt{ax}\$의 시작점은 \$(0, 0)\$이었지만, \$x\$축으로 \$p\$, \$y\$축으로 \$q\$만큼 평행이동했으므로 새로운 시작점은 \$(p, q)\$가 됩니다. 또한, 근호 안의 값은 항상 \$0\$ 이상이어야 하므로 \$a(x-p) \\ge 0\$을 만족해야 합니다. 따라서 \$a > 0\$일 때 정의역은 \$x \\ge p\$, 치역은 \$y \\ge q\$가 되며, \$a\$의 부호와 근호 앞의 부호에 따라 그래프가 뻗어 나가는 방향이 결정됩니다.',
              '예를 들어, 함수 \$y = \\sqrt{2x-4} + 3\$의 그래프를 그려봅시다. 먼저 이 식을 평행이동이 잘 보이도록 \$y = \\sqrt{2(x-2)} + 3\$으로 변형합니다. 이 식은 기본형인 \$y = \\sqrt{2x}\$를 \$x\$축의 방향으로 \$2\$만큼, \$y\$축의 방향으로 \$3\$만큼 평행이동한 것입니다. 따라서 이 함수의 시작점은 \$(2, 3)\$이 되며, 그래프는 시작점에서 오른쪽 위를 향해 완만하게 뻗어 나가는 곡선 형태가 됩니다.',
              '이제 구체적인 예제 문제를 풀어보겠습니다. \'함수 \$y = \\sqrt{3x+6} - 1\$의 그래프를 그리고, 정의역과 치역을 구하시오.\'라는 문제가 있다면, 가장 먼저 식을 표준형으로 정리해야 합니다. 근호 안을 \$x\$의 계수로 묶으면 \$\$y = \\sqrt{3(x+2)} - 1\$\$이 됩니다. 이 식을 통해 우리는 이 그래프가 \$y = \\sqrt{3x}\$를 \$x\$축으로 \$-2\$만큼, \$y\$축으로 \$-1\$만큼 평행이동했음을 알 수 있습니다.',
              '마지막으로, 위에서 구한 식을 바탕으로 정의역과 치역을 결정합니다. 근호 안의 값인 \$3(x+2)\$가 \$0\$보다 크거나 같아야 하므로 \$x+2 \\ge 0\$, 즉 \$x \\ge -2\$가 정의역이 됩니다. 또한, 무리함수 값 \$\\sqrt{3(x+2)}\$는 항상 \$0\$ 이상이므로, 여기에 \$-1\$을 더한 전체 식의 값은 \$-1\$보다 크거나 같습니다. 따라서 치역은 \$y \\ge -1\$이 됩니다. 이처럼 평행이동된 무리함수는 시작점 \$(p, q)\$를 기준으로 정의역과 치역을 쉽게 파악할 수 있습니다.',
            ],
          ),
        ],
      ),
    ],
  ),
  '최댓값(이차함수)': BookData(
    id: 'concept_최댓값(이차함수)',
    title: '최댓값(이차함수)',
    subtitle: '공통수학1 > 이차함수 > 이차함수의최대최소 > 최댓값(이차함수)',
    category: 'common',
    tags: ['공통수학1', '이차함수', '이차함수의최대최소', '최댓값(이차함수)'],
    chapters: [
      BookChapter(
        title: '최댓값(이차함수)',
        intro: ['공통수학1 > 이차함수 > 이차함수의최대최소 > 최댓값(이차함수) 개념 학습'],
        sections: [
          BookSection(
            title: '최댓값(이차함수)',
            paragraphs: [
              '이차함수의 최댓값이란 그래프가 위로 볼록할 때, 즉 이차항의 계수가 음수일 때 함숫값이 가질 수 있는 가장 큰 값을 의미합니다. 이차함수 \$y = ax^2 + bx + c\$ (\$a \\neq 0\$)의 그래프는 포물선 모양을 띠는데, \$a < 0\$이면 그래프는 위로 볼록한 형태가 되어 꼭짓점에서 최댓값을 갖게 됩니다. 이때의 최댓값은 그래프의 가장 높은 지점의 \$y\$ 좌표와 같습니다.',
              '이차함수의 최댓값을 구하기 위해서는 먼저 주어진 식을 완전제곱식 꼴인 \$y = a(x - p)^2 + q\$로 변형해야 합니다. 이 표준형에서 꼭짓점의 좌표는 \$(p, q)\$가 되며, \$a < 0\$일 때 함수 \$y\$는 \$x = p\$에서 최댓값 \$q\$를 가집니다. 만약 \$a > 0\$이라면 그래프는 아래로 볼록하여 최솟값만 존재하고 최댓값은 한없이 커지므로 존재하지 않는다는 점을 유의해야 합니다.',
              '범위가 제한된 구간 \$[m, n]\$에서 이차함수의 최댓값을 구할 때는 꼭짓점의 \$x\$ 좌표인 \$p\$가 구간 안에 포함되는지 확인하는 것이 핵심입니다. 만약 \$p\$가 구간 안에 있다면 꼭짓점의 \$y\$ 좌표인 \$q\$가 최댓값 후보가 되며, 구간의 양 끝점인 \$f(m)\$과 \$f(n)\$의 값과 비교하여 가장 큰 값을 선택합니다. 만약 \$p\$가 구간 밖에 있다면, 구간 내에서 함수는 계속 증가하거나 감소하므로 양 끝점 중 하나가 최댓값이 됩니다.',
              '예제: 이차함수 \$y = -2x^2 + 8x + 3\$의 최댓값을 구하시오. 먼저 식을 표준형으로 바꾸기 위해 \$x\$항을 묶어줍니다. \$y = -2(x^2 - 4x) + 3\$이 되고, 괄호 안을 완전제곱식으로 만들기 위해 \$4\$를 더하고 빼면 \$y = -2(x^2 - 4x + 4 - 4) + 3\$이 됩니다. 이를 정리하면 \$y = -2(x - 2)^2 + 8 + 3\$, 즉 \$y = -2(x - 2)^2 + 11\$이 됩니다.',
              '위의 풀이에서 구한 표준형 \$y = -2(x - 2)^2 + 11\$을 살펴보면, 이차항의 계수가 \$-2\$로 음수이므로 이 그래프는 위로 볼록합니다. 따라서 꼭짓점 \$(2, 11)\$에서 최댓값을 갖게 됩니다. 결론적으로 \$x = 2\$일 때, 주어진 이차함수의 최댓값은 \$11\$이 됩니다.',
            ],
          ),
        ],
      ),
    ],
  ),
  '접선의기울기': BookData(
    id: 'concept_접선의기울기',
    title: '접선의기울기',
    subtitle: '미적분Ⅰ > 접선의방정식 > 접선의기울기',
    category: 'common',
    tags: ['미적분Ⅰ', '접선의방정식', '접선의기울기'],
    chapters: [
      BookChapter(
        title: '접선의기울기',
        intro: ['미적분Ⅰ > 접선의방정식 > 접선의기울기 개념 학습'],
        sections: [
          BookSection(
            title: '접선의기울기',
            paragraphs: [
              '함수 \$y=f(x)\$의 그래프 위의 한 점 \$(a, f(a))\$에서 접선의 기울기는 그 점에서의 미분계수 \$f\'(a)\$와 같습니다. 미분계수는 곡선 위의 점 \$x=a\$에서 \$x\$가 아주 조금 변할 때 \$y\$가 얼마나 변하는지를 나타내는 순간적인 변화율을 의미합니다. 즉, 곡선 위의 한 점을 지나는 직선이 그 점 근처에서 곡선과 가장 비슷하게 겹쳐지는 직선의 기울기를 구하는 과정이 바로 접선의 기울기를 찾는 과정입니다.',
              '접선의 기울기를 구하는 핵심 공식은 미분의 정의를 이용한 극한식입니다. 함수 \$f(x)\$가 \$x=a\$에서 미분가능할 때, 점 \$(a, f(a))\$에서의 접선의 기울기 \$m\$은 다음과 같이 정의됩니다. \$\$m = f\'(a) = \\lim_{h \\to 0} \\frac{f(a+h) - f(a)}{h}\$\$ 이 식은 점 \$a\$와 점 \$a+h\$를 잇는 할선의 기울기에서 \$h\$를 0으로 한없이 가깝게 보냄으로써, 두 점이 한 점으로 모일 때의 기울기를 구하는 원리를 담고 있습니다.',
              '접선의 기울기를 알면 접선의 방정식을 쉽게 구할 수 있습니다. 점 \$(a, f(a))\$를 지나고 기울기가 \$f\'(a)\$인 직선의 방정식은 다음과 같습니다. \$\$y - f(a) = f\'(a)(x - a)\$\$ 이 식은 기울기의 정의를 활용하여 점과 기울기가 주어졌을 때 직선을 만드는 표준적인 방법입니다. 따라서 곡선 위의 한 점에서의 기울기만 정확히 계산할 수 있다면, 그 점에서의 접선 전체를 완벽하게 정의할 수 있습니다.',
              '예제: 함수 \$f(x) = x^2 + 3x\$의 그래프 위의 점 \$(1, 4)\$에서의 접선의 기울기를 구하고, 접선의 방정식을 세워봅시다. 먼저 기울기를 구하기 위해 함수를 미분하면 \$f\'(x) = 2x + 3\$이 됩니다. 이제 \$x=1\$을 대입하여 접선의 기울기 \$m\$을 구합니다. \$\$m = f\'(1) = 2(1) + 3 = 5\$\$ 따라서 구하고자 하는 접선의 기울기는 5입니다.',
              '이제 구한 기울기 \$m=5\$와 점 \$(1, 4)\$를 이용하여 접선의 방정식을 완성합니다. 접선의 방정식 공식 \$y - f(a) = f\'(a)(x - a)\$에 \$a=1, f(a)=4, f\'(a)=5\$를 각각 대입합니다. \$\$y - 4 = 5(x - 1)\$\$ 이를 정리하면 \$y - 4 = 5x - 5\$가 되어, 최종적인 접선의 방정식은 \$\$y = 5x - 1\$\$이 됩니다. 이처럼 미분법을 이용하면 복잡한 곡선 위에서도 원하는 지점의 기울기와 직선의 방정식을 간단히 찾아낼 수 있습니다.',
            ],
          ),
        ],
      ),
    ],
  ),
  '진부분집합': BookData(
    id: 'concept_진부분집합',
    title: '진부분집합',
    subtitle: '공통수학2 > 집합 > 집합의포함관계 > 진부분집합',
