    chapters: [
      BookChapter(
        title: '진부분집합',
        intro: ['공통수학2 > 집합 > 집합의포함관계 > 진부분집합 개념 학습'],
        sections: [
          BookSection(
            title: '진부분집합',
            paragraphs: [
              '집합 \$A\$의 모든 원소가 집합 \$B\$에 속할 때, 우리는 \$A\$를 \$B\$의 부분집합이라고 하며 \$A \\subset B\$로 나타냅니다. 이때, 부분집합 중에서 자기 자신인 집합을 제외한 나머지 부분집합들을 \'진부분집합\'이라고 부릅니다. 즉, 집합 \$A\$가 \$B\$의 부분집합이면서 \$A\$와 \$B\$가 서로 같지 않을 때(\$A \\neq B\$), \$A\$를 \$B\$의 진부분집합이라고 정의합니다.',
              '집합 \$A\$의 원소의 개수를 \$n\$이라고 할 때, \$A\$의 모든 부분집합의 개수는 \$2^n\$개입니다. 진부분집합은 이 전체 부분집합 중에서 자기 자신인 집합 하나를 제외한 것이므로, 진부분집합의 개수를 구하는 공식은 다음과 같습니다. \$\$ \\text{진부분집합의 개수} = 2^n - 1 \$\$ 이 공식은 집합 \$A\$가 공집합이 아닐 때 성립하며, 진부분집합은 자기 자신을 포함하지 않는다는 점이 핵심입니다.',
              '진부분집합의 성질을 이해하기 위해 예를 들어보겠습니다. 집합 \$A = \\{1, 2\\}\$의 부분집합을 모두 나열하면 \$\\emptyset, \\{1\\}, \\{2\\}, \\{1, 2\\}\$의 4개입니다. 여기서 자기 자신인 \$\\{1, 2\\}\$를 제외하면 남는 것은 \$\\emptyset, \\{1\\}, \\{2\\}\$이며, 이 3개가 바로 집합 \$A\$의 진부분집합이 됩니다. 공식에 대입하면 \$2^2 - 1 = 4 - 1 = 3\$이 되어 결과가 일치함을 알 수 있습니다.',
              '이제 구체적인 예제를 풀어봅시다. 집합 \$A = \\{a, b, c, d\\}\$의 진부분집합의 개수를 구하는 과정을 단계별로 살펴보겠습니다. 첫째, 집합 \$A\$의 원소의 개수 \$n\$을 확인합니다. \$A\$에는 \$a, b, c, d\$라는 4개의 원소가 있으므로 \$n = 4\$입니다.',
              '둘째, 전체 부분집합의 개수를 구합니다. 부분집합의 개수는 \$2^n\$이므로 \$2^4 = 16\$입니다. 셋째, 진부분집합의 개수를 구하기 위해 전체 부분집합의 개수에서 자기 자신인 집합 하나를 뺍니다. 따라서 계산식은 다음과 같습니다. \$\$ 2^4 - 1 = 16 - 1 = 15 \$\$ 결과적으로 집합 \$A\$의 진부분집합은 총 15개입니다.',
            ],
          ),
        ],
      ),
    ],
