  '등비수열의일반항': BookData(
    id: 'concept_등비수열의일반항',
    title: '등비수열의일반항',
    subtitle: '대수 > 수열 > 등비수열 > 등비수열의일반항',
    category: 'common',
    tags: ['대수', '수열', '등비수열', '등비수열의일반항'],
    chapters: [
      BookChapter(
        title: '등비수열의일반항',
        intro: ['대수 > 수열 > 등비수열 > 등비수열의일반항 개념 학습'],
        sections: [
          BookSection(
            title: '등비수열의일반항',
            paragraphs: [
              '등비수열이란 첫째항부터 차례대로 일정한 수를 곱하여 만들어지는 수열을 말합니다. 이때 곱하는 일정한 수를 \'공비(common ratio)\'라고 하며, 보통 기호 \$r\$로 나타냅니다. 첫째항을 \$a\$라고 할 때, 이 수열은 \$a, ar, ar^2, ar^3, \\dots\$와 같은 규칙으로 나열됩니다. 즉, 앞의 항에 공비 \$r\$을 곱하면 다음 항이 되는 구조를 가지고 있습니다.',
              '등비수열의 일반항 \$a_n\$은 첫째항 \$a\$에 공비 \$r\$을 \$(n-1)\$번 곱한 것으로 정의합니다. 수열의 첫 번째 항은 \$a \\times r^0\$, 두 번째 항은 \$a \\times r^1\$, 세 번째 항은 \$a \\times r^2\$인 규칙을 관찰하면, \$n\$번째 항인 일반항의 공식은 다음과 같이 유도됩니다. \$\$a_n = a \\cdot r^{n-1} \\quad (a \\neq 0, r \\neq 0)\$\$ 이 공식은 첫째항과 공비만 알면 수열의 어떤 번째 항이라도 바로 구할 수 있게 해주는 매우 유용한 도구입니다.',
              '등비수열의 성질 중 중요한 것은 인접한 두 항의 비가 항상 일정하다는 점입니다. 즉, \$\\frac{a_{n+1}}{a_n} = r\$이 성립합니다. 또한, 세 수 \$a, b, c\$가 이 순서대로 등비수열을 이룰 때, 가운데 항 \$b\$를 \$a\$와 \$c\$의 \'등비중항\'이라고 하며, \$b^2 = ac\$라는 관계가 성립합니다. 이러한 성질들은 복잡한 수열의 문제를 해결할 때 핵심적인 단서가 됩니다.',
              '예제: 첫째항이 3이고 공비가 2인 등비수열에서 제5항을 구해보겠습니다. 일반항 공식 \$a_n = a \\cdot r^{n-1}\$에 주어진 값 \$a=3, r=2, n=5\$를 대입합니다. 그러면 \$a_5 = 3 \\cdot 2^{5-1}\$이 됩니다. 이를 계산하면 \$a_5 = 3 \\cdot 2^4 = 3 \\cdot 16 = 48\$이 되어, 제5항은 48임을 알 수 있습니다.',
              '예제: 제2항이 6이고 제4항이 54인 등비수열이 있습니다. 공비 \$r\$이 양수일 때, 이 수열의 일반항을 구하는 과정입니다. 일반항 공식에 따라 \$a_2 = ar = 6\$이고 \$a_4 = ar^3 = 54\$입니다. 두 식을 나누면 \$\\frac{ar^3}{ar} = \\frac{54}{6}\$이 되어 \$r^2 = 9\$를 얻습니다. 공비가 양수이므로 \$r=3\$이고, 이를 \$ar=6\$에 대입하면 \$a=2\$가 됩니다. 따라서 일반항은 \$\$a_n = 2 \\cdot 3^{n-1}\$\$ 입니다.',
            ],
          ),
        ],
      ),
    ],
