            title: '접선방정식구하기',
            paragraphs: [
              '미분계수의 기하학적 의미는 곡선 위의 한 점에서의 \'접선의 기울기\'입니다. 함수 \$f(x)\$ 위의 점 \$(a, f(a))\$에서 접하는 직선의 방정식을 구하려면, 우선 해당 점에서의 미분계수 \$f\'(a)\$를 구해야 합니다. 이 \$f\'(a)\$가 바로 접선의 기울기가 되며, 점 \$(a, f(a))\$를 지나고 기울기가 \$f\'(a)\$인 직선의 방정식은 점-기울기 공식을 이용하여 다음과 같이 나타낼 수 있습니다.',
              '점 \$(a, f(a))\$에서의 접선의 방정식 공식은 다음과 같습니다. \$\$y - f(a) = f\'(a)(x - a)\$\$ 이를 \$y\$에 관하여 정리하면 \$\$y = f\'(a)(x - a) + f(a)\$\$가 됩니다. 여기서 \$f\'(a)\$는 \$x=a\$에서의 순간변화율이자 접선의 기울기이며, 이 식을 이용하면 곡선 위의 임의의 점에서의 접선을 언제나 정확하게 찾아낼 수 있습니다.',
              '접선의 방정식을 구할 때는 먼저 주어진 점의 좌표 \$(a, f(a))\$를 확인하고, 함수를 미분하여 도함수 \$f\'(x)\$를 구한 뒤 \$x=a\$를 대입하여 기울기를 찾는 순서로 진행합니다. 만약 접점의 좌표가 주어지지 않고 기울기만 주어졌다면, \$f\'(x) = m\$을 만족하는 \$x\$ 값을 먼저 찾아 접점을 구한 후 위 공식을 적용하면 됩니다.',
              '예제: 함수 \$f(x) = x^2 + 3x\$ 위의 점 \$(1, 4)\$에서의 접선의 방정식을 구해보겠습니다. 먼저 접점은 \$(1, 4)\$이므로 \$a=1, f(a)=4\$입니다. 다음으로 도함수를 구하면 \$f\'(x) = 2x + 3\$이 됩니다. 이제 접점의 \$x\$ 좌표인 \$1\$을 도함수에 대입하여 기울기를 구하면 \$f\'(1) = 2(1) + 3 = 5\$입니다.',
              '이제 구한 기울기 \$5\$와 점 \$(1, 4)\$를 접선의 방정식 공식 \$y - f(a) = f\'(a)(x - a)\$에 대입합니다. 식을 세우면 \$y - 4 = 5(x - 1)\$이 됩니다. 이를 정리하면 \$y - 4 = 5x - 5\$가 되어, 최종적인 접선의 방정식은 \$\$y = 5x - 1\$\$이 됩니다. 이처럼 미분을 활용하면 복잡한 곡선 위에서도 원하는 지점의 접선을 간단히 구할 수 있습니다.',
