            title: '조립제법',
            paragraphs: [
              '조립제법은 다항식을 일차식으로 나눌 때, 다항식의 계수만을 사용하여 몫과 나머지를 빠르고 간편하게 구하는 방법입니다. 일반적인 다항식의 나눗셈은 세로셈을 이용해야 해서 번거롭지만, 나누는 식이 \$x-a\$와 같은 일차식일 때는 조립제법을 사용하면 계산 과정을 획기적으로 줄일 수 있습니다. 다만, 나누는 식의 \$x\$의 계수가 1이 아닐 경우에는 주의가 필요하며, 이는 뒤에서 다룰 예제를 통해 자세히 설명하겠습니다.',
              '조립제법을 수행하는 방법은 다음과 같습니다. 먼저 나뉠 다항식의 계수를 차수가 높은 순서대로 나열합니다. 이때, 특정 차수의 항이 없다면 그 자리에 0을 반드시 써주어야 합니다. 그 후, 나누는 식 \$x-a\$를 0으로 만드는 값인 \$a\$를 왼쪽에 적습니다. 첫 번째 계수는 그대로 내리고, 그 값에 \$a\$를 곱하여 다음 계수 아래에 적은 뒤 더하는 과정을 반복하면 마지막에 나머지가, 나머지 숫자들은 몫의 계수가 됩니다.',
              '조립제법의 핵심 공식과 원리는 다항식 \$P(x)\$를 \$x-a\$로 나눌 때, \$P(x) = (x-a)Q(x) + R\$의 꼴로 나타내는 것입니다. 여기서 \$Q(x)\$는 몫이고 \$R\$은 나머지입니다. 만약 나누는 식이 \$ax+b\$와 같이 \$x\$의 계수가 \$a\$인 경우라면, 조립제법으로 구한 몫을 \$Q\'(x)\$라고 할 때 실제 몫은 \$Q(x) = \\frac{Q\'(x)}{a}\$가 되며, 나머지는 변하지 않는다는 성질을 기억해야 합니다.',
              '예제: 다항식 \$2x^3 - 3x^2 + 4x - 5\$를 \$x-2\$로 나눌 때의 몫과 나머지를 구하시오. 먼저 계수 2, -3, 4, -5를 나열하고, 나누는 식을 0으로 만드는 값인 2를 왼쪽에 씁니다. 첫 번째 계수 2를 그대로 내리고, \$2 \\times 2 = 4\$를 -3 아래에 적어 더하면 1이 됩니다. 다시 \$1 \\times 2 = 2\$를 4 아래에 적어 더하면 6이 되고, 마지막으로 \$6 \\times 2 = 12\$를 -5 아래에 적어 더하면 7이 됩니다.',
              '위의 계산 과정을 정리하면 다음과 같습니다. 조립제법의 결과로 얻은 계수 2, 1, 6은 몫의 계수가 되고, 마지막 값 7은 나머지가 됩니다. 따라서 몫 \$Q(x) = 2x^2 + x + 6\$이며, 나머지 \$R = 7\$입니다. 이를 검산식으로 나타내면 \$2x^3 - 3x^2 + 4x - 5 = (x-2)(2x^2 + x + 6) + 7\$이 되어 정확하게 나누어떨어짐을 확인할 수 있습니다.',
            ],
          ),
        ],
      ),
    ],
  ),
