              '좌표평면 위의 두 점 사이의 거리는 두 점을 잇는 선분의 길이를 의미합니다. 수직선 위에서 두 점 \$A(x_1)\$, \$B(x_2)\$ 사이의 거리는 두 좌표의 차에 절댓값을 씌운 \$|x_2 - x_1|\$로 나타냅니다. 이를 이차원 좌표평면으로 확장하면, 두 점 \$A(x_1, y_1)\$과 \$B(x_2, y_2)\$ 사이의 거리는 피타고라스의 정리를 이용하여 구할 수 있습니다.',
              '두 점 \$A(x_1, y_1)\$과 \$B(x_2, y_2)\$를 지나는 선분을 빗변으로 하고, 각 축에 평행한 두 변을 가진 직각삼각형을 생각해보면 밑변의 길이는 \$|x_2 - x_1|\$, 높이는 \$|y_2 - y_1|\$이 됩니다. 피타고라스의 정리에 의해 두 점 사이의 거리 \$d\$는 다음과 같은 공식으로 정의됩니다. \$\$d = \\sqrt{(x_2 - x_1)^2 + (y_2 - y_1)^2}\$\$',
              '이 공식은 좌표평면 위의 어떤 두 점 사이의 거리라도 구할 수 있는 매우 강력한 도구입니다. 특히 한 점이 원점 \$(0, 0)\$인 경우, 점 \$(x, y)\$와 원점 사이의 거리는 \$d = \\sqrt{x^2 + y^2}\$가 됩니다. 이 공식은 도형의 성질을 분석하거나 원의 방정식을 유도할 때 기초가 되는 핵심 개념입니다.',
              '예제: 두 점 \$A(1, 2)\$와 \$B(4, 6)\$ 사이의 거리를 구해보세요. 먼저 공식에 대입하기 위해 각 좌표의 차를 구합니다. \$x\$좌표의 차는 \$4 - 1 = 3\$이고, \$y\$좌표의 차는 \$6 - 2 = 4\$입니다. 이제 이 값들을 공식에 대입합니다. \$\$d = \\sqrt{(4 - 1)^2 + (6 - 2)^2} = \\sqrt{3^2 + 4^2}\$\$',
              '위 식을 계산하면 \$d = \\sqrt{9 + 16} = \\sqrt{25}\$가 됩니다. 따라서 두 점 사이의 거리는 \$5\$입니다. 이처럼 두 점의 좌표만 알면 피타고라스의 정리를 활용해 누구나 쉽게 두 점 사이의 거리를 정확하게 계산할 수 있습니다.',
            ],
          ),
        ],
      ),
    ],
  ),
  '정수지수': BookData(
    id: 'concept_정수지수',
    title: '정수지수',
    subtitle: '대수 > 지수 > 지수의확장 > 정수지수',
    category: 'common',
    tags: ['대수', '지수', '지수의확장', '정수지수'],
    chapters: [
      BookChapter(
        title: '정수지수',
        intro: ['대수 > 지수 > 지수의확장 > 정수지수 개념 학습'],
        sections: [
          BookSection(
            title: '정수지수',
            paragraphs: [
              '지수법칙은 자연수 범위에서 정의된 개념을 정수 전체로 확장할 수 있습니다. 0이 아닌 실수 \$a\$에 대하여 \$a^0 = 1\$로 정의하고, 자연수 \$n\$에 대하여 \$a^{-n} = \\frac{1}{a^n}\$으로 정의합니다. 이러한 정의를 도입하면, 지수가 음수이거나 0인 경우에도 자연수에서 성립하던 지수법칙이 그대로 유지되어 계산의 편리함을 얻을 수 있습니다.',
              '정수지수에서 성립하는 지수법칙은 다음과 같습니다. \$a, b\$가 0이 아닌 실수이고 \$m, n\$이 정수일 때, 첫째로 \$a^m \\times a^n = a^{m+n}\$이 성립합니다. 둘째로 \$(a^m)^n = a^{mn}\$이며, 셋째로 \$(ab)^n = a^n b^n\$이 성립합니다. 또한 나눗셈에 대해서는 \$a^m \\div a^n = a^{m-n}\$이 성립하는데, 이는 지수가 음수일 때도 일관되게 적용됩니다.',
              '예를 들어, \$2^{-3}\$은 정의에 따라 \$\\frac{1}{2^3} = \\frac{1}{8}\$이 됩니다. 또한 \$5^0 = 1\$과 같이 어떠한 0이 아닌 수의 0제곱은 항상 1이라는 성질은 매우 중요합니다. 이러한 정수지수의 확장은 복잡한 분수 형태의 식을 지수 형태의 곱셈으로 간단히 표현할 수 있게 해주어, 이후 배우게 될 로그나 함수 단원의 기초가 됩니다.',
              '이제 예제 문제를 풀어봅시다. 문제: \'\$2^5 \\div 2^7\$을 계산하고, 그 결과를 정수지수 형태로 나타내시오.\' 이 문제는 지수법칙 \$a^m \\div a^n = a^{m-n}\$을 활용하여 해결할 수 있습니다. 밑이 2로 같으므로 지수끼리 빼주면 됩니다.',
              '단계별 풀이는 다음과 같습니다. 먼저 지수법칙을 적용하면 \$2^5 \\div 2^7 = 2^{5-7}\$이 됩니다. 이를 계산하면 \$2^{-2}\$가 됩니다. 정의에 따라 \$2^{-2} = \\frac{1}{2^2} = \\frac{1}{4}\$이므로, 최종적인 답은 \$2^{-2}\$ 또는 \$\\frac{1}{4}\$입니다.',
              '또 다른 예제로 \$(3^2)^{-1} \\times 3^4\$를 계산해 봅시다. 먼저 괄호 안의 지수법칙 \$(a^m)^n = a^{mn}\$을 적용하면 \$(3^2)^{-1} = 3^{2 \\times (-1)} = 3^{-2}\$가 됩니다. 이제 \$3^{-2} \\times 3^4\$를 계산하면 지수법칙 \$a^m \\times a^n = a^{m+n}\$에 의해 \$3^{-2+4} = 3^2 = 9\$가 됨을 알 수 있습니다.',
            ],
          ),
        ],
      ),
    ],
  ),
  '최솟값(이차함수)': BookData(
    id: 'concept_최솟값(이차함수)',
    title: '최솟값(이차함수)',
    subtitle: '공통수학1 > 이차함수 > 이차함수의최대최소 > 최솟값(이차함수)',
    category: 'common',
    tags: ['공통수학1', '이차함수', '이차함수의최대최소', '최솟값(이차함수)'],
    chapters: [
      BookChapter(
        title: '최솟값(이차함수)',
        intro: ['공통수학1 > 이차함수 > 이차함수의최대최소 > 최솟값(이차함수) 개념 학습'],
        sections: [
          BookSection(
            title: '최솟값(이차함수)',
            paragraphs: [
              '이차함수의 최솟값은 그래프의 모양에 따라 결정됩니다. 이차함수 \$y = ax^2 + bx + c\$ (\$a \\neq 0\$)의 그래프는 포물선 모양인데, \$a > 0\$일 때 그래프는 아래로 볼록한 모양이 됩니다. 이때 그래프의 가장 낮은 지점인 꼭짓점에서 함숫값은 최솟값을 가지며, 반대로 \$a < 0\$일 때는 위로 볼록하여 최댓값만 존재하고 최솟값은 정할 수 없게 됩니다. 따라서 이차함수의 최솟값을 구하려면 먼저 그래프가 아래로 볼록한지 확인해야 합니다.',
              '이차함수의 최솟값을 구하기 위해서는 주어진 식을 완전제곱식 꼴인 \$\$y = a(x - p)^2 + q\$\$ 형태로 변형해야 합니다. 여기서 \$(p, q)\$는 포물선의 꼭짓점 좌표를 의미합니다. \$a > 0\$일 때, \$(x - p)^2\$은 항상 \$0\$ 이상의 값을 가지므로, \$x = p\$일 때 전체 식의 값은 가장 작은 값인 \$q\$가 됩니다. 즉, 이차함수 \$y = a(x - p)^2 + q\$ (\$a > 0\$)의 최솟값은 \$q\$이며, 이때의 \$x\$ 값은 \$p\$입니다.',
              '만약 정의역(x의 범위)이 제한되어 있다면 최솟값은 꼭짓점의 \$y\$ 좌표가 아닐 수도 있습니다. 하지만 정의역이 실수 전체라면, 아래로 볼록한 이차함수의 최솟값은 항상 꼭짓점의 \$y\$ 좌표와 일치합니다. 이 성질을 이용하면 복잡한 이차식이라도 꼭짓점만 찾아내면 최솟값을 쉽게 구할 수 있습니다. 이제 이 원리를 바탕으로 실제 문제를 풀어보며 익혀봅시다.',
              '예제: 이차함수 \$y = x^2 - 4x + 7\$의 최솟값을 구하시오. 먼저 이 식을 완전제곱식으로 변형해야 합니다. \$x\$항이 포함된 부분을 \$x^2 - 4x\$와 같이 묶은 뒤, \$x\$ 계수인 \$-4\$의 절반의 제곱인 \$4\$를 더하고 빼줍니다. 식을 정리하면 \$\$y = (x^2 - 4x + 4) - 4 + 7\$\$이 됩니다.',
              '이제 괄호 안을 인수분해하여 식을 완성합니다. \$\$y = (x - 2)^2 + 3\$\$ 이 식을 보면 \$a = 1 > 0\$이므로 아래로 볼록한 포물선임을 알 수 있습니다. \$(x - 2)^2\$은 \$x = 2\$일 때 \$0\$이 되어 가장 작아지므로, 전체 식의 최솟값은 \$3\$이 됩니다. 따라서 주어진 이차함수의 최솟값은 \$x = 2\$일 때 \$3\$입니다.',
            ],
          ),
        ],
      ),
    ],
  ),
  '항등식의성질': BookData(
    id: 'concept_항등식의성질',
    title: '항등식의성질',
    subtitle: '공통수학1 > 다항식 > 항등식 > 항등식의성질',
    category: 'common',
    tags: ['공통수학1', '다항식', '항등식', '항등식의성질'],
    chapters: [
      BookChapter(
        title: '항등식의성질',
        intro: ['공통수학1 > 다항식 > 항등식 > 항등식의성질 개념 학습'],
        sections: [
          BookSection(
            title: '항등식의성질',
            paragraphs: [
              '항등식이란 변수 \$x\$에 어떤 값을 대입하더라도 항상 성립하는 등식을 말합니다. 예를 들어 \$2(x+1) = 2x+2\$와 같은 식은 \$x\$에 1을 넣든 100을 넣든 좌변과 우변의 값이 항상 같으므로 항등식입니다. 반면, \$x+1=3\$처럼 특정 값(\$x=2\$)일 때만 성립하는 식은 \'방정식\'이라고 부릅니다. 항등식은 문제에서 \'모든 \$x\$에 대하여 성립한다\', \'임의의 \$x\$에 대하여 성립한다\', \'\$x\$의 값에 관계없이 항상 성립한다\'와 같은 표현으로 자주 등장합니다.',
              '다항식 \$ax^2 + bx + c = 0\$이 \$x\$에 대한 항등식이 되려면, 모든 \$x\$에 대하여 식이 성립해야 하므로 계수들이 모두 0이어야 합니다. 즉, \$\$a=0, \\; b=0, \\; c=0\$\$이 성립해야 합니다. 더 나아가 두 다항식 \$ax^2 + bx + c\$와 \$a\'x^2 + b\'x + c\'\$가 모든 \$x\$에 대하여 같으려면, 양변의 대응하는 항의 계수가 서로 같아야 합니다. 이를 \'계수비교법\'의 원리라고 하며 다음과 같이 정리할 수 있습니다. \$\$a=a\', \\; b=b\', \\; c=c\'\$\$',
              '항등식의 성질을 이용하는 방법에는 크게 두 가지가 있습니다. 첫째는 위에서 언급한 \'계수비교법\'으로, 양변의 동류항의 계수를 직접 비교하는 방식입니다. 둘째는 \'수치대입법\'으로, 항등식이 모든 \$x\$에 대해 성립한다는 점을 이용하여 적절한 \$x\$ 값을 대입해 미지수를 구하는 방식입니다. 문제의 형태에 따라 계수를 비교하는 것이 편할 때도 있고, 특정 값을 대입하여 식을 간단히 만드는 것이 빠를 때도 있으니 상황에 맞춰 선택하는 연습이 필요합니다.',
              '예제: 등식 \$ax(x-1) + b(x-1) + c = 2x^2 + 3x + 1\$이 모든 \$x\$에 대하여 성립할 때, 상수 \$a, b, c\$의 값을 구하시오. 이 문제는 수치대입법을 사용하면 매우 편리합니다. 식에 \$x=1\$을 대입하면 \$a(0) + b(0) + c = 2(1)^2 + 3(1) + 1\$이 되어, 좌변은 \$c\$만 남고 우변은 \$2+3+1=6\$이 됩니다. 따라서 \$\$c=6\$\$임을 바로 알 수 있습니다.',
              '이제 \$c=6\$을 대입한 후, 다른 \$x\$ 값을 대입하거나 계수를 비교합니다. 식은 \$ax^2 + (b-a)x - b + 6 = 2x^2 + 3x + 1\$이 됩니다. 여기서 \$x^2\$의 계수를 비교하면 \$a=2\$임을 알 수 있습니다. 이를 \$x\$의 계수 비교식인 \$b-a=3\$에 대입하면 \$b-2=3\$이 되어 \$\$b=5\$\$를 얻습니다. 최종적으로 구하는 값은 \$\$a=2, \\; b=5, \\; c=6\$\$입니다.',
            ],
          ),
        ],
      ),
    ],
  ),
