        title: '등비수열의합',
        intro: ['대수 > 수열 > 등비수열 > 등비수열의합 개념 학습'],
        sections: [
          BookSection(
            title: '등비수열의합',
            paragraphs: [
              '등비수열이란 첫째항부터 차례대로 일정한 수인 \'공비\'를 곱하여 만들어지는 수열을 말합니다. 이러한 등비수열의 첫째항부터 제\$n\$항까지의 합을 \$S_n\$이라고 할 때, 이를 구하는 공식은 공비 \$r\$의 값에 따라 달라집니다. 공비 \$r\$이 1이 아닐 때, 첫째항을 \$a\$, 공비를 \$r\$이라 하면 제\$n\$항까지의 합 \$S_n\$은 다음과 같은 공식으로 나타낼 수 있습니다.',
              '\$\$S_n = \\frac{a(r^n - 1)}{r - 1} \\quad (r \\neq 1)\$\$ 또는 분모와 분자에 -1을 곱하여 \$\$S_n = \\frac{a(1 - r^n)}{1 - r} \\quad (r \\neq 1)\$\$ 로도 쓸 수 있습니다. 만약 공비 \$r\$이 1이라면, 모든 항이 첫째항 \$a\$와 같으므로 합은 단순히 \$a\$를 \$n\$번 더한 값인 \$\$S_n = na\$\$가 됩니다. 이 공식들은 수열의 항이 많아질 때 일일이 더하지 않고도 빠르게 합을 구할 수 있게 해주는 매우 유용한 도구입니다.',
              '이제 구체적인 예제를 통해 등비수열의 합을 구하는 방법을 알아봅시다. 첫째항이 2이고 공비가 3인 등비수열의 제5항까지의 합을 구해보겠습니다. 먼저 주어진 조건에서 \$a=2, r=3, n=5\$임을 확인합니다. 공비가 1이 아니므로 위에서 배운 공식을 그대로 적용하면 됩니다.',
              '공식 \$\$S_n = \\frac{a(r^n - 1)}{r - 1}\$\$에 주어진 값들을 대입하면 다음과 같습니다. \$\$S_5 = \\frac{2(3^5 - 1)}{3 - 1}\$\$ 여기서 \$3^5\$은 \$3 \\times 3 \\times 3 \\times 3 \\times 3 = 243\$이므로, 식을 정리하면 \$\$S_5 = \\frac{2(243 - 1)}{2} = \\frac{2 \\times 242}{2}\$\$가 됩니다. 따라서 최종 결과는 \$\$S_5 = 242\$\$가 됩니다.',
              '또 다른 예제로, 첫째항이 8이고 공비가 \$\\frac{1}{2}\$인 등비수열의 제4항까지의 합을 구해봅시다. 여기서 \$a=8, r=\\frac{1}{2}, n=4\$입니다. 이번에는 공비가 1보다 작으므로 \$\$S_n = \\frac{a(1 - r^n)}{1 - r}\$\$ 공식을 사용하는 것이 계산하기에 더 편리합니다.',
              '공식에 값을 대입하면 \$\$S_4 = \\frac{8(1 - (\\frac{1}{2})^4)}{1 - \\frac{1}{2}}\$\$이 됩니다. 분모는 \$\\frac{1}{2}\$이 되고, 분자는 \$8(1 - \\frac{1}{16}) = 8(\\frac{15}{16}) = \\frac{15}{2}\$가 됩니다. 이를 계산하면 \$\$S_4 = \\frac{15/2}{1/2} = \\frac{15}{2} \\times 2 = 15\$\$가 되어, 제4항까지의 합은 15임을 알 수 있습니다.',
            ],
          ),
        ],
      ),
    ],
