  '명제의참거짓': BookData(
    id: 'concept_명제의참거짓',
    title: '명제의참거짓',
    subtitle: '공통수학2 > 명제 > 명제의참거짓',
    category: 'common',
    tags: ['공통수학2', '명제', '명제의참거짓'],
    chapters: [
      BookChapter(
        title: '명제의참거짓',
        intro: ['공통수학2 > 명제 > 명제의참거짓 개념 학습'],
        sections: [
          BookSection(
            title: '명제의참거짓',
            paragraphs: [
              '명제란 문장이나 식 중에서 그 참과 거짓을 명확하게 판별할 수 있는 것을 말합니다. 예를 들어 \'3은 5보다 작다\'는 참인 명제이고, \'서울은 대한민국의 수도이다\' 역시 참인 명제입니다. 하지만 \'수학은 재미있다\'와 같이 사람마다 생각이 달라 참과 거짓을 객관적으로 정할 수 없는 문장은 명제가 아닙니다. 명제는 보통 소문자 \$p, q, r\$ 등으로 나타내며, 참인 명제는 기호로 \$T\$(True), 거짓인 명제는 \$F\$(False)로 구분합니다.',
              '명제의 참과 거짓을 판별할 때 가장 중요한 것은 조건이 포함된 명제입니다. 변수 \$x\$의 값에 따라 참이 되기도 하고 거짓이 되기도 하는 문장을 \'조건\'이라고 합니다. 조건 \$p(x)\$가 참이 되게 하는 모든 \$x\$의 값의 집합을 그 조건의 \'진리집합\'이라고 하며, 보통 대문자 \$P\$로 나타냅니다. 전체집합 \$U\$의 원소 중 진리집합 \$P\$에 속하는 원소는 명제를 참으로 만들고, 그렇지 않은 원소는 명제를 거짓으로 만듭니다.',
              '명제 \$p\$에 대하여 \'p가 아니다\'를 부정이라 하며, 기호로 \$\\sim p\$라고 씁니다. 명제 \$p\$가 참이면 부정 \$\\sim p\$는 거짓이고, 명제 \$p\$가 거짓이면 부정 \$\\sim p\$는 참이 됩니다. 또한, 두 조건 \$p, q\$에 대하여 \'\$p\$이면 \$q\$이다\' 꼴의 명제는 \$p \\implies q\$로 나타냅니다. 이때 진리집합 \$P\$가 \$Q\$의 부분집합(\$P \\subset Q\$)이면 명제 \$p \\implies q\$는 참이 되고, 그렇지 않으면 거짓이 됩니다.',
              '예제 1: 다음 명제의 참과 거짓을 판별하고, 그 이유를 설명하세요. [명제: \'모든 실수 \$x\$에 대하여 \$x^2 > 0\$이다.\'] 풀이: 이 명제는 거짓입니다. 왜냐하면 \$x=0\$일 때 \$x^2 = 0\$이 되어 \$0 > 0\$이라는 부등식이 성립하지 않기 때문입니다. 즉, \$x=0\$이라는 반례(counterexample)가 존재하므로 주어진 명제는 거짓입니다.',
              '예제 2: 전체집합 \$U = \\{1, 2, 3, 4, 5, 6\\}\$에 대하여, 조건 \$p: \'x\$는 12의 약수이다\'의 진리집합을 구하고 명제의 참을 판별하세요. 풀이: 먼저 12의 약수를 구하면 \$1, 2, 3, 4, 6, 12\$입니다. 전체집합 \$U\$의 원소 중에서 이 조건에 해당하는 원소를 찾으면 진리집합 \$P = \\{1, 2, 3, 4, 6\\}\$이 됩니다. 따라서 \$U\$의 모든 원소가 \$P\$에 포함되지는 않으므로(예를 들어 \$5 \\notin P\$), \'모든 \$x \\in U\$에 대하여 \$p\$이다\'라는 명제는 거짓입니다.',
              '예제 3: 두 조건 \$p: x < 3\$, \$q: x < 5\$에 대하여 명제 \$p \\implies q\$의 참과 거짓을 판별하세요. 풀이: 조건 \$p\$의 진리집합을 \$P\$, 조건 \$q\$의 진리집합을 \$Q\$라고 하면 \$P = \\{x \\mid x < 3\\}\$, \$Q = \\{x \\mid x < 5\\}\$입니다. 수직선 위에서 \$P\$의 모든 원소는 \$Q\$의 범위 안에 포함되므로 \$P \\subset Q\$가 성립합니다. 따라서 명제 \$p \\implies q\$는 참입니다.',
            ],
          ),
        ],
      ),
    ],
