  '내분점공식': BookData(
    id: 'concept_내분점공식',
    title: '내분점공식',
    subtitle: '공통수학2 > 좌표평면 > 선분의내분점 > 내분점공식',
    category: 'common',
    tags: ['공통수학2', '좌표평면', '선분의내분점', '내분점공식'],
    chapters: [
      BookChapter(
        title: '내분점공식',
        intro: ['공통수학2 > 좌표평면 > 선분의내분점 > 내분점공식 개념 학습'],
        sections: [
          BookSection(
            title: '내분점공식',
            paragraphs: [
              '수직선 위에서 두 점 \$A(x_1)\$과 \$B(x_2)\$를 잇는 선분 \$AB\$를 \$m:n\$의 비율로 나누는 점 \$P(x)\$를 \'내분점\'이라고 합니다. 여기서 내분이란 선분 안쪽에서 점이 나누어진다는 뜻입니다. 점 \$P\$가 선분 \$AB\$를 \$m:n\$으로 내분한다는 것은 \$AP:PB = m:n\$임을 의미하며, 이를 만족하는 점 \$P\$의 좌표 \$x\$를 구하는 공식은 다음과 같습니다.',
              '내분점의 좌표 \$x\$를 구하는 공식은 두 점의 좌표에 비례 배분을 적용한 결과입니다. 공식은 \$\$x = \\frac{mx_2 + nx_1}{m+n}\$\$과 같습니다. 이 공식은 좌표평면으로 확장해도 동일하게 적용됩니다. 두 점 \$A(x_1, y_1)\$과 \$B(x_2, y_2)\$를 \$m:n\$으로 내분하는 점 \$P(x, y)\$의 좌표는 \$x\$좌표와 \$y\$좌표를 각각 따로 계산하여 \$\$P\\left( \\frac{mx_2 + nx_1}{m+n}, \\frac{my_2 + ny_1}{m+n} \\right)\$\$와 같이 나타낼 수 있습니다.',
              '공식을 외울 때는 분모에는 비의 합인 \$m+n\$을 쓰고, 분자에는 비와 좌표를 서로 엇갈려 곱한 뒤 더한다는 점을 기억하면 쉽습니다. 특히 \$m=n=1\$인 경우, 즉 \$1:1\$로 내분하는 점은 선분의 중점이 되며, 이때의 좌표는 두 좌표의 평균인 \$M\\left( \\frac{x_1+x_2}{2}, \\frac{y_1+y_2}{2} \\right)\$가 됩니다. 이 성질은 기하학적 문제를 해결할 때 매우 유용하게 사용됩니다.',
              '예제 문제를 통해 공식을 적용해 봅시다. 두 점 \$A(1, 2)\$와 \$B(7, 8)\$을 \$2:1\$로 내분하는 점 \$P\$의 좌표를 구해보겠습니다. 먼저 \$x\$좌표를 구하면, 공식에 따라 \$x = \\frac{2 \\times 7 + 1 \\times 1}{2+1}\$이 됩니다. 이를 계산하면 \$x = \\frac{14+1}{3} = \\frac{15}{3} = 5\$가 나옵니다.',
              '다음으로 \$y\$좌표를 구합니다. 같은 방식으로 \$y = \\frac{2 \\times 8 + 1 \\times 2}{2+1}\$을 계산합니다. 분자를 정리하면 \$y = \\frac{16+2}{3} = \\frac{18}{3} = 6\$이 됩니다. 따라서 두 점 \$A\$와 \$B\$를 \$2:1\$로 내분하는 점 \$P\$의 좌표는 \$(5, 6)\$입니다. 이처럼 내분점 공식은 복잡한 좌표 문제도 간단한 산수 과정으로 해결할 수 있게 해줍니다.',
            ],
          ),
        ],
      ),
    ],
  ),
  '유리수지수': BookData(
    id: 'concept_유리수지수',
    title: '유리수지수',
    subtitle: '대수 > 지수 > 지수의확장 > 유리수지수',
    category: 'common',
    tags: ['대수', '지수', '지수의확장', '유리수지수'],
    chapters: [
      BookChapter(
        title: '유리수지수',
        intro: ['대수 > 지수 > 지수의확장 > 유리수지수 개념 학습'],
        sections: [
          BookSection(
            title: '유리수지수',
            paragraphs: [
              '지수의 확장이란 자연수 범위에서 정의되었던 지수 법칙을 정수, 유리수, 나아가 실수 범위까지 넓히는 과정을 말합니다. 먼저 유리수 지수는 거듭제곱근의 개념을 사용하여 정의합니다. \$n\$이 2 이상의 자연수이고 \$a > 0\$일 때, \$n\$제곱하여 \$a\$가 되는 수 중 양수인 것을 \$\\sqrt[n]{a}\$라고 하며, 이를 지수 형태로 나타내면 \$a^{\\frac{1}{n}}\$이 됩니다. 즉, \$\\sqrt[n]{a} = a^{\\frac{1}{n}}\$이라는 약속을 통해 지수에 분수가 등장할 수 있게 됩니다.',
              '더 나아가 분자가 1이 아닌 유리수 지수는 \$a^{\\frac{m}{n}} = \\sqrt[n]{a^m} = (\\sqrt[n]{a})^m\$으로 정의합니다. 여기서 \$m\$은 정수이고 \$n\$은 2 이상의 자연수입니다. 이 정의를 사용하면 자연수 범위에서 성립하던 지수 법칙인 \$a^p \\times a^q = a^{p+q}\$, \$(a^p)^q = a^{pq}\$, \$(ab)^p = a^p b^p\$ 등이 지수가 유리수인 경우에도 그대로 성립하게 됩니다. 단, 밑 \$a\$가 0보다 커야 한다는 조건은 유리수 지수에서 매우 중요합니다.',
              '유리수 지수를 활용하면 복잡한 거듭제곱근의 계산을 훨씬 간편하게 수행할 수 있습니다. 예를 들어, 서로 다른 거듭제곱근이 곱해져 있는 식을 계산할 때, 모든 항을 유리수 지수로 바꾸어 지수법칙을 적용하면 밑이 같은 수들의 지수끼리 더하거나 빼는 것만으로 간단히 정리할 수 있습니다. 이는 수학적 계산의 효율성을 높여줄 뿐만 아니라, 이후 배우게 될 로그나 지수함수를 이해하는 데 필수적인 기초가 됩니다.',
              '예제: 다음 식을 간단히 하시오. \$\$\\sqrt[3]{2} \\times \\sqrt[6]{2^4}\$\$ 단계별 풀이: 첫째, 각 거듭제곱근을 유리수 지수로 변환합니다. \$\\sqrt[3]{2} = 2^{\\frac{1}{3}}\$이고, \$\\sqrt[6]{2^4} = 2^{\\frac{4}{6}}\$입니다. 여기서 지수 \$\\frac{4}{6}\$은 약분하여 \$\\frac{2}{3}\$로 나타낼 수 있습니다. 따라서 식은 \$2^{\\frac{1}{3}} \\times 2^{\\frac{2}{3}}\$이 됩니다.',
              '둘째, 지수법칙 \$a^p \\times a^q = a^{p+q}\$를 적용합니다. 밑이 2로 같으므로 지수끼리 더하면 \$2^{\\frac{1}{3} + \\frac{2}{3}} = 2^{\\frac{3}{3}}\$이 됩니다. 마지막으로 지수를 계산하면 \$2^1 = 2\$라는 결과를 얻습니다. 이처럼 유리수 지수를 이용하면 복잡해 보이는 거듭제곱근의 곱셈도 지수의 덧셈만으로 쉽게 해결할 수 있습니다.',
            ],
          ),
        ],
      ),
    ],
  ),
  '정의역에서의최대최소': BookData(
