              '이차함수의 최대와 최소는 함수의 그래프가 아래로 볼록한지, 위로 볼록한지에 따라 결정됩니다. 정의역이 실수 전체일 때는 꼭짓점에서 최댓값 또는 최솟값을 갖지만, 정의역이 특정 구간 \$[p, q]\$로 제한되면 상황이 달라집니다. 이때는 주어진 구간 내에서 그래프의 가장 높은 점과 가장 낮은 점을 찾아야 합니다.',
              '정의역이 제한된 이차함수 \$f(x) = a(x-m)^2 + n\$의 최댓값과 최솟값을 구하는 방법은 다음과 같습니다. 먼저 꼭짓점의 \$x\$좌표인 \$m\$이 주어진 구간 \$[p, q]\$에 포함되는지 확인합니다. 만약 \$m\$이 구간 안에 있다면, 꼭짓점에서의 함숫값 \$f(m)\$과 구간의 양 끝점에서의 함숫값 \$f(p), f(q)\$를 모두 비교하여 가장 큰 값이 최댓값, 가장 작은 값이 최솟값이 됩니다.',
