              '예제: 이차함수 \$f(x) = x^2 - 4x + 5\$의 정의역이 \$0 \\le x \\le 3\$일 때, 이 함수의 최댓값과 최솟값을 구하시오. 먼저 함수식을 표준형으로 바꾸면 \$f(x) = (x-2)^2 + 1\$이 됩니다. 여기서 꼭짓점의 좌표는 \$(2, 1)\$이고, \$x=2\$는 주어진 구간 \$[0, 3]\$ 안에 포함됩니다.',
