  '증가함수': BookData(
    id: 'concept_증가함수',
    title: '증가함수',
    subtitle: '미적분Ⅰ > 함수의증가와감소 > 증가함수',
    category: 'common',
    tags: ['미적분Ⅰ', '함수의증가와감소', '증가함수'],
    chapters: [
      BookChapter(
        title: '증가함수',
        intro: ['미적분Ⅰ > 함수의증가와감소 > 증가함수 개념 학습'],
        sections: [
          BookSection(
            title: '증가함수',
            paragraphs: [
              '[   "함수 \$f(x)\$가 어떤 구간에 속하는 임의의 두 실수 \$x_1, x_2\$에 대하여 \$x_1 < x_2\$일 때, 항상 \$f(x_1) < f(x_2)\$가 성립하면 이 함수를 그 구간에서 \'증가함수\'라고 합니다. 쉽게 말해, 그래프를 왼쪽에서 오른쪽으로 따라갈 때 함수의 높이(함숫값)가 점점 높아지는 상태를 의미합니다. 직관적으로는 그래프가 오른쪽 위를 향해 뻗어 나가는 모양을 상상하면 이해하기 쉽습니다.",   "미분 가능한 함수 \$f(x)\$가 어떤 구간에서 증가함수인지 판별하려면 도함수 \$f\'(x)\$를 이용합니다. 만약 어떤 구간의 모든 \$x\$에 대하여 \$f\'(x) > 0\$이면, 함수 \$f(x)\$는 그 구간에서 증가합니다. 다만, \$f\'(x) = 0\$인 점이 있더라도 그 점이 연속적으로 이어지지 않고 드문드문 존재한다면 함수 전체는 여전히 증가하는 상태로 봅니다. 따라서 일반적으로 함수 \$f(x)\$가 구간에서 증가하기 위한 필요충분조건은 다음과 같습니다. \$\$f\'(x) \\\\ge 0\$\$",   "증가함수의 핵심 성질은 함숫값의 대소 관계가 정의역의 대소 관계와 일치한다는 점입니다. 즉, \$x\$값이 커질수록 \$y\$값도 커지거나 일정하게 유지됩니다. 만약 구간 내의 모든 점에서 \$f\'(x) > 0\$이라면 함수는 엄격하게 증가하며, \$f\'(x) \\ge 0\$이면서 특정 구간에서 \$f\'(x) = 0\$이 된다면 그 구간에서는 그래프가 잠시 평평해졌다가 다시 올라가는 형태가 됩니다.",   "예제: 함수 \$f(x) = x^3 - 3x + 5\$가 증가하는 구간을 구하시오. 먼저 함수가 증가하기 위한 조건인 \$f\'(x) \\\\ge 0\$을 만족하는 범위를 찾아야 합니다. 주어진 함수를 \$x\$에 대하여 미분하면 다음과 같습니다. \$\$f\'(x) = 3x^2 - 3\$\$",   "이제 부등식 \$3x^2 - 3 \\\\ge 0\$을 풀어봅시다. 양변을 3으로 나누면 \$x^2 - 1 \\\\ge 0\$이 되고, 이를 인수분해하면 \$(x+1)(x-1) \\\\ge 0\$이 됩니다. 이차부등식의 성질에 따라 이 식을 만족하는 \$x\$의 범위는 다음과 같습니다. \$\$x \\\\le -1 \\\\quad \\\\text{또는} \\\\quad x \\\\ge 1\$\$",   "따라서 함수 \$f(x) = x^3 - 3x + 5\$는 구간 \$(-\\\\infty, -1]\$과 \$[1, \\\\infty)\$에서 증가합니다. 이처럼 도함수의 부호를 조사하면 함수의 증가와 감소 상태를 명확하게 파악할 수 있습니다. 그래프를 그려보면 \$x=-1\$과 \$x=1\$을 기준으로 함수의 방향이 바뀌는 것을 확인할 수 있으며, 이는 미분을 통해 함수의 개형을 추론하는 가장 기본적인 과정입니다." ]',
            ],
          ),
