  '역': BookData(
    id: 'concept_역',
    title: '역',
    subtitle: '공통수학2 > 명제 > 명제의역과대우 > 역',
    category: 'common',
    tags: ['공통수학2', '명제', '명제의역과대우', '역'],
    chapters: [
      BookChapter(
        title: '역',
        intro: ['공통수학2 > 명제 > 명제의역과대우 > 역 개념 학습'],
        sections: [
          BookSection(
            title: '역',
            paragraphs: [
              '명제란 참과 거짓을 명확하게 판별할 수 있는 문장이나 식을 말합니다. 일반적으로 명제는 \'가정\'과 \'결론\'으로 이루어져 있으며, 이를 기호로 나타내면 \'\$p \\rightarrow q\$\'와 같이 표현합니다. 여기서 \'\$p\$\'는 가정, \'\$q\$\'는 결론을 의미합니다. 명제의 \'역\'이란, 원래 명제의 가정과 결론의 위치를 서로 바꾸어 놓은 새로운 명제를 말합니다. 즉, 명제 \'\$p \\rightarrow q\$\'의 역은 \'\$q \\rightarrow p\$\'가 됩니다.',
              '역을 만드는 방법은 매우 간단합니다. 원래 명제에서 \'~이면\' 뒤에 오는 결론 부분을 가정으로 옮기고, 처음에 있던 가정 부분을 결론으로 옮기면 됩니다. 예를 들어 \'x가 2이면 x^2은 4이다\'라는 명제가 있다면, 그 역은 \'x^2이 4이면 x는 2이다\'가 됩니다. 주의할 점은 원래 명제가 참이라고 해서 그 역도 반드시 참인 것은 아니라는 사실입니다. 역은 원래 명제와는 독립적인 새로운 명제이므로, 참과 거짓을 별도로 판별해야 합니다.',
              '역의 성질을 이해할 때 가장 중요한 것은 \'논리적 관계\'입니다. 명제 \'\$p \\rightarrow q\$\'가 참이라고 해서 그 역인 \'\$q \\rightarrow p\$\'가 항상 참이 되는 것은 아닙니다. 예를 들어 \'사람이면 동물이다\'는 참이지만, 그 역인 \'동물이면 사람이다\'는 거짓입니다. 따라서 어떤 명제의 역을 구할 때는 단순히 위치만 바꾸는 것에 그치지 않고, 바뀐 문장이 논리적으로 성립하는지 반드시 검토하는 습관을 길러야 합니다.',
              '예제 문제를 통해 역을 구하는 과정을 살펴봅시다. 명제 \'x가 6의 배수이면 x는 3의 배수이다\'의 역을 구하고 참, 거짓을 판별해 보세요. 먼저, 이 명제의 가정은 \'x가 6의 배수이다\'이고, 결론은 \'x는 3의 배수이다\'입니다. 역은 가정과 결론의 위치를 바꾸어 \'\$q \\rightarrow p\$\'의 형태로 만듭니다. 따라서 역은 \'x가 3의 배수이면 x는 6의 배수이다\'가 됩니다.',
              '이제 구한 역의 참과 거짓을 판별해 봅시다. 역인 \'x가 3의 배수이면 x는 6의 배수이다\'에서, x가 3인 경우를 생각해 봅시다. 3은 3의 배수이지만 6의 배수는 아닙니다. 이처럼 가정은 만족하지만 결론을 만족하지 않는 경우를 \'반례\'라고 합니다. 반례가 하나라도 존재하므로, 이 명제의 역은 \'거짓\'이 됩니다. 이와 같이 역을 구할 때는 반례를 찾아보는 과정이 매우 중요합니다.',
            ],
          ),
        ],
      ),
    ],
  ),
  '등비중항': BookData(
