        title: '등비중항',
        intro: ['대수 > 수열 > 등비수열 > 등비중항 개념 학습'],
        sections: [
          BookSection(
            title: '등비중항',
            paragraphs: [
              '등비수열에서 연속하는 세 항 \$a, b, c\$가 이 순서대로 등비수열을 이룰 때, 가운데 있는 항 \$b\$를 \$a\$와 \$c\$의 \'등비중항\'이라고 합니다. 등비수열의 정의에 따라 두 번째 항을 첫 번째 항으로 나눈 비와 세 번째 항을 두 번째 항으로 나눈 비는 서로 같아야 하므로, \$\\frac{b}{a} = \\frac{c}{b}\$라는 관계식이 성립합니다.',
              '위의 식을 정리하면 \$b^2 = ac\$라는 중요한 공식이 유도됩니다. 즉, 세 수 \$a, b, c\$가 등비수열을 이룰 때, 가운데 항의 제곱은 양옆의 두 항을 곱한 것과 같습니다. 이를 통해 \$b = \\pm\\sqrt{ac}\$임을 알 수 있으며, 이때 \$\\sqrt{ac}\$를 \$a\$와 \$c\$의 양의 등비중항, \$-\\sqrt{ac}\$를 음의 등비중항이라고 부릅니다.',
              '등비중항은 단순히 세 수 사이의 관계를 넘어, 수열의 규칙성을 파악하는 데 매우 유용합니다. 만약 어떤 수열의 연속된 세 항이 등비수열을 이룬다는 사실을 알면, 등비중항 공식을 사용하여 미지수를 빠르게 구할 수 있습니다. 이는 복잡한 계산 과정을 줄여주며, 등비수열의 성질을 이해하는 핵심적인 도구가 됩니다.',
              '예제: 세 수 \$4, x, 16\$이 이 순서대로 등비수열을 이룰 때, 양수 \$x\$의 값을 구하시오. 풀이 단계는 다음과 같습니다. 첫째, 등비중항의 정의에 따라 가운데 항의 제곱은 양옆의 두 항의 곱과 같으므로 \$x^2 = 4 \\times 16\$이 성립합니다.',
              '둘째, 우변을 계산하면 \$x^2 = 64\$가 됩니다. 셋째, 제곱하여 \$64\$가 되는 수는 \$8\$과 \$-8\$입니다. 문제에서 \$x\$가 양수라는 조건이 주어졌으므로, 최종적으로 구하는 값은 \$x = 8\$입니다. 이처럼 등비중항 공식을 활용하면 미지수 \$x\$를 간단히 찾을 수 있습니다.',
