  '미정계수법': BookData(
    id: 'concept_미정계수법',
    title: '미정계수법',
    subtitle: '공통수학1 > 다항식 > 항등식 > 미정계수법',
    category: 'common',
    tags: ['공통수학1', '다항식', '항등식', '미정계수법'],
    chapters: [
      BookChapter(
        title: '미정계수법',
        intro: ['공통수학1 > 다항식 > 항등식 > 미정계수법 개념 학습'],
        sections: [
          BookSection(
            title: '미정계수법',
            paragraphs: [
              '미정계수법이란 다항식의 항등식에서 아직 정해지지 않은 계수를 구하는 방법을 말합니다. 항등식이란 변수 \$x\$에 어떤 값을 대입해도 항상 성립하는 등식을 의미하는데, 이때 양변의 대응하는 항의 계수가 서로 같다는 성질을 이용합니다. 즉, \$ax^2 + bx + c = a\'x^2 + b\'x + c\'\$가 \$x\$에 대한 항등식이 되려면 \$a=a\'\$, \$b=b\'\$, \$c=c\'\$가 만족되어야 한다는 원리입니다.',
              '미정계수법은 크게 \'계수비교법\'과 \'수치대입법\' 두 가지로 나뉩니다. 계수비교법은 양변의 다항식을 전개하여 내림차순으로 정리한 뒤, 같은 차수의 항끼리 계수를 비교하여 미지수를 구하는 방식입니다. 반면, 수치대입법은 항등식의 성질을 이용하여 \$x\$에 적절한 값을 대입함으로써 미지수를 구하는 방식입니다. 보통 식을 전개하기 복잡할 때는 수치대입법이, 식의 구조가 단순할 때는 계수비교법이 효율적입니다.',
              '예를 들어, 등식 \$ax(x-1) + b(x-1) + c = 2x^2 - 3x + 1\$이 모든 \$x\$에 대하여 성립할 때, 계수 \$a, b, c\$를 구해보겠습니다. 먼저 계수비교법을 사용하면, 좌변을 전개하여 \$ax^2 + (b-a)x + (c-b) = 2x^2 - 3x + 1\$로 만듭니다. 이제 각 항의 계수를 비교하면 \$a=2\$, \$b-a=-3\$, \$c-b=1\$이라는 연립방정식을 얻을 수 있습니다.',
              '위의 연립방정식을 단계별로 풀어봅시다. 첫째, \$x^2\$의 계수를 비교하면 즉시 \$a=2\$임을 알 수 있습니다. 둘째, \$x\$의 계수를 비교한 식 \$b-a=-3\$에 \$a=2\$를 대입하면 \$b-2=-3\$이 되어 \$b=-1\$이 됩니다. 셋째, 상수항을 비교한 식 \$c-b=1\$에 \$b=-1\$을 대입하면 \$c-(-1)=1\$이 되어 \$c=0\$이 나옵니다. 따라서 구하는 계수는 \$a=2, b=-1, c=0\$입니다.',
              '이번에는 수치대입법을 활용한 예제를 살펴봅시다. \$x^2 + 3x + 2 = a(x-1)(x-2) + b(x-2) + c\$가 항등식일 때 \$a, b, c\$를 구하는 문제입니다. 이 식은 \$x=1, x=2\$를 대입하면 계산이 매우 간편해집니다. 먼저 \$x=1\$을 대입하면 \$1+3+2 = a(0) + b(-1) + c\$가 되어 \$-b+c=6\$을 얻습니다. 다음으로 \$x=2\$를 대입하면 \$4+6+2 = a(0) + b(0) + c\$가 되어 \$c=12\$를 바로 구할 수 있습니다.',
              '마지막으로 \$c=12\$를 \$-b+c=6\$에 대입하면 \$-b+12=6\$이 되어 \$b=6\$이 됩니다. 마지막으로 \$a\$를 구하기 위해 \$x=0\$을 대입하면 \$2 = a(-1)(-2) + b(-2) + c\$가 되고, 여기에 \$b=6, c=12\$를 대입하면 \$2 = 2a - 12 + 12\$가 되어 \$2a=2\$, 즉 \$a=1\$임을 알 수 있습니다. 이처럼 미정계수법은 문제의 형태에 따라 적절한 방법을 선택하면 복잡한 식도 쉽게 해결할 수 있습니다.',
            ],
          ),
        ],
      ),
    ],
  ),
  '외분점': BookData(
    id: 'concept_외분점',
    title: '외분점',
    subtitle: '공통수학2 > 좌표평면 > 선분의내분점 > 외분점',
    category: 'common',
    tags: ['공통수학2', '좌표평면', '선분의내분점', '외분점'],
    chapters: [
      BookChapter(
        title: '외분점',
        intro: ['공통수학2 > 좌표평면 > 선분의내분점 > 외분점 개념 학습'],
        sections: [
          BookSection(
            title: '외분점',
            paragraphs: [
              '좌표평면 위의 두 점 \$A(x_1, y_1)\$과 \$B(x_2, y_2)\$를 잇는 선분 \$AB\$가 있을 때, 선분 \$AB\$의 연장선 위에 있으면서 \$AP : BP = m : n\$ (\$m \\neq n\$)을 만족하는 점 \$P\$를 선분 \$AB\$의 외분점이라고 합니다. 내분점이 선분 안쪽에서 비율을 나누는 점이라면, 외분점은 선분 밖에서 그 비율을 유지하며 위치하는 점입니다. 이때 \$m > n\$이면 점 \$P\$는 점 \$B\$의 바깥쪽에, \$m < n\$이면 점 \$A\$의 바깥쪽에 위치하게 됩니다.',
              '외분점 \$P\$의 좌표를 구하는 공식은 내분점 공식에서 비율 중 하나를 음수로 바꾸어 생각하면 쉽게 유도할 수 있습니다. 두 점 \$A(x_1, y_1)\$과 \$B(x_2, y_2)\$를 \$m : n\$으로 외분하는 점 \$P(x, y)\$의 좌표는 다음과 같습니다. \$\$P = \\left( \\frac{mx_2 - nx_1}{m - n}, \\frac{my_2 - ny_1}{m - n} \\right)\$\$ 이 공식은 \$m\$과 \$n\$이 다를 때만 성립하며, 분모와 분자에 각각 외분하는 비율의 차와 곱의 차를 적용하는 것이 핵심입니다.',
              '외분점의 성질을 이해할 때 가장 중요한 것은 \'거리의 비\'입니다. 점 \$P\$가 선분 \$AB\$를 \$m : n\$으로 외분한다는 것은 점 \$P\$로부터 점 \$A\$까지의 거리와 점 \$P\$로부터 점 \$B\$까지의 거리의 비가 \$m : n\$임을 의미합니다. 만약 \$m=n\$이라면 두 점 사이의 거리가 같아지므로 외분점은 존재하지 않게 되며, 이는 공식의 분모인 \$m-n\$이 \$0\$이 되어 정의할 수 없는 상황과 일치합니다.',
              '예제: 두 점 \$A(1, 2)\$와 \$B(4, 8)\$에 대하여 선분 \$AB\$를 \$2 : 1\$로 외분하는 점 \$P\$의 좌표를 구해보겠습니다. 먼저 공식에 주어진 값들을 대입합니다. 여기서 \$x_1=1, y_1=2, x_2=4, y_2=8, m=2, n=1\$입니다. 외분점 공식에 따라 \$x\$좌표와 \$y\$좌표를 각각 계산합니다.',
              '단계별 풀이: 먼저 \$x\$좌표를 구하면 \$x = \\frac{2 \\times 4 - 1 \\times 1}{2 - 1} = \\frac{8 - 1}{1} = 7\$입니다. 이어서 \$y\$좌표를 구하면 \$y = \\frac{2 \\times 8 - 1 \\times 2}{2 - 1} = \\frac{16 - 2}{1} = 14\$가 됩니다. 따라서 구하는 외분점 \$P\$의 좌표는 \$(7, 14)\$입니다. 이처럼 외분점 공식은 복잡해 보이지만, 각 좌표에 대해 비례 배분과 유사한 연산을 수행하면 누구나 정확하게 좌표를 찾아낼 수 있습니다.',
            ],
          ),
        ],
      ),
    ],
  ),
  '감소함수': BookData(
    id: 'concept_감소함수',
    title: '감소함수',
    subtitle: '미적분Ⅰ > 함수의증가와감소 > 감소함수',
    category: 'common',
    tags: ['미적분Ⅰ', '함수의증가와감소', '감소함수'],
    chapters: [
      BookChapter(
        title: '감소함수',
        intro: ['미적분Ⅰ > 함수의증가와감소 > 감소함수 개념 학습'],
        sections: [
          BookSection(
            title: '감소함수',
            paragraphs: [
              '[   "함수의 증가와 감소는 그래프의 모양을 결정하는 매우 중요한 요소입니다. 어떤 구간에 속하는 임의의 두 실수 \$x_1, x_2\$에 대하여 \$x_1 < x_2\$일 때, 함숫값의 대소 관계가 \$f(x_1) > f(x_2)\$를 만족하면 함수 \$f(x)\$는 그 구간에서 \'감소한다\'고 합니다. 즉, \$x\$의 값이 커질수록 대응하는 \$y\$의 값은 점점 작아지는 상태를 의미하며, 그래프를 왼쪽에서 오른쪽으로 따라갔을 때 아래로 내려가는 모양을 띠게 됩니다.",   "미분가능한 함수 \$f(x)\$에 대하여, 어떤 구간에서 \$f\'(x) < 0\$이면 함수 \$f(x)\$는 그 구간에서 감소합니다. 또한, 구간 내의 모든 \$x\$에 대하여 \$f\'(x) \\leq 0\$이더라도 함수가 특정 지점에서 잠시 멈출 뿐 전체적으로 감소하는 경향을 보인다면 이를 감소함수로 정의합니다. 이를 수식으로 정리하면, 구간 내의 모든 \$x\$에 대하여 \$\$f\'(x) \\leq 0\$\$일 때, 함수 \$f(x)\$는 해당 구간에서 감소한다고 말할 수 있습니다.",   "감소함수의 성질을 이해할 때 주의할 점은 도함수의 부호입니다. 도함수 \$f\'(x)\$는 그래프의 접선의 기울기를 의미하므로, 접선의 기울기가 음수라는 것은 그래프가 오른쪽 아래로 향하고 있음을 나타냅니다. 따라서 함수가 감소하는 구간을 찾으려면 먼저 주어진 함수를 미분하여 도함수를 구한 뒤, 그 도함수가 0보다 작거나 같은 범위를 찾아내면 됩니다.",   "예제: 함수 \$f(x) = -x^3 + 3x^2 + 9x + 5\$가 감소하는 구간을 구하시오. 먼저 함수를 미분하여 도함수 \$f\'(x)\$를 구합니다. \$\$f\'(x) = -3x^2 + 6x + 9\$\$ 입니다. 함수가 감소하기 위해서는 \$f\'(x) \\leq 0\$이어야 하므로, 부등식 \$-3x^2 + 6x + 9 \\leq 0\$을 풀어야 합니다.",   "위 부등식의 양변을 \$-3\$으로 나누면 부등호의 방향이 바뀌어 \$\$x^2 - 2x - 3 \\geq 0\$\$이 됩니다. 이를 인수분해하면 \$\$(x - 3)(x + 1) \\geq 0\$\$이 됩니다. 이차부등식의 해를 구하면 \$x \\leq -1\$ 또는 \$x \\geq 3\$이 나옵니다. 따라서 함수 \$f(x)\$는 구간 \$(-\\\\infty, -1]\$과 \$[3, \\\\infty)\$에서 감소한다고 결론 내릴 수 있습니다." ]',
            ],
          ),
        ],
      ),
    ],
  ),
  '이차함수와이차방정식': BookData(
    id: 'concept_이차함수와이차방정식',
    title: '이차함수와이차방정식',
    subtitle: '공통수학1 > 이차함수 > 이차함수와이차방정식',
    category: 'common',
    tags: ['공통수학1', '이차함수', '이차함수와이차방정식'],
    chapters: [
      BookChapter(
        title: '이차함수와이차방정식',
        intro: ['공통수학1 > 이차함수 > 이차함수와이차방정식 개념 학습'],
        sections: [
          BookSection(
            title: '이차함수와이차방정식',
            paragraphs: [
              '이차함수 \$y = ax^2 + bx + c\$ (\$a \\neq 0\$)의 그래프와 \$x\$축의 교점은 이차함수의 함숫값이 \$0\$이 되는 지점, 즉 \$ax^2 + bx + c = 0\$을 만족하는 \$x\$의 값과 같습니다. 따라서 이차함수의 그래프가 \$x\$축과 만나는 점의 \$x\$좌표는 이차방정식의 실근과 일치합니다. 그래프가 \$x\$축과 만나는 위치와 개수는 이차방정식의 판별식 \$D = b^2 - 4ac\$의 부호에 따라 결정됩니다.',
              '판별식 \$D\$의 값에 따른 이차함수 그래프와 \$x\$축의 위치 관계는 다음과 같습니다. 첫째, \$D > 0\$이면 서로 다른 두 점에서 만나고, 둘째, \$D = 0\$이면 한 점(꼭짓점)에서 접하며, 셋째, \$D < 0\$이면 \$x\$축과 만나지 않습니다. 이처럼 이차함수의 그래프를 통해 이차방정식의 근의 개수를 기하학적으로 해석할 수 있으며, 이는 함수와 방정식이 서로 밀접하게 연결되어 있음을 보여주는 중요한 원리입니다.',
              '이제 이차함수 \$y = x^2 - 4x + 3\$의 그래프와 \$x\$축의 교점 좌표를 구하는 예제를 살펴봅시다. 교점을 구하기 위해서는 함숫값 \$y\$에 \$0\$을 대입하여 이차방정식 \$x^2 - 4x + 3 = 0\$을 세워야 합니다. 이 방정식은 인수분해를 통해 \$(x - 1)(x - 3) = 0\$으로 변형할 수 있습니다.',
              '위의 식을 풀면 \$x = 1\$ 또는 \$x = 3\$이라는 두 개의 근을 얻게 됩니다. 따라서 이차함수 \$y = x^2 - 4x + 3\$의 그래프는 \$x\$축과 점 \$(1, 0)\$과 \$(3, 0)\$에서 만난다는 것을 알 수 있습니다. 이처럼 이차방정식의 해를 구하는 과정은 곧 이차함수 그래프의 절편을 찾는 과정과 동일합니다.',
              '마지막으로 이차함수 \$y = x^2 - 2x + 2\$가 \$x\$축과 만나는지 확인해 봅시다. 판별식 \$D = b^2 - 4ac\$에 계수를 대입하면 \$D = (-2)^2 - 4 \\times 1 \\times 2 = 4 - 8 = -4\$가 됩니다. 판별식의 값이 \$0\$보다 작으므로, 이 이차함수의 그래프는 \$x\$축과 만나지 않는다는 결론을 내릴 수 있습니다.',
            ],
          ),
        ],
      ),
    ],
  ),
  '실수지수': BookData(
    id: 'concept_실수지수',
    title: '실수지수',
    subtitle: '대수 > 지수 > 지수의확장 > 실수지수',
    category: 'common',
    tags: ['대수', '지수', '지수의확장', '실수지수'],
    chapters: [
      BookChapter(
        title: '실수지수',
        intro: ['대수 > 지수 > 지수의확장 > 실수지수 개념 학습'],
        sections: [
          BookSection(
            title: '실수지수',
            paragraphs: [
              '지수의 확장은 자연수에서 정수로, 다시 유리수로 확장되는 과정을 거쳐 최종적으로 실수 전체의 범위까지 넓어집니다. 실수지수란 지수 자리에 유리수가 아닌 무리수(예: \$\\sqrt{2}, \\pi\$ 등)가 오는 경우를 의미합니다. 유리수 지수 \$a^r\$ (\$a>0, r\$은 유리수)가 정의될 때, 무리수 지수 \$a^x\$ (\$x\$는 무리수)는 \$x\$에 한없이 가까워지는 유리수들의 수열을 이용하여 그 극한값으로 정의합니다. 이때 밑 \$a\$는 항상 양수(\$a>0\$)여야 한다는 점이 매우 중요합니다.',
              '실수지수에서도 지수법칙은 그대로 성립합니다. \$a>0, b>0\$이고 \$x, y\$가 임의의 실수일 때, 다음의 핵심 공식들이 성립합니다. 첫째, \$a^x \\cdot a^y = a^{x+y}\$이며, 둘째, \$(a^x)^y = a^{xy}\$입니다. 셋째, \$(ab)^x = a^x b^x\$이고, 넷째, \$a^x / a^y = a^{x-y}\$입니다. 이러한 성질들은 지수가 실수 범위로 확장되어도 지수법칙이 일관되게 적용됨을 보여주며, 이는 복잡한 수식을 간결하게 계산하는 강력한 도구가 됩니다.',
              '실수지수를 활용하면 \$2^{\\sqrt{2}}\$와 같이 직관적으로 계산하기 어려운 값도 수열의 극한을 통해 그 위치를 파악할 수 있습니다. 예를 들어, \$\\sqrt{2} \\approx 1.414...\$이므로 \$2^{1.4}, 2^{1.41}, 2^{1.414}, \\dots\$와 같은 값들을 차례로 계산하면 하나의 일정한 값으로 수렴하게 되는데, 이 값을 \$2^{\\sqrt{2}}\$로 정의하는 것입니다. 이처럼 실수지수는 지수함수의 연속성을 보장하며, 수학적 모델링에서 성장과 감쇠를 다룰 때 필수적인 개념입니다.',
              '예제: 다음 식을 간단히 하시오. \$(3^{\\sqrt{2}})^{\\sqrt{8}} \\div 3^2\$. 이 문제를 풀기 위해서는 지수법칙 \$(a^x)^y = a^{xy}\$와 \$a^x \\div a^y = a^{x-y}\$를 순차적으로 적용해야 합니다. 먼저 괄호 안의 지수를 계산하면 \$\\sqrt{2} \\times \\sqrt{8} = \\sqrt{16} = 4\$가 됩니다. 따라서 식은 \$3^4 \\div 3^2\$이 됩니다.',
              '단계별 풀이를 진행하면 다음과 같습니다. 첫째, \$(3^{\\sqrt{2}})^{\\sqrt{8}} = 3^{\\sqrt{2} \\times \\sqrt{8}} = 3^{\\sqrt{16}} = 3^4\$입니다. 둘째, 이를 나눗셈 식에 대입하면 \$3^4 \\div 3^2\$이 됩니다. 셋째, 지수법칙 \$a^x \\div a^y = a^{x-y}\$에 의해 \$3^{4-2} = 3^2\$이 됩니다. 최종적으로 \$3^2 = 9\$라는 값을 얻을 수 있습니다.',
            ],
          ),
        ],
      ),
    ],
