  '대우': BookData(
    id: 'concept_대우',
    title: '대우',
    subtitle: '공통수학2 > 명제 > 명제의역과대우 > 대우',
    category: 'common',
    tags: ['공통수학2', '명제', '명제의역과대우', '대우'],
    chapters: [
      BookChapter(
        title: '대우',
        intro: ['공통수학2 > 명제 > 명제의역과대우 > 대우 개념 학습'],
        sections: [
          BookSection(
            title: '대우',
            paragraphs: [
              '명제 \'이면 \$p\$이면 \$q\$이다\'를 기호로 \$p \\implies q\$라고 나타냅니다. 여기서 가정인 \$p\$와 결론인 \$q\$의 위치를 바꾸고, 각각을 부정하여 \'이면 \$q\$가 아니면 \$p\$가 아니다\'로 만든 명제를 원래 명제의 \'대우\'라고 합니다. 이를 기호로 나타내면 \$\\neg q \\implies \\neg p\$가 됩니다. 대우는 명제와 매우 특별한 관계를 맺고 있는데, 원래 명제가 참이면 그 대우도 반드시 참이고, 원래 명제가 거짓이면 그 대우도 반드시 거짓이라는 성질이 있습니다.',
              '이러한 성질이 중요한 이유는 어떤 명제의 참과 거짓을 판별하기 어려울 때, 그 대우를 이용하면 훨씬 쉽게 해결할 수 있기 때문입니다. 예를 들어, \'어떤 조건이 복잡하게 얽혀 있어 직접 증명하기 힘들 때\' 그 대우를 구하여 증명하면 논리적으로 완벽하게 원래 명제의 참, 거짓을 밝혀낼 수 있습니다. 수학에서 대우는 복잡한 문제를 단순한 문제로 바꾸어 해결하는 강력한 도구로 사용됩니다.',
              '이제 구체적인 예제를 통해 대우를 구하는 방법을 알아봅시다. 명제 \'\$x\$가 홀수이면 \$x^2\$은 홀수이다\'라는 문장이 있을 때, 이 명제의 대우를 구해보겠습니다. 먼저 가정인 \'\$x\$가 홀수이다\'의 부정은 \'\$x\$가 짝수이다\'가 되고, 결론인 \'\$x^2\$은 홀수이다\'의 부정은 \'\$x^2\$은 짝수이다\'가 됩니다. 이제 가정과 결론의 위치를 바꾸어 연결하면 대우는 \'\$x^2\$이 짝수이면 \$x\$는 짝수이다\'가 됩니다.',
              '또 다른 예제로, \'두 실수 \$a, b\$에 대하여 \$a+b > 2\$이면 \$a > 1\$ 또는 \$b > 1\$이다\'라는 명제의 대우를 구해봅시다. 여기서 \'또는\'의 부정은 \'그리고\'가 됨을 주의해야 합니다. 따라서 가정과 결론의 위치를 바꾸고 각각을 부정하면, 대우는 \'\$a \\le 1\$이고 \$b \\le 1\$이면 \$a+b \\le 2\$이다\'가 됩니다. 이처럼 대우를 구할 때는 \'그리고\'와 \'또는\'의 관계가 서로 바뀐다는 점을 항상 기억해야 합니다.',
              '마지막으로 대우를 이용한 증명 문제를 풀어봅시다. \'자연수 \$n\$에 대하여 \$n^2\$이 3의 배수이면 \$n\$도 3의 배수이다\'라는 명제를 증명하기 위해 대우를 이용해 보겠습니다. 이 명제의 대우는 \'\$n\$이 3의 배수가 아니면 \$n^2\$도 3의 배수가 아니다\'입니다. \$n\$이 3의 배수가 아니면 \$n\$은 \$3k+1\$ 또는 \$3k+2\$ (단, \$k\$는 0 이상의 정수) 꼴로 나타낼 수 있습니다.',
              '첫째, \$n = 3k+1\$일 때 \$n^2 = (3k+1)^2 = 9k^2 + 6k + 1 = 3(3k^2 + 2k) + 1\$이 되어 3의 배수가 아닙니다. 둘째, \$n = 3k+2\$일 때 \$n^2 = (3k+2)^2 = 9k^2 + 12k + 4 = 3(3k^2 + 4k + 1) + 1\$이 되어 역시 3의 배수가 아닙니다. 대우가 참임을 확인했으므로, 원래 명제인 \'\$n^2\$이 3의 배수이면 \$n\$도 3의 배수이다\'도 참이라는 결론을 내릴 수 있습니다.',
            ],
          ),
        ],
      ),
    ],
