  '나머지정리증명': BookData(
    id: 'concept_나머지정리증명',
    title: '나머지정리증명',
    subtitle: '공통수학1 > 다항식 > 나머지정리 > 나머지정리증명',
    category: 'common',
    tags: ['공통수학1', '다항식', '나머지정리', '나머지정리증명'],
    chapters: [
      BookChapter(
        title: '나머지정리증명',
        intro: ['공통수학1 > 다항식 > 나머지정리 > 나머지정리증명 개념 학습'],
        sections: [
          BookSection(
            title: '나머지정리증명',
            paragraphs: [
              '나머지정리란 다항식 \$P(x)\$를 일차식 \$x-a\$로 나누었을 때의 나머지를 직접 나눗셈을 하지 않고도 간단히 구할 수 있는 정리입니다. 다항식 \$P(x)\$를 \$x-a\$로 나누었을 때의 몫을 \$Q(x)\$, 나머지를 \$R\$이라고 하면, 나눗셈의 원리에 의해 \$P(x) = (x-a)Q(x) + R\$이라는 항등식이 성립합니다. 이때 나머지는 나누는 식의 차수보다 낮아야 하므로, 일차식으로 나누었을 때의 나머지 \$R\$은 상수항이 됩니다.',
              '이 항등식에서 \$x\$에 어떤 값을 대입해도 등식은 항상 성립합니다. 따라서 \$x\$ 대신 \$a\$를 대입하면 \$P(a) = (a-a)Q(a) + R\$이 됩니다. 여기서 \$(a-a)\$는 \$0\$이므로 \$0 \\cdot Q(a)\$는 사라지고, 결과적으로 \$P(a) = R\$이라는 결론을 얻게 됩니다. 즉, 다항식 \$P(x)\$를 \$x-a\$로 나눈 나머지는 다항식에 \$x=a\$를 대입한 값인 \$P(a)\$와 같습니다.',
              '이 성질을 확장하면 \$P(x)\$를 \$ax+b\$ 꼴의 일차식으로 나눌 때도 적용할 수 있습니다. \$P(x) = (ax+b)Q(x) + R\$에서 \$ax+b=0\$이 되는 \$x\$값인 \$-\\frac{b}{a}\$를 대입하면, \$P(-\\frac{b}{a}) = (a \\cdot (-\\frac{b}{a}) + b)Q(-\\frac{b}{a}) + R\$이 되어 결국 \$P(-\\frac{b}{a}) = R\$이 성립함을 알 수 있습니다.',
              '이제 예제를 통해 직접 적용해 봅시다. 다항식 \$P(x) = 2x^3 - 3x^2 + x + 5\$를 \$x-2\$로 나누었을 때의 나머지를 구하는 문제입니다. 나머지정리에 따르면 나머지는 \$P(2)\$의 값과 같습니다. 먼저 \$x\$ 자리에 \$2\$를 대입하여 식을 세웁니다. \$P(2) = 2(2)^3 - 3(2)^2 + 2 + 5\$.',
              '단계별로 계산하면, \$2^3 = 8\$이므로 \$2 \\times 8 = 16\$이고, \$2^2 = 4\$이므로 \$3 \\times 4 = 12\$가 됩니다. 이를 식에 대입하면 \$P(2) = 16 - 12 + 2 + 5\$가 됩니다. 이를 차례대로 계산하면 \$16 - 12 = 4\$이고, \$4 + 2 + 5 = 11\$이 됩니다. 따라서 다항식 \$P(x)\$를 \$x-2\$로 나눈 나머지는 \$11\$입니다.',
            ],
          ),
        ],
      ),
    ],
  ),
  '시그마의성질': BookData(
    id: 'concept_시그마의성질',
    title: '시그마의성질',
    subtitle: '대수 > 수열 > 합의기호시그마 > 시그마의성질',
    category: 'common',
    tags: ['대수', '수열', '합의기호시그마', '시그마의성질'],
    chapters: [
      BookChapter(
        title: '시그마의성질',
        intro: ['대수 > 수열 > 합의기호시그마 > 시그마의성질 개념 학습'],
        sections: [
          BookSection(
            title: '시그마의성질',
            paragraphs: [
              '수열의 합을 나타내는 기호인 시그마(\$\\sum\$)는 복잡한 수열의 합을 간결하게 표현하기 위해 사용합니다. 시그마의 성질을 이해하면 수열의 합을 계산할 때 일일이 나열하지 않고도 효율적으로 값을 구할 수 있습니다. 가장 기본적인 성질은 합의 기호 안에서 상수배가 되어 있는 경우 상수를 기호 앞으로 끄집어낼 수 있다는 점입니다. 즉, 상수 \$c\$에 대하여 \$\$\\sum_{k=1}^{n} c a_k = c \\sum_{k=1}^{n} a_k\$\$ 가 성립합니다.',
              '또한, 시그마는 덧셈과 뺄셈에 대해 각각 분배가 가능하다는 중요한 성질을 가지고 있습니다. 두 수열 \$a_k\$와 \$b_k\$에 대하여 합과 차의 시그마는 각각의 시그마를 더하거나 뺀 것과 같습니다. 이를 식으로 나타내면 \$\$\\sum_{k=1}^{n} (a_k + b_k) = \\sum_{k=1}^{n} a_k + \\sum_{k=1}^{n} b_k\$\$ 이고, \$\$\\sum_{k=1}^{n} (a_k - b_k) = \\sum_{k=1}^{n} a_k - \\sum_{k=1}^{n} b_k\$\$ 입니다. 다만, 곱셈이나 나눗셈에 대해서는 이러한 분배 법칙이 성립하지 않으므로 주의해야 합니다.',
              '마지막으로, 시그마 기호 안의 값이 상수인 경우의 성질입니다. 만약 \$k\$값에 관계없이 항상 일정한 상수 \$c\$를 \$n\$번 더한다면, 그 결과는 상수 \$c\$에 항의 개수인 \$n\$을 곱한 것과 같습니다. 즉, \$\$\\sum_{k=1}^{n} c = nc\$\$ 라는 공식이 성립합니다. 이 세 가지 성질(상수배, 덧셈·뺄셈의 분배, 상수항의 합)을 적절히 조합하면 어떤 다항식 형태의 수열 합이라도 쉽게 계산할 수 있습니다.',
              '이제 예제를 통해 시그마의 성질을 적용해 봅시다. 문제: \$\\sum_{k=1}^{10} (3k + 2)\$의 값을 구하시오. 먼저 시그마의 덧셈 성질을 이용하여 식을 분리합니다. \$\$\\sum_{k=1}^{10} (3k + 2) = \\sum_{k=1}^{10} 3k + \\sum_{k=1}^{10} 2\$\$ 로 나눌 수 있습니다. 여기서 첫 번째 항은 상수배 성질을 이용해 \$3 \\sum_{k=1}^{10} k\$로 변형합니다.',
              '이제 각 부분을 계산합니다. 자연수의 합 공식 \$\\sum_{k=1}^{n} k = \\frac{n(n+1)}{2}\$을 이용하면, \$3 \\sum_{k=1}^{10} k = 3 \\times \\frac{10 \\times 11}{2} = 3 \\times 55 = 165\$가 됩니다. 또한 상수항의 성질에 의해 \$\\sum_{k=1}^{10} 2 = 2 \\times 10 = 20\$이 됩니다. 최종적으로 두 값을 더하면 \$165 + 20 = 185\$라는 결과를 얻을 수 있습니다.',
            ],
          ),
        ],
      ),
    ],
  ),
  '중점': BookData(
    id: 'concept_중점',
    title: '중점',
    subtitle: '공통수학2 > 좌표평면 > 선분의내분점 > 중점',
    category: 'common',
    tags: ['공통수학2', '좌표평면', '선분의내분점', '중점'],
    chapters: [
      BookChapter(
        title: '중점',
        intro: ['공통수학2 > 좌표평면 > 선분의내분점 > 중점 개념 학습'],
        sections: [
          BookSection(
            title: '중점',
            paragraphs: [
              '좌표평면 위의 두 점 \$A(x_1, y_1)\$과 \$B(x_2, y_2)\$를 잇는 선분 \$AB\$가 있을 때, 이 선분을 똑같은 길이로 이등분하는 점을 \'중점\'이라고 합니다. 중점은 선분의 양 끝점으로부터 같은 거리에 위치하며, 기하학적으로는 선분의 무게중심과 같은 역할을 합니다. 중점의 좌표를 구하는 것은 선분을 \$1:1\$의 비율로 내분하는 점을 찾는 것과 동일한 원리입니다.',
              '중점의 좌표를 구하는 공식은 매우 직관적입니다. 두 점의 \$x\$좌표끼리 더해서 \$2\$로 나누고, \$y\$좌표끼리 더해서 \$2\$로 나누면 됩니다. 즉, 선분 \$AB\$의 중점 \$M(x, y)\$의 좌표는 다음과 같이 정의됩니다. \$\$M = \\left( \\frac{x_1 + x_2}{2}, \\frac{y_1 + y_2}{2} \\right)\$\$ 이 공식은 수직선 위에서 두 점의 평균을 구하는 것과 같은 논리이며, 좌표평면에서는 \$x\$축과 \$y\$축에 대해 각각 평균을 구하는 것으로 이해할 수 있습니다.',
              '예를 들어, 좌표평면 위의 두 점 \$A(2, 4)\$와 \$B(6, 8)\$을 잇는 선분 \$AB\$의 중점 \$M\$을 구하는 과정을 살펴봅시다. 중점의 \$x\$좌표는 두 점의 \$x\$좌표인 \$2\$와 \$6\$의 평균이므로 \$\\frac{2+6}{2} = 4\$가 됩니다. 마찬가지로 \$y\$좌표는 두 점의 \$y\$좌표인 \$4\$와 \$8\$의 평균이므로 \$\\frac{4+8}{2} = 6\$이 됩니다. 따라서 구하는 중점 \$M\$의 좌표는 \$(4, 6)\$입니다.',
              '조금 더 복잡한 예제로, 점 \$A(-3, 5)\$와 점 \$B(5, -1)\$을 잇는 선분 \$AB\$의 중점 \$M\$을 구해 보겠습니다. 공식에 따라 \$x\$좌표와 \$y\$좌표를 각각 계산하면 다음과 같습니다. 먼저 \$x\$좌표는 \$x = \\frac{-3 + 5}{2} = \\frac{2}{2} = 1\$입니다. 다음으로 \$y\$좌표는 \$y = \\frac{5 + (-1)}{2} = \\frac{4}{2} = 2\$입니다. 결과적으로 중점 \$M\$의 좌표는 \$(1, 2)\$가 됩니다.',
              '마지막으로, 중점의 성질을 활용하여 미지수를 구하는 문제를 풀어봅시다. 선분 \$AB\$의 중점이 \$M(3, 2)\$이고, 점 \$A\$의 좌표가 \$(1, 5)\$일 때, 점 \$B(x, y)\$의 좌표를 구하는 문제입니다. 중점 공식에 의해 \$\\frac{1+x}{2} = 3\$이고 \$\\frac{5+y}{2} = 2\$가 성립합니다. 첫 번째 식에서 \$1+x = 6\$이 되어 \$x = 5\$를 얻고, 두 번째 식에서 \$5+y = 4\$가 되어 \$y = -1\$을 얻습니다. 따라서 점 \$B\$의 좌표는 \$(5, -1)\$입니다.',
            ],
          ),
        ],
      ),
    ],
  ),
