        sections: [
          BookSection(
            title: '지수법칙의성질',
            paragraphs: [
              '지수법칙이란 거듭제곱의 계산을 간편하게 하기 위해 만들어진 수학적 약속입니다. 어떤 수 \$a\$를 \$n\$번 곱한 것을 \$a^n\$이라 쓰고, 이때 \$a\$를 밑, \$n\$을 지수라고 합니다. 지수법칙의 가장 기초가 되는 성질은 밑이 같은 두 거듭제곱을 곱할 때 지수끼리 더하는 것입니다. 즉, \$a^m \\times a^n = a^{m+n}\$이 성립합니다. 이는 \$a\$를 \$m\$번 곱한 것에 \$a\$를 \$n\$번 더 곱하면 총 \$a\$를 \$m+n\$번 곱하게 된다는 원리에서 비롯됩니다.',
              '지수법칙에는 곱셈 외에도 나눗셈과 거듭제곱의 거듭제곱에 관한 성질이 있습니다. 나눗셈의 경우 \$a^m \\div a^n = a^{m-n}\$ (\$m > n\$일 때)이 성립하며, 거듭제곱의 거듭제곱은 \$(a^m)^n = a^{m \\times n}\$으로 계산합니다. 또한, 괄호 안의 곱셈이나 나눗셈에 지수가 붙어 있을 때는 \$(ab)^n = a^n b^n\$ 또는 \$(\\frac{a}{b})^n = \\frac{a^n}{b^n}\$과 같이 지수를 각각 분배할 수 있습니다. 이러한 성질들을 익히면 복잡한 식을 매우 간단하게 정리할 수 있습니다.',
              '이제 구체적인 예제를 통해 지수법칙을 적용해 보겠습니다. 첫 번째 문제는 \$2^3 \\times 2^4\$을 계산하는 것입니다. 이 식은 밑이 2로 같으므로 지수법칙 \$a^m \\times a^n = a^{m+n}\$을 적용할 수 있습니다. 따라서 \$2^3 \\times 2^4 = 2^{3+4} = 2^7\$이 됩니다. \$2^7\$은 2를 7번 곱한 값인 128이므로, 최종 결과는 128입니다.',
              '두 번째 예제로 식 \$(x^2 y^3)^4\$을 간단히 정리해 봅시다. 이 식은 괄호 안의 각 항에 지수 4를 분배하는 법칙인 \$(a^m b^n)^p = a^{m \\times p} b^{n \\times p}\$를 이용합니다. 먼저 \$x^2\$에 4를 곱하여 \$x^{2 \\times 4} = x^8\$이 되고, \$y^3\$에 4를 곱하여 \$y^{3 \\times 4} = y^{12}\$가 됩니다. 따라서 식을 정리하면 \$x^8 y^{12}\$라는 결과를 얻을 수 있습니다.',
              '마지막으로 나눗셈이 포함된 식 \$\\frac{3^6}{3^2}\$을 계산해 보겠습니다. 지수법칙 \$a^m \\div a^n = a^{m-n}\$을 적용하면 밑이 3일 때 지수끼리 빼주면 됩니다. 즉, \$3^{6-2} = 3^4\$이 됩니다. \$3^4\$은 \$3 \\times 3 \\times 3 \\times 3\$을 의미하므로, \$9 \\times 9 = 81\$이 최종 정답입니다. 이처럼 지수법칙을 활용하면 큰 수를 직접 곱하지 않고도 빠르고 정확하게 계산할 수 있습니다.',
            ],
          ),
        ],
      ),
    ],
  ),
  '도함수의부호': BookData(
    id: 'concept_도함수의부호',
    title: '도함수의부호',
    subtitle: '미적분Ⅰ > 함수의증가와감소 > 도함수의부호',
    category: 'common',
    tags: ['미적분Ⅰ', '함수의증가와감소', '도함수의부호'],
    chapters: [
      BookChapter(
        title: '도함수의부호',
        intro: ['미적분Ⅰ > 함수의증가와감소 > 도함수의부호 개념 학습'],
        sections: [
          BookSection(
            title: '도함수의부호',
            paragraphs: [
              '[   "함수의 증가와 감소를 판단할 때 가장 강력한 도구는 바로 \'도함수의 부호\'입니다. 어떤 구간에서 미분가능한 함수 \$f(x)\$가 있을 때, 그 구간의 모든 \$x\$에 대하여 \$f\'(x) > 0\$이면 함수 \$f(x)\$는 그 구간에서 증가합니다. 반대로 \$f\'(x) < 0\$이면 함수 \$f(x)\$는 그 구간에서 감소하게 됩니다. 이는 도함수 \$f\'(x)\$가 해당 지점에서의 접선의 기울기를 의미하기 때문인데, 기울기가 양수라는 것은 오른쪽 위로 향하는 그래프를, 음수라는 것은 오른쪽 아래로 향하는 그래프를 그린다는 뜻입니다.",   "조금 더 엄밀하게 말하면, 구간 내의 모든 \$x\$에 대하여 \$f\'(x) \\geq 0\$이고, 어떤 열린 구간에서도 \$f\'(x)\$가 항상 \$0\$이 되지 않는다면 함수 \$f(x)\$는 그 구간에서 증가한다고 말합니다. 마찬가지로 \$f\'(x) \\leq 0\$인 경우에도 동일한 논리가 적용됩니다. 즉, 도함수의 부호는 함수의 그래프가 위로 올라가는지, 아니면 아래로 내려가는지를 결정짓는 핵심적인 지표가 됩니다.",   "이제 구체적인 예제를 통해 도함수의 부호를 활용하는 방법을 알아봅시다. 함수 \$f(x) = x^3 - 3x^2 + 2\$가 증가하는 구간과 감소하는 구간을 구해보겠습니다. 먼저 함수를 미분하여 도함수를 구하면 다음과 같습니다. \$\$f\'(x) = 3x^2 - 6x\$\$",   "도함수의 부호를 조사하기 위해 \$f\'(x) = 0\$이 되는 지점을 찾습니다. \$\$3x(x - 2) = 0\$\$ 이 식을 풀면 \$x = 0\$ 또는 \$x = 2\$가 됩니다. 이제 이 두 지점을 기준으로 구간을 나누어 도함수의 부호를 확인합니다. \$x < 0\$인 구간에서는 \$f\'(x) > 0\$이므로 함수는 증가하고, \$0 < x < 2\$인 구간에서는 \$f\'(x) < 0\$이므로 함수는 감소합니다. 마지막으로 \$x > 2\$인 구간에서는 다시 \$f\'(x) > 0\$이 되어 함수는 증가하게 됩니다.",   "결과적으로 함수 \$f(x) = x^3 - 3x^2 + 2\$는 구간 \$(-\\\\infty, 0]\$과 \$[2, \\\\infty)\$에서 증가하며, 구간 \$[0, 2]\$에서 감소한다는 결론을 얻을 수 있습니다. 이처럼 도함수의 부호를 조사하는 과정은 함수의 개형을 파악하는 가장 기초적이면서도 중요한 단계입니다. 여러분도 다양한 다항함수를 미분해보고, 도함수가 0이 되는 지점을 찾아 그래프의 모양을 직접 그려보는 연습을 해보길 바랍니다." ]',
            ],
          ),
        ],
      ),
    ],
  ),
  '이차함수와이차부등식': BookData(
    id: 'concept_이차함수와이차부등식',
    title: '이차함수와이차부등식',
    subtitle: '공통수학1 > 이차함수 > 이차함수와이차부등식',
    category: 'common',
    tags: ['공통수학1', '이차함수', '이차함수와이차부등식'],
    chapters: [
      BookChapter(
        title: '이차함수와이차부등식',
        intro: ['공통수학1 > 이차함수 > 이차함수와이차부등식 개념 학습'],
        sections: [
          BookSection(
            title: '이차함수와이차부등식',
            paragraphs: [
              '이차함수 \$y = ax^2 + bx + c\$ (\$a \\neq 0\$)의 그래프는 포물선 모양을 띠며, 이 그래프와 \$x\$축의 위치 관계는 이차방정식 \$ax^2 + bx + c = 0\$의 판별식 \$D = b^2 - 4ac\$의 값에 따라 결정됩니다. 이차부등식 \$ax^2 + bx + c > 0\$ 또는 \$ax^2 + bx + c < 0\$을 푼다는 것은, 이차함수의 그래프가 \$x\$축보다 위쪽에 있거나 아래쪽에 있는 \$x\$의 값의 범위를 찾는 것과 같습니다.',
              '이차부등식을 풀기 위해서는 먼저 이차방정식 \$ax^2 + bx + c = 0\$의 두 실근을 \$\\alpha, \\beta\$ (\$\\alpha < \\beta\$)라 할 때, \$a > 0\$인 경우 다음과 같은 성질을 이용합니다. \$ax^2 + bx + c > 0\$의 해는 \$x < \\alpha\$ 또는 \$x > \\beta\$이고, \$ax^2 + bx + c < 0\$의 해는 \$\\alpha < x < \\beta\$입니다. 만약 판별식 \$D=0\$이라면 그래프가 \$x\$축에 접하므로 해는 특수한 형태가 되며, \$D < 0\$이면 그래프가 항상 \$x\$축 위에 떠 있어 해가 모든 실수가 되거나 해가 없을 수도 있습니다.',
              '이제 구체적인 예제를 통해 확인해 봅시다. 이차부등식 \$x^2 - 5x + 6 < 0\$을 풀어보겠습니다. 먼저 이 식에 대응하는 이차방정식 \$x^2 - 5x + 6 = 0\$을 인수분해하면 \$(x - 2)(x - 3) = 0\$이 되어 두 근은 \$x = 2\$와 \$x = 3\$임을 알 수 있습니다.',
              '이차함수 \$y = x^2 - 5x + 6\$의 그래프는 아래로 볼록한 포물선이며 \$x\$축과 두 점 \$(2, 0)\$과 \$(3, 0)\$에서 만납니다. 부등식에서 \$0\$보다 작은 범위를 구하라고 했으므로, 그래프가 \$x\$축보다 아래쪽에 위치하는 구간을 찾으면 됩니다. 따라서 구하는 해는 \$2 < x < 3\$이 됩니다.',
              '또 다른 예로 \$x^2 - 2x - 3 \\geq 0\$을 풀어봅시다. 먼저 방정식 \$x^2 - 2x - 3 = 0\$을 인수분해하면 \$(x + 1)(x - 3) = 0\$이 되어 근은 \$x = -1\$과 \$x = 3\$입니다. 그래프는 아래로 볼록하고 \$x\$축과 두 점에서 만납니다.',
              '이 부등식은 \$0\$보다 크거나 같은 범위를 찾는 것이므로, 그래프가 \$x\$축 위쪽에 있거나 \$x\$축과 만나는 지점을 포함해야 합니다. 따라서 그래프의 양 끝부분에 해당하는 범위인 \$x \\leq -1\$ 또는 \$x \\geq 3\$이 최종적인 해가 됩니다.',
            ],
          ),
        ],
      ),
    ],
  ),
  '이': BookData(
    id: 'concept_이',
    title: '이',
    subtitle: '공통수학2 > 명제 > 명제의역과대우 > 이',
    category: 'common',
    tags: ['공통수학2', '명제', '명제의역과대우', '이'],
    chapters: [
      BookChapter(
        title: '이',
        intro: ['공통수학2 > 명제 > 명제의역과대우 > 이 개념 학습'],
        sections: [
          BookSection(
            title: '이',
            paragraphs: [
              '명제에서 \'이(Converse)\'란 주어진 조건명제 \'\$p \\rightarrow q\$\'의 가정과 결론을 서로 바꾸어 만든 새로운 명제를 의미합니다. 원래 명제 \'\$p \\rightarrow q\$\'에서 \'\$p\$\'는 가정, \'\$q\$\'는 결론이라고 부르는데, 이를 뒤집어 \'\$q \\rightarrow p\$\'의 형태로 만드는 것이 바로 \'이\'입니다. 예를 들어 \'비가 오면 땅이 젖는다\'라는 명제가 있다면, 이 명제의 이는 \'땅이 젖으면 비가 온다\'가 됩니다.',
              '명제의 \'이\'를 다룰 때 주의할 점은 원래 명제의 참과 거짓이 그 \'이\'의 참과 거짓과 항상 일치하지는 않는다는 것입니다. 예를 들어 \'x가 4의 배수이면 x는 짝수이다\'라는 명제는 참이지만, 그 \'이\'인 \'x가 짝수이면 x는 4의 배수이다\'는 2나 6과 같은 반례가 존재하므로 거짓이 됩니다. 이처럼 명제와 그 이는 논리적으로 서로 다른 진릿값을 가질 수 있습니다.',
              '수학적으로 명제 \'\$p \\rightarrow q\$\'의 이를 기호로 나타내면 다음과 같습니다. 원래 명제가 \'\$p \\rightarrow q\$\'일 때, 그 이는 \$\$q \\rightarrow p\$\$가 됩니다. 만약 주어진 명제에 부정(\$\\sim\$)이 포함되어 있다면, 가정과 결론의 위치만 바꾸는 것이 \'이\'이므로, \'\$\\sim p \\rightarrow \\sim q\$\'의 이는 \'\$\\sim q \\rightarrow \\sim p\$\'가 됨을 기억해야 합니다.',
              '예제 문제: 다음 명제의 \'이\'를 구하고, 원래 명제와 그 이의 참, 거짓을 판별하시오. [명제: \$x^2 = 9\$이면 \$x = 3\$이다.]',
              '풀이 단계 1: 먼저 주어진 명제의 가정 \'\$p\$\'는 \'\$x^2 = 9\$\'이고, 결론 \'\$q\$\'는 \'\$x = 3\$\'입니다. 이를 서로 바꾸어 \'이\'를 만들면 \'\$x = 3\$이면 \$x^2 = 9\$이다.\'가 됩니다. 원래 명제에서 \$x^2 = 9\$를 만족하는 \$x\$는 \$3\$과 \$-3\$이 있는데, 결론인 \$x=3\$만으로는 이를 모두 설명할 수 없으므로 원래 명제는 거짓입니다.',
              '풀이 단계 2: 이제 구한 \'이\'인 \'\$x = 3 \\rightarrow x^2 = 9\$\'를 살펴봅시다. \$x\$가 \$3\$이면 \$x^2\$은 반드시 \$3^2 = 9\$가 되므로, 이 명제는 참입니다. 따라서 주어진 명제는 거짓이지만, 그 \'이\'는 참이 되는 경우임을 확인할 수 있습니다. 이처럼 명제와 그 이는 각각 독립적으로 참과 거짓을 판별해야 합니다.',
            ],
          ),
        ],
      ),
    ],
  ),
  '시그마공식': BookData(
    id: 'concept_시그마공식',
    title: '시그마공식',
    subtitle: '대수 > 수열 > 합의기호시그마 > 시그마공식',
    category: 'common',
    tags: ['대수', '수열', '합의기호시그마', '시그마공식'],
    chapters: [
      BookChapter(
        title: '시그마공식',
        intro: ['대수 > 수열 > 합의기호시그마 > 시그마공식 개념 학습'],
        sections: [
          BookSection(
            title: '시그마공식',
            paragraphs: [
              '수열의 합을 나타내는 기호인 시그마(\$\\sum\$)는 복잡한 수열의 합을 간결하게 표현하기 위해 사용합니다. 시그마 기호 아래에는 변수와 시작 값을, 위에는 끝 값을 적어 수열의 항들을 어디부터 어디까지 더할지 명시합니다. 예를 들어, 수열 \$a_n\$의 첫째 항부터 제\$n\$항까지의 합은 \$\\sum_{k=1}^{n} a_k\$와 같이 나타내며, 이는 \$a_1 + a_2 + \\dots + a_n\$을 의미합니다.',
              '시그마는 합의 성질에 따라 몇 가지 중요한 공식들을 가집니다. 가장 기본이 되는 공식은 자연수의 거듭제곱의 합입니다. 첫째, 자연수 \$k\$의 합은 \$\$\\sum_{k=1}^{n} k = \\frac{n(n+1)}{2}\$\$ 이고, 둘째, 제곱의 합은 \$\$\\sum_{k=1}^{n} k^2 = \\frac{n(n+1)(2n+1)}{6}\$\$ 입니다. 마지막으로 세제곱의 합은 \$\$\\sum_{k=1}^{n} k^3 = \\left\\{ \\frac{n(n+1)}{2} \\right\\}^2\$\$ 와 같이 정의됩니다.',
              '시그마는 선형성을 가지고 있어, 상수배나 덧셈, 뺄셈에 대해 분리할 수 있습니다. 즉, \$c\$가 상수일 때 \$\$\\sum_{k=1}^{n} c a_k = c \\sum_{k=1}^{n} a_k\$\$ 가 성립하며, \$\$\\sum_{k=1}^{n} (a_k \\pm b_k) = \\sum_{k=1}^{n} a_k \\pm \\sum_{k=1}^{n} b_k\$\$ 와 같이 각각의 합으로 나누어 계산할 수 있습니다. 또한, 상수 \$c\$를 \$n\$번 더하면 \$\$\\sum_{k=1}^{n} c = cn\$\$ 이 된다는 점도 기억해야 합니다.',
              '이제 예제를 통해 시그마 공식을 적용해 봅시다. 문제: \$\\sum_{k=1}^{10} (2k + 3)\$의 값을 구하시오. 이 식은 시그마의 성질을 이용하여 두 부분으로 나눌 수 있습니다. 즉, \$\$\\sum_{k=1}^{10} 2k + \\sum_{k=1}^{10} 3\$\$ 으로 분리합니다. 여기서 상수 2를 앞으로 빼내면 \$2 \\sum_{k=1}^{10} k + \\sum_{k=1}^{10} 3\$이 됩니다.',
              '이제 위에서 배운 공식을 대입하여 계산합니다. 첫 번째 항은 \$2 \\times \\frac{10(10+1)}{2} = 10 \\times 11 = 110\$이 되고, 두 번째 항은 상수를 10번 더하는 것이므로 \$3 \\times 10 = 30\$이 됩니다. 따라서 전체 합은 \$110 + 30 = 140\$입니다. 이처럼 시그마 공식을 활용하면 일일이 숫자를 더하지 않고도 빠르고 정확하게 수열의 합을 구할 수 있습니다.',
            ],
          ),
        ],
      ),
    ],
