        title: '나머지정리활용',
        intro: ['공통수학1 > 다항식 > 나머지정리 > 나머지정리활용 개념 학습'],
        sections: [
          BookSection(
            title: '나머지정리활용',
            paragraphs: [
              '나머지정리란 다항식 \$P(x)\$를 일차식 \$x-a\$로 나누었을 때의 나머지가 \$P(a)\$와 같다는 매우 유용한 성질입니다. 이를 활용하면 다항식을 실제로 나누지 않고도 나머지를 빠르게 구할 수 있습니다. 만약 다항식 \$P(x)\$를 이차식 \$(x-a)(x-b)\$로 나누는 경우, 나머지는 일차식 형태인 \$ax+b\$로 가정하여 문제를 해결할 수 있습니다. 이때 나누는 식을 \$P(x) = (x-a)(x-b)Q(x) + ax+b\$와 같이 항등식으로 표현하는 것이 핵심입니다.',
              '나머지정리를 활용할 때 가장 중요한 것은 나누는 식의 인수분해 가능 여부입니다. 나누는 식이 \$(x-a)^2\$과 같이 완전제곱식인 경우에는 수치대입법을 한 번만 사용할 수 있기 때문에, 미분법을 이용하거나 식을 변형하여 나머지 \$R(x)\$를 구합니다. 또한, 나누는 식이 인수분해되지 않는 이차식일 때는 직접적인 대입보다는 계수 비교법이나 식의 구조적 특징을 활용하여 나머지를 결정하게 됩니다.',
              '예제 문제: 다항식 \$P(x)\$를 \$(x-1)\$로 나누면 나머지가 2이고, \$(x-2)\$로 나누면 나머지가 3입니다. 이때 \$P(x)\$를 \$(x-1)(x-2)\$로 나눈 나머지를 구하시오. 이 문제를 풀기 위해 먼저 나머지정리에 의해 \$P(1)=2\$, \$P(2)=3\$임을 알 수 있습니다. 구하는 나머지를 \$R(x)=ax+b\$라고 하면, \$P(x) = (x-1)(x-2)Q(x) + ax+b\$라는 항등식을 세울 수 있습니다.',
              '이제 위 항등식에 \$x=1\$과 \$x=2\$를 차례대로 대입하여 연립방정식을 만듭니다. \$x=1\$을 대입하면 \$P(1) = a(1) + b = 2\$가 되고, \$x=2\$를 대입하면 \$P(2) = a(2) + b = 3\$이 됩니다. 이 두 식을 연립하면 \$a+b=2\$와 \$2a+b=3\$이 나옵니다. 아래 식에서 위 식을 빼면 \$a=1\$을 얻고, 이를 다시 대입하면 \$b=1\$이 됨을 알 수 있습니다.',
              '따라서 우리가 구하고자 하는 나머지 \$R(x)\$는 \$ax+b\$에 \$a=1, b=1\$을 대입한 \$x+1\$이 됩니다. 이처럼 나머지정리를 활용하면 복잡한 다항식의 나눗셈 과정을 거치지 않고도, 나누는 식의 근을 대입하는 것만으로 나머지를 정확하게 찾아낼 수 있습니다. 이 방법은 고등 수학에서 다항식의 성질을 이해하고 문제를 효율적으로 해결하는 데 필수적인 도구입니다.',
            ],
          ),
        ],
      ),
    ],
