  '기울기': BookData(
    id: 'concept_기울기',
    title: '기울기',
    subtitle: '공통수학2 > 좌표평면 > 직선의방정식 > 기울기',
    category: 'common',
    tags: ['공통수학2', '좌표평면', '직선의방정식', '기울기'],
    chapters: [
      BookChapter(
        title: '기울기',
        intro: ['공통수학2 > 좌표평면 > 직선의방정식 > 기울기 개념 학습'],
        sections: [
          BookSection(
            title: '기울기',
            paragraphs: [
              '좌표평면에서 직선의 기울기는 직선이 얼마나 가파르게 기울어져 있는지를 나타내는 척도입니다. 직선 위의 서로 다른 두 점 \$A(x_1, y_1)\$과 \$B(x_2, y_2)\$를 지날 때, 기울기는 \'\$x\$의 증가량에 대한 \$y\$의 증가량의 비율\'로 정의합니다. 즉, \$x\$값이 \$x_1\$에서 \$x_2\$로 변할 때 \$y\$값이 \$y_1\$에서 \$y_2\$로 변한다면, 기울기 \$m\$은 다음과 같은 공식으로 구할 수 있습니다.',
              '기울기 \$m\$을 구하는 공식은 다음과 같습니다. \$\$m = \\frac{y_2 - y_1}{x_2 - x_1} = \\frac{\\Delta y}{\\Delta x} \\quad (x_1 \\neq x_2)\$\$ 이 식에서 분모인 \$x_2 - x_1\$은 \$x\$의 변화량, 분자인 \$y_2 - y_1\$은 \$y\$의 변화량을 의미합니다. 만약 \$x_1 = x_2\$라면 분모가 0이 되어 기울기를 정의할 수 없는데, 이는 직선이 \$y\$축과 평행한 수직선인 경우를 뜻합니다.',
              '기울기의 부호는 직선의 방향을 결정합니다. 기울기가 양수(\$m > 0\$)이면 오른쪽 위로 향하는 직선이 되고, 기울기가 음수(\$m < 0\$)이면 오른쪽 아래로 향하는 직선이 됩니다. 또한 기울기가 0(\$m = 0\$)이면 \$x\$축과 평행한 수평선이 됩니다. 기울기의 절댓값이 클수록 직선은 \$y\$축에 더 가깝게 가파르게 서 있게 됩니다.',
              '예제: 두 점 \$A(1, 2)\$와 \$B(3, 6)\$을 지나는 직선의 기울기를 구해 봅시다. 먼저 공식에 각 점의 좌표를 대입합니다. 여기서 \$x_1=1, y_1=2\$이고 \$x_2=3, y_2=6\$입니다. 기울기 \$m\$은 다음과 같이 계산됩니다. \$\$m = \\frac{6 - 2}{3 - 1} = \\frac{4}{2} = 2\$\$ 따라서 이 직선의 기울기는 2입니다.',
              '위의 결과에서 기울기가 2라는 것은 \$x\$값이 1만큼 증가할 때 \$y\$값은 2만큼 증가한다는 뜻입니다. 만약 점 \$A\$에서 시작하여 \$x\$축 방향으로 1만큼, \$y\$축 방향으로 2만큼 이동하면 점 \$(1+1, 2+2) = (2, 4)\$에 도달하게 되는데, 이 점 역시 해당 직선 위에 존재하게 됩니다. 이처럼 기울기는 직선 위의 임의의 두 점을 선택해도 항상 일정하다는 성질을 가지고 있습니다.',
            ],
          ),
        ],
      ),
    ],
  ),
  '지수함수의그래프': BookData(
