    chapters: [
      BookChapter(
        title: '지수함수의그래프',
        intro: ['대수 > 지수함수 > 지수함수의그래프 개념 학습'],
        sections: [
          BookSection(
            title: '지수함수의그래프',
            paragraphs: [
              '지수함수란 변수 \$x\$가 지수에 있는 함수로, 일반적으로 \$f(x) = a^x\$ (단, \$a > 0, a \\neq 1\$)의 꼴로 나타냅니다. 이때 \$a\$를 밑이라고 하며, 밑의 값에 따라 그래프의 모양이 결정됩니다. \$a > 1\$일 때는 \$x\$가 커질수록 \$y\$값도 급격히 커지는 증가함수가 되고, \$0 < a < 1\$일 때는 \$x\$가 커질수록 \$y\$값이 0에 한없이 가까워지는 감소함수가 됩니다.',
              '지수함수 \$y = a^x\$의 그래프는 몇 가지 중요한 성질을 가집니다. 첫째, 모든 지수함수의 그래프는 \$x\$가 무엇이든 \$a^0 = 1\$이 되므로 항상 점 \$(0, 1)\$을 지납니다. 둘째, \$a^x\$는 항상 양수이므로 그래프는 \$x\$축보다 항상 위쪽에 그려지며, \$x\$축(\$y=0\$)을 점근선으로 가집니다. 셋째, \$x\$값이 증가할 때 \$y\$값도 증가하거나 감소하는 일대일 대응 함수이므로 역함수가 존재합니다.',
              '지수함수의 그래프를 평행이동하거나 대칭이동하면 더 다양한 형태를 얻을 수 있습니다. 예를 들어 \$y = a^x + q\$는 원래 그래프를 \$y\$축 방향으로 \$q\$만큼 평행이동한 것이며, 이로 인해 점근선도 \$y = q\$로 변하게 됩니다. 또한 \$y = a^{-x} = (1/a)^x\$는 \$y\$축에 대하여 대칭인 그래프가 되어, 밑의 역수 관계가 그래프의 대칭성을 결정한다는 점을 이해하는 것이 중요합니다.',
              '예제: 함수 \$f(x) = 2^x - 1\$의 그래프를 그리고 점근선을 구하시오. 먼저 기본형인 \$y = 2^x\$의 그래프를 생각합니다. 이 그래프는 \$(0, 1)\$을 지나고 \$x\$축을 점근선으로 가집니다. 주어진 함수는 이를 \$y\$축 방향으로 \$-1\$만큼 평행이동한 것이므로, 모든 점의 \$y\$좌표에서 1을 뺍니다. 따라서 \$(0, 1)\$은 \$(0, 0)\$으로 이동합니다.',
              '단계별 풀이: 1단계, 기본 그래프 \$y = 2^x\$를 그립니다. 2단계, 함수식 \$y = 2^x - 1\$을 확인하여 그래프를 아래로 1만큼 내립니다. 3단계, 원래 점근선이 \$y = 0\$이었으므로, 평행이동에 의해 새로운 점근선은 \$y = -1\$이 됩니다. 결과적으로 이 그래프는 점 \$(0, 0)\$을 지나며 \$y = -1\$을 점근선으로 하는 증가하는 곡선이 됩니다.',
            ],
          ),
        ],
      ),
    ],
