    chapters: [
      BookChapter(
        title: '극댓값',
        intro: ['미적분Ⅰ > 함수의극대와극소 > 극댓값 개념 학습'],
        sections: [
          BookSection(
            title: '극댓값',
            paragraphs: [
              '함수의 극댓값이란, 어떤 열린 구간에서 함수 \$f(x)\$의 값이 그 구간에 속하는 모든 \$x\$에 대하여 \$f(x) \\le f(a)\$를 만족할 때, \$f(a)\$를 그 함수가 \$x=a\$에서 가지는 극댓값이라고 정의합니다. 쉽게 말해, 그래프가 주변보다 볼록하게 솟아오른 \'산봉우리\'와 같은 지점의 높이를 의미합니다. 이때 함수가 \$x=a\$를 포함하는 어떤 작은 범위 내에서 가장 큰 값을 가진다면, 그 지점을 극대점이라고 부릅니다.',
              '함수 \$f(x)\$가 미분 가능할 때, \$x=a\$에서 극댓값을 가지기 위한 필요조건은 \$f\'(a)=0\$입니다. 하지만 미분계수가 0이라고 해서 반드시 극댓값이 되는 것은 아닙니다. 정확한 판별을 위해서는 \$x=a\$를 기준으로 좌우에서의 도함수 부호 변화를 살펴야 합니다. 즉, \$x=a\$의 왼쪽에서 \$f\'(x) > 0\$이고, 오른쪽에서 \$f\'(x) < 0\$으로 부호가 바뀐다면, 함수 \$f(x)\$는 \$x=a\$에서 증가하다가 감소하게 되므로 \$f(a)\$는 극댓값이 됩니다.',
              '정리하자면, 극댓값을 찾기 위해서는 먼저 도함수 \$f\'(x)\$를 구하여 \$f\'(x)=0\$이 되는 \$x\$의 값을 찾습니다. 이후, 그 지점을 기준으로 도함수의 부호가 양(+)에서 음(-)으로 변하는지 확인하는 것이 핵심입니다. 이러한 성질을 이용하면 복잡한 다항함수의 그래프 개형을 정확하게 파악하고, 함수의 최댓값과 최솟값을 구하는 문제까지 확장하여 해결할 수 있습니다.',
              '예제: 함수 \$f(x) = -x^3 + 3x^2 + 9x\$의 극댓값을 구해보겠습니다. 먼저 함수를 미분하여 도함수를 구하면 \$f\'(x) = -3x^2 + 6x + 9\$가 됩니다. 극대 또는 극소가 되는 지점을 찾기 위해 \$f\'(x) = 0\$을 풀면 \$-3(x^2 - 2x - 3) = -3(x-3)(x+1) = 0\$이 되어, \$x=-1\$ 또는 \$x=3\$에서 도함수가 0이 됨을 알 수 있습니다.',
              '이제 \$x=-1\$과 \$x=3\$을 기준으로 도함수의 부호를 조사합니다. \$x < -1\$일 때 \$f\'(x) < 0\$, \$-1 < x < 3\$일 때 \$f\'(x) > 0\$, \$x > 3\$일 때 \$f\'(x) < 0\$이 됩니다. 따라서 \$x=-1\$에서는 감소하다가 증가하므로 극솟값을 갖고, \$x=3\$에서는 증가하다가 감소하므로 극댓값을 가집니다. 최종적으로 \$x=3\$을 원래 함수에 대입하면 \$f(3) = -(3)^3 + 3(3)^2 + 9(3) = -27 + 27 + 27 = 27\$이 되어, 구하는 극댓값은 \$27\$입니다.',
            ],
          ),
        ],
      ),
    ],
  ),
