            title: '이차부등식의풀이',
            paragraphs: [
              '이차부등식이란 부등식의 모든 항을 좌변으로 이항하여 정리했을 때, 좌변이 \$x\$에 대한 이차식인 부등식을 말합니다. 일반적으로 \$ax^2 + bx + c > 0\$ (또는 \$<, \\le, \\ge\$)의 꼴로 나타내며, 여기서 \$a, b, c\$는 상수이고 \$a \\neq 0\$입니다. 이차부등식을 푼다는 것은 부등식을 만족하는 \$x\$의 값의 범위를 구하는 것을 의미하며, 이는 이차함수 \$y = ax^2 + bx + c\$의 그래프가 \$x\$축보다 위쪽에 있는지, 아래쪽에 있는지, 혹은 만나는지를 확인하는 과정과 같습니다.',
              '이차부등식을 풀기 위해서는 먼저 이차방정식 \$ax^2 + bx + c = 0\$의 해를 구해야 합니다. 이차방정식의 두 실근을 \$\\alpha, \\beta\$ (단, \$\\alpha < \\beta\$)라고 할 때, \$a > 0\$인 경우 부등식의 해는 다음과 같이 결정됩니다. 첫째, \$ax^2 + bx + c > 0\$의 해는 \$x < \\alpha\$ 또는 \$x > \\beta\$입니다. 둘째, \$ax^2 + bx + c < 0\$의 해는 두 근 사이인 \$\\alpha < x < \\beta\$가 됩니다. 만약 판별식 \$D = b^2 - 4ac\$가 \$0\$이거나 \$0\$보다 작다면, 그래프의 위치 관계를 고려하여 해가 모든 실수이거나 해가 존재하지 않는 경우를 따져야 합니다.',
              '예를 들어 이차부등식 \$x^2 - 5x + 6 < 0\$을 풀어봅시다. 먼저 좌변을 인수분해하면 \$(x - 2)(x - 3) < 0\$이 됩니다. 이는 이차함수 \$y = x^2 - 5x + 6\$의 그래프가 \$x\$축과 만나는 두 점의 \$x\$좌표가 \$2\$와 \$3\$임을 의미합니다. \$x^2\$의 계수가 양수이므로 아래로 볼록한 포물선이 그려지며, 함숫값이 \$0\$보다 작은 구간은 두 교점 사이가 됩니다.',
              '따라서 부등식 \$x^2 - 5x + 6 < 0\$의 해는 \$2 < x < 3\$입니다. 이처럼 이차부등식을 풀 때는 항상 이차항의 계수를 양수로 맞춘 뒤, 인수분해를 통해 \$x\$축과의 교점을 찾고, 그래프의 개형을 그려 부등호의 방향에 맞는 범위를 선택하는 것이 가장 정확하고 효율적인 방법입니다.',
              '또 다른 예로 \$x^2 - 4x + 4 \\le 0\$을 풀어보겠습니다. 좌변을 인수분해하면 \$(x - 2)^2 \\le 0\$이 됩니다. 이차함수 \$y = (x - 2)^2\$의 그래프는 꼭짓점이 \$(2, 0)\$인 아래로 볼록한 포물선입니다. 이 그래프는 \$x=2\$일 때 \$0\$이 되고, 나머지 모든 \$x\$에 대해서는 항상 \$0\$보다 큽니다. 문제에서는 \$0\$보다 작거나 같은 범위를 찾으라고 했으므로, 조건을 만족하는 값은 \$x = 2\$뿐입니다.',
            ],
          ),
        ],
      ),
    ],
