        intro: ['대수 > 수열 > 여러가지수열의합 > 자연수의거듭제곱의합 개념 학습'],
        sections: [
          BookSection(
            title: '자연수의거듭제곱의합',
            paragraphs: [
              '자연수의 거듭제곱의 합이란 1부터 n까지의 자연수를 각각 거듭제곱하여 모두 더한 값을 의미합니다. 수열의 합을 나타내는 기호인 시그마(\$\\sum\$)를 사용하여 표현하며, 가장 대표적인 세 가지 공식은 자연수 그 자체의 합, 제곱의 합, 세제곱의 합입니다. 이 공식들은 수열의 일반항이 \$k, k^2, k^3\$인 경우의 합을 구하는 과정에서 매우 유용하게 사용됩니다.',
              '첫 번째로 1부터 \$n\$까지의 자연수의 합은 \$\$ \\sum_{k=1}^{n} k = \\frac{n(n+1)}{2} \$\$ 입니다. 두 번째로 자연수의 제곱의 합은 \$\$ \\sum_{k=1}^{n} k^2 = \\frac{n(n+1)(2n+1)}{6} \$\$ 이며, 마지막으로 자연수의 세제곱의 합은 \$\$ \\sum_{k=1}^{n} k^3 = \\left\\{ \\frac{n(n+1)}{2} \\right\\}^2 \$\$ 로 계산됩니다. 이 공식들은 수학적 귀납법을 통해 증명할 수 있으며, 복잡한 수열의 합을 구할 때 기본이 되는 도구입니다.',
              '이제 예제를 통해 직접 적용해 봅시다. 첫 번째 문제는 \'1부터 10까지의 제곱의 합을 구하시오\'입니다. 즉, \$1^2 + 2^2 + \\dots + 10^2\$의 값을 구하는 것입니다. 여기서 \$n=10\$이므로, 앞서 배운 제곱의 합 공식을 그대로 대입하면 됩니다.',
              '풀이 과정은 다음과 같습니다. 공식 \$\$ \\sum_{k=1}^{n} k^2 = \\frac{n(n+1)(2n+1)}{6} \$\$ 에 \$n=10\$을 대입하면, \$\$ \\frac{10(10+1)(2 \\times 10 + 1)}{6} = \\frac{10 \\times 11 \\times 21}{6} \$\$ 이 됩니다. 이를 계산하면 \$\$ \\frac{2310}{6} = 385 \$\$ 가 되어, 1부터 10까지의 제곱의 합은 385임을 알 수 있습니다.',
              '두 번째 예제로 \'1부터 5까지의 세제곱의 합을 구하시오\'를 풀어보겠습니다. 이는 \$1^3 + 2^3 + 3^3 + 4^3 + 5^3\$을 계산하는 문제입니다. 세제곱의 합 공식인 \$\$ \\sum_{k=1}^{n} k^3 = \\left\\{ \\frac{n(n+1)}{2} \\right\\}^2 \$\$ 에 \$n=5\$를 대입합니다.',
              '단계별 풀이는 다음과 같습니다. 먼저 괄호 안의 값을 계산하면 \$\$ \\frac{5(5+1)}{2} = \\frac{5 \\times 6}{2} = 15 \$\$ 입니다. 이제 이 값을 제곱하면 \$\$ 15^2 = 225 \$\$ 가 됩니다. 따라서 1부터 5까지의 세제곱의 합은 225입니다. 이처럼 공식을 활용하면 일일이 더하지 않아도 빠르고 정확하게 합을 구할 수 있습니다.',
            ],
          ),
        ],
      ),
    ],
  ),
  '필요조건': BookData(
    id: 'concept_필요조건',
    title: '필요조건',
    subtitle: '공통수학2 > 명제 > 충분조건과필요조건 > 필요조건',
    category: 'common',
    tags: ['공통수학2', '명제', '충분조건과필요조건', '필요조건'],
    chapters: [
      BookChapter(
        title: '필요조건',
        intro: ['공통수학2 > 명제 > 충분조건과필요조건 > 필요조건 개념 학습'],
        sections: [
          BookSection(
            title: '필요조건',
            paragraphs: [
              '두 조건 \$p, q\$에 대하여 명제 \'\$p\$이면 \$q\$이다(\$p \\implies q\$)\'가 참일 때, 우리는 \$p\$를 \$q\$이기 위한 \'충분조건\'이라고 부릅니다. 반대로 \$q\$의 입장에서는 \$p\$가 참이 되기 위해 반드시 만족해야 하는 조건이 되므로, \$q\$를 \$p\$이기 위한 \'필요조건\'이라고 정의합니다. 즉, \$p \\implies q\$가 참이라는 것은 \$p\$가 일어나는 상황이 \$q\$가 일어나는 상황에 포함된다는 뜻이며, 이때 \$q\$는 \$p\$를 받아들이기 위한 넓은 울타리 역할을 한다고 이해할 수 있습니다.',
              '필요조건을 판별하는 핵심은 진리집합 사이의 포함 관계를 확인하는 것입니다. 두 조건 \$p, q\$의 진리집합을 각각 \$P, Q\$라고 할 때, \$P \\subseteq Q\$이면 명제 \$p \\implies q\$는 참이 됩니다. 이때 \$q\$는 \$p\$이기 위한 필요조건입니다. 만약 \$P = Q\$인 경우에는 \$p\$는 \$q\$이기 위한 필요충분조건이 되며, 이는 필요조건의 정의를 만족하는 특수한 경우라고 볼 수 있습니다.',
              '예를 들어, \'\$x\$는 4의 배수이다\'라는 조건 \$p\$와 \'\$x\$는 2의 배수이다\'라는 조건 \$q\$를 생각해 봅시다. 4의 배수는 모두 2의 배수이므로 \$p \\implies q\$는 참입니다. 이때 \$p\$의 진리집합 \$P = \\{4, 8, 12, \\dots\\}\$는 \$q\$의 진리집합 \$Q = \\{2, 4, 6, 8, \\dots\\}\$에 포함됩니다. 따라서 \$q\$는 \$p\$이기 위한 필요조건이 됩니다. 즉, \$x\$가 4의 배수가 되려면 일단 2의 배수라는 조건이 반드시 필요하기 때문에 이러한 이름이 붙은 것입니다.',
              '다음 예제를 통해 필요조건을 확인해 봅시다. 두 조건 \$p: x > 3\$, \$q: x > 1\$에 대하여 \$q\$가 \$p\$이기 위한 필요조건인지 판별해 보세요. 먼저 각 조건의 진리집합을 수직선 위에 나타내면 \$P = \\{x \\mid x > 3\\}\$이고 \$Q = \\{x \\mid x > 1\\}\$입니다. 수직선에서 \$P\$의 범위가 \$Q\$의 범위 안에 완전히 포함되는지 확인하면, \$3\$보다 큰 모든 수는 \$1\$보다 크다는 사실을 알 수 있습니다.',
              '따라서 진리집합 사이의 관계는 \$P \\subset Q\$가 성립합니다. 이는 명제 \'\$p \\implies q\$\'가 참임을 의미하며, 정의에 따라 \$q\$는 \$p\$이기 위한 필요조건이 됩니다. 이처럼 어떤 조건이 다른 조건의 범위를 포함하고 있을 때, 그 포함하는 쪽의 조건이 바로 \'필요조건\'이 된다는 점을 기억하면 문제를 쉽게 해결할 수 있습니다.',
            ],
          ),
        ],
      ),
    ],
  ),
  '인수정리증명': BookData(
    id: 'concept_인수정리증명',
    title: '인수정리증명',
    subtitle: '공통수학1 > 다항식 > 인수정리 > 인수정리증명',
    category: 'common',
    tags: ['공통수학1', '다항식', '인수정리', '인수정리증명'],
    chapters: [
      BookChapter(
        title: '인수정리증명',
        intro: ['공통수학1 > 다항식 > 인수정리 > 인수정리증명 개념 학습'],
        sections: [
          BookSection(
            title: '인수정리증명',
            paragraphs: [
              '[   "인수정리란 다항식 \$P(x)\$에 대하여 \$P(a)=0\$이면, 다항식 \$P(x)\$는 일차식 \$(x-a)\$를 인수로 가진다는 정리입니다. 이는 나머지정리의 특수한 경우로, 다항식을 \$(x-a)\$로 나누었을 때 나머지가 0이 되는 상황을 의미합니다. 즉, 어떤 다항식의 값을 0으로 만드는 \$x\$의 값을 찾으면, 그 다항식을 나누어떨어지게 하는 일차식 인수를 바로 찾아낼 수 있다는 매우 강력한 도구입니다.",   "인수정리를 증명하기 위해서는 다항식의 나눗셈에 대한 항등식을 이용합니다. 다항식 \$P(x)\$를 \$(x-a)\$로 나누었을 때의 몫을 \$Q(x)\$, 나머지를 \$R\$이라고 하면, 나눗셈의 원리에 의해 \$\$P(x) = (x-a)Q(x) + R\$\$이라는 식을 세울 수 있습니다. 이때 나누는 식이 일차식이므로 나머지는 상수 \$R\$이 됩니다. 여기서 양변에 \$x=a\$를 대입하면 \$\$P(a) = (a-a)Q(a) + R = 0 \\cdot Q(a) + R = R\$\$이 되어, 결국 \$R=P(a)\$라는 나머지정리가 성립함을 알 수 있습니다.",   "이제 인수정리를 증명해 봅시다. 만약 \$P(a)=0\$이라면, 위에서 구한 식 \$R=P(a)\$에 의해 나머지 \$R\$은 0이 됩니다. 따라서 처음의 항등식은 \$\$P(x) = (x-a)Q(x)\$\$가 됩니다. 이 식은 \$P(x)\$가 \$(x-a)\$와 \$Q(x)\$의 곱으로 나타내어짐을 의미하므로, \$(x-a)\$는 \$P(x)\$의 인수가 됩니다. 역으로 \$P(x)\$가 \$(x-a)\$를 인수로 가진다면 \$P(x)=(x-a)Q(x)\$이므로 \$x=a\$를 대입했을 때 \$P(a)=0\$이 됨은 자명합니다.",   "예제: 다항식 \$P(x) = x^3 - 2x^2 - x + 2\$가 \$(x-1)\$을 인수로 가지는지 인수정리를 이용하여 확인해 봅시다. 먼저 인수정리에 따라 \$x=1\$을 다항식에 대입하여 \$P(1)\$의 값을 구합니다. \$\$P(1) = 1^3 - 2(1)^2 - 1 + 2 = 1 - 2 - 1 + 2 = 0\$\$입니다. \$P(1)=0\$이므로, 인수정리에 의해 \$P(x)\$는 \$(x-1)\$을 인수로 가짐을 알 수 있습니다.",   "위에서 확인한 인수를 바탕으로 다항식을 완전히 인수분해해 봅시다. \$P(x) = x^3 - 2x^2 - x + 2\$를 \$(x-1)\$로 나누면 몫은 조립제법을 통해 구할 수 있습니다. 계수 1, -2, -1, 2를 1로 나누면 몫의 계수는 1, -1, -2가 되어 몫은 \$x^2 - x - 2\$가 됩니다. 따라서 \$\$P(x) = (x-1)(x^2 - x - 2)\$\$가 되며, 이차식 \$x^2 - x - 2\$를 다시 인수분해하면 \$\$(x-1)(x-2)(x+1)\$\$이라는 최종 결과를 얻을 수 있습니다." ]',
            ],
          ),
        ],
      ),
    ],
  ),
  '절편': BookData(
    id: 'concept_절편',
    title: '절편',
    subtitle: '공통수학2 > 좌표평면 > 직선의방정식 > 절편',
    category: 'common',
    tags: ['공통수학2', '좌표평면', '직선의방정식', '절편'],
    chapters: [
      BookChapter(
        title: '절편',
        intro: ['공통수학2 > 좌표평면 > 직선의방정식 > 절편 개념 학습'],
        sections: [
          BookSection(
            title: '절편',
            paragraphs: [
              '좌표평면 위에서 직선이 x축이나 y축과 만나는 점을 \'절편\'이라고 합니다. 구체적으로, 직선이 x축과 만나는 점의 x좌표를 \'x절편\'이라 하고, y축과 만나는 점의 y좌표를 \'y절편\'이라고 부릅니다. x축 위의 모든 점은 y좌표가 0이므로, x절편을 구하려면 직선의 방정식에 \$y=0\$을 대입하여 x의 값을 찾으면 됩니다. 반대로 y축 위의 모든 점은 x좌표가 0이므로, y절편을 구하려면 \$x=0\$을 대입하여 y의 값을 찾습니다.',
              '직선의 방정식을 \$ax + by + c = 0\$ (단, \$a, b \\neq 0\$)의 형태로 나타낼 때, x절편은 \$y=0\$을 대입한 \$ax + c = 0\$에서 \$x = -\\frac{c}{a}\$가 됩니다. 마찬가지로 y절편은 \$x=0\$을 대입한 \$by + c = 0\$에서 \$y = -\\frac{c}{b}\$가 됩니다. 만약 직선이 x절편을 \$p\$, y절편을 \$q\$라고 할 때, 이 직선의 방정식은 다음과 같은 아름다운 공식으로 표현할 수 있습니다. \$\$\\frac{x}{p} + \\frac{y}{q} = 1 \\quad (p \\neq 0, q \\neq 0)\$\$',
              '절편은 직선의 그래프를 그릴 때 매우 유용합니다. 두 점만 알면 직선을 그릴 수 있는데, x절편과 y절편은 좌표축 위에서 쉽게 찾을 수 있는 두 점이기 때문입니다. 따라서 직선의 방정식을 알면 절편을 구하여 좌표평면에 점을 찍고, 그 두 점을 곧게 연결하기만 하면 그래프를 빠르게 완성할 수 있습니다. 이제 이 개념을 활용하여 구체적인 예제를 풀어보겠습니다.',
              '예제: 직선 \$2x - 3y + 6 = 0\$의 x절편과 y절편을 각각 구하고, 이를 이용하여 그래프를 그려봅시다. 먼저 x절편을 구하기 위해 \$y=0\$을 대입하면 \$2x - 3(0) + 6 = 0\$이 됩니다. 이를 정리하면 \$2x = -6\$이 되어 \$x = -3\$을 얻습니다. 따라서 x절편은 \$-3\$이며, 그래프는 점 \$(-3, 0)\$을 지납니다.',
              '다음으로 y절편을 구하기 위해 \$x=0\$을 대입하면 \$2(0) - 3y + 6 = 0\$이 됩니다. 이를 정리하면 \$-3y = -6\$이 되어 \$y = 2\$를 얻습니다. 따라서 y절편은 \$2\$이며, 그래프는 점 \$(0, 2)\$를 지납니다. 결론적으로 이 직선은 좌표평면에서 \$(-3, 0)\$과 \$(0, 2)\$라는 두 점을 지나는 직선이 됩니다. 이 두 점을 자를 대고 연결하면 우리가 원하는 직선의 그래프가 완성됩니다.',
