              '함수가 미분 가능할 때, 극솟값을 찾는 방법은 도함수 \$f\'(x)\$를 활용하는 것입니다. 만약 \$x=a\$에서 함수 \$f(x)\$가 극솟값을 가진다면, 그 지점에서의 접선의 기울기는 \$0\$이 되어야 하므로 \$f\'(a)=0\$을 만족합니다. 이때 \$x=a\$를 기준으로 왼쪽에서는 도함수의 부호가 음수(\$f\'(x) < 0\$)였다가 오른쪽에서 양수(\$f\'(x) > 0\$)로 바뀌는 현상이 나타납니다. 이를 통해 우리는 도함수의 부호 변화를 관찰하여 극솟값을 정확히 판별할 수 있습니다.',
              '정리하자면, 극솟값을 구하는 과정은 크게 두 단계로 나뉩니다. 첫째, 방정식 \$f\'(x)=0\$을 풀어 미분계수가 \$0\$이 되는 \$x\$의 값들을 찾습니다. 둘째, 그 지점의 좌우에서 도함수의 부호가 \'음에서 양\'으로 변하는지 확인합니다. 만약 부호가 바뀐다면 그 지점의 함숫값 \$f(a)\$가 바로 극솟값이 됩니다. 이 원리는 복잡한 다항함수의 그래프 개형을 파악하는 데 매우 중요한 도구가 됩니다.',
              '예제 문제: 함수 \$f(x) = x^3 - 3x + 2\$의 극솟값을 구하시오. 먼저 주어진 함수를 미분하면 \$f\'(x) = 3x^2 - 3\$이 됩니다. 극값이 될 후보를 찾기 위해 \$f\'(x) = 0\$을 계산하면 \$3(x^2 - 1) = 0\$이 되어 \$x = 1\$ 또는 \$x = -1\$이라는 두 개의 임계점을 얻을 수 있습니다.',
              '이제 각 지점에서의 부호 변화를 살펴봅시다. \$x < -1\$일 때 \$f\'(x) > 0\$, \$-1 < x < 1\$일 때 \$f\'(x) < 0\$, \$x > 1\$일 때 \$f\'(x) > 0\$이 됩니다. \$x=1\$인 지점을 보면 도함수의 부호가 음수에서 양수로 바뀌고 있으므로, \$x=1\$에서 극솟값을 가짐을 알 수 있습니다. 따라서 구하는 극솟값은 \$f(1)\$을 계산하여 얻을 수 있습니다.',
              '최종 계산을 수행하면 \$f(1) = 1^3 - 3(1) + 2 = 1 - 3 + 2 = 0\$이 됩니다. 따라서 함수 \$f(x) = x^3 - 3x + 2\$의 극솟값은 \$0\$입니다. 이처럼 도함수의 부호 변화를 꼼꼼히 확인하는 습관을 들이면, 어떤 함수가 주어지더라도 정확하게 극솟값을 찾아낼 수 있습니다.',
            ],
          ),
