        title: '지수함수의성질',
        intro: ['대수 > 지수함수 > 지수함수의성질 개념 학습'],
        sections: [
          BookSection(
            title: '지수함수의성질',
            paragraphs: [
              '지수함수란 변수 \$x\$가 지수 자리에 있는 함수로, 일반적으로 \$f(x) = a^x\$ (단, \$a > 0, a \\neq 1\$)의 꼴로 나타냅니다. 여기서 \$a\$를 밑이라고 하며, 밑이 1보다 크면 \$x\$가 커질수록 함숫값도 커지는 증가함수가 되고, 밑이 0과 1 사이이면 \$x\$가 커질수록 함숫값은 작아지는 감소함수가 됩니다. 모든 지수함수는 \$x\$의 값에 관계없이 \$a^0 = 1\$이므로 항상 점 \$(0, 1)\$을 지나며, \$x\$축(\$y=0\$)을 점근선으로 갖는다는 중요한 특징이 있습니다.',
              '지수함수의 성질을 이해하기 위해서는 지수 법칙을 잘 활용해야 합니다. 지수함수 \$f(x) = a^x\$에 대하여 정의역은 모든 실수이고, 치역은 항상 양의 실수 전체의 집합(\$y > 0\$)입니다. 또한, \$a > 1\$일 때 \$x_1 < x_2\$이면 \$a^{x_1} < a^{x_2}\$가 성립하고, \$0 < a < 1\$일 때 \$x_1 < x_2\$이면 \$a^{x_1} > a^{x_2}\$가 성립합니다. 이러한 성질은 부등식을 풀거나 함수의 최댓값과 최솟값을 구할 때 매우 유용하게 사용됩니다.',
              '예를 들어, 함수 \$f(x) = 2^x\$와 \$g(x) = (1/2)^x\$를 비교해 봅시다. \$f(x)\$는 밑이 2로 1보다 크기 때문에 오른쪽 위로 향하는 그래프를 그리며, \$g(x)\$는 밑이 1/2로 0과 1 사이이므로 오른쪽 아래로 향하는 그래프를 그립니다. 특히 \$g(x) = (1/2)^x = 2^{-x}\$이므로, \$g(x)\$의 그래프는 \$f(x)\$의 그래프를 \$y\$축에 대하여 대칭이동한 것과 같다는 성질을 확인할 수 있습니다.',
